window.CY = {"meta":{"city":"花蓮縣","slug":"hualien-county","updated":"2026-11-01","designer":"Allan Lo","designed":"2026/11/1","ai":"Claude Opus 5.5"},"config":{"slug":"hualien-county","name":"花蓮縣","short":"花蓮","center":[23.75,121.45],"zoom":9,"minZoom":8,"detailZoom":16,"timeZoom":10,"categories":["國定古蹟","縣定古蹟","歷史建築","聚落建築群","考古遺址","文化景觀"],"towns":["秀林鄉","新城鄉","花蓮市","吉安鄉","壽豐鄉","鳳林鎮","萬榮鄉","光復鄉","豐濱鄉","瑞穗鄉","玉里鎮","卓溪鄉","富里鄉"],"ubikeAreas":[],"wiki":{"title":"維基百科「花蓮縣文化資產」","url":"https://zh.wikipedia.org/zh-tw/%E8%8A%B1%E8%93%AE%E7%B8%A3%E6%96%87%E5%8C%96%E8%B3%87%E7%94%A2"},"introTitle":"歡迎來到花蓮","quizTitle":"洄瀾文資通","eraLabels":{"dutch":"西荷時期","zheng":"部落社會（明鄭與清前期）","qing":"清代（1875 年開山以後）"},"board":{"name":"洄瀾擲骰大冒險","start":"出發：花蓮火車站","train":"花東線火車","trainText":"搭上花東線火車，前進 3 格！","food":"扁食補給站"},"planner":{"speeds":{"car":32,"scooter":28,"bike":13,"walk":4.5,"ubike":13},"hints":{"car":"花蓮縣南北超過 120 公里，從新城到富里開車要兩個多小時，景點分散在花蓮市區、花東縱谷與山區，開車最方便。蘇花公路與中橫公路的通行狀況請先查詢最新公告。每站已預留約 8 分鐘停車時間。","scooter":"花蓮市區與縱谷騎機車很方便；走台9線、台11線長途時請注意大型車與強風，山區道路彎多，雨後與地震後留意落石。","bike":"花蓮市區有美崙溪、海濱的自行車道，縱谷的鳳林、光復、瑞穗、玉里、富里地勢平坦；單段超過 12 公里會建議改開車或搭臺鐵。","walk":"花蓮市區的日式宿舍、將軍府、松園別館與文創園區彼此不遠，可以步行串遊；單段超過 3 公里會建議改搭車。","ubike":"花蓮縣目前沒有 YouBike 2.0 站點，建議開車、騎機車，或搭臺鐵北迴線、花東線與客運。"},"defaultMode":"car","lunchNote":"花蓮在地小吃：扁食、麻糬、炸彈蔥油餅、花蓮薯；縱谷可吃鳳林客家菜、瑞穗鮮奶與玉里麵","eveningNote":"晚上可逛花蓮市的東大門夜市（營業日以現場公告為準），或到花蓮港、南濱公園、北濱公園看海散步","walkMaxKm":3,"bikeMaxKm":12,"ubikeStationMaxKm":1.2,"farKm":130},"eras":{"dutch":{"layers":[],"paper":true,"end":1662,"note":"西班牙與荷蘭時期沒有花蓮的實測地圖，底圖改成古紙風格，標示的是推定位置。"},"zheng":{"layers":[],"paper":true,"end":1874,"note":"明鄭與清前期，後山仍是阿美族、撒奇萊雅族、太魯閣族等族群的家園，清廷也未設治，沒有實測地圖，底圖改成古紙風格，標示的是推定位置。"},"qing":{"layers":["1904"],"end":1895,"note":"1904 年的臺灣堡圖是日治初期實測，記錄了清末花蓮港、璞石閣（今玉里）等街庄與縱谷部落。山區不在這張圖的範圍內。"},"japan":{"layers":["1916","1945"],"end":1945,"note":"1921 年與 1944 年的地形圖沒有涵蓋花蓮。這裡改用 1916 年蕃地地形圖看縱谷、海岸與山區部落；花蓮市區可切換 1945 年美軍繪製的花蓮港市街圖。"},"early-roc":{"layers":["1950"],"end":1960,"note":"1950 年的地形圖：戰後初期的花蓮縣。"},"roc60":{"layers":["1966","corona"],"end":1981,"note":"1957–1969 年的二萬五千分之一地形圖，也可以切換 1966 年的 Corona 衛星影像，看中橫公路通車後、北迴鐵路通車前的花蓮。"},"now":{"layers":["photo","1989"],"end":2026,"opacity":0,"note":"今天的花蓮縣。可疊上正射影像或 1989 年的地形圖做對照。"}}},"categories":["國定古蹟","縣定古蹟","歷史建築","聚落建築群","考古遺址","文化景觀"],"sites":[{"id":"yuli-batongguangudao","name":"八通關古道","short":"八通關古道","category":"國定古蹟","level":"國定古蹟","town":"玉里鎮","types":["碑碣"],"lat":23.33392,"lng":121.31601,"address":"花蓮縣玉里鎮光復路54巷（協天宮一帶，古道東端璞石閣）","announced":"1987-04-17","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19870417000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/37604/photo/96b0b3c4-2efd-4817-afeb-67c7479a3efa.jpg","year":1875,"yearText":"1875年（清光緒元年）開闢","era":"qing","themes":["清代開山","原住民族文化"],"yearUnknown":false,"summary":"與南投共有、東抵玉里的清代中路國定古蹟","intro":"八通關古道是與南投縣共有的跨縣市國定古蹟，官方紀錄登錄於南投縣。1874年牡丹社事件後，清廷推動開山撫番，1875年由總兵吳光亮率兵開闢「中路」，西起林圯埔（今竹山），東到璞石閣（今玉里），全長約152公里，東段經卓溪鄉山區，1987年指定為一級古蹟。對清廷而言這是開發後山的通道，對原住民族則是武力進入傳統領域。古道後來逐漸荒廢，東段大多已湮沒；今日登山客走的是日治1919至1921年另闢的八通關越嶺道，兩者不同。花蓮端可到玉里協天宮看「後山保障」匾。","highlights":["玉里協天宮正殿的「後山保障」木匾","古道東端璞石閣，就是今天的玉里","分清楚清代古道與日治越嶺道"],"funFact":"「後山保障」匾落款只寫一個「吳」字，相傳是吳光亮，也有文史考證認為是其弟吳光忠。","photoSpot":"在協天宮正殿抬頭拍「後山保障」匾額","visitMin":30,"openNote":"花蓮端到訪點為玉里鎮協天宮（古道東端璞石閣），可搭臺鐵花東線至玉里站。清代古道東段大多已湮沒；若要走卓溪鄉南安進出的八通關越嶺道，須依玉山國家公園規定申請入山入園，東段山區路況請查詢玉山國家公園管理處最新公告。","dialogue":[{"who":"A","text":"阿拉蕾，先老實招認，花蓮登錄的國定古蹟只有一條，而且是和南投共有的跨縣市古道。"},{"who":"R","text":"我猜到了，是八通關古道！它是什麼時候開的？"},{"who":"A","text":"1875年，牡丹社事件後清廷推動開山撫番，總兵吳光亮率兵從林圯埔，也就是竹山，開到璞石閣，就是玉里。"},{"who":"R","text":"全長有多長？我的腳已經先發抖了。"},{"who":"A","text":"約152公里，東段穿過卓溪鄉山區。對清廷是開發後山，對原住民族卻是軍隊進入自己的傳統領域。"},{"who":"R","text":"那現在登山客走的八通關，就是這條清代古道嗎？"},{"who":"A","text":"不是喔，清代古道東段大多已湮沒，大家走的是日治1919到1921年另闢的越嶺道，1987年指定的是清代這條。"},{"who":"R","text":"原來是兩條路，差點被名字騙了！那在花蓮哪裡可以找到它的痕跡？"},{"who":"A","text":"到玉里協天宮抬頭找「後山保障」木匾，相傳和清軍有關。想上山，記得依國家公園規定申請，先查最新路況！"}],"clues":["我1987年被指定為古蹟，卻常被誤認成日治時期的另一條路","我西起林圯埔，東到璞石閣，全長約152公里","我是清代總兵吳光亮率兵開闢的中路"],"quiz":[{"q":"八通關古道是哪一年開闢的？","options":["1875年","1874年","1919年","1987年"],"answer":0,"explain":"清光緒元年（1875年）由吳光亮率兵開闢。"},{"q":"今日登山客走的八通關越嶺道是哪個時期開闢的？","options":["清代","日治時期","戰後","荷蘭時期"],"answer":1,"explain":"越嶺道為日治1919至1921年另闢，與清代古道不同。"}],"images":[]},{"id":"xincheng-shenshejiuzhi","name":"新城神社舊址","short":"新城神社舊址","category":"縣定古蹟","level":"縣(市)定古蹟","town":"新城鄉","types":["寺廟"],"lat":24.1293,"lng":121.65037,"address":"花蓮縣新城鄉新城村博愛路64 號","announced":"2002-09-23","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20050223000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-30/f3d977e2-842e-45d0-a83a-94737a7b4ca2/b新城-神社舊址36.jpg","year":1914,"yearText":"1914年（大正3年）建社，1937年改建","era":"japan","themes":["神社遺構","原住民族文化","宗教信仰"],"yearUnknown":false,"summary":"神社遺構與天主堂共存，見證新城事件","intro":"新城神社舊址位於新城鄉新城村博愛路，今為新城天主堂。新城一帶原為太魯閣族與阿美族南勢群居地。1896年12月，日軍欺辱當地少女，引發太魯閣族人殺死13名日軍的「新城事件」，被視為東部重要的抗日事件，也成為後來1914年太魯閣戰役的遠因之一。日方於1914年為紀念死亡日軍建神社，1937年以水泥重建。1962年天主教會購地改建為教堂，至今仍保留鳥居兩座、石燈籠八座、守護獸兩對、手水舍及「殉難將士瘞骨碑」等遺構。","highlights":["兩座洗石子鳥居與參道兩旁八座石燈籠","庭園中的日軍「殉難將士瘞骨碑」","原紀念碑處改設的聖母像與老黑松"],"funFact":"神社原本的手水舍現在變成涼亭，洗手的花崗岩水池則搬進教堂裡保存。","photoSpot":"從鳥居下框住天主堂與聖母園","visitMin":30,"openNote":"位於新城鄉新城村博愛路，今為新城天主堂，官方資料記載自由參觀。教堂為宗教場所，彌撒時段請保持安靜。可搭臺鐵到新城站，再步行或轉車前往。","dialogue":[{"who":"A","text":"阿拉蕾，你猜猜看，哪裡可以同時看到鳥居和聖母像？"},{"who":"R","text":"日本神社加天主教堂？這是什麼神奇組合？"},{"who":"A","text":"就是新城天主堂！這裡原本是新城神社，1962年天主教會買下土地改建教堂，神社遺構都留了下來。"},{"who":"R","text":"那神社當初為什麼會蓋在新城這裡呢？"},{"who":"A","text":"1896年日軍欺辱當地少女，太魯閣族人反擊，殺死13名日軍，史稱新城事件，日方後來建神社紀念死去的士兵。"},{"who":"R","text":"所以對太魯閣族人來說，這是保護族人的抵抗，對日本人則是紀念戰死者，同一個地方兩種記憶。"},{"who":"A","text":"說得很好。這件事也是1914年太魯閣戰役的遠因之一，所以來這裡要用安靜的心情看。"},{"who":"R","text":"我會的！那有什麼比較輕鬆的小發現嗎？"},{"who":"A","text":"有，以前的手水舍現在變涼亭了。請你數一數參道兩旁，石燈籠是不是真的有8座！"}],"clues":["我的園子裡有鳥居、石燈籠，還有一尊聖母像","我最早是為紀念1896年一場事件中死亡的日軍而建","我在新城鄉博愛路，今天是一座天主堂"],"quiz":[{"q":"新城事件發生在哪一年？","options":["1896年","1908年","1914年","1930年"],"answer":0,"explain":"1896年12月爆發新城事件。"},{"q":"1962年起，新城神社舊址變成了什麼？","options":["國民小學","天主教堂","鄉公所","佛教寺院"],"answer":1,"explain":"1962年由天主教會購得，改建為禮拜堂。"}],"images":[{"file":"新城社鳥居.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/42/%E6%96%B0%E5%9F%8E%E7%A4%BE%E9%B3%A5%E5%B1%85.JPG/960px-%E6%96%B0%E5%9F%8E%E7%A4%BE%E9%B3%A5%E5%B1%85.JPG","page":"https://commons.wikimedia.org/wiki/File:%E6%96%B0%E5%9F%8E%E7%A4%BE%E9%B3%A5%E5%B1%85.JPG","artist":"Pbdragonwang","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/xincheng-shenshejiuzhi-0.webp","small":"img/xincheng-shenshejiuzhi-0-s.webp"}]},{"id":"ruisui-saobasuidao","name":"掃叭隧道","short":"掃叭隧道","category":"縣定古蹟","level":"縣(市)定古蹟","town":"瑞穗鄉","types":["其他設施"],"lat":23.46584,"lng":121.34795,"address":"花蓮縣瑞穗鄉北口位於瑞穗鄉舞鶴78號旁","announced":"2016-12-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20161221000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-30/3171245e-067f-44af-9faa-c8ec3e05576f/i瑞穗-掃叭隊道11.jpg","year":1916,"yearText":"1914年動工，1916年（大正5年）完工","era":"japan","themes":["鐵道交通"],"yearUnknown":false,"summary":"臺東線最早開鑿、唯一的磚拱鐵道隧道","intro":"掃叭隧道位於瑞穗鄉舞鶴，是臺東線鐵道最早開鑿的隧道，1914年6月動工、1916年10月完工，全長約1,166公尺，以人力開挖後用紅磚襯砌，外觀採一皮順磚、一皮丁磚的荷蘭式砌法。施工時遇到地質與天災困難，官方記載曾有多名工人罹難。北口有第五任臺灣總督佐久間左馬太題「無窮」，南口有第六任總督安東貞美題「宏達」。東線拓寬時另建新隧道取代，1984年底切換完成後廢棄。如今北口因地下水形成濕地，設有步道與單車道；南口因風災坍塌，幾乎被土石掩埋。","highlights":["北口佐久間左馬太總督題的「無窮」","一皮順磚一皮丁磚的荷蘭式砌法","北口地下水形成的掃叭濕地"],"funFact":"隧道兩端題字出自兩任總督：北口「無窮」、南口「宏達」，一條隧道就有兩位總督題字。","photoSpot":"在北口正面拍「無窮」題字與紅磚拱圈","visitMin":30,"openNote":"位於瑞穗鄉舞鶴，北口設有步道與單車道，南口已坍塌不易抵達。官方資料未載開放時間，出發前請查詢最新開放與道路狀況；建議開車前往。","dialogue":[{"who":"A","text":"阿拉蕾，前面這個爬滿綠意的紅磚拱門，就是瑞穗舞鶴的掃叭隧道北口。"},{"who":"R","text":"哇，好像童話故事裡通往祕密花園的入口！"},{"who":"A","text":"它可是臺東線最早開鑿的隧道，1914年動工、1916年完工，全長大約1166公尺。"},{"who":"R","text":"一百多年前，怎麼挖得出這麼長的隧道？"},{"who":"A","text":"靠人力開挖，再一塊塊砌紅磚。地質不好又遇到天災，官方紀錄說有多名工人在施工中罹難。"},{"who":"R","text":"原來這麼辛苦，那拱門上寫的是什麼字？"},{"who":"A","text":"北口是佐久間左馬太總督題的「無窮」，南口是安東貞美總督題的「宏達」，一條隧道兩位總督簽名。"},{"who":"R","text":"那這條隧道現在還有火車經過嗎？"},{"who":"A","text":"1984年底就停用了，北口現在變成濕地。請你數數看拱門的紅磚，順磚和丁磚是怎麼一層層交錯的！"}],"clues":["我的北口寫著「無窮」，南口寫著「宏達」","我1916年完工，1984年底被新隧道取代","我是臺東線最早開鑿的磚拱鐵道隧道，在瑞穗舞鶴"],"quiz":[{"q":"掃叭隧道北口的題字是什麼？","options":["宏達","萬年亨衢","無窮","後山保障"],"answer":2,"explain":"北口為佐久間左馬太總督所題「無窮」。"},{"q":"掃叭隧道的紅磚採用哪種砌法？","options":["荷蘭式砌法","英國式砌法","法國式砌法","人字砌法"],"answer":0,"explain":"一皮順磚、一皮丁磚的荷蘭式砌法。"}],"images":[{"file":"掃叭隧道北口.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/43/%E6%8E%83%E5%8F%AD%E9%9A%A7%E9%81%93%E5%8C%97%E5%8F%A3.JPG/960px-%E6%8E%83%E5%8F%AD%E9%9A%A7%E9%81%93%E5%8C%97%E5%8F%A3.JPG","page":"https://commons.wikimedia.org/wiki/File:%E6%8E%83%E5%8F%AD%E9%9A%A7%E9%81%93%E5%8C%97%E5%8F%A3.JPG","artist":"ckbubutp","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/ruisui-saobasuidao-0.webp","small":"img/ruisui-saobasuidao-0-s.webp"}]},{"id":"jian-qingxiuyuan","name":"吉安慶修院","short":"吉安慶修院","category":"縣定古蹟","level":"縣(市)定古蹟","town":"吉安鄉","types":["寺廟"],"lat":23.973699,"lng":121.564755,"address":"花蓮縣吉安鄉中興路345-1號","announced":"1997-04-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19970401000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-09/bc471650-a380-41be-946d-c062629fe70f/吉安慶修院.jpg","year":1917,"yearText":"1917年（大正6年）","era":"japan","themes":["日治移民村","宗教信仰","日式建築"],"yearUnknown":false,"summary":"吉野移民村留下的真言宗佈教所","intro":"吉安慶修院位於吉安鄉中興路，原為日治時期吉野移民村的真言宗吉野布教所。1908年七腳川事件後，日方驅散七腳川社並沒收土地，1910年起在此安置來自日本德島縣的移民，設立臺灣第一座官營移民村吉野村，移民拓荒艱辛，原住民族則失去傳統土地。1917年川端滿二募建布教所，供奉不動明王，庭院四周有石碑與八十八尊石佛。戰後由吳添妹接管，改名慶修院，改祀釋迦牟尼佛與觀音菩薩。建築為木構架，屋頂是日式「寶形造」並鋪金屬浪板，正面有出軒式「向拜」入口，三面迴廊附木欄杆，1997年指定為縣定古蹟。","highlights":["寶形造四角攢尖屋頂與金屬浪板屋面","正面出軒式向拜入口與三面迴廊木欄杆","庭院四周的石碑與八十八尊石佛"],"funFact":"官方資料推測，那八十八尊石佛可能是仿照空海遺規，從日本四國八十八所寺院請回來的。","photoSpot":"從正面參道拍寶形造屋頂與向拜","visitMin":45,"openNote":"位於吉安鄉中興路，官方資料記載週二至週日8:30至17:00開放，週一休館，全票30元，設籍花蓮縣民等可免費入場，以現場公告為準。距臺鐵吉安站車程約5分鐘。","dialogue":[{"who":"A","text":"阿拉蕾，一走進這裡，是不是有種到了日本寺廟的感覺？"},{"who":"R","text":"真的！屋頂尖尖的，四個角往中間收，好像一頂大斗笠。"},{"who":"A","text":"這種屋頂叫寶形造。這裡是吉安慶修院，1917年蓋的，原本是真言宗的吉野布教所。"},{"who":"R","text":"吉野？所以吉安這個地方，以前叫做吉野嗎？"},{"who":"A","text":"對。1908年七腳川事件後，日方沒收七腳川社的土地，1910年起安置德島縣移民，成立吉野村。"},{"who":"R","text":"所以移民在這裡辛苦開墾，原本住在這裡的族人卻失去了土地。"},{"who":"A","text":"沒錯，這段歷史兩面都要記得。移民生活不安，就需要信仰寄託，布教所就成了大家的心靈依靠。"},{"who":"R","text":"那戰後呢？日本人走了以後誰照顧它？"},{"who":"A","text":"由吳添妹接管，改名慶修院。你去庭院數數看，那一圈石佛是不是真的有八十八尊！"}],"clues":["我原本供奉不動明王，戰後改祀釋迦牟尼佛與觀音","我的庭院圍著一圈八十八尊石佛","我是吉野移民村留下的真言宗佈教所"],"quiz":[{"q":"慶修院的屋頂屬於哪一種日式形式？","options":["入母屋造","寶形造","切妻造","唐破風"],"answer":1,"explain":"屋頂為日本寶形造，也就是四注攢尖。"},{"q":"慶修院原本是哪個佛教宗派的布教所？","options":["真言宗","淨土宗","日蓮宗","臨濟宗"],"answer":0,"explain":"1917年川端滿二募建真言宗吉野布教所。"}],"images":[{"file":"吉安慶修院.jpg","thumb":"https://upload.wikimedia.org/wikipedia/commons/2/2b/%E5%90%89%E5%AE%89%E6%85%B6%E4%BF%AE%E9%99%A2.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%90%89%E5%AE%89%E6%85%B6%E4%BF%AE%E9%99%A2.jpg","artist":"Fcuk1203","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"}]},{"id":"yuli-dijieluqiaocanji","name":"玉里迪階陸橋殘蹟","short":"迪階陸橋殘蹟","category":"縣定古蹟","level":"縣(市)定古蹟","town":"玉里鎮","types":["橋樑"],"lat":23.440803,"lng":121.349882,"address":"花蓮縣玉里鎮玉里鎮三民里，鐵路臺東縣K70+600處，可由三民國小往立山及崙山之道路經羅梁橋到達。","announced":"2013-08-12","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20130812000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-02-18/d14d573a-3bb2-4405-b969-18a3e68989cd/j玉里-迪階陸橋07.jpg","year":1917,"yearText":"1916年動工，1917年（大正6年）完工","era":"japan","themes":["鐵道交通"],"yearUnknown":false,"summary":"臺東線第一期工程留下的紅磚橋墩","intro":"玉里迪階陸橋殘蹟位於玉里鎮三民里，在鐵路臺東線K70+600附近。1909年臺灣總督府鐵道部設花蓮港出張所，開始鋪設東部鐵道；臺東線第一期由花蓮港到璞石閣（今玉里），1910年起分六個工區施工，迪階（舊稱迪佳）陸橋屬第六工區，1916年5月開工、1917年4月完工。現存紅磚橋墩採一皮順磚、一皮丁磚的荷蘭式砌法，轉角以全磚與七五磚交替疊砌；下層基座面飾水泥砂漿，上兩層呈梯形向上砌築，整體高約7公尺，是東部鐵道少數留存的磚造構造物。","highlights":["整體高約7公尺的紅磚橋墩","全磚與七五磚交替疊砌的轉角","上兩層呈梯形向上收的砌體"],"funFact":"迪階陸橋舊稱迪佳，屬臺東線第一期工程的第六工區，從開工到完工大約花了一年。","photoSpot":"在稻田邊仰拍紅磚橋墩與天空","visitMin":15,"openNote":"官方資料記載隨時開放。位於玉里鎮三民里，可由三民國小往立山、崙山方向的道路經羅梁橋抵達，周邊為鄉間道路，建議開車前往。","dialogue":[{"who":"R","text":"Allan，田邊怎麼站著幾根紅磚柱子，是誰忘了把房子蓋完嗎？"},{"who":"A","text":"哈，這不是爛尾樓，是玉里三民的迪階陸橋殘蹟，日治時期鐵道陸橋留下的橋墩。"},{"who":"R","text":"原來火車曾經從這裡經過！是什麼時候蓋的？"},{"who":"A","text":"1916年5月開工，1917年4月完工，屬於臺東線第一期花蓮港到璞石閣的第六工區，當年可是重要工程。"},{"who":"R","text":"璞石閣就是玉里的舊名對吧？我果然是花蓮通！"},{"who":"A","text":"答對加十分！橋墩高約7公尺，用一皮順磚一皮丁磚的荷蘭式砌法，轉角還有七五磚交替。"},{"who":"R","text":"七五磚？聽起來像是打七五折的磚頭。"},{"who":"A","text":"是切成四分之三長的磚，專門用來收轉角。到現場請你找找轉角處，看長短不同的磚怎麼交錯排列！"}],"clues":["我舊稱迪佳，屬第六工區","我1917年完工，現在只剩高約7公尺的紅磚橋墩","我是玉里三民里的日治鐵道陸橋遺跡"],"quiz":[{"q":"迪階陸橋屬於臺東線第一期工程的第幾工區？","options":["第二工區","第四工區","第六工區","第八工區"],"answer":2,"explain":"拔仔庄至迪佳為第五、迪佳至璞石閣為第六工區。"},{"q":"迪階陸橋現存的紅磚橋墩高約多少？","options":["7公尺","3公尺","12公尺","20公尺"],"answer":0,"explain":"三層基座加梯形砌體，整體高約7公尺。"}],"images":[]},{"id":"jian-hengduandaolukai","name":"吉安橫斷道路開鑿記念碑","short":"橫斷道路記念碑","category":"縣定古蹟","level":"縣(市)定古蹟","town":"吉安鄉","types":["碑碣"],"lat":23.948884,"lng":121.523234,"address":"花蓮縣吉安鄉干城村，位於西寧寺（吉安鄉干城村吉安路6段839號）側面","announced":"1997-04-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19970401000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-25/f0c5bcdb-71d1-4ab1-bd26-eee50a8ae19e/d吉安-橫斷記念碑04.jpg","year":1918,"yearText":"1918年（大正7年）","era":"japan","themes":["紀念地景","墓葬碑碣"],"yearUnknown":false,"summary":"能高越嶺道東段完工的紀念碑與殉職碑","intro":"吉安橫斷道路開鑿記念碑位於吉安鄉干城村西寧寺旁，包含「橫斷道路開鑿記念碑」與「殉職者之碑」。能高越嶺路徑原是太魯閣族巴雷巴奧群往來狩獵、貿易的山徑，日治時期成為推進隘勇線的道路。1908年七腳川事件後，日方對花蓮平原原住民採高壓政策並強制遷移族人；控制穩定後，總督府1917年開闢能高橫斷道路，全長約90公里，東段約44公里，動員大量人力，地勢險峻、死傷頗多。1918年東段完工時在出口處立碑紀念。後因開闢台9丙線兩碑分隔路的兩側，西寧寺將殉職碑移到記念碑前並立，居民尊稱「殉職公」祭拜。1997年指定古蹟。","highlights":["高約160公分的變質灰長岩記念碑","立在紅色磁磚基座上、設有供桌的殉職者之碑","記念碑下高約110公分的原始石砌基座"],"funFact":"殉職者之碑在當地被居民尊稱為「殉職公」，設有供桌，至今仍有人祭拜。","photoSpot":"在鐵皮棚外拍兩碑前後並立的樣子","visitMin":15,"openNote":"位於吉安鄉干城村，台9丙線旁西寧寺側，官方資料記載隨時開放。建議開車前往，可與附近的吉安不盡跌水井一起參觀。殉職碑設有供桌，參觀時請保持莊重。","dialogue":[{"who":"R","text":"Allan，這兩塊石碑一前一後站著，前面還有供桌，是在拜什麼呢？"},{"who":"A","text":"後面那塊是橫斷道路開鑿記念碑，前面是殉職者之碑，居民稱它殉職公。"},{"who":"R","text":"橫斷道路，指的是哪一條橫越山脈的路呢？"},{"who":"A","text":"是能高越嶺道。1917年日方開闢這條橫越中央山脈的道路，東段大約44公里，1918年完工。"},{"who":"R","text":"要在山裡開一條這麼長的路，一定很危險吧？"},{"who":"A","text":"是的，地勢險峻，死傷很多，所以立了殉職碑。這條路原本也是太魯閣族巴雷巴奧群的狩獵和交易山徑。"},{"who":"R","text":"原來族人走了很久的路，後來被拿來當作推進隘勇線的道路。"},{"who":"A","text":"對，這段歷史有開發也有壓迫，要一起理解。兩塊碑原本因為修路分隔兩邊，後來才被移到一起。"},{"who":"R","text":"我們安靜地看一下，找找記念碑底下那座石砌的原始基座有多高。"}],"clues":["我和夥伴曾經被一條公路隔開，後來才又站在一起","居民為我身旁的夥伴擺上供桌，稱他為殉職公","我紀念一條橫越中央山脈的道路東段完工"],"quiz":[{"q":"吉安橫斷道路開鑿記念碑紀念的是哪條道路？","options":["八通關越嶺道","蘇花臨海道","合歡越嶺道","能高越嶺道"],"answer":3,"explain":"紀念能高橫斷道路東段在1918年完工。"},{"q":"殉職者之碑在當地被居民尊稱為什麼？","options":["石頭公","開路公","殉職公","土地公"],"answer":2,"explain":"殉職碑設有供桌，居民尊稱為殉職公。"}],"images":[{"file":"Jian Cross Trail Excavation Memorial, Jian Township, Hualien County (Taiwan).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/90/Jian_Cross_Trail_Excavation_Memorial%2C_Jian_Township%2C_Hualien_County_%28Taiwan%29.jpg/960px-Jian_Cross_Trail_Excavation_Memorial%2C_Jian_Township%2C_Hualien_County_%28Taiwan%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Jian_Cross_Trail_Excavation_Memorial,_Jian_Township,_Hualien_County_(Taiwan).jpg","artist":"Mk2010","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jian-hengduandaolukai-0.webp","small":"img/jian-hengduandaolukai-0-s.webp"}]},{"id":"guangfu-tangchangzhaodai","name":"花蓮糖廠招待所","short":"糖廠招待所","category":"縣定古蹟","level":"縣(市)定古蹟","town":"光復鄉","types":["機關"],"lat":23.653149,"lng":121.419042,"address":"花蓮縣光復鄉光復鄉大進村大進街19號","announced":"2011-10-04","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20111004000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-02-18/badfb854-ef3b-4363-89f9-6dc5600c62d3/h光復-糖場招街所04.jpg","year":1921,"yearText":"日治時期（大和工場1921年設立後）","era":"japan","themes":["糖業","日式建築"],"yearUnknown":false,"summary":"日治叫俱樂部，戰後迎來無數黨國要人","intro":"花蓮糖廠招待所位於光復鄉大進村，日治時期稱為俱樂部或「五番」，設有小型會議室、套房、棋室與會客室，是達官顯要下榻的地方。戰後蔣經國、嚴家淦、吳國楨、何應欽、白崇禧、李石曾等人都曾在此留宿，居正、李超哉兩位也在此下榻並留下墨寶贈與糖廠。約1979年新宿舍完工後，招待所逐漸改作員工宿舍與建教合作學生的住宿空間，並增建鋼筋混凝土的廚房與餐廳，使原本L型的配置成為ㄇ形格局。原有一座供住客交誼的露臺，後因拓寬馬路被拆除，花糖員工期盼未來能恢復。","highlights":["由L型擴建成ㄇ形的建築配置","日治俱樂部時期的會議室與套房格局","居正、李超哉留贈糖廠的墨寶故事"],"funFact":"日治時期招待所又被叫作「五番」，戰後則成了員工與南光中學建教合作學生的宿舍。","photoSpot":"在大進街上拍木造舊館的立面","visitMin":15,"openNote":"位於光復鄉大進村大進街，官方資料未載開放資訊，以外觀參觀為主。光復鄉在2025年9月馬太鞍溪堰塞湖溢流後仍在復原，出發前請查詢最新開放與道路狀況。","dialogue":[{"who":"R","text":"Allan，這棟木造房子以前是糖廠的招待所？招待誰啊？"},{"who":"A","text":"招待的可都是大人物。日治時期它叫俱樂部，也叫五番，是達官顯要下榻的地方。"},{"who":"R","text":"五番？聽起來像拉麵店的套餐編號！"},{"who":"A","text":"哈，那我要加蛋。戰後蔣經國、嚴家淦、白崇禧等人都曾在這裡過夜。"},{"who":"R","text":"哇，這間房子的訪客名單比我的通訊錄還厲害！"},{"who":"A","text":"後來它改當員工宿舍和建教學生宿舍，還加蓋了混凝土的廚房和餐廳，房子越長越大。"},{"who":"R","text":"那以前有沒有什麼設施現在不見了？"},{"who":"A","text":"原本有座讓住客聊天的露臺，因為拓寬馬路被拆了，老員工到現在還很懷念。"},{"who":"R","text":"我要繞房子走一圈，找找木造舊館和後來加蓋的混凝土房子交界在哪裡！"}],"clues":["日治時期我有個像編號的暱稱叫五番","蔣經國、嚴家淦、白崇禧都曾在我這裡過夜","我是光復鄉糖廠接待貴賓的地方"],"quiz":[{"q":"糖廠招待所在日治時期還被稱為什麼？","options":["五番","一番館","大和館","迎賓樓"],"answer":0,"explain":"招待所日治時期舊稱俱樂部或五番。"},{"q":"招待所增建後，平面格局從L型變成什麼形？","options":["口字形","一字形","ㄇ字形","T字形"],"answer":2,"explain":"增建RC建築後成為ㄇ形格局。"}],"images":[]},{"id":"guangfu-tangchangzhitang","name":"花蓮糖廠製糖工場","short":"花蓮糖廠製糖工場","category":"縣定古蹟","level":"縣(市)定古蹟","town":"光復鄉","types":["產業"],"lat":23.658651,"lng":121.422204,"address":"花蓮縣光復鄉大進村糖廠街18號","announced":"2011-10-04","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20111004000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-20/70a4afaa-6750-44a8-b967-cd4ca2670515/h光復-糖製糖工場46.jpg","year":1921,"yearText":"1921年（大正10年）","era":"japan","themes":["糖業","產業遺產"],"yearUnknown":false,"summary":"東部糖業的心臟，關廠後轉型觀光糖廠","intro":"花蓮的糖業最早由漢人糖廍經營，日治初期賀田組投入，後由臺東拓殖會社接手，再併入鹽水港製糖株式會社。1913年先在今壽豐鄉建壽工場，1921年又在光復鄉建大和工場，就是花蓮糖廠的前身。二戰末期兩座工場都遭轟炸，壽工場拆除，只修復大和工場。1947年5月1日成立台糖花蓮糖廠，2002年4月關廠，轉型為觀光糖廠，製糖工場是園區的核心建築，2011年公告為縣定古蹟。2025年9月馬太鞍溪堰塞湖溢流時，糖廠一帶因地勢較高受損相對輕微，曾作為救災物資與前進指揮基地。","highlights":["H型鋼骨架與鐵皮外牆的大型工場","見證東部製糖業的核心生產空間","園區內的糖廠冰品與老宿舍群"],"funFact":"花蓮糖廠有兩位前身兄弟：壽豐的壽工場與光復的大和工場，戰後只有大和工場被修復留下。","photoSpot":"在工場前拍整面鐵皮外牆與廠房","visitMin":60,"openNote":"位於光復鄉大進村糖廠街，官方資料記載觀光糖廠園區全年開放，商店街09:00至18:00，冰品08:00至20:00，七、八月延至21:00。光復鄉在2025年9月馬太鞍溪堰塞湖溢流後仍在復原，出發前請查詢最新開放與道路狀況。","dialogue":[{"who":"A","text":"到光復一定要來花蓮糖廠，而這座製糖工場就是整個糖廠的心臟。"},{"who":"R","text":"心臟？那它以前每天都在跳著做糖嗎？"},{"who":"A","text":"差不多。它的前身是1921年建的大和工場，戰後1947年成立台糖花蓮糖廠。"},{"who":"R","text":"那這座大工場現在還在轟隆隆地做糖嗎？"},{"who":"A","text":"2002年關廠了，轉型成觀光糖廠，工場功成身退，換成冰品接棒。"},{"who":"R","text":"所以Allan來這裡，其實是為了冰吧！"},{"who":"A","text":"被拆穿了。不過也要記得，2025年馬太鞍溪堰塞湖溢流時，這裡曾是救災物資和指揮基地。"},{"who":"R","text":"原來糖廠在大家最需要的時候，也默默撐起了一份力量。"},{"who":"A","text":"是的。現場請抬頭看看工場的鋼骨和鐵皮外牆，找一塊新舊補丁拍下來。"}],"clues":["戰爭末期我和壽豐的兄弟一起被轟炸，只有我被修復","2002年我停止製糖，換成冰品當主角","我是光復鄉台糖花蓮糖廠的核心工場"],"quiz":[{"q":"花蓮糖廠的前身是哪一座工場？","options":["壽工場","吉野工場","大和工場","鯉魚尾工場"],"answer":2,"explain":"1921年在光復建立的大和工場是花蓮糖廠前身。"},{"q":"花蓮糖廠在哪一年關廠並轉型觀光糖廠？","options":["2002年","1997年","1987年","2011年"],"answer":0,"explain":"花蓮糖廠2002年4月關廠，轉型為觀光糖廠。"}],"images":[{"file":"Guangfu Sugar Factory 光復糖廠 - panoramio.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d0/Guangfu_Sugar_Factory_%E5%85%89%E5%BE%A9%E7%B3%96%E5%BB%A0_-_panoramio.jpg/960px-Guangfu_Sugar_Factory_%E5%85%89%E5%BE%A9%E7%B3%96%E5%BB%A0_-_panoramio.jpg","page":"https://commons.wikimedia.org/wiki/File:Guangfu_Sugar_Factory_%E5%85%89%E5%BE%A9%E7%B3%96%E5%BB%A0_-_panoramio.jpg","artist":"lienyuan lee","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0","local":"img/guangfu-tangchangzhitang-0.webp","small":"img/guangfu-tangchangzhitang-0-s.webp"}]},{"id":"yuli-shenshecanji","name":"玉里社殘蹟","short":"玉里社殘蹟","category":"縣定古蹟","level":"縣(市)定古蹟","town":"玉里鎮","types":["寺廟"],"lat":23.334552,"lng":121.308212,"address":"花蓮縣玉里鎮神社段481-1、482-1、500-1、501地號、(玉里鎮西邊街西側丘陵海拔約150公尺處)","announced":"2008-07-23","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20080723000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-04-13/ccd74a7c-3f20-4c4d-8901-3eeaa04ebd3c/20201214_095648.jpg","year":1928,"yearText":"1928年（昭和3年）鎮座","era":"japan","themes":["神社遺構","紀念地景"],"yearUnknown":false,"summary":"保存17座石燈籠與2座鳥居的神社遺跡","intro":"玉里社殘蹟位於玉里鎮西邊街西側、海拔約150公尺的丘陵上，可俯瞰玉里市街。玉里社於1928年鎮座，祭祀天照大神與造化三神。日治時期警察隊出發攻擊附近布農族人前，以及男子受徵召出征前，都會到此祈求「武運長久」；入口的「表忠碑」則表彰為理蕃或因瘴癘犧牲的日本警察。本殿與拜殿已毀，但仍保存本殿基座、拜殿遺構、2座鳥居、表忠碑、17座石燈籠與參拜道，是花蓮縣保有文物最多的神社遺址之一。神社位於日治八通關越道上，過去還立有八通關開鑿紀念碑。","highlights":["參拜道兩旁的大型石燈籠","保存下來的2座鳥居與表忠碑","從丘陵俯瞰玉里市街的視野"],"funFact":"玉里社就在日治八通關越道旁，過去立有八通關開鑿紀念碑，可和古道串成一條歷史線。","photoSpot":"從參拜道下方仰拍鳥居與石燈籠","visitMin":30,"openNote":"官方資料記載隨時開放。位於玉里鎮西邊街西側山坡，從玉里市區前往不遠，參拜道有階梯與坡道，請注意腳步。","dialogue":[{"who":"A","text":"阿拉蕾，深呼吸，我們要爬上玉里鎮西邊的山坡，去看玉里社殘蹟。"},{"who":"R","text":"又要爬樓梯？Allan你明明說今天是美食行程！"},{"who":"A","text":"爬完再去吃玉里麵，熱量剛好抵銷。這座神社1928年鎮座，祭祀天照大神與造化三神。"},{"who":"R","text":"好吧，看在玉里麵的份上。那以前大家來這裡做什麼？"},{"who":"A","text":"日治時期警察隊出發攻擊附近布農族人前，還有男子被徵召出征前，都會來祈求武運長久。"},{"who":"R","text":"原來這裡也連著一段沉重的歷史。"},{"who":"A","text":"是的，入口的表忠碑表彰的是日本警察，對布農族來說卻是另一段記憶，兩邊都要看見。"},{"who":"R","text":"那現在山坡上的神社，還剩下哪些東西呢？"},{"who":"A","text":"本殿和拜殿已毀，但還有2座鳥居和17座石燈籠。請你沿著參拜道數一數，看看石燈籠是不是真的有17座！"}],"clues":["我的入口有一座表彰日本警察的表忠碑","我保存了2座鳥居和17座石燈籠","我是1928年鎮座、可俯瞰玉里市街的神社遺跡"],"quiz":[{"q":"玉里社在哪一年鎮座？","options":["1928年","1917年","1937年","1945年"],"answer":0,"explain":"玉里社於1928年（昭和3年）10月鎮座。"},{"q":"玉里社殘蹟保存了幾座石燈籠？","options":["7座","12座","24座","17座"],"answer":3,"explain":"現存鳥居2座、表忠碑1座與石燈籠17座。"}],"images":[{"file":"玉里社鳥居.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ee/%E7%8E%89%E9%87%8C%E7%A4%BE%E9%B3%A5%E5%B1%85.JPG/960px-%E7%8E%89%E9%87%8C%E7%A4%BE%E9%B3%A5%E5%B1%85.JPG","page":"https://commons.wikimedia.org/wiki/File:%E7%8E%89%E9%87%8C%E7%A4%BE%E9%B3%A5%E5%B1%85.JPG","artist":"Pbdragonwang","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/yuli-shenshecanji-0.webp","small":"img/yuli-shenshecanji-0-s.webp"}]},{"id":"hualian-gangshanlinshiye","name":"花蓮港山林事業所","short":"花蓮港山林事業所","category":"縣定古蹟","level":"縣(市)定古蹟","town":"花蓮市","types":["辦公廳舍"],"lat":23.980365,"lng":121.615933,"address":"花蓮縣花蓮市菁華街10 號旁","announced":"2003-03-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20030319000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-25/bb2aad94-ae0a-4136-950e-3396f188a267/c花蓮-山林事業所15.jpg","year":1929,"yearText":"1929年（昭和4年）遷至現址","era":"japan","themes":["林業聚落","公共建築"],"yearUnknown":false,"summary":"管理東部林業的和洋混合風辦公廳舍","intro":"花蓮港山林事業所位於花蓮市菁華街，是東臺灣林業史的重要見證。1919年花蓮港木材株式會社成立，採伐林田山、大安山一帶的檜木；同年官方設東部作業所，次年併入營林所東部出張所，負責造林。1929年出張所遷至現址，1942年改稱花蓮港山林事業所。戰後由花蓮縣山林管理所使用，1970年裁撤後閒置，2001年民間志工與社區居民促成重新開放。建築左右對稱，洗石子披覆鋼筋混凝土牆、木構屋架覆文化瓦，大門有仿古典的拱弧與立柱，院中植大葉欖仁與大王椰子。","highlights":["大門簡化仿古典的雙柱與弧頂裝飾","屋簷下的Y字形柱列與洗石子牆面","院落裡的大王椰子與大葉欖仁"],"funFact":"屋架背牆的通氣孔設在「敷桁」與「鼻母屋」兩支構件之間，外加木櫺，讓屋頂層也能通風。","photoSpot":"正面對稱構圖拍大門拱弧與雙柱","visitMin":30,"openNote":"位於花蓮市菁華街，官方資料記載週三至週日11:00至19:00開放，以現場公告為準。鄰近將軍府與松園別館，可步行串遊。","dialogue":[{"who":"R","text":"Allan，這棟白白的對稱建築好像小小的銀行喔！"},{"who":"A","text":"眼光不錯，它是花蓮港山林事業所，日治時期管理東部林業的辦公室，1929年搬到這裡。"},{"who":"R","text":"管林業的？那林田山那些檜木也歸它管嗎？"},{"who":"A","text":"1919年成立的花蓮港木材會社就在林田山、大安山一帶採伐檜木，這裡負責接受委託做造林。"},{"who":"R","text":"一邊砍樹一邊種樹，總算有在認真補作業。"},{"who":"A","text":"沒錯！戰後這裡是縣山林管理所，1970年裁撤後閒置，2001年靠志工和居民讓它重見天日。"},{"who":"R","text":"大家一起動手救老房子，好感動喔！"},{"who":"A","text":"院子裡種的是大王椰子和大葉欖仁，很有南洋味。請你站到正中間，拍一張左右完全對稱的大門照！"}],"clues":["我的院子裡種著大王椰子和大葉欖仁","我在1929年搬到現址，1942年改了現在的名字","我是日治時期管理東部造林與林業的花蓮港辦公廳舍"],"quiz":[{"q":"花蓮港山林事業所的建築風格屬於？","options":["閩南傳統合院","現代主義玻璃帷幕","巴洛克街屋","和洋混合風格"],"answer":3,"explain":"主體屬和洋混合風格，格局左右對稱。"},{"q":"2001年讓山林事業所重新開放的是誰？","options":["日本林業公司","鐵路局","民間志工與社區居民","國防部"],"answer":2,"explain":"民間團體號召志工與居民，讓它重見天日。"}],"images":[{"file":"花蓮港山林事業所02.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/65/%E8%8A%B1%E8%93%AE%E6%B8%AF%E5%B1%B1%E6%9E%97%E4%BA%8B%E6%A5%AD%E6%89%8002.jpg/960px-%E8%8A%B1%E8%93%AE%E6%B8%AF%E5%B1%B1%E6%9E%97%E4%BA%8B%E6%A5%AD%E6%89%8002.jpg","page":"https://commons.wikimedia.org/wiki/File:%E8%8A%B1%E8%93%AE%E6%B8%AF%E5%B1%B1%E6%9E%97%E4%BA%8B%E6%A5%AD%E6%89%8002.jpg","artist":"王綉敏","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/hualian-gangshanlinshiye-0.webp","small":"img/hualian-gangshanlinshiye-0-s.webp"}]},{"id":"hualian-gangxiaoxuexiaowei","name":"花蓮港小學校圍牆殘蹟","short":"花蓮港小學校圍牆","category":"縣定古蹟","level":"縣(市)定古蹟","town":"花蓮市","types":["學校"],"lat":23.97719,"lng":121.612075,"address":"花蓮縣花蓮市公園路40號","announced":"2013-05-13","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20130513000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-27/9e85e554-6e9f-45f7-9a2f-4ee1eb68435f/c花蓮-花蓮港小學圍牆11.jpg","year":1930,"yearText":"日治時期（圍牆逾80年，確切年份未載）","era":"japan","themes":["教育運動"],"yearUnknown":false,"summary":"花崗國中邊的石砌擋土牆，花蓮新式教育起點","intro":"花蓮港小學校圍牆殘蹟位於花蓮市公園路花崗國中，沿軒轅路一側。花崗國中前身為日治時期的「花蓮港小學校」，官方認為是花蓮地區最早的新式學校之一，代表花蓮現代教育的起點。校舍在1950年代初的颱風與地震後改建，日治建築已不復見，但軒轅路旁仍保存日治時期及戰後初期的石砌擋土牆、磚造水泥牆面圍牆，以及花蓮師範時期所建的校門。毛利之俊《東臺灣展望》一書曾記錄當年花蓮港小學校的照片。","highlights":["軒轅路旁的石砌擋土牆","磚造水泥牆面的老圍牆","花蓮師範時期所建的校門"],"funFact":"學校建築都換新了，留下來的「古蹟」反而是一道圍牆，見證80多年的校園變遷。","photoSpot":"沿軒轅路拍石砌牆面的紋理","visitMin":15,"openNote":"位於花蓮市公園路花崗國中沿軒轅路一側，官方資料記載隨時開放，可從人行道觀看圍牆，進入校園請遵守學校規定。位於花蓮舊市區，可步行串遊。","dialogue":[{"who":"A","text":"阿拉蕾，今天的古蹟主角很低調，是一道圍牆。"},{"who":"R","text":"圍牆？古蹟不是應該是大房子嗎？"},{"who":"A","text":"這裡是花崗國中，前身是日治的花蓮港小學校，算是花蓮最早的新式學校之一。"},{"who":"R","text":"那原本日治時期的教室跑去哪裡了？"},{"who":"A","text":"1950年代初颱風和地震讓校舍改建，舊建築都不見了，只剩軒轅路旁的圍牆和擋土牆。"},{"who":"R","text":"原來是圍牆守住了學校的記憶，它根本是最資深的警衛！"},{"who":"A","text":"哈，形容得真好。牆上有日治的石砌擋土牆，也有磚造水泥牆，還有花師時期的校門。"},{"who":"R","text":"不同時代一層一層疊在同一道牆上，好像千層蛋糕。"},{"who":"A","text":"到現場沿著軒轅路走，用手機拍一張石頭和磚牆交界的地方，看看兩個時代怎麼接在一起！"}],"clues":["我是一道沿著軒轅路的牆，比校舍還長壽","我身上有石砌擋土牆，也有花蓮師範時期的校門","我屬於今天的花崗國中，前身是日治的小學校"],"quiz":[{"q":"花崗國中的前身是？","options":["花蓮港公學校","花蓮港小學校","花蓮港中學校","花蓮師範學校"],"answer":1,"explain":"前身為日治時期的花蓮港小學校。"},{"q":"花崗國中的日治校舍為何改建？","options":["戰爭轟炸","道路拓寬","白蟻蛀蝕","颱風與地震侵襲"],"answer":3,"explain":"1950年代初颱風與地震侵襲後改建。"}],"images":[]},{"id":"fuli-xiangdonglicunqiu","name":"富里鄉東里村邱家古厝","short":"東里邱家古厝","category":"縣定古蹟","level":"縣(市)定古蹟","town":"富里鄉","types":["宅第"],"lat":23.267666,"lng":121.304378,"address":"花蓮縣富里鄉東里村7鄰道化路28、30、32、34、36、38號","announced":"2009-10-30","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20091030000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-29/18d06da7-8b87-4e97-8fc6-2f20d25ff78e/l富里-邱家古厝03.jpg","year":1930,"yearText":"1928年動工，1930年（昭和5年）竣工","era":"japan","themes":["宅第家族"],"yearUnknown":false,"summary":"檐廊有罕見竹節石柱的七開間古厝","intro":"富里鄉東里村邱家古厝位於東里村道化路旁，1928年動工、1930年竣工，最初是五開間「一條龍」形式的傳統民居。家族成員增加後左右加建開間，形成反三合院格局；1951年花蓮大地震使建築嚴重損毀，修復後成為今日的七開間一條龍建築，2000年碧利斯颱風後也曾整修。正身屋脊高6.16公尺，最大特色是檐廊上兩根少見的竹節石柱。古厝曾有中藥房、裁縫店等空間，展示室陳列牛車木輪、舊帳冊、藥房牌匾等家族舊物，至今仍有邱家後代居住，是縣內少見維護良好的古厝。","highlights":["檐廊上兩根少見的竹節石柱","七開間一條龍的正身格局","陳列牛車木輪與藥房牌匾的展示室"],"funFact":"依官方紀錄，古厝右前方的小伸手被當作冰室使用，經營冰店，看古蹟也能順便消暑。","photoSpot":"在前埕拍檐廊與兩根竹節石柱","visitMin":20,"openNote":"位於富里鄉東里村道化路，仍有邱家後代居住，官方資料未載開放時間，參觀內部展示空間請先洽詢屋主；可搭臺鐵花東線至東里站。","dialogue":[{"who":"A","text":"阿拉蕾，來到富里東里村，先考考你的眼力，這座古厝門前的柱子有什麼特別？"},{"who":"R","text":"一節一節的，好像竹子！可是摸起來是石頭耶。"},{"who":"A","text":"答對了，這就是少見的竹節石柱，傳統民宅很少看到，是邱家古厝最大的特色。"},{"who":"R","text":"竹子變石頭，是被施了石化魔法嗎？"},{"who":"A","text":"是工匠的魔法啦。古厝1928年動工、1930年完工，原本是五開間的一條龍。"},{"who":"R","text":"那現在怎麼會從五開間變成七開間呢？"},{"who":"A","text":"家族人口變多先加蓋，1951年花蓮大地震嚴重受損，修復後才成為現在的七開間。"},{"who":"R","text":"一棟房子跟著家族一起長大，好溫馨。"},{"who":"A","text":"官方紀錄說右前方的小伸手還開過冰店。看完古厝，請你數數竹節石柱有幾節，再去吃一碗冰！"}],"clues":["我的檐廊上有兩根少見的竹節石柱","1951年大地震後，我變成七開間一條龍","我是富里東里村道化路上的家族古厝"],"quiz":[{"q":"邱家古厝最大的建築特色是什麼？","options":["八角形窗戶","檐廊的竹節石柱","紅磚拱廊","洗石子山牆"],"answer":1,"explain":"檐廊上兩根竹節石柱在傳統民宅中十分少見。"},{"q":"邱家古厝在哪一年竣工？","options":["1930年","1951年","1928年","2005年"],"answer":0,"explain":"1928年動工、1930年竣工。"}],"images":[{"file":"富里鄉東里村邱家古厝.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d9/%E5%AF%8C%E9%87%8C%E9%84%89%E6%9D%B1%E9%87%8C%E6%9D%91%E9%82%B1%E5%AE%B6%E5%8F%A4%E5%8E%9D.JPG/960px-%E5%AF%8C%E9%87%8C%E9%84%89%E6%9D%B1%E9%87%8C%E6%9D%91%E9%82%B1%E5%AE%B6%E5%8F%A4%E5%8E%9D.JPG","page":"https://commons.wikimedia.org/wiki/File:%E5%AF%8C%E9%87%8C%E9%84%89%E6%9D%B1%E9%87%8C%E6%9D%91%E9%82%B1%E5%AE%B6%E5%8F%A4%E5%8E%9D.JPG","artist":"SSR2000","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/fuli-xiangdonglicunqiu-0.webp","small":"img/fuli-xiangdonglicunqiu-0-s.webp"}]},{"id":"jian-jiyekaicunjinian","name":"花蓮吉野開村記念碑","short":"吉野開村記念碑","category":"縣定古蹟","level":"縣(市)定古蹟","town":"吉安鄉","types":["碑碣"],"lat":23.980212,"lng":121.565419,"address":"花蓮縣吉安鄉慶豐村中山路三段473號後方","announced":"2003-07-02","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20030731000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-24/e4ebd400-5974-4164-a65a-74f6545cd2c4/d吉安-吉野開村記念碑05.jpg","year":1933,"yearText":"1933年（昭和8年）立碑","era":"japan","themes":["日治移民村","紀念地景","神社遺構"],"yearUnknown":false,"summary":"臺灣第一座官營移民村的開村紀念碑","intro":"花蓮吉野開村記念碑位於吉安鄉慶豐村中山路三段後方，見證臺灣第一座官營移民村吉野村。1910年日方在荳蘭社一帶設移民指導所，移民多來自德島縣吉野川沿岸，因此取名「吉野」；移民設村的土地，則來自1908年七腳川事件後被沒收的部落土地。1912年颱風幾乎摧毀村落，移民重建後到大正末年約有330戶、1700多人，道路、水圳、學校、郵局一應俱全。1933年立起高逾3公尺的「拓地開村」石碑，由臺灣總督中川健藏題字。另有1912年所立的吉野神社鎮座紀念碑，神社本身已成廢墟。2003年指定為縣定古蹟。","highlights":["總督中川健藏題字的「拓地開村」碑","以日式自然石堆疊而成的碑座","1912年所立的吉野神社鎮座紀念碑"],"funFact":"吉野這個地名，是因為移民多來自日本德島縣吉野川沿岸；戰後1948年才改稱吉安。","photoSpot":"在大樹下仰拍高逾3公尺的開村石碑","visitMin":20,"openNote":"位於吉安鄉慶豐村中山路三段後方，周邊為綠地，官方資料記載隨時開放，可與好客藝術村、慶修院一帶串遊。距臺鐵吉安站車程約5分鐘。","dialogue":[{"who":"R","text":"Allan，這塊大石頭比你還高，上面寫著拓地開村，是誰寫的？"},{"who":"A","text":"是1933年臺灣總督中川健藏題的字，紀念吉野村開村，石碑超過3公尺高。"},{"who":"R","text":"吉野村跟其他村子比起來，有什麼特別的？"},{"who":"A","text":"它是臺灣第一座官營移民村，1910年開始，移民多來自日本德島縣的吉野川沿岸。"},{"who":"R","text":"所以才叫吉野！那村子是蓋在空地上嗎？"},{"who":"A","text":"不是空地。那是1908年七腳川事件後，阿美族七腳川社被沒收的土地，這一點不能忘記。"},{"who":"R","text":"移民辛苦開墾，族人卻失去家園，兩邊的故事都要知道。"},{"who":"A","text":"對。移民也吃了很多苦，1912年颱風幾乎把村子夷平，後來重建到三百多戶，才有今天的街道格局。"},{"who":"R","text":"那大家繞到石碑後面，看看碑座是不是用一顆顆自然石疊起來的！"}],"clues":["我旁邊還有一塊神社鎮座的紀念碑","我身上有臺灣總督題的四個字","我紀念臺灣第一座官營移民村的誕生"],"quiz":[{"q":"吉野村的名稱來自哪裡？","options":["奈良的吉野山","德島縣的吉野川","第一任村長姓吉野","吉祥田野的寓意"],"answer":1,"explain":"移民多住在德島縣吉野川沿岸，因此取名吉野。"},{"q":"「拓地開村」四個字是誰題的？","options":["中川健藏","北白川宮能久親王","佐久間左馬太","賀田金三郎"],"answer":0,"explain":"1933年由臺灣總督中川健藏題字。"}],"images":[]},{"id":"guangfu-tangchangchang","name":"花蓮糖廠廠長宿舍","short":"糖廠廠長宿舍","category":"縣定古蹟","level":"縣(市)定古蹟","town":"光復鄉","types":["宅第"],"lat":23.655817,"lng":121.420434,"address":"花蓮縣光復鄉大進村糖廠街6巷5號","announced":"2011-10-04","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20111004000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-02-18/d088120e-44b5-4301-adcc-845ed52ead6f/h光復-廠長宿舍04.jpg","year":1934,"yearText":"1934年（昭和9年）","era":"japan","themes":["糖業","職務宿舍","日式建築"],"yearUnknown":false,"summary":"糖廠宿舍群的頭號人物，附水池日式庭園","intro":"花蓮糖廠廠長宿舍位於光復鄉大進村糖廠東南側，1934年興建，是糖廠宿舍建築群中最重要的一幢，2011年公告為縣定古蹟。它與副廠長宿舍同在一區，旁邊就是日治時期的大和尋常高等小學校，也就是今天的大進國小。獨棟木造建築坐東朝西，瓦屋頂、簷廊、雨戶袋與斜撐木齊備，前後有寬闊庭院與高大樹木，左側還有水池造景的日式庭園。獨立寬廣的空間反映當時糖廠階級分明，主管擁有較多資源與較好的生活品質，也讓人得以一窺工廠的經營管理方式。室內經住戶修繕，但結構多保有原構造邏輯。","highlights":["左側水池造景的日式庭園","簷廊、雨戶袋與斜撐木等木造細節","與大進國小相鄰的主管宿舍區位"],"funFact":"廠長宿舍旁邊就是日治時期的大和尋常高等小學校，今天的大進國小，主管家的孩子上學走路就到。","photoSpot":"隔著庭院拍木造宿舍與水池","visitMin":15,"openNote":"位於光復鄉大進村糖廠街，官方資料未載開放資訊，請在外觀欣賞並尊重使用者。光復鄉在2025年9月馬太鞍溪堰塞湖溢流後仍在復原，出發前請查詢最新開放與道路狀況。","dialogue":[{"who":"A","text":"阿拉蕾，在糖廠宿舍區裡，你覺得哪一棟的院子最大？"},{"who":"R","text":"我猜是這棟有水池的！住在這裡的人是不是很大咖？"},{"who":"A","text":"猜對了，這是花蓮糖廠廠長宿舍，1934年興建，是整個宿舍群最重要的一棟。"},{"who":"R","text":"廠長家還有日式水池，那池子裡是不是養了很多錦鯉？"},{"who":"A","text":"官方資料只說有水池造景，沒說養什麼，我們不能亂講，雖然我也很想看魚。"},{"who":"R","text":"好吧，不亂猜。那為什麼廠長的房子院子特別大、特別氣派？"},{"who":"A","text":"當年糖廠階級分明，主管擁有比較多資源，從房子大小就看得出來。"},{"who":"R","text":"原來房子的大小，就是當年職位的名片！"},{"who":"A","text":"說得好。到現場請找找屋簷下收雨戶的木箱，那叫雨戶袋，拍下來吧！"}],"clues":["我的鄰居是日治時期的大和尋常高等小學校","我有水池造景的日式庭園，是宿舍群裡最重要的一棟","我是光復鄉糖廠最高主管的家"],"quiz":[{"q":"花蓮糖廠廠長宿舍興建於哪一年？","options":["1921年","1934年","1949年","1952年"],"answer":1,"explain":"廠長宿舍創建於1934年，同年竣工。"},{"q":"廠長宿舍旁的日治小學校，今天是哪所學校？","options":["太巴塱國小","大榮國小","豐裡國小","大進國小"],"answer":3,"explain":"大和尋常高等小學校即今大進國小。"}],"images":[{"file":"Factory Manager's Quarters (1949), Hualien Sugar Factory, Guangfu Township, Hualien County (Taiwan).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/ba/Factory_Manager%27s_Quarters_%281949%29%2C_Hualien_Sugar_Factory%2C_Guangfu_Township%2C_Hualien_County_%28Taiwan%29.jpg/960px-Factory_Manager%27s_Quarters_%281949%29%2C_Hualien_Sugar_Factory%2C_Guangfu_Township%2C_Hualien_County_%28Taiwan%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Factory_Manager%27s_Quarters_(1949),_Hualien_Sugar_Factory,_Guangfu_Township,_Hualien_County_(Taiwan).jpg","artist":"Mk2010","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/guangfu-tangchangchang-0.webp","small":"img/guangfu-tangchangchang-0-s.webp"}]},{"id":"hualian-ganggaoerfuqiujule","name":"花蓮港高爾夫球俱樂部","short":"高爾夫俱樂部","category":"縣定古蹟","level":"縣(市)定古蹟","town":"花蓮市","types":["其他設施"],"lat":23.999365,"lng":121.625931,"address":"花蓮縣花蓮市位於化道路北側，今花蓮高爾夫球場入口左側","announced":"2019-12-02","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20200318000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-27/d185f972-7e18-4e7d-89b7-e2093febb76a/c花蓮-高爾夫球樂部0105.jpg","year":1935,"yearText":"1935年（昭和10年）會館落成","era":"japan","themes":["教育運動","日式建築"],"yearUnknown":false,"summary":"東臺灣第一座球場留下的表現主義會館","intro":"花蓮港高爾夫球俱樂部位於花蓮市化道路北側、今花蓮高爾夫球場入口左側。花蓮港高爾夫球場是臺灣東部第一處高爾夫球場，依官方資料於1928年9月23日完竣，俱樂部會館於1935年10月落成，是經歷日治後期與戰後兩個時代留存的球場建築，反映1930年代東臺灣體育運動與美崙市街的發展。會館以鋼筋混凝土為牆身，西式木桁架支撐圓弧形屋頂，立面有圓弧窗與圓拱突出的大門，具表現主義的摩登造型。中央原有圓頂，風災後以鐵皮覆蓋。2019年指定為縣定古蹟。","highlights":["圓拱突出的大門與圓弧形窗戶","鋼筋混凝土牆身配木桁架圓弧屋頂","曾有圓頂的屋頂中央位置"],"funFact":"會館戰後一度淪為倉庫堆放肥料與工具，2019年還差點因欠稅被拍賣，後來才指定為古蹟。","photoSpot":"正面拍圓拱大門與弧形窗","visitMin":15,"openNote":"位於花蓮市化道路北側、花蓮高爾夫球場入口左側。官方資料記載修復工程進行中，未載開放時間，請以外觀參觀為主並勿進入球道，出發前請查詢最新開放狀況。","dialogue":[{"who":"A","text":"阿拉蕾，你會打高爾夫嗎？今天帶你看東臺灣第一座球場的老會館。"},{"who":"R","text":"我只會打電動版的！這棟房子怎麼長得圓圓的，好可愛。"},{"who":"A","text":"它是1935年落成的俱樂部會館，有圓拱大門和圓弧窗，屬於當時很前衛的表現主義造型。"},{"who":"R","text":"原來日治時期花蓮就這麼時髦！那球場是什麼時候開的？"},{"who":"A","text":"依官方資料，球場1928年完竣，是東部第一座，也是臺灣歷史第二悠久的高爾夫球場。"},{"who":"R","text":"第二名耶！那屋頂中間為什麼看起來平平的？"},{"who":"A","text":"原本有個圓頂，風災後被鐵皮蓋住了。戰後它還當過倉庫，2019年差點被拍賣，後來才成為古蹟。"},{"who":"R","text":"好險，差一點就被一桿進洞送走了！"},{"who":"A","text":"笑點滿分。到現場別闖球道，從入口旁看看，找出那扇圓拱大門，猜猜原本的圓頂有多大！"}],"clues":["我的大門是圓拱突出的造型，屋頂中央原本有圓頂","我曾被當成倉庫，2019年差點因欠稅被拍賣","我是東臺灣第一座高爾夫球場的俱樂部會館"],"quiz":[{"q":"花蓮港高爾夫球俱樂部會館的造型特色屬於？","options":["閩南燕尾式","表現主義摩登風格","中國北方宮殿式","日式書院造"],"answer":1,"explain":"具現代主義之表現主義造型特徵。"},{"q":"會館屋頂中央原本的圓頂後來怎麼了？","options":["改成玻璃天窗","加蓋成二樓","拆下送博物館","風災後以鐵皮蓋住"],"answer":3,"explain":"經風災後以鐵皮覆蓋。"}],"images":[]},{"id":"hualian-jianchazhangsushe","name":"檢察長宿舍","short":"檢察長宿舍","category":"縣定古蹟","level":"縣(市)定古蹟","town":"花蓮市","types":["官邸"],"lat":23.979909,"lng":121.6089,"address":"花蓮縣花蓮市三民街23號","announced":"2008-07-23","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20080723000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-27/9b6bcac2-a2c5-4d66-ae85-a1ba50b5f7b7/c花蓮-檢查長宿舍05.jpg","year":1936,"yearText":"約1936年（昭和11年）前後","era":"japan","themes":["職務宿舍","日式建築"],"yearUnknown":false,"summary":"花蓮法院支部時代的高等官和式官舍","intro":"檢察長宿舍位於花蓮市三民街。1935年起籌設臺北地方法院花蓮港支部，1936年3月廳舍落成，花蓮港支部自宜蘭支部獨立，管轄花蓮港廳與臺東廳。戰後房舍撥給首席檢察官作官舍，1980年審檢分隸後由地檢署管理，1986年首席檢察官改稱檢察長，宿舍隨之改名。約1993年新官舍落成後閒置，2008年指定為縣定古蹟。屬第二種高等官舍，以玄關為界，左側是洋式辦公室與書齋兼應接室，右側為座敷、居間、茶間、台所、風呂等居住空間，入口門廊裝飾獨特。","highlights":["裝飾獨特的入口門廊","玄關左洋右和的空間配置","座敷、居間外三尺寬的緣側走廊"],"funFact":"這棟官舍跟著職稱改了好幾次名，1986年「首席檢察官」改稱「檢察長」，它才變成檢察長宿舍。","photoSpot":"正面拍入口門廊的裝飾","visitMin":40,"openNote":"位於花蓮市三民街，官方資料記載營業時間12:00至21:00，每週四公休，以現場公告為準。距花蓮舊市區景點不遠，可步行串遊。","dialogue":[{"who":"A","text":"阿拉蕾，今天帶你去檢察長家作客，不用緊張，主人已經搬走很久了。"},{"who":"R","text":"嚇我一跳，我還以為今天要被傳喚問案！"},{"who":"A","text":"這棟是日治時期法院花蓮港支部時代的高等官舍，戰後給首席檢察官住，1986年改稱檢察長宿舍。"},{"who":"R","text":"它的裡面跟一般的日式房子一樣嗎？"},{"who":"A","text":"有點不同。以玄關為界，左邊是洋式辦公室和書齋，右邊才是座敷、茶間、廚房和浴室。"},{"who":"R","text":"左邊上班、右邊下班，通勤時間只要三步，好羨慕！"},{"who":"A","text":"哈，所以官員很難說自己塞車遲到。座敷外面還有三尺寬的緣側，可以坐著看庭園。"},{"who":"R","text":"那我要坐在緣側，吃花蓮麻糬配熱茶！"},{"who":"A","text":"好主意！到了現場，先別急著吃，抬頭看看入口門廊，找出它最特別的裝飾在哪裡。"}],"clues":["我的玄關左邊是洋式辦公室，右邊是和式起居空間","1980年審檢分隸後，我改由地檢署管理","我在花蓮市三民街，名字跟一位檢察首長有關"],"quiz":[{"q":"檢察長宿舍玄關左側是什麼空間？","options":["浴室與廚房","洋式辦公室與書齋","神龕與佛堂","傭人房"],"answer":1,"explain":"以玄關為界，左側為洋式辦公室與書齋兼應接室。"},{"q":"「首席檢察官」改稱「檢察長」是在哪一年？","options":["1946年","1966年","1980年","1986年"],"answer":3,"explain":"1986年首席檢察官改稱檢察長，宿舍跟著改名。"}],"images":[{"file":"Former Residence of the Chief Prosecutor, Hualien City, (Taiwan).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9a/Former_Residence_of_the_Chief_Prosecutor%2C_Hualien_City%2C_%28Taiwan%29.jpg/960px-Former_Residence_of_the_Chief_Prosecutor%2C_Hualien_City%2C_%28Taiwan%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Former_Residence_of_the_Chief_Prosecutor,_Hualien_City,_(Taiwan).jpg","artist":"Mk2010","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/hualian-jianchazhangsushe-0.webp","small":"img/hualian-jianchazhangsushe-0-s.webp"}]},{"id":"hualian-meilunxipanrishisu","name":"美崙溪畔日式宿舍","short":"將軍府本屋","category":"縣定古蹟","level":"縣(市)定古蹟","town":"花蓮市","types":["官邸"],"lat":23.980455,"lng":121.613144,"address":"花蓮縣花蓮市民勤段1426地號","announced":"2005-02-23","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20050223000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2026-06-12/9780addf-b3ea-4d88-b1a0-a3939229e26b/1781247093742_0.jpg","year":1936,"yearText":"1936年（昭和11年）","era":"japan","themes":["日式建築","職務宿舍","眷村與戰後移民"],"yearUnknown":false,"summary":"美崙溪畔軍官社區中心，相傳中村大佐寓所","intro":"美崙溪畔日式宿舍（縣定古蹟）位於花蓮市中正路622巷一帶，俗稱「將軍府」本屋。1936年以檜木等高級木料建成，是高級軍官居住的小型社區中心，相傳為日軍花蓮指揮官中村大佐的寓所。本屋獨棟獨院，敷地約300坪、建坪約54坪，基座也比周邊宿舍高，屬高等官第二種官舍，顯示其在社區中地位最高；周邊618巷、622巷則是雙併式宿舍。戰後成為國軍眷舍，2005年經居民與學者連署指定為縣定古蹟。屋簷下設通風口，牆內中空夾層可讓熱空氣上升排出。","highlights":["獨棟獨院、基座最高的高等官舍本屋","正立面仿稻草泥土混合的立體質感處理","屋簷下的通風口與牆內對流夾層"],"funFact":"附近居民原本不知道中村大佐是誰，只聽說住了一位官階很高的「大將軍」，將軍府之名由此而來。","photoSpot":"在庭院外拍本屋高基座與屋簷","visitMin":40,"openNote":"位於花蓮市中正路622巷一帶的將軍府園區。官方資料記載曾進行修復工程，目前開放時間與參觀方式請出發前查詢。與松園別館、花蓮港山林事業所相近，可步行串遊。","dialogue":[{"who":"A","text":"阿拉蕾，歡迎來到將軍府！不過我先爆個料，這裡其實沒有將軍。"},{"who":"R","text":"什麼？那這個名字不就是誇大不實嗎？"},{"who":"A","text":"別急，1936年這裡住的是相傳的日軍花蓮指揮官中村大佐，鄰居不清楚他的身分，只知道官很大，就叫他將軍。"},{"who":"R","text":"原來是鄰居幫忙升官！那這棟本屋跟旁邊的房子有什麼不一樣？"},{"who":"A","text":"本屋獨棟獨院，地有300坪左右，基座也墊得最高，等級最高。旁邊巷子裡的則是兩戶相連的雙併宿舍。"},{"who":"R","text":"連地基都比別人高一截，果然是社區的老大！"},{"who":"A","text":"戰後這裡變成國軍眷舍。2001年中村大佐的後代還回來尋根，寫信感謝住戶把房子照顧得很好。"},{"who":"R","text":"好溫暖的故事，房子把兩代人連在一起了。"},{"who":"A","text":"沒錯。請你蹲低一點，看看本屋基座和屋簷下，找出讓房子呼吸的通風口！"}],"clues":["我獨棟獨院，基座比周圍的房子都高","相傳我是一位日軍大佐的寓所，鄰居以為他是大將軍","我是美崙溪畔軍官社區的中心建築，俗稱將軍府"],"quiz":[{"q":"「將軍府」這個稱呼是怎麼來的？","options":["日本天皇親自命名","鄰居以為住了大將軍","戰後國軍上將入住","因為門口有將軍雕像"],"answer":1,"explain":"居民不知中村大佐身分，只知官階很高，便稱將軍府。"},{"q":"將軍府本屋屬於哪一種官舍？","options":["判任官乙種官舍","判任官甲種官舍","高等官第二種官舍","奏任官第四種官舍"],"answer":2,"explain":"敷地約300坪，屬高等官第二種官舍。"}],"images":[{"file":"花蓮民生社區將軍府建築群.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/03/%E8%8A%B1%E8%93%AE%E6%B0%91%E7%94%9F%E7%A4%BE%E5%8D%80%E5%B0%87%E8%BB%8D%E5%BA%9C%E5%BB%BA%E7%AF%89%E7%BE%A4.jpg/960px-%E8%8A%B1%E8%93%AE%E6%B0%91%E7%94%9F%E7%A4%BE%E5%8D%80%E5%B0%87%E8%BB%8D%E5%BA%9C%E5%BB%BA%E7%AF%89%E7%BE%A4.jpg","page":"https://commons.wikimedia.org/wiki/File:%E8%8A%B1%E8%93%AE%E6%B0%91%E7%94%9F%E7%A4%BE%E5%8D%80%E5%B0%87%E8%BB%8D%E5%BA%9C%E5%BB%BA%E7%AF%89%E7%BE%A4.jpg","artist":"☼ うみ 目覚めたら from Taipei, Taiwan","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","local":"img/hualian-meilunxipanrishisu-0.webp","small":"img/hualian-meilunxipanrishisu-0-s.webp"}]},{"id":"hualian-jiujianyuyiji","name":"花蓮舊監獄遺蹟","short":"花蓮舊監獄遺蹟","category":"縣定古蹟","level":"縣(市)定古蹟","town":"花蓮市","types":["其他設施"],"lat":23.984692,"lng":121.60365,"address":"花蓮縣花蓮市花蓮市中山路與明智路交接口處、國安郵局旁","announced":"2012-02-04","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20120204000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-25/7db3d642-b7b4-40c2-a67c-9e62986f0d71/c花蓮-舊監獄04.jpg","year":1937,"yearText":"1937年（昭和12年）完工","era":"japan","themes":["公共建築","紀念地景"],"yearUnknown":false,"summary":"自由廣場裡的監獄圍牆與兩座瞭望台","intro":"花蓮舊監獄遺蹟位於花蓮市中山路與明智街口，今「自由廣場」。日治時期花蓮居民須到宜蘭受審，交通不便，總督府於1935年興建「臺北刑務所花蓮港支所」，1937年完工。戰後1946年改為臺灣第一監獄第二分監，1947年改稱臺灣花蓮港監獄，1958年改為臺灣花蓮監獄。監獄遷出後主要建物拆除，1982年開放為城垣園，後因颱風受損關閉，2013年活化為自由廣場。今僅存ㄈ字形高矮圍牆與方形、圓形兩座瞭望哨站，圍牆高386公分，是人權與地方發展的重要物證。","highlights":["高386公分的ㄈ字形監獄圍牆","北側方塔哨與西側圓塔哨兩座瞭望台","園區30公尺長、融入原住民族風格的編織牆"],"funFact":"北側方塔哨原本只有兩層，後來才在上面加蓋第三層磚造的圓形空間。","photoSpot":"從廣場內拍圓形哨塔與老圍牆","visitMin":20,"openNote":"位於花蓮市中山路與明智街口，今自由廣場，官方資料記載隨時開放。位於市中心，可由花蓮舊市區步行前往。","dialogue":[{"who":"R","text":"Allan，這裡叫自由廣場，可是旁邊的高牆和塔樓怎麼看都不太自由耶。"},{"who":"A","text":"觀察入微！這裡原本是1937年完工的臺北刑務所花蓮港支所，也就是花蓮的監獄。"},{"who":"R","text":"為什麼花蓮當時要自己蓋一座監獄？"},{"who":"A","text":"因為以前花蓮的人要到宜蘭才能受審，交通太不方便，所以總督府決定在花蓮設刑務所。"},{"who":"R","text":"原來是怕大家坐車坐到暈。那現在還剩什麼？"},{"who":"A","text":"主要建物拆了，只剩三面相連的高矮圍牆和兩座瞭望台，一座方形、一座圓形，圍牆高386公分。"},{"who":"R","text":"比籃球框還要高，想翻牆出去是不可能了。"},{"who":"A","text":"所以這裡也是記錄人權教訓的地方，現在則變成大家散步的公園。請你找出圓形和方形兩座哨塔，比比看哪一座比較高！"}],"clues":["我只剩一道ㄈ字形的高牆和兩座瞭望台","我在1937年完工，讓花蓮人不必再遠赴宜蘭受審","我今天變成花蓮市中山路口的一座廣場"],"quiz":[{"q":"花蓮舊監獄的兩座瞭望台形狀是？","options":["一方一圓","兩座都是圓形","兩座都是八角形","一座三角一座方"],"answer":0,"explain":"北側方塔哨與西側圓塔哨。"},{"q":"花蓮舊監獄遺址今天成為什麼場所？","options":["鐵道文化園區","原住民族博物館","國軍營區","自由廣場"],"answer":3,"explain":"2013年活化後命名為自由廣場。"}],"images":[{"file":"Old prison ,Hualien , Taiwan1.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/65/Old_prison_%2CHualien_%2C_Taiwan1.jpg/960px-Old_prison_%2CHualien_%2C_Taiwan1.jpg","page":"https://commons.wikimedia.org/wiki/File:Old_prison_,Hualien_,_Taiwan1.jpg","artist":"王綉敏","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/hualian-jiujianyuyiji-0.webp","small":"img/hualian-jiujianyuyiji-0-s.webp"}]},{"id":"hualian-taifeizhaodaisuo","name":"花蓮台肥招待所","short":"台肥招待所","category":"縣定古蹟","level":"縣(市)定古蹟","town":"花蓮市","types":["機關"],"lat":23.989192,"lng":121.624371,"address":"花蓮縣花蓮市中美路160號","announced":"2004-03-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20080723000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-01-07/f45faf32-6052-4f4f-91a2-5a1cf439a865/花蓮台肥招待所.jpg","year":1938,"yearText":"約1937～1938年（昭和12～13年）","era":"japan","themes":["日式建築","產業遺產"],"yearUnknown":false,"summary":"日本鋁會社為長官出差而建的大型日式招待所","intro":"花蓮台肥招待所位於花蓮市中美路的美崙地區。台肥花蓮廠前身是日本鋁株式會社花蓮港工場，約1938年擴廠時，為接待總公司長官與工程人員，在米崙規劃了兩處旅館般的招待會所，目前僅存這一處，約建於1937至1938年，另一處已毀於火災。戰後由台肥接收供高階主管居住，2008年國有眷舍清理時，台肥其他宿舍拆除拍賣，只有招待所保留下來。建築混用切妻、寄棟與入母屋屋頂，外牆為雨淋板；右側屋宇已改為水泥牆，左側保留較多原貌，是格局完整的大型日式木造住屋。","highlights":["切妻、寄棟、入母屋三種屋頂組合","新舊並置：左側保留原貌、右側已改水泥牆","寬闊完整的庭院與建築格局"],"funFact":"台肥花蓮廠的前身不是做肥料，而是日本鋁株式會社的花蓮港工場。","photoSpot":"從庭院拍左側保留原貌的木造立面","visitMin":20,"openNote":"位於花蓮市中美路，官方資料記載仍作為台肥員工宿舍與差旅住宿使用，未載開放時間，請以外觀參觀為主，出發前請查詢最新開放狀況。","dialogue":[{"who":"R","text":"Allan，這間日式大房子是旅館嗎？看起來好高級！"},{"who":"A","text":"很接近喔，它是招待所，專門給從總公司出差來花蓮的長官和工程人員住的，像公司自己的旅館。"},{"who":"R","text":"招待誰的長官？是台肥公司的嗎？"},{"who":"A","text":"日治時期這裡是日本鋁株式會社花蓮港工場，台肥是戰後才接手的。"},{"who":"R","text":"從做鋁變成做肥料，這間工廠也太會轉行了吧！難怪招待所也跟著換主人。"},{"who":"A","text":"時代變了嘛。當年有兩處招待所，另一處被火燒掉了，2008年台肥其他宿舍又拆除，只剩它。"},{"who":"R","text":"所以它是唯一的倖存者，真的好珍貴！"},{"who":"A","text":"對，而且一次集合了切妻、寄棟和入母屋三種屋頂。它現在還是員工宿舍，請你在外面找找看，三種屋頂各在哪裡！"}],"clues":["我是為接待總公司長官與工程師而建的會所","我的工廠主人前身是一家日本鋁會社","我在花蓮市中美路，戰後由肥料公司接管"],"quiz":[{"q":"台肥花蓮廠的前身是什麼工廠？","options":["日本鋁株式會社工場","鹽水港製糖工場","花蓮港木材會社","臺灣電力會社"],"answer":0,"explain":"前身為日本鋁株式會社花蓮港工場。"},{"q":"2008年國有眷舍清理時，台肥招待所的命運是？","options":["被拍賣給私人","被保存下來","改建成大樓","遷移到他處"],"answer":1,"explain":"其他宿舍拆除拍賣，僅招待所被保存。"}],"images":[]},{"id":"shoufeng-wuquanchengkaituo","name":"吳全城開拓記念碑","short":"吳全城記念碑","category":"縣定古蹟","level":"縣(市)定古蹟","town":"壽豐鄉","types":["碑碣"],"lat":23.888911,"lng":121.552409,"address":"花蓮縣壽豐鄉壽豐鄉平和村吳全公墓旁","announced":"2012-10-30","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20121030000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-04-06/cb4b2ee2-1b5f-493b-a7df-89b202b75bf4/e壽豐-吳全城記念碑03.jpg","year":1940,"yearText":"1940年（昭和15年）","era":"japan","themes":["糖業","紀念地景","墓葬碑碣"],"yearUnknown":false,"summary":"從清代石堡到製糖會社的拓墾記憶","intro":"吳全城開拓記念碑位於壽豐鄉平和村吳全公墓旁。1825年淡水富豪吳全、蔡伯玉從噶瑪蘭帶領約200名漢人到此開墾，為防木瓜社族人襲擊而築石堡，稱為「吳全城」，但因水土不服與衝突，吳全病逝後佃農紛紛北歸。1899年日本企業賀田組進入，以客家人為佃農，種植甘蔗並設黑糖廍，事業後來由臺東拓殖會社、鹽水港製糖會社接手。1940年鹽水港製糖會社在辦公室前立碑，紀念吳全與賀田金三郎的開發，並慰藉罹疫或遇害的殉職者。碑文立場反映當時殖民者的視角。石堡、地洞與深井今已消失，2012年指定為縣定古蹟。","highlights":["以大石亂砌、高約127公分的碑座","紀念吳全與賀田金三郎開發的碑文","碑旁吳全公墓一帶的平和村聚落"],"funFact":"吳全城原有一口深約四十丈的井，因為太危險，1999年被填平，現在已不見蹤跡。","photoSpot":"從側面拍大石亂砌的碑座與碑身","visitMin":15,"openNote":"位於壽豐鄉平和村吳全公墓旁，官方資料記載隨時開放。鄰近公墓，參觀時請保持莊重。建議開車走台9線前往，可與壽豐、豐田一帶景點串遊。","dialogue":[{"who":"R","text":"Allan，這塊碑旁邊就是公墓，氣氛有點安靜。吳全是誰啊？"},{"who":"A","text":"吳全是清代淡水的富豪。1825年他和蔡伯玉從噶瑪蘭帶了大約200人到這裡開墾。"},{"who":"R","text":"為什麼叫吳全城？這裡有城牆嗎？"},{"who":"A","text":"他們為了防備當地木瓜社族人的襲擊，蓋了石堡，大家就叫它吳全城。"},{"who":"R","text":"那他們後來在這裡開墾成功了嗎？"},{"who":"A","text":"很可惜，大家水土不服，又和族人衝突，吳全病逝後佃農就陸續回北部了。"},{"who":"R","text":"那眼前這塊紀念碑，又是誰立的呢？"},{"who":"A","text":"是1940年鹽水港製糖會社立的，紀念吳全和賀田金三郎。碑文是當時殖民者的角度，看的時候要多想一層。"},{"who":"R","text":"了解！大家去看看碑座，數數看那些大石頭有幾顆比你的頭還大！"}],"clues":["清代有人在這裡築石堡防守，最後卻還是北歸","一家製糖會社在1940年為我刻下紀念文字","我在壽豐平和村，名字來自一位淡水富豪"],"quiz":[{"q":"吳全城這個名字的由來是什麼？","options":["清廷設置的縣城","吳全等人築的防禦石堡","日本人建的糖廠","原住民的部落名"],"answer":1,"explain":"吳全率眾築石堡防禦，後人稱為吳全城。"},{"q":"吳全城開拓記念碑是由誰設立的？","options":["鹽水港製糖會社","賀田組","臺東拓殖會社","花蓮港廳"],"answer":0,"explain":"1940年由鹽水港製糖株式會社建立。"}],"images":[{"file":"Wuquan City Founding Memorial Stele (Taiwan).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/Wuquan_City_Founding_Memorial_Stele_%28Taiwan%29.jpg/960px-Wuquan_City_Founding_Memorial_Stele_%28Taiwan%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Wuquan_City_Founding_Memorial_Stele_(Taiwan).jpg","artist":"Mk2010","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/shoufeng-wuquanchengkaituo-0.webp","small":"img/shoufeng-wuquanchengkaituo-0-s.webp"}]},{"id":"hualian-xucongminguju","name":"許聰敏故居","short":"許聰敏故居","category":"縣定古蹟","level":"縣(市)定古蹟","town":"花蓮市","types":["宅第"],"lat":23.975604,"lng":121.611534,"address":"花蓮縣花蓮市花蓮市復興街4-1號、６號","announced":"2019-12-03","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20200318000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-01-12/156e9e0a-8822-475f-959f-afeadea39b86/許聰敏故居.jpg","year":1943,"yearText":"約1941～1945年（昭和16～20年）","era":"japan","themes":["日式建築","宗教信仰"],"yearUnknown":false,"summary":"花蓮實業家的街角洋樓，藏有防空通道","intro":"許聰敏故居位於花蓮市復興街與軒轅路口，日治時為春日通與朝日通交會的繁華街廓。許聰敏是經歷日治與戰後的花蓮文人與實業家，在商業與佛教界影響深遠，兼營銀行、米倉與木材行，也是1960年籌建秀林普明寺的人。故居約建於1941至1945年，復興街6號為兩層昭和型街屋，騎樓圓柱以小口馬賽克與洗石子作柱身，雨庇形成水平線條，後方有太平洋戰爭時期的防空通道；東側4-1號應為戰後初期所建。二樓曾為佛堂，1960年代證嚴法師曾暫住。後來曾作卡拉OK店，2019年指定為縣定古蹟。","highlights":["騎樓兩根馬賽克與洗石子圓柱","雨庇拉出的水平線條立面","後方太平洋戰爭時期的防空通道"],"funFact":"這棟實業家宅第後來曾開過「一往情深」卡拉OK店，2019年又因法拍易手，同年成為古蹟。","photoSpot":"站在對角路口拍街角兩棟立面","visitMin":10,"openNote":"位於花蓮市復興街與軒轅路口，官方資料記載目前閒置、未對外開放，請以外觀參觀為主。位於花蓮舊市區，可與花崗國中圍牆一起步行串遊。","dialogue":[{"who":"A","text":"阿拉蕾，還記得秀林的普明寺嗎？蓋它的人，家就在這個街角。"},{"who":"R","text":"是許聰敏先生！他家看起來好氣派。"},{"who":"A","text":"他經營銀行、米倉、木材行，這裡日治時期是春日通和朝日通交會，超熱鬧的商業區。"},{"who":"R","text":"那這棟街角的老房子有什麼看頭？"},{"who":"A","text":"騎樓有兩根圓柱，用小小的馬賽克和洗石子做柱身，後面還有太平洋戰爭時期的防空通道。"},{"who":"R","text":"家裡居然有地道，聽起來好像諜報電影的場景！"},{"who":"A","text":"二樓以前是佛堂，證嚴法師1960年代也曾暫住。後來還變成唱歌的店，2019年成為古蹟。"},{"who":"R","text":"從佛堂到唱歌的店，這棟房子的人生也太精采了！"},{"who":"A","text":"可惜它目前沒有開放。請你在路口仔細看騎樓圓柱，找出柱頭和柱身的分界線！"}],"clues":["我後方藏著一條太平洋戰爭時期的防空通道","我二樓曾是佛堂，一位法師1960年代曾在這裡暫住","我是籌建普明寺那位花蓮實業家的街角宅第"],"quiz":[{"q":"許聰敏故居復興街6號後方保存了什麼特殊設施？","options":["防空通道","地下酒窖","古井","神社遺構"],"answer":0,"explain":"後方有見證太平洋戰爭時期的防空通道。"},{"q":"許聰敏故居騎樓圓柱的柱身用了哪些材料？","options":["檜木與銅片","紅磚與石灰","小口馬賽克與洗石子","大理石與琉璃"],"answer":2,"explain":"以小口馬賽克及洗石子作為柱身與柱頭材料。"}],"images":[{"file":"許聰敏故居.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ac/%E8%A8%B1%E8%81%B0%E6%95%8F%E6%95%85%E5%B1%85.jpg/960px-%E8%A8%B1%E8%81%B0%E6%95%8F%E6%95%85%E5%B1%85.jpg","page":"https://commons.wikimedia.org/wiki/File:%E8%A8%B1%E8%81%B0%E6%95%8F%E6%95%85%E5%B1%85.jpg","artist":"弟魯","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/hualian-xucongminguju-0.webp","small":"img/hualian-xucongminguju-0-s.webp"}]},{"id":"ruisui-fuyuanbaoangong","name":"富源保安宮","short":"富源保安宮","category":"歷史建築","level":"","town":"瑞穗鄉","types":["寺廟"],"lat":23.576315,"lng":121.375888,"address":"花蓮縣瑞穗鄉瑞穗鄉富民村中正路一段239號","announced":"2012-10-18","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20121018000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-30/26fc6668-ebd2-420b-8965-79dcbe954f81/i瑞穗-富源保安宮09.jpg","year":1889,"yearText":"1889年（清光緒15年）","era":"qing","themes":["宗教信仰","清代開山"],"yearUnknown":false,"summary":"花蓮地區最早的城隍廟，守護拔仔庄","intro":"富源保安宮位於瑞穗鄉富民村，俗稱城隍廟，主祀霞海城隍，官方資料指出它是花蓮地區最早的城隍廟。1888年清廷設臺東直隸州，原擬以水尾（今瑞穗）為州治，因大庄事件水尾遭焚而作罷；隔年謝芳榮建茅屋奉祀城隍，取名保安宮。1929年改建為石造小廟，日治後期皇民化運動時，村民將城隍金身移往復興山腳下暫避，戰後才迎回。1950年重建，1972年改建為今日的鋼筋混凝土仿木構廟宇，仍保有1934年所獻的龍虎堵。廟址位在當年漢人庄與阿美族部落的交界，見證清末開山撫番與族群互動。","highlights":["1934年信眾所獻、保留至今的龍虎堵","嵌入廟名與村名的楷書楹聯","廟內磚刻的福德正神"],"funFact":"每年農曆5月12日晚上有「暗訪」夜巡，隔天繞境時一定經過當年藏金身的復興山腳下。","photoSpot":"從中正路牌樓下拍廟門與正殿","visitMin":20,"openNote":"官方資料記載隨時開放參觀。位於瑞穗鄉富源，臺鐵花東線富源站在附近；農曆5月12日暗訪、13日繞境期間人潮多，日期以廟方公告為準。","dialogue":[{"who":"R","text":"Allan，大家都叫這間廟城隍廟，城隍爺不是都住在大城市嗎？"},{"who":"A","text":"好問題！富源保安宮可是花蓮地區最早的城隍廟，主祀霞海城隍，跟臺北大稻埕同一個來源。"},{"who":"R","text":"那城隍爺是怎麼一路來到瑞穗的？"},{"who":"A","text":"1888年清廷設臺東直隸州，本來想把州治設在水尾，也就是今天的瑞穗，後來因大庄事件沒設成。"},{"who":"R","text":"差一點瑞穗就變成州政府所在地了！"},{"who":"A","text":"對啊，隔年謝芳榮先生蓋了一間茅屋奉祀城隍，就是保安宮的起點。日治後期村民還把金身藏到山腳下大樹旁。"},{"who":"R","text":"村民真的好用心守護信仰。那現在還看得到這段故事嗎？"},{"who":"A","text":"看得到，每年農曆5月12日晚上暗訪、13日繞境，路線必經當年藏金身的山腳下，表示不忘舊恩。"},{"who":"R","text":"我要進廟找昭和9年留下的龍虎堵，看看龍和虎哪一隻表情比較兇！"}],"clues":["皇民化運動時，村民把我的主神藏到山腳下大樹旁","我每年農曆5月12日晚上會舉行暗訪","我是花蓮地區最早的城隍廟，在瑞穗富源"],"quiz":[{"q":"富源保安宮主祀哪一位神明？","options":["關聖帝君","福德正神","五穀先帝","霞海城隍"],"answer":3,"explain":"保安宮主祀霞海城隍，俗稱城隍廟。"},{"q":"清廷原本想把臺東直隸州州治設在哪裡？","options":["璞石閣","卑南","花蓮港","水尾"],"answer":3,"explain":"原擬設於水尾（今瑞穗），因大庄事件作罷。"}],"images":[{"file":"2025 FuYuan Bao-an Temple a5.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bc/2025_FuYuan_Bao-an_Temple_a5.jpg/960px-2025_FuYuan_Bao-an_Temple_a5.jpg","page":"https://commons.wikimedia.org/wiki/File:2025_FuYuan_Bao-an_Temple_a5.jpg","artist":"Taiwankengo","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/ruisui-fuyuanbaoangong-0.webp","small":"img/ruisui-fuyuanbaoangong-0-s.webp"}]},{"id":"jian-bujindieshuijing","name":"吉安不盡跌水井","short":"不盡跌水井","category":"歷史建築","level":"","town":"吉安鄉","types":["其他設施"],"lat":23.949572,"lng":121.52374,"address":"花蓮縣吉安鄉吉安鄉山下路上，靠近台9丙公路。","announced":"2016-09-06","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20160906000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-22/0d17719a-cbb7-4e21-94c3-26181f97658d/d吉安-不盡跌水井13.jpg","year":1913,"yearText":"日治時期吉野圳設施（確切年代不詳）","era":"japan","themes":["水利設施","日治移民村"],"yearUnknown":false,"summary":"水流高速墜落消能的百年水圳節點","intro":"吉安不盡跌水井位於吉安鄉干城村山下路旁，靠近台9丙線，是吉野圳（今吉安圳）的重要節點。吉野圳1911年開始調查開鑿，引木瓜溪水灌溉吉野移民村，1916年加開草分支線，1932年與1941年又兩度擴建，戰後1948年隨地名改稱吉安圳，並引入初英發電廠尾水，灌溉面積擴大為2500多公頃。這口跌水井直徑約4.7公尺、深約8公尺，因為這裡沒有斜坡或水躍可以減速，水流以高速射流跌入下方靜水池，靠亂流擴散來消除能量，是水利工程的關鍵設施，2016年登錄為歷史建築。","highlights":["直徑約4.7公尺、深約8公尺的跌水井","高速射流落入靜水池的消能設計","入口旁拓印自出水口的「不盡」石碑"],"funFact":"入口旁的「不盡」石碑，字樣拓印自出水口，寓意水源源源不絕。","photoSpot":"在井邊護欄往下拍水流翻騰的白浪","visitMin":20,"openNote":"位於吉安鄉干城村山下路旁、近台9丙線，官方資料記載隨時開放，入口有水利生態步道與小型停車場。可與附近的橫斷道路開鑿記念碑及吉安圳自行車道一起安排，建議開車前往。","dialogue":[{"who":"R","text":"Allan，這口井好吵喔，水嘩啦啦地往下衝，是在洗衣服嗎？"},{"who":"A","text":"這可不是普通的井，它是吉安不盡跌水井，吉野圳上很重要的水利設施。"},{"who":"R","text":"跌水？水也會像我一樣走路跌倒喔？"},{"who":"A","text":"差不多！這裡沒有斜坡可以讓水慢慢減速，所以讓水直接高速跌進下面的靜水池。"},{"who":"R","text":"那不就像溜滑梯直接變成跳水嗎？"},{"who":"A","text":"形容得好！水跌下去產生亂流，能量就消掉了，下游渠道才不會被沖壞。"},{"who":"R","text":"那這條吉野圳，是什麼時候開始挖的呢？"},{"who":"A","text":"1911年開始調查開鑿，引木瓜溪水灌溉移民村，戰後改叫吉安圳，到現在還在灌溉兩千多公頃田地。"},{"who":"R","text":"那大家到入口找找那塊不盡石碑，再猜猜看這口井到底有多深！"}],"clues":["我這裡沒有斜坡，水只好高速一躍而下","我直徑約4.7公尺，下方有一座靜水池消能","我在吉安干城的山下路旁，名字寓意水流源源不絕"],"quiz":[{"q":"不盡跌水井的主要功能是什麼？","options":["抽取地下水","讓水流跌落消能","儲存飲用水","推動水車發電"],"answer":1,"explain":"水流高速跌入靜水池，以亂流擴散消能。"},{"q":"吉野圳在戰後改名為什麼？","options":["吉安圳","初英圳","木瓜圳","干城圳"],"answer":0,"explain":"1948年吉野改為吉安，吉野圳也改為吉安圳。"}],"images":[]},{"id":"shoufeng-jiufengtianyimin","name":"舊豐田移民村警察官吏派出所(壽豐鄉文史館)","short":"豐田派出所","category":"歷史建築","level":"","town":"壽豐鄉","types":["衙署"],"lat":23.841097,"lng":121.507966,"address":"花蓮縣壽豐鄉豐裡村中山路320號","announced":"2009-08-13","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20090813000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-01-07/7df510bc-85dd-4162-90ae-233d3ddb2264/舊豐田移民村警察官吏派出所(壽豐文史館).jpg","year":1913,"yearText":"1913年（大正2年）","era":"japan","themes":["日治移民村","公共建築"],"yearUnknown":false,"summary":"移民村的警察廳舍，今為壽豐鄉文史館","intro":"舊豐田移民村警察官吏派出所位於壽豐鄉豐裡村中山路與和平街口，對面就是豐裡國小。1913年設立的豐田警察官吏派出所，負責管理日本官營移民村豐田村的警政事務。日治時期移民村以「指導所」為核心，配置學校、宗教、醫療、農業設施、警察與住宿等生活機能，派出所就是其中一環。1999年由文建會補助整修，成為今天的「壽豐鄉文史館」，用來推廣鄉土教育、接待遊客與供居民休憩。建築平面呈T形，外圍有ㄇ字形迴廊，屋頂為寄棟與切妻組合，牆面仍保留竹片、泥層與石灰的原始結構。登錄理由坦言建築經修建後與原貌差異甚大，但原址仍具紀念價值。","highlights":["保留竹片、泥層與石灰的原始牆體","T形平面與外圍ㄇ字形迴廊","大型窗框配小方塊玻璃的窗戶"],"funFact":"登錄理由很誠實：這棟建築修建後和原貌差異很大，但地點和原建築仍有紀念價值。","photoSpot":"在中山路與和平街口拍迴廊與屋頂","visitMin":30,"openNote":"位於壽豐鄉豐裡村中山路與和平街口，現為壽豐鄉文史館，官方資料記載週一、週五休館，其餘時間8:00至17:30開放，出發前請再確認。臺鐵豐田站附近，可與豐裡國小劍道館、移民墓園步行串遊。","dialogue":[{"who":"R","text":"Allan，這間有迴廊的房子好可愛，以前是什麼地方？"},{"who":"A","text":"說出來你可能會立正站好，這裡是1913年設立的豐田警察官吏派出所。"},{"who":"R","text":"派出所！那它當年負責管的是什麼範圍？"},{"who":"A","text":"管的是日本官營移民村豐田村的警政事務。那時移民村有學校、醫療、宗教設施，警察也是其中一環。"},{"who":"R","text":"那現在這裡還有警察叔叔在值班嗎？"},{"who":"A","text":"沒有了，1999年整修後變成壽豐鄉文史館，有展示也有閱覽室，連飲料都有。"},{"who":"R","text":"從派出所變成可以喝飲料的地方，這轉變也太大了！"},{"who":"A","text":"所以我現在進來都不緊張了。不過牆裡面還藏著竹片、泥層加石灰的老結構，是真正的老骨頭。"},{"who":"R","text":"大家進去參觀時，找找看哪裡能看到牆裡的竹片結構，拍下來給Allan看！"}],"clues":["我以前讓人一進門就緊張，現在卻提供飲料","我的牆裡藏著竹片、泥層和石灰","我曾管理豐田移民村的治安，現在是鄉裡的文史館"],"quiz":[{"q":"舊豐田移民村派出所現在作什麼用途？","options":["豐裡國小教室","壽豐鄉文史館","警察局分駐所","農會倉庫"],"answer":1,"explain":"1999年整修後成為壽豐鄉文史館。"},{"q":"豐田警察官吏派出所設立於哪一年？","options":["1913年","1899年","1910年","1933年"],"answer":0,"explain":"派出所設立於1913年，即大正2年。"}],"images":[]},{"id":"shoufeng-nongchangzhaodai","name":"花蓮農場招待所","short":"花蓮農場招待所","category":"歷史建築","level":"","town":"壽豐鄉","types":["官邸"],"lat":23.871707,"lng":121.515037,"address":"花蓮縣壽豐鄉共和村大同路2號","announced":"2004-03-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20040319000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-04-10/d3ef2646-fae1-43b4-a709-16c0d669fc48/e壽豐-花蓮農場招待所01.jpg","year":1913,"yearText":"日治時期（壽工場1913年設立）","era":"japan","themes":["糖業","職務宿舍","日式建築"],"yearUnknown":false,"summary":"製糖所所長公館，戰後成為花蓮農場招待所","intro":"花蓮農場招待所位於壽豐鄉共和村，原是鹽水港製糖株式會社花蓮港製糖所的所長公館。日治時期該會社在東部開墾農場、發展糖業，1913年於鯉魚尾荖溪南岸設立壽工場。戰後為安置移居東部的外省族群，1952年成立「花蓮大同合作農場」，後撥交退輔會，即今花蓮農場的由來，2013年併入臺東農場成為花蓮分場。建物為木造瓦房，面積約258.6平方公尺，有雨淋板外牆、編竹灰泥牆與多種屋頂形式；中央庭院以疊石、白卵石、石龜與石燈籠構成。2011年依原樣修復後，作為招待所住宿與展示館使用。","highlights":["切妻、入母屋、寄棟三種屋頂形式交錯","基礎的木百葉通氣口與洗石子線腳","以石龜、石燈籠點綴的中央日式庭院"],"funFact":"地板抬高約2尺半到3尺，牆下開小方窗通風，也方便貓狗進出，官方說明還拿龍貓裡的灰塵精靈來比喻。","photoSpot":"從庭院石燈籠旁斜拍屋頂層次","visitMin":30,"openNote":"位於壽豐鄉共和村，官方資料記載由花蓮農場自營作為招待所住宿與展示館，參觀或住宿請先洽詢。近臺鐵壽豐站，建議開車前往。","dialogue":[{"who":"A","text":"壽豐鄉共和村這棟木造瓦房，日治時期可是製糖所所長的公館，等級很高喔。"},{"who":"R","text":"所長住的房子？那他每天早餐是不是直接配一碗糖水啊？"},{"who":"A","text":"糖水不一定，但壽工場1913年就在附近設立，所長住這裡上班很方便。"},{"who":"R","text":"那為什麼現在叫花蓮農場招待所？跟農場有什麼關係？"},{"who":"A","text":"戰後1952年成立大同合作農場，安置移居東部的外省族群，房子就由農場接手。"},{"who":"R","text":"一棟房子換了兩種主人，經歷很豐富耶！"},{"who":"A","text":"它的屋頂也很豐富，切妻、入母屋、寄棟三種一起出現，像屋頂界的拼盤。"},{"who":"R","text":"Allan你是不是又餓了？什麼都講成吃的！"},{"who":"A","text":"被你發現了。到了現場，請蹲低一點，找找牆腳下那排讓貓狗鑽的小方窗！"}],"clues":["官方說明用龍貓裡的灰塵精靈，來形容我牆腳下的小洞","日治時是製糖所所長公館，戰後由安置外省族群的農場接手","我在壽豐鄉共和村，現在可以住宿也能看展示"],"quiz":[{"q":"這棟建築在日治時期原本是誰的住所？","options":["鐵道部站長","移民村村長","製糖所所長","郵便局局長"],"answer":2,"explain":"原為鹽水港製糖株式會社花蓮港製糖所所長公館。"},{"q":"戰後接手這棟建築的農場最初名稱是？","options":["花蓮大同合作農場","鯉魚尾開墾農場","壽豐甘蔗農場","共和退輔農場"],"answer":0,"explain":"1952年成立花蓮大同合作農場，後撥交退輔會。"}],"images":[]},{"id":"shoufeng-fengtiancunyimin","name":"豐田村移民指導所事務室","short":"豐田移民指導所","category":"歷史建築","level":"","town":"壽豐鄉","types":["辦公廳舍"],"lat":23.84144,"lng":121.5088,"address":"花蓮縣壽豐鄉壽豐鄉豐裡村文化街(壽豐鄉豐裡國小東側)","announced":"2013-01-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20130131000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-04-10/c63c2cfd-5b1e-4e5c-acf5-efaec5c527a6/e壽豐-移民指導所01.jpg","year":1913,"yearText":"日治時期（豐田村1913年建村）","era":"japan","themes":["日治移民村","公共建築"],"yearUnknown":false,"summary":"豐田移民村的行政中樞，管土地也管衛生","intro":"日治時期總督府自1909年至1917年在花蓮港廳陸續建立吉野、豐田、林田三個官營移民村。豐田村位於壽豐鄉知亞干溪出山口北側，舊名鯉魚尾，1913年建村，分為大平、中里、森本、山下四個聚落。移民指導所是村裡的行政中樞，除一般行政，還負責土地分配、農耕、婦女女紅、兵役與衛生。官營移民一面是日本移民在異鄉辛苦開墾，一面也伴隨總督府對東部土地的重新安排。戰後這裡曾作為國語民教班與豐裡國小輔導教室，如今是社區深度旅遊導覽的起點。相較其他移民村，豐田仍保留較多原村落格局。","highlights":["移民村行政中樞的日式事務室建築","戰後國語民教班與輔導教室的使用痕跡","以此為起點走訪豐田移民村棋盤街道"],"funFact":"豐田舊名「鯉魚尾」，因水田多、土地肥沃而得名，日治時期則分成大平、中里、森本、山下四個聚落。","photoSpot":"在文化街上拍事務室正面與老樹","visitMin":20,"openNote":"位於壽豐鄉豐裡國小東側文化街，作為社區導覽起點與空間租借使用，官方未公告固定開放時間，出發前請查詢。近臺鐵豐田站。","dialogue":[{"who":"R","text":"Allan，這間小小的辦公室看起來很普通，為什麼會是歷史建築？"},{"who":"A","text":"別小看它，這是豐田移民村的移民指導所，整個村的大小事都從這裡發號施令。"},{"who":"R","text":"大小事？Allan，到底有多大、又有多小呢？"},{"who":"A","text":"大到土地分配、農耕、兵役，小到衛生和婦女女紅，全部一手包辦。"},{"who":"R","text":"哇，這根本是日治版的萬能里長辦公室嘛！"},{"who":"A","text":"形容得很好。豐田村1913年建村，移民辛苦開墾，同時也牽動了東部土地的重新安排。"},{"who":"R","text":"那日本移民離開以後，戰後這裡拿來做什麼用？"},{"who":"A","text":"當過國語民教班，也當過豐裡國小輔導教室，現在是社區導覽的起點。"},{"who":"R","text":"身兼多職的建築！我要去找找它旁邊的國小，看看兩者靠得多近！"}],"clues":["戰後我當過國語民教班，也當過國小的輔導教室","日治時期負責分配土地、指導農耕與管理衛生","我是壽豐鄉鯉魚尾移民村的行政中樞"],"quiz":[{"q":"豐田村的舊地名是什麼？","options":["荖溪口","七腳川","鯉魚潭","鯉魚尾"],"answer":3,"explain":"因水田多、土地肥沃而得名鯉魚尾。"},{"q":"下列哪一項不是移民指導所負責的業務？","options":["土地分配","鐵路售票","衛生管理","農耕指導"],"answer":1,"explain":"指導所負責土地、農耕、女紅、兵役、衛生等。"}],"images":[{"file":"Former Fengtian Village immigration office, Shoufeng Township, Hualien County (Taiwan).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/14/Former_Fengtian_Village_immigration_office%2C_Shoufeng_Township%2C_Hualien_County_%28Taiwan%29.jpg/960px-Former_Fengtian_Village_immigration_office%2C_Shoufeng_Township%2C_Hualien_County_%28Taiwan%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Former_Fengtian_Village_immigration_office,_Shoufeng_Township,_Hualien_County_(Taiwan).jpg","artist":"Mk2010","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/shoufeng-fengtiancunyimin-0.webp","small":"img/shoufeng-fengtiancunyimin-0-s.webp"}]},{"id":"fenglin-lintianzhenhongxi","name":"林田圳虹吸式圳道","short":"林田圳虹吸圳道","category":"歷史建築","level":"","town":"鳳林鎮","types":["其他設施"],"lat":23.76345,"lng":121.4667,"address":"花蓮縣鳳林鎮鳳林鎮北林段172、1247、1298-4地號","announced":"2016-12-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20161221000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-04-14/16769d11-fb47-4a5d-95a1-f7a6f8b88b3c/20210115_140531.jpg","year":1914,"yearText":"1914年（大正3年）移民村設立後興設","era":"japan","themes":["水利設施","日治移民村"],"yearUnknown":false,"summary":"讓圳水從溪底鑽過去的虹吸工法","intro":"林田圳是日治時期官營移民村「林田村」（含南岡、中野、北林三聚落）的命脈。1914年移民村設立後，為了農耕興設灌溉系統，從鳳林山南麓接萬里溪處引水。早年渠道都是土溝，後來改為混凝土造，最初只有一、二支線，1960年代增設三支線。其中二支線最特別：圳水抵達鳳林溪畔後，以虹吸工法從堤防下方、溪床底下穿過，再引入北林地區。這項跨越障礙的工法是稻作成功的關鍵設施，具水利技術史的保存價值。","highlights":["二支線從鳳林溪床底下穿越的虹吸段","由土溝演進為混凝土造的圳道","灌溉林田村北林地區的水利命脈"],"funFact":"虹吸工法利用水壓差讓水先下後上，像用吸管喝飲料，水能從溪底鑽過再冒出來。","photoSpot":"在鳳林溪畔拍圳道進出堤防處","visitMin":15,"openNote":"位於鳳林鎮北林里鳳林溪畔，官方資料記載隨時開放。為灌溉設施，請勿下水或攀爬，雨天注意安全。建議開車前往。","dialogue":[{"who":"A","text":"阿拉蕾，考考你，水圳遇到一條溪擋路，除了架橋，還有什麼辦法？"},{"who":"R","text":"嗯，請水圳學游泳？還是叫它繞遠路？"},{"who":"A","text":"都不是。林田圳二支線直接從鳳林溪的溪床底下鑽過去，這叫虹吸工法。"},{"who":"R","text":"水會自己往上爬？這不是違反物理嗎？"},{"who":"A","text":"不違反，靠的是兩端水位差，就像你用吸管喝珍奶，珍珠都會乖乖爬上來。"},{"who":"R","text":"原來如此！那這條會鑽溪底的水圳，當初是為誰挖的？"},{"who":"A","text":"1914年林田移民村設立後興設，是南岡、中野、北林三個聚落種稻的命脈。"},{"who":"R","text":"所以鳳林香噴噴的米飯，有一部分要感謝這根超大吸管囉！"},{"who":"A","text":"沒錯。到了溪畔，請找找圳水鑽進堤防和冒出來的兩個地方，拍下來比對！"}],"clues":["我讓水先往下鑽、再往上冒出來","我從鳳林溪的堤防和溪床底下穿過去","我是林田移民村灌溉水圳二支線的特殊段落"],"quiz":[{"q":"林田圳二支線用什麼工法穿越鳳林溪？","options":["架高渡槽","虹吸工法","抽水馬達","人工挑水"],"answer":1,"explain":"二支線以虹吸工法穿越堤防與溪床底下。"},{"q":"林田圳的三支線是什麼時候增設的？","options":["1914年","1930年代","1990年代","1960年代"],"answer":3,"explain":"最初只有一、二支線，1960年代再增設三支線。"}],"images":[]},{"id":"fenglin-lintianjingchaguan","name":"林田警察官吏派出所及舊林田派出所","short":"林田派出所","category":"歷史建築","level":"","town":"鳳林鎮","types":["辦公廳舍"],"lat":23.752546,"lng":121.467728,"address":"花蓮縣鳳林鎮鳳林鎮大榮里復興路71號","announced":"2015-11-26","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20151126000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-04-11/2f76ba0d-76ed-447f-8273-521d701a963f/g鳳林-林田派出所03.jpg","year":1914,"yearText":"日治時期（林田村1914年設立）","era":"japan","themes":["日治移民村","公共建築"],"yearUnknown":false,"summary":"日治與戰後兩代派出所比鄰而立","intro":"林田移民村於1914年設立，規劃為南岡、中野、北林三區，中野是指導機關所在地，集中事務所、倉庫、醫療所、布教所、學校與警察官吏派出所，反映住宅與機關分區的配置。林田警察官吏派出所是寄棟與切妻屋頂的日式木結構建築；戰後在旁邊另建鋼筋混凝土的新式廳舍，即舊林田派出所（大榮派出所），日治建築則轉作宿舍。兩個不同時代的警察廳舍並存相鄰，官方稱為少數孤例，見證警察建築樣式的演變。現已再利用為警務展示館，有互動牆面、歷史照片、文檔櫃與警察制服等展示。","highlights":["日式木構與戰後混凝土兩代派出所並肩","展示館裡的老警察制服與文檔櫃","互動牆面體驗當年派出所格局"],"funFact":"兩代派出所緊鄰並存在全臺很少見，官方直接稱它是「少數之孤例」。","photoSpot":"在復興路上把新舊兩棟廳舍同框","visitMin":25,"openNote":"位於鳳林鎮大榮里復興路，現為警務展示館。官方資料標示全天開放，但室內展示開放時間請出發前查詢。可與林田神社、大榮國小宿舍一起步行串遊。","dialogue":[{"who":"R","text":"Allan，為什麼這裡有兩間派出所靠在一起？是怕小偷太多嗎？"},{"who":"A","text":"哈，不是治安太差。這兩間是不同時代的派出所，一間日治，一間戰後。"},{"who":"R","text":"那它們要怎麼分辨？兩間長得很像嗎？"},{"who":"A","text":"日治的林田警察官吏派出所是日式木造，戰後那間是鋼筋混凝土，一眼就分得出來。"},{"who":"R","text":"好像兩代警察在交接班，學長和學弟站一起拍照！"},{"who":"A","text":"說得好。林田移民村1914年設立，分成南岡、中野、北林三區，派出所就蓋在機關集中的中野區。"},{"who":"R","text":"那現在裡面還有警察在值班、做筆錄嗎？"},{"who":"A","text":"現在變成警務展示館，有歷史照片、老制服，還能體驗當年的派出所格局。"},{"who":"R","text":"我要去找那套老警察制服，看看帽子跟現在差在哪裡！"}],"clues":["我和學弟相鄰而立，官方說這是少數孤例","我是日式木構的警察廳舍，戰後轉作宿舍，現在是展示館","我在鳳林移民村機關集中的中野區守護治安"],"quiz":[{"q":"林田移民村的指導機關集中在哪一區？","options":["南岡","森坂","北林","中野"],"answer":3,"explain":"中野是指導機關設置地，派出所也在此。"},{"q":"戰後新建的舊林田派出所是什麼結構？","options":["日式木造","鋼筋混凝土","竹編泥牆","紅磚拱圈"],"answer":1,"explain":"舊林田派出所為RC，也就是鋼筋混凝土結構。"}],"images":[{"file":"林田警察官吏派出所及舊林田派出所.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7b/%E6%9E%97%E7%94%B0%E8%AD%A6%E5%AF%9F%E5%AE%98%E5%90%8F%E6%B4%BE%E5%87%BA%E6%89%80%E5%8F%8A%E8%88%8A%E6%9E%97%E7%94%B0%E6%B4%BE%E5%87%BA%E6%89%80.jpg/960px-%E6%9E%97%E7%94%B0%E8%AD%A6%E5%AF%9F%E5%AE%98%E5%90%8F%E6%B4%BE%E5%87%BA%E6%89%80%E5%8F%8A%E8%88%8A%E6%9E%97%E7%94%B0%E6%B4%BE%E5%87%BA%E6%89%80.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%9E%97%E7%94%B0%E8%AD%A6%E5%AF%9F%E5%AE%98%E5%90%8F%E6%B4%BE%E5%87%BA%E6%89%80%E5%8F%8A%E8%88%8A%E6%9E%97%E7%94%B0%E6%B4%BE%E5%87%BA%E6%89%80.jpg","artist":"Pbdragonwang","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/fenglin-lintianjingchaguan-0.webp","small":"img/fenglin-lintianjingchaguan-0-s.webp"}]},{"id":"shoufeng-fengtianshenshecan","name":"豐田神社參道與遺構(碧蓮寺之周邊設施)","short":"豐田神社遺構","category":"歷史建築","level":"","town":"壽豐鄉","types":["其他設施"],"lat":23.838939,"lng":121.501547,"address":"花蓮縣壽豐鄉豐裡村民權街與中山路交叉口及民權街與豐正路(壽豐鄉民權街1號)","announced":"2009-08-13","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20090813000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-04-10/f4f97e96-3c74-4206-9542-017c0afbb50f/e壽豐-碧連寺10.jpg","year":1915,"yearText":"1915年（大正4年）鎮座","era":"japan","themes":["神社遺構","日治移民村","宗教信仰"],"yearUnknown":false,"summary":"鳥居與狛犬還在，神社已化身碧蓮寺","intro":"豐田神社是日治時期豐田移民村的信仰中心，1915年舉行鎮座式。豐田村被視為移民村的模範村，市街規劃成棋盤式，神社、派出所、醫療所、小學校多集中於此。戰後神社改奉佛教神佛，成為今天壽豐鄉豐裡村的碧蓮寺，原神社建築後毀於颱風。目前登錄的遺構包括鳥居、石燈籠、狛犬與參道，另有開村三十週年紀念碑與水井一併登錄。從中山路可見第一鳥居，沿參道往內約570公尺可見第二鳥居與石燈籠，狛犬則移到寺前兩側。據維基百科，豐田神社坐南朝北，與多數臺灣神社的方位不同。","highlights":["中山路口改作山門的第一鳥居","參道深處的第二鳥居與石燈籠","移到碧蓮寺前兩側的一對狛犬"],"funFact":"神社例祭原定6月5日，因正逢農忙又炎熱，1922年改到10月25日，可見移民村生活跟著農事走。","photoSpot":"站在參道中央拍第二鳥居與石燈籠","visitMin":30,"openNote":"位於壽豐鄉豐裡村民權街與中山路口，官方資料記載每日06:00至20:00開放。現為寺廟，參觀請保持安靜。近臺鐵豐田站。","dialogue":[{"who":"A","text":"阿拉蕾，從中山路走進這座鳥居，你覺得我們現在是要去神社，還是去寺廟？"},{"who":"R","text":"看到鳥居應該是神社吧？可是前面怎麼寫著碧蓮寺？"},{"who":"A","text":"答對一半。這裡原是1915年鎮座的豐田神社，戰後改奉佛教神佛，成了碧蓮寺。"},{"who":"R","text":"所以是日式外殼包著台式內餡，像一顆混血湯圓！"},{"who":"A","text":"這比喻我給滿分。神社本體已不在，但鳥居、石燈籠、狛犬和參道都留下來了。"},{"who":"R","text":"那這條參道有多長？我穿拖鞋走得完嗎？"},{"who":"A","text":"從第一鳥居往內約570公尺才到第二鳥居，剛好散步消化一個炸彈蔥油餅。"},{"who":"R","text":"又是吃的！那守護神社的狛犬跑去哪裡了？"},{"who":"A","text":"牠們搬到寺前兩側站崗了。請你去比比看，兩隻狛犬的嘴巴是不是一開一合！"}],"clues":["我的例祭日曾因農忙而從6月改到10月","我的鳥居還在，但主殿已改供佛教神佛","我是壽豐鄉移民村的神社，如今成了碧蓮寺"],"quiz":[{"q":"豐田神社在戰後變成了什麼？","options":["忠烈祠","碧蓮寺","國民小學","鄉公所"],"answer":1,"explain":"戰後改奉佛教神佛，成為今天的碧蓮寺。"},{"q":"從第一鳥居沿參道到第二鳥居大約多遠？","options":["約57公尺","約1.5公里","約5.7公里","約570公尺"],"answer":3,"explain":"官方說明參道向內約570公尺可見第二鳥居。"}],"images":[]},{"id":"fenglin-lintianshenshecan","name":"林田神社殘蹟","short":"林田神社殘蹟","category":"歷史建築","level":"","town":"鳳林鎮","types":["其他設施"],"lat":23.748773,"lng":121.465952,"address":"花蓮縣鳳林鎮鳳林鎮鳳信段845地號(鳳林鎮大榮里復興路39號旁)","announced":"2016-09-06","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20160906000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-04-11/f69a2b60-2071-473b-b1f6-8ca54422002f/g鳳林-林田神社殘蹟11.jpg","year":1915,"yearText":"1915年（大正4年）鎮座","era":"japan","themes":["神社遺構","日治移民村"],"yearUnknown":false,"summary":"玉垣上還刻著當年奉納者的名字","intro":"林田神社位於鳳林鎮大榮里，是林田移民村最重要的信仰中心。1914年移民代表向總督府提出神社建立申請，隔年動工並於6月6日舉行鎮座儀式。1944至1945年盟軍空襲花蓮時，社務所毀於火災。戰後神社一度改為「鳳林區忠烈祠」，祭祀黃花崗七十二烈士；1974年內政部要求清除日本神社遺跡，林田神社也在此時遭到破壞。目前拜殿與本殿基壇尚完整，混凝土玉垣仍是原構，每根都寫有奉納者姓名，是花蓮三大移民村中唯一保存玉垣與基壇的神社。2014年依日治設計圖復建鳥居、石燈籠與參道，並立林田村建村百年紀念碑。","highlights":["刻有奉納者姓名的原構玉垣","保存完整的拜殿與本殿基壇","2014年復建的鳥居、石燈籠與百年紀念碑"],"funFact":"2014年復建石燈籠時，施工人員誤把設計圖上的方形看成圓形，所以燈籠的桿子做成了圓的。","photoSpot":"沿參道拍石燈籠一路通往基壇","visitMin":25,"openNote":"位於鳳林鎮大榮里復興路旁，官方資料記載隨時開放。神社遺構請勿攀爬玉垣。建議開車前往，可與附近林田派出所一起走訪。","dialogue":[{"who":"A","text":"阿拉蕾，這裡的鳥居和石燈籠看起來很新，但你腳邊這圈矮欄杆可是百年原件喔。"},{"who":"R","text":"矮欄杆？上面好像寫滿了名字，是畢業紀念冊嗎？"},{"who":"A","text":"這叫玉垣，每一根都刻著當年捐獻者的名字，在花蓮三大移民村裡只剩這裡有。"},{"who":"R","text":"哇，那林田神社是什麼時候蓋的？"},{"who":"A","text":"1915年鎮座。戰後改成忠烈祠，1974年又因政策被拆，只剩基壇和玉垣。"},{"who":"R","text":"命運好曲折。那這些新的石燈籠是怎麼來的？"},{"who":"A","text":"2014年照日治設計圖復建，結果工人把方形看成圓形，燈籠桿就變圓的了。"},{"who":"R","text":"這根本是古蹟版的看錯菜單，點牛肉麵來了牛肉湯！"},{"who":"A","text":"哈，比喻滿分。現場請找一根玉垣，試著辨認上面刻的是哪一個名字！"}],"clues":["我的石燈籠因為有人把方形看成圓形，桿子變成圓的","戰後我一度改祭黃花崗七十二烈士","我在鳳林移民村，玉垣上刻滿奉納者姓名"],"quiz":[{"q":"林田神社戰後一度被改成什麼？","options":["佛寺","國民小學","忠烈祠","農會倉庫"],"answer":2,"explain":"戰後改為鳳林區忠烈祠，祭祀黃花崗七十二烈士。"},{"q":"2014年復建的石燈籠，桿子為什麼是圓形？","options":["施工人員看錯設計圖","日治原本就是圓的","圓形比較防颱","居民投票決定"],"answer":0,"explain":"施工人員誤將方形設計看成圓形。"}],"images":[{"file":"林田神社玉垣.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/%E6%9E%97%E7%94%B0%E7%A5%9E%E7%A4%BE%E7%8E%89%E5%9E%A3.jpg/960px-%E6%9E%97%E7%94%B0%E7%A5%9E%E7%A4%BE%E7%8E%89%E5%9E%A3.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%9E%97%E7%94%B0%E7%A5%9E%E7%A4%BE%E7%8E%89%E5%9E%A3.jpg","artist":"Pbdragonwang","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/fenglin-lintianshenshecan-0.webp","small":"img/fenglin-lintianshenshecan-0-s.webp"}]},{"id":"guangfu-xiangbeifucunfu","name":"光復鄉北富村富田古井","short":"太巴塱富田古井","category":"歷史建築","level":"","town":"光復鄉","types":["其他設施"],"lat":23.661216,"lng":121.453546,"address":"花蓮縣光復鄉北富村富強街","announced":"2002-09-23","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020923000007","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-01-07/70f536fd-a358-469d-a4d7-1d85cfa8ffc4/3602332554188.jpg","year":1916,"yearText":"約1916年（大正5年）","era":"japan","themes":["原住民族文化","水利設施"],"yearUnknown":false,"summary":"太巴塱八大古井之一，以石頭和糯米砌成","intro":"富田古井位於光復鄉北富村，約建於1916年。日治時期太巴塱（官方資料寫作大巴塱）一度改名「富田」，戰後分為東、西、南、北富田四村。相傳這口井由太巴塱先祖拉鼓娃階層合力挖掘，供應居民日常飲水，是太巴塱部落八大古井之一，後來因自來水普及而廢棄。古井以石頭與糯米砌成，十分珍貴。1999年由拉度倫階層的周添丁、黃仁義等15位阿美族人發起修復，妥善維護並立碑紀念，展現部落年齡階層共同守護公共事務的傳統。","highlights":["以石頭與糯米砌成的井壁","1999年族人修復後所立的紀念碑","太巴塱八大古井之一的部落記憶"],"funFact":"這口井由拉鼓娃階層挖掘、拉度倫階層修復，兩個不同年齡階層前後接力守護同一口井。","photoSpot":"在古井旁連同紀念碑一起入鏡","visitMin":15,"openNote":"位於光復鄉北富村富強街，官方資料記載隨時開放。位在部落生活區，請放低音量，勿攀爬或投物入井。光復鄉在2025年9月馬太鞍溪堰塞湖溢流後仍在復原，出發前請查詢最新開放與道路狀況。","dialogue":[{"who":"R","text":"Allan，這口井看起來好有年紀，是誰挖的呀？"},{"who":"A","text":"相傳是太巴塱的先祖拉鼓娃階層合力挖的，大約1916年，是部落八大古井之一。"},{"who":"R","text":"部落有八大古井！那這口井的井壁是用什麼材料砌的？"},{"who":"A","text":"用石頭加糯米砌成。糯米不只能包粽子，還能當黏著劑，我每次聽到都餓了。"},{"who":"R","text":"Allan你真的三句不離吃！那這口古井後來為什麼不用了？"},{"who":"A","text":"自來水普及以後就廢棄了，但1999年拉度倫階層的15位族人發起修復，還立了碑。"},{"who":"R","text":"先祖挖井，後輩修井，好像一場跨越好幾代的接力賽！"},{"who":"A","text":"正是部落年齡階層一起守護公共事務的精神。現場請找到紀念碑，讀讀上面的字。"}],"clues":["我的井壁用石頭和糯米砌成","1999年由15位阿美族人發起修復並立碑","我是太巴塱部落八大古井之一"],"quiz":[{"q":"富田古井的井壁是用什麼材料砌成的？","options":["紅磚與水泥","鐵板與鋼筋","木板與竹片","石頭與糯米"],"answer":3,"explain":"古井以石頭與糯米砌成。"},{"q":"1999年發起修復富田古井的是哪個階層的族人？","options":["拉鼓娃階層","拉度倫階層","頭目家族","鄉公所職員"],"answer":1,"explain":"拉度倫階層周添丁、黃仁義等15人發起修復。"}],"images":[]},{"id":"hualian-jinghualinyuan","name":"菁華林苑(花蓮港山林事業所官舍)","short":"菁華林苑","category":"歷史建築","level":"","town":"花蓮市","types":["宅第"],"lat":23.980692,"lng":121.61611,"address":"花蓮縣花蓮市花蓮市菁華街10號","announced":"2002-09-23","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020923000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-27/f13aec35-a7d6-4e8c-8f60-2c914f551944/c花蓮-菁華林苑02.jpg","year":1919,"yearText":"1919年（大正8年）","era":"japan","themes":["林業聚落","日式建築","職務宿舍"],"yearUnknown":false,"summary":"八角窗與拱廊並存的林業長官官舍","intro":"菁華林苑位於花蓮市菁華街，原為花蓮港山林事業所的官舍區。官方資料記載這裡1919年原為花蓮港木材株式會社，1929年殖產局營林所東部出張所遷入，1942年改稱「花蓮港山林事業所」，戰後由縣府接管，1960年裁撤後閒置。2001年定名「菁華林苑」，2002年登錄為歷史建築，隔年範圍內的辦公廳舍另外指定為縣定古蹟。官舍以日式軸組工法建造，寄棟式屋頂，四面有大片玻璃窗提高採光，大門右側有一面外框八角形、內為不規則幾何圖樣的窗戶。庭園有樟樹、瓊崖海棠與羊蹄甲相伴，是日治林業產業的重要見證。","highlights":["大門右側八角形外框的幾何圖樣窗","寄棟式屋頂與四面大片玻璃窗","辦公廳舍與長官宿舍間巷弄內的木造日式屋"],"funFact":"菁華林苑登錄歷史建築隔年，範圍內的辦公廳舍又被另外指定為縣定古蹟，一個園區兩種身分。","photoSpot":"在大門旁拍那扇八角形幾何窗","visitMin":30,"openNote":"位於花蓮市菁華街，與縣定古蹟花蓮港山林事業所相鄰，官方資料未載開放時間，參觀前請查詢最新開放狀況。周邊日式宿舍群可步行串遊。","dialogue":[{"who":"R","text":"Allan，這扇窗戶好特別，外面八角形，裡面又是亂亂的幾何圖案！"},{"who":"A","text":"這就是菁華林苑的招牌窗，官方形容它頗有現代藝術設計的味道。"},{"who":"R","text":"菁華林苑，這名字聽起來好像跟森林有關？"},{"who":"A","text":"答對了！這裡是花蓮港山林事業所的官舍，負責東部林業的長官就住在這一帶。"},{"who":"R","text":"那這裡是從什麼時候開始有人辦公的？"},{"who":"A","text":"1919年先是花蓮港木材株式會社，1929年營林所東部出張所搬進來，1942年改名山林事業所。"},{"who":"R","text":"改名改了好多次，忙得跟一直在搬家一樣。"},{"who":"A","text":"管木頭的人，房子當然也講究。院子裡有樟樹、瓊崖海棠和羊蹄甲，我每次來都想在樹下午睡。"},{"who":"R","text":"大家去院子裡找找看，羊蹄甲的葉子是不是真的長得像羊蹄！"}],"clues":["我曾經由木材會社使用，後來換營林所的長官進駐","我大門旁有一扇八角形、內有幾何圖案的窗","我在菁華街，名字裡有森林的林"],"quiz":[{"q":"菁華林苑原本是哪個機關的官舍？","options":["花蓮港廳警務課","專賣局花蓮支局","花蓮港高等女學校","花蓮港山林事業所"],"answer":3,"explain":"它原為花蓮港山林事業所的官舍區。"},{"q":"菁華林苑大門右側那扇窗戶的外型是？","options":["圓形","三角形","八角形","心形"],"answer":2,"explain":"大門右側有一面八角形外型的窗戶。"}],"images":[]},{"id":"fenglin-pinglinzhenguoshui","name":"平林圳過水橋","short":"平林圳過水橋","category":"歷史建築","level":"","town":"鳳林鎮","types":["其他設施"],"lat":23.79301,"lng":121.44923,"address":"花蓮縣鳳林鎮鳳林鎮南平段1地號","announced":"2016-12-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20161221000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-04-11/1b75f59a-b14a-4de5-bc55-4baeb178076f/g鳳林-過水橋02.jpg","year":1919,"yearText":"1919年（大正8年）一支線興闢","era":"japan","themes":["水利設施","客家文化"],"yearUnknown":false,"summary":"水圳搭橋過溪，還能讓人走在上面","intro":"平林圳是鳳林鎮林榮、南平、北林一帶的灌溉水圳。1914年林田移民村設立後，南平地區移入許多客家人，形成「上工寮」聚落。約1918年，居民在北清水溪山麓鑿洞引水，完成今平林圳二支線，因水質清澈被稱為「鮮水」；1919年又闢引自壽豐溪的一支線，水較混濁，稱為「汶水」。一支線流經乾砌卵石渠道後，以一座鋼筋混凝土過水橋越過北清水溪河床進入南平里。橋由六座梯形橋墩支承，內為密封方形涵管，橋面兼作人行，是水圳跨越溪谷的重要工法。","highlights":["六座梯形橋墩撐起的混凝土過水橋","密封方形涵管，上方兼作人行道","「鮮水」與「汶水」兩條支線的故事"],"funFact":"同一條平林圳有兩個綽號：引北清水溪的二支線清澈叫「鮮水」，引壽豐溪的一支線較混濁叫「汶水」。","photoSpot":"在溪床旁仰拍六座梯形橋墩","visitMin":20,"openNote":"位於鳳林鎮南平里北清水溪上，官方資料記載隨時開放。溪床與水圳旁請注意安全，雨後勿靠近。建議開車前往。","dialogue":[{"who":"A","text":"阿拉蕾，你看這座橋，上面走人，肚子裡卻走水，是不是很像在變魔術？"},{"who":"R","text":"肚子裡走水？難道是一座會喝水的橋？"},{"who":"A","text":"差不多。這是平林圳過水橋，裡面是密封的方形涵管，把圳水送過北清水溪。"},{"who":"R","text":"為什麼不讓水直接流進溪裡就好？"},{"who":"A","text":"因為對岸的南平里田地要用水啊，水得跨過溪才到得了，所以蓋橋讓水過河。"},{"who":"R","text":"原來不是人過橋，是水在過橋！那這條水圳是誰挖的？"},{"who":"A","text":"林田移民村設立後，南平一帶來了很多客家鄉親，1919年闢了引壽豐溪的這條一支線。"},{"who":"R","text":"我聽說還有鮮水和汶水兩種，是飲料店的新口味嗎？"},{"who":"A","text":"哈，是水質清濁的綽號。到現場請數一數，撐著水橋的梯形橋墩是不是剛好6座！"}],"clues":["當地人用「鮮水」和「汶水」形容我所屬水圳的兩條支線","我由六座梯形橋墩撐起，肚子裡是密封的方形涵管","我讓鳳林的灌溉圳水跨過北清水溪進入南平里"],"quiz":[{"q":"平林圳二支線因水質清澈，被居民稱為什麼？","options":["汶水","清泉","鮮水","甘水"],"answer":2,"explain":"引北清水溪的二支線清澈，居民稱為鮮水。"},{"q":"平林圳過水橋由幾座梯形橋墩支承？","options":["6座","5座","4座","8座"],"answer":0,"explain":"官方說明過水橋由六座梯形橋墩支承。"}],"images":[]},{"id":"xincheng-xiangyuanyanhai","name":"新城鄉原研海庄役場","short":"研海庄役場","category":"歷史建築","level":"","town":"新城鄉","types":["衙署"],"lat":24.126369,"lng":121.65338,"address":"花蓮縣新城鄉新城鄉信義路6號旁","announced":"2017-08-03","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20170803000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-30/c5063e1f-edef-4b87-aace-5dffbfbff0c5/b新城-原研海庄役03.jpg","year":1920,"yearText":"日治時期（1920年設研海區役場）","era":"japan","themes":["公共建築"],"yearUnknown":false,"summary":"見證新城地區行政更迭的日治舊辦公廳舍","intro":"新城鄉原研海庄役場位於新城鄉新城村信義路，在新城分局對面、中山路與信義路口。新城一帶原為太魯閣族常居之地，日治初期衝突不斷，約20年才趨於穩定；1914年太魯閣戰役後設新城支廳，1920年改為研海支廳，並設研海區役場管轄今新城及北埔地區。戰後恢復新城舊名，新城村辦公處曾短暫設在這裡。建築為寄棟屋頂，外牆混合混凝土牆與雨淋板，開長條直立窗，圍牆局部為卵石砌。官方記載基礎與牆體嚴重受潮、屋頂木構件多處損毀。","highlights":["寄棟式屋頂與長條形直立窗","混凝土牆與雨淋板並用的外牆","圍牆上看得到一顆顆卵石"],"funFact":"「研海」這個地名用了二十多年，戰後才又改回新城的舊名。","photoSpot":"從路口斜拍卵石圍牆與屋頂","visitMin":10,"openNote":"位於新城鄉新城村信義路口，新城分局對面，官方資料記載隨時開放，惟建物狀況不佳，請以外觀參觀為主。可搭臺鐵到新城站。","dialogue":[{"who":"R","text":"Allan，這間舊房子的名字好難唸，研海庄役場是什麼意思？"},{"who":"A","text":"庄役場就是日治時期的鄉公所，研海是當時這一帶的地名，1920年設了研海區役場。"},{"who":"R","text":"所以新城在日治時期不叫新城囉？"},{"who":"A","text":"日治時期改叫研海，戰後才恢復新城舊名，新城村辦公處還短暫在這裡辦公過。"},{"who":"R","text":"地名這樣改來改去，當時的郵差一定很頭痛吧！"},{"who":"A","text":"哈哈，這一帶在日治初期衝突不斷，太魯閣族的土地也在這段時間被納入日本的行政體系，行政區一直調整。"},{"who":"R","text":"原來一間小小的辦公室，藏著這麼多時代變化。"},{"who":"A","text":"對啊。官方記載它受潮嚴重、屋頂木構件也有損毀，請在外面看就好。找找看圍牆上，有幾顆露出來的圓卵石！"}],"clues":["我的圍牆局部用圓圓的卵石砌成","我是日治時期的地方行政辦公室，戰後當過村辦公處","我在新城鄉信義路口，名字裡有日治時期的舊地名研海"],"quiz":[{"q":"日治時期新城地區曾改用什麼地名？","options":["加禮宛","米崙","北埔","研海"],"answer":3,"explain":"1920年新城支廳改為研海支廳，設研海區役場。"},{"q":"戰後這棟建築曾短暫作為什麼用途？","options":["派出所","郵局","村辦公處","小學教室"],"answer":2,"explain":"戰後新城村辦公處曾短暫設於此。"}],"images":[{"file":"新城鄉原研海庄役場01.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bc/%E6%96%B0%E5%9F%8E%E9%84%89%E5%8E%9F%E7%A0%94%E6%B5%B7%E5%BA%84%E5%BD%B9%E5%A0%B401.jpg/960px-%E6%96%B0%E5%9F%8E%E9%84%89%E5%8E%9F%E7%A0%94%E6%B5%B7%E5%BA%84%E5%BD%B9%E5%A0%B401.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%96%B0%E5%9F%8E%E9%84%89%E5%8E%9F%E7%A0%94%E6%B5%B7%E5%BA%84%E5%BD%B9%E5%A0%B401.jpg","artist":"王綉敏","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/xincheng-xiangyuanyanhai-0.webp","small":"img/xincheng-xiangyuanyanhai-0-s.webp"}]},{"id":"xincheng-xiangxinchengcun","name":"新城鄉新城村信義路6號日式舊宿舍","short":"新城信義路宿舍","category":"歷史建築","level":"","town":"新城鄉","types":["辦公廳舍"],"lat":24.126066,"lng":121.653729,"address":"花蓮縣新城鄉新城村信義路6號","announced":"2017-08-03","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20170803000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-30/fd36fe22-d550-4e10-8644-816615818fb2/b新城-信義路舊宿01.jpg","year":1920,"yearText":"日治時期（確切年份未載）","era":"japan","themes":["日式建築","職務宿舍"],"yearUnknown":false,"summary":"緊鄰研海庄役場的日治木造職員宿舍","intro":"新城鄉新城村信義路日式舊宿舍，緊鄰原研海庄役場，是日治時期行政廳舍區域供日籍職員居住的宿舍，沿用至今，見證新城地區行政發展。建築為切妻式水泥瓦屋頂，以軸組工法構成的日式木造宿舍，外牆原為「簓子下見板張」，也就是以壓條固定的雨淋板。空間分前院與後院：前院是大門到屋子之間的過渡空間，仍保留部分植栽；後院較私密，後來因生活需要增建了飼養家畜的棚架。官方認為主體構造、屋架、屋面與軸組保存完整。","highlights":["切妻式水泥瓦屋頂","外牆原有的簓子下見板張雨淋板","前院保留下來的庭園植栽"],"funFact":"簓子下見板張是用細長壓條把重疊的木板一片片壓住的外牆做法，看起來像橫向的魚鱗。","photoSpot":"在信義路上拍切妻屋頂側面","visitMin":10,"openNote":"位於新城鄉新城村信義路，鄰近原研海庄役場，官方未載開放資訊，可能仍有人使用，請勿擅入，以外觀參觀為主。可搭臺鐵到新城站。","dialogue":[{"who":"A","text":"隔壁是研海庄役場，阿拉蕾，你猜這棟木頭房子是給誰住的？"},{"who":"R","text":"在辦公室旁邊，一定是上班族宿舍吧！"},{"who":"A","text":"答對了！這是日治時期給附近行政廳舍職員住的宿舍，一直沿用到今天。"},{"who":"R","text":"它的外牆木板一片疊著一片，看起來好像魚鱗喔。"},{"who":"A","text":"觀察力很好，那叫簓子下見板張，用細長壓條把雨淋板壓住，防風又防雨。"},{"who":"R","text":"名字好長又好拗口，Allan你是不是故意考我發音？"},{"who":"A","text":"沒有啦，我自己也是背了三天才記住。前院還有老植栽，後院後來還加了養家畜的棚架。"},{"who":"R","text":"從上班族宿舍變成迷你小農場，好有生活感！"},{"who":"A","text":"這裡可能還有人使用，請在路邊安靜欣賞，數一數外牆上的壓條，一共可以看到幾條！"}],"clues":["我的外牆曾用細長壓條固定雨淋板","我的後院後來增建了飼養家畜的棚架","我是新城鄉信義路上、緊鄰舊庄役場的日式木造宿舍"],"quiz":[{"q":"這棟宿舍的屋頂形式是？","options":["入母屋造","寄棟造","切妻式","平屋頂"],"answer":2,"explain":"切妻屋根形式的水泥瓦屋頂。"},{"q":"「簓子下見板張」指的是建築哪個部位的做法？","options":["外牆","地板","屋架","門窗"],"answer":0,"explain":"真壁構造外牆原為簓子下見板張。"}],"images":[{"file":"Japanese-style Dormitory, no. 6 Xinyi Road, Xincheng Township, Hualien County (Taiwan).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f1/Japanese-style_Dormitory%2C_no._6_Xinyi_Road%2C_Xincheng_Township%2C_Hualien_County_%28Taiwan%29.jpg/960px-Japanese-style_Dormitory%2C_no._6_Xinyi_Road%2C_Xincheng_Township%2C_Hualien_County_%28Taiwan%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Japanese-style_Dormitory,_no._6_Xinyi_Road,_Xincheng_Township,_Hualien_County_(Taiwan).jpg","artist":"Mk2010","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/xincheng-xiangxinchengcun-0.webp","small":"img/xincheng-xiangxinchengcun-0-s.webp"}]},{"id":"hualian-jiujiuchang","name":"花蓮舊酒廠","short":"花蓮舊酒廠","category":"歷史建築","level":"","town":"花蓮市","types":["產業"],"lat":23.976073,"lng":121.604659,"address":"花蓮縣花蓮市中華路144號(中華路與中正路交叉口)","announced":"2002-09-23","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020923000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-25/1e5bf7ce-2026-4340-8db2-c77c16542fbc/c花蓮-舊酒場28.jpg","year":1920,"yearText":"約1920年（大正9年）木構廠房興建","era":"japan","themes":["產業遺產","藝術文化"],"yearUnknown":false,"summary":"近百年酒廠，今為市中心的文創園區","intro":"花蓮舊酒廠位於花蓮市中華路與中正路口，前身是日治時期民營的「宜蘭振拓株式會社花蓮港稻住工場」。1922年總督府實施酒類專賣，同年7月由專賣局接管，稱臺灣專賣局花蓮港支局；戰後改隸菸酒公賣局，歷經花蓮港工廠、第八酒廠、花蓮酒廠等名稱。廠區約3.3公頃，保有日式建築、造酒與釀酒廠房，以及一口專供釀酒的古井。其中木構造山形建築約建於1920年，磚牆山形廠房為1940年重建，平頂建築則是1950年代所建，全區現存26幢建築。2000年土地變更為歷史風貌公園用地，2002年登錄歷史建築，今為花蓮文化創意產業園區。","highlights":["約1920年興建的木構造山形廠房","曾專供釀酒、出水甘甜的古井","辦公廳舍東側的六幢宿舍與倉庫群"],"funFact":"酒廠戰後改過好幾次名字，其中一個是「臺灣省菸酒公賣局第八酒廠」。","photoSpot":"在倉庫群之間拍成排的山形屋頂","visitMin":60,"openNote":"位於花蓮市中華路與中正路口，今為花蓮文化創意產業園區，官方資料記載戶外空間24小時開放，室內依各活動公告。距臺鐵花蓮站車程約10分鐘，市區景點可步行串遊。","dialogue":[{"who":"R","text":"Allan，這裡好多展覽和市集，跟酒有什麼關係啊？"},{"who":"A","text":"關係可大了！這裡是花蓮舊酒廠，日治時期從民營的稻住工場起家，1922年改由專賣局接管。"},{"who":"R","text":"專賣是什麼意思？只能在這裡買酒嗎？"},{"who":"A","text":"是政府獨家製造販賣的意思。戰後換公賣局接手，還叫過第八酒廠，名字比我的綽號還多。"},{"who":"R","text":"那這些廠房都是同一時間蓋的嗎？"},{"who":"A","text":"不是喔。木構造山形廠房約1920年，磚牆廠房1940年重建，平頂建築則是1950年代的。"},{"who":"R","text":"原來屋頂形狀就是年代的線索！還有什麼秘密？"},{"who":"A","text":"廠區有一口古井，以前出水甘甜，專門拿來釀酒。可惜現在只能看，不能喝。"},{"who":"R","text":"那大家去找找那口古井，順便數數看園區有幾種不同的屋頂吧！"}],"clues":["我曾經是政府獨家生產某種飲品的工廠","我有一口專門用來釀造的甘甜古井","我在花蓮市中心，現在是文創市集和展覽的園區"],"quiz":[{"q":"花蓮舊酒廠在哪一年改由專賣局接管？","options":["1912年","1922年","1932年","1945年"],"answer":1,"explain":"1922年總督府實施酒類專賣，同年7月接管。"},{"q":"舊酒廠今天是什麼地方？","options":["花蓮文化創意產業園區","花蓮縣議會","鐵道文化園區","國立東華大學分部"],"answer":0,"explain":"舊酒廠今為花蓮文化創意產業園區。"}],"images":[{"file":"Hualien Cultural & Creative Industries Park, pond, Hualien City (Taiwan).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2c/Hualien_Cultural_%26_Creative_Industries_Park%2C_pond%2C_Hualien_City_%28Taiwan%29.jpg/960px-Hualien_Cultural_%26_Creative_Industries_Park%2C_pond%2C_Hualien_City_%28Taiwan%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Hualien_Cultural_%26_Creative_Industries_Park,_pond,_Hualien_City_(Taiwan).jpg","artist":"Mk2010","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/hualian-jiujiuchang-0.webp","small":"img/hualian-jiujiuchang-0-s.webp"}]},{"id":"ruisui-xiangqingangongtu","name":"瑞穗鄉慶安宮土地公廟","short":"慶安宮土地公廟","category":"歷史建築","level":"","town":"瑞穗鄉","types":["寺廟"],"lat":23.570393,"lng":121.400599,"address":"花蓮縣瑞穗鄉瑞穗鄉富興村海岸山脈西麓山腳下，縣道193號78公里處，東興橋西側。","announced":"2008-03-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20191211000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-30/125e42e2-e5eb-4e05-b57a-d34919158d5b/i瑞穗-慶安宮04.jpg","year":1920,"yearText":"1920年（大正9年）","era":"japan","themes":["宗教信仰"],"yearUnknown":false,"summary":"十三塊石板砌成的極簡土地公祠","intro":"瑞穗鄉慶安宮土地公廟位於富興村海岸山脈西麓、縣道193號旁東興橋西側，是以十三塊石板（或石塊）雕鑿砌成的小型土地公祠，形制極為儉樸，屋面與屋脊卻有精細雕刻。現存廟祠建於1920年，由當時大和村（今光復鄉大富、大農與瑞穗鄉富源、富興一帶）的村民集資興建。1951年大地震時傾圮，之後遷移重建，除台基外構件都是原物，成為地震的見證，也反映閩南移民由西部再移往東部的歷程，具信仰與社區意義。","highlights":["十三塊石板砌成的極簡土地公祠","屋面與屋脊上的細緻雕刻","1951年震後遷建，構件幾乎都是原物"],"funFact":"整座廟只用十三塊石板或石塊組成，1951年震倒後重組，除了台基都是原本的構件。","photoSpot":"蹲低拍屋脊雕刻與石板廟身","visitMin":10,"openNote":"官方資料記載隨時開放。位於瑞穗鄉富興村縣道193號旁、東興橋西側，周邊為造林地，建議開車前往。","dialogue":[{"who":"A","text":"阿拉蕾，猜猜看，蓋一座廟最少需要幾塊石頭？"},{"who":"R","text":"至少要好幾百塊吧？還要有屋頂和柱子。"},{"who":"A","text":"瑞穗富興村這座慶安宮土地公廟，只用十三塊石板或石塊就蓋好了，堪稱積木大師級作品。"},{"who":"R","text":"才十三塊！那它會不會搖搖晃晃很不穩？"},{"who":"A","text":"1951年大地震時真的倒了，後來換了位置重建，神奇的是除了台基，其他構件都是原本那幾塊。"},{"who":"R","text":"就像拼圖倒了再拼回去，一塊都沒少。"},{"who":"A","text":"這座廟建於1920年，是當年大和村村民集資蓋的，也見證閩南移民從西部再遷到東部。"},{"who":"R","text":"小小一座，故事好大一包。那我們要看哪裡？"},{"who":"A","text":"別看它樸素，屋面和屋脊都有雕刻。請你蹲低一點，找找屋脊上的雕紋，拍一張特寫！"}],"clues":["我整座廟只用了十三塊石板或石塊","1951年大地震把我震倒，重建後構件幾乎都是原物","我是瑞穗富興村縣道193號旁的小土地公祠"],"quiz":[{"q":"這座土地公廟由幾塊石板或石塊砌成？","options":["8塊","21塊","36塊","13塊"],"answer":3,"explain":"以十三塊石板或石塊雕鑿砌築而成。"},{"q":"土地公廟在哪一年的大地震中傾圮？","options":["1920年","1935年","1951年","1999年"],"answer":2,"explain":"1951年大地震傾圮後遷移重建。"}],"images":[{"file":"2024 Qing An Temple (Ruisui Township) m2.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dc/2024_Qing_An_Temple_%28Ruisui_Township%29_m2.jpg/960px-2024_Qing_An_Temple_%28Ruisui_Township%29_m2.jpg","page":"https://commons.wikimedia.org/wiki/File:2024_Qing_An_Temple_(Ruisui_Township)_m2.jpg","artist":"Taiwankengo","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","local":"img/ruisui-xiangqingangongtu-0.webp","small":"img/ruisui-xiangqingangongtu-0-s.webp"}]},{"id":"guangfu-xiangdafengcungu","name":"光復鄉大豐村古厝（穎川堂）","short":"穎川堂鍾家古厝","category":"歷史建築","level":"","town":"光復鄉","types":["宅第"],"lat":23.590616,"lng":121.380183,"address":"花蓮縣光復鄉大豐村9 鄰267 號","announced":"2002-09-23","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020923000010","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-02-18/86d042f6-899a-4dd9-a6ff-7ffda1ff3bfd/h光復-穎川堂05.jpg","year":1921,"yearText":"1921年（大正10年）","era":"japan","themes":["客家文化"],"yearUnknown":false,"summary":"富源山腳下的百年客家三合院","intro":"穎川堂古厝位於光復鄉大豐村、富源山腳下，坐北朝南。1921年鍾家第16代祖先鍾阿宗從頭份攜眷遷居此地，延請唐山起厝師傅興建三合院，2年後完成。這是傳統客家式建築，有簡潔的飛簷與西施脊，堂中雕樑畫棟，屋簷上滿是忠孝節義的歷史故事。古厝使用自製的黃磚與泥磚，屋樑與柱子是當年鍾家壯丁上山砍伐的檜木與茄苳木製成。屋頂後來改為仿瓦鐵皮，歷經颱風、地震侵襲，仍大致保持完整，是見證後山客家拓墾歷史的建築，官方說明花蓮縣內這樣的古厝並不多見。","highlights":["簡潔飛簷與西施脊的屋頂線條","屋簷上忠孝節義的彩繪故事","自製黃磚、泥磚與檜木樑柱"],"funFact":"古厝的屋樑與柱子，是當年鍾家壯丁親自上山砍伐檜木和茄苳木做成的。","photoSpot":"在禾埕外拍三合院正身與飛簷","visitMin":15,"openNote":"位於光復鄉大豐村，為私人宅第，請在外觀欣賞，勿擅入打擾。光復鄉在2025年9月馬太鞍溪堰塞湖溢流後仍在復原，出發前請查詢最新開放與道路狀況。建議開車前往。","dialogue":[{"who":"A","text":"富源山腳下這座三合院叫穎川堂，是鍾家從頭份遷來後蓋的客家古厝。"},{"who":"R","text":"1921年就開始蓋了嗎？那時候從頭份搬到花蓮，交通很不方便吧！"},{"who":"A","text":"1921年開工，花了2年完成，還特地請唐山的起厝師傅來蓋。"},{"who":"R","text":"Allan，屋頂上那條翹起來的線叫什麼？"},{"who":"A","text":"那叫西施脊。別誤會，不是西施本人來蓋房子，是屋脊的一種樣式。"},{"who":"R","text":"我差點以為古代美女也會做工！那柱子是什麼木頭？"},{"who":"A","text":"是鍾家壯丁親自上山砍的檜木和茄苳木，磚也是自己做的黃磚和泥磚。"},{"who":"R","text":"從木頭到磚頭都自己來，這才是真正的家！"},{"who":"A","text":"說得好。現場請從外面欣賞屋簷，找一個忠孝節義的故事畫面拍下來。"}],"clues":["我的樑柱是家族壯丁上山砍的檜木和茄苳","1921年由唐山起厝師傅動工，2年後完成","我是光復鄉大豐村、富源山腳下的客家三合院"],"quiz":[{"q":"穎川堂的鍾家祖先是從哪裡遷來的？","options":["桃園龍潭","新竹關西","苗栗頭份","屏東佳冬"],"answer":2,"explain":"鍾家第16代祖先鍾阿宗從頭份攜眷遷居此地。"},{"q":"穎川堂屋頂上翹起的屋脊樣式叫什麼？","options":["西施脊","馬背","燕尾脊","硬山脊"],"answer":0,"explain":"古厝有簡潔的飛簷及西施脊。"}],"images":[{"file":"2024 YingChuan Hall (Guangfu Township) m1.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0c/2024_YingChuan_Hall_%28Guangfu_Township%29_m1.jpg/960px-2024_YingChuan_Hall_%28Guangfu_Township%29_m1.jpg","page":"https://commons.wikimedia.org/wiki/File:2024_YingChuan_Hall_(Guangfu_Township)_m1.jpg","artist":"Taiwankengo","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","local":"img/guangfu-xiangdafengcungu-0.webp","small":"img/guangfu-xiangdafengcungu-0-s.webp"}]},{"id":"guangfu-tangchangyuanliao","name":"花蓮糖廠原料區辦公室","short":"糖廠原料區辦公室","category":"歷史建築","level":"","town":"光復鄉","types":["辦公廳舍"],"lat":23.655227,"lng":121.420122,"address":"花蓮縣光復鄉光復鄉大進村糖廠街10號","announced":"2011-10-04","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20111004000010","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-20/eada932c-3777-4508-907c-36d138f90fb6/h光復-糖廠原料辦公室02.jpg","year":1921,"yearText":"日治時期（大和工場1921年設立後）","era":"japan","themes":["糖業","產業遺產"],"yearUnknown":false,"summary":"管甘蔗原料的辦公室，後來變身餐廳","intro":"花蓮糖廠原料區辦公室位於光復鄉大進村糖廠街，在遊客服務中心對面，日治時期屬鹽水港製糖株式會社花蓮港製糖所大和工場的建築群。日本領臺後，臺灣成為提供粗糖原料給日本本土的產地，新式製糖會社陸續成立，鹽水港製糖後來也著手開發東部事業。戰後大和工場更名為花蓮糖廠，這棟辦公室改為光復原料區、工會與政風等辦公室。建築為寄棟屋頂、水泥瓦，牆面是雨淋板，下部設有高約40公分的無雙窗，四周加斜撐木防颱防震。轉型閒置後，2009年曾租借作電視劇拍攝場地，官方資料記載後來作為餐廳使用。","highlights":["牆腳下高約40公分的無雙窗","房屋四周防颱防震的斜撐木","雨淋板外牆與寄棟水泥瓦屋頂"],"funFact":"原料區辦公室在2009年曾借給電視劇當拍攝場地，之後又變身餐廳，從管甘蔗變成管吃飯。","photoSpot":"從遊客中心對面拍整排斜撐木","visitMin":20,"openNote":"位於光復鄉大進村糖廠街，遊客服務中心對面，官方資料記載曾作為餐廳使用，現況營業情形請出發前查詢。光復鄉在2025年9月馬太鞍溪堰塞湖溢流後仍在復原，出發前請查詢最新開放與道路狀況。","dialogue":[{"who":"A","text":"阿拉蕾，糖要從哪裡來？這棟原料區辦公室就是專門管這個問題的。"},{"who":"R","text":"糖從甘蔗來！所以這裡是管甘蔗的辦公室？"},{"who":"A","text":"答對了。日治時期它屬大和工場，戰後改當原料區、工會和政風的辦公室，忙著跟甘蔗打交道。"},{"who":"R","text":"後來糖廠不做糖了，它不就失業了？"},{"who":"A","text":"它很會轉職，2009年先借給電視劇拍戲，後來又變成餐廳。"},{"who":"R","text":"從管甘蔗變成管吃飯，跟Allan的人生志向一模一樣！"},{"who":"A","text":"知我者阿拉蕾也。不過建築本身也很講究，四周都有斜撐木防颱防震。"},{"who":"R","text":"咦，牆腳下那排矮矮的小窗戶是做什麼用的？"},{"who":"A","text":"那叫無雙窗，高約40公分，可以調節通風。請你蹲下來找找它，拍張特寫！"}],"clues":["2009年我曾借給電視劇當拍攝場地","戰後我成了原料區、工會與政風的辦公室","我在光復鄉糖廠遊客中心對面，以前專管甘蔗原料"],"quiz":[{"q":"原料區辦公室牆腳下高約40公分的窗戶叫什麼？","options":["無雙窗","雨戶袋","老虎窗","八角窗"],"answer":0,"explain":"下部設置高40公分的無雙窗。"},{"q":"原料區辦公室在2009年曾被借去做什麼？","options":["防疫中心","選舉投票所","電視劇拍攝場地","美術館"],"answer":2,"explain":"2009年因電視劇租借整理作為拍攝場地。"}],"images":[{"file":"花蓮光復糖廠 花蓮縣 宅第 Venation 2.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ad/%E8%8A%B1%E8%93%AE%E5%85%89%E5%BE%A9%E7%B3%96%E5%BB%A0_%E8%8A%B1%E8%93%AE%E7%B8%A3_%E5%AE%85%E7%AC%AC_Venation_2.jpg/960px-%E8%8A%B1%E8%93%AE%E5%85%89%E5%BE%A9%E7%B3%96%E5%BB%A0_%E8%8A%B1%E8%93%AE%E7%B8%A3_%E5%AE%85%E7%AC%AC_Venation_2.jpg","page":"https://commons.wikimedia.org/wiki/File:%E8%8A%B1%E8%93%AE%E5%85%89%E5%BE%A9%E7%B3%96%E5%BB%A0_%E8%8A%B1%E8%93%AE%E7%B8%A3_%E5%AE%85%E7%AC%AC_Venation_2.jpg","artist":"Venation","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/guangfu-tangchangyuanliao-0.webp","small":"img/guangfu-tangchangyuanliao-0-s.webp"}]},{"id":"guangfu-tangchangyuangong3","name":"花蓮糖廠員工宿舍7巷1、3號","short":"糖廠宿舍7巷1、3號","category":"歷史建築","level":"","town":"光復鄉","types":["宅第"],"lat":23.656204,"lng":121.419559,"address":"花蓮縣光復鄉光復鄉大進村糖廠街7巷1、3號","announced":"2011-10-04","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20111004000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-20/8353297e-9321-445e-bd9a-295f1e9753eb/h光復-糖廠宿舍7巷1 3號02.jpg","year":1922,"yearText":"約1922年（大正11年，最早一批宿舍）","era":"japan","themes":["糖業","職務宿舍","日式建築"],"yearUnknown":false,"summary":"花蓮糖廠最早一批雙併丙種員工宿舍","intro":"花蓮糖廠員工宿舍7巷1、3號位於光復鄉大進村糖廠街7巷，與同巷5、7號同屬廠區最早一批興建的宿舍，設計為雙併丙種員工宿舍。花蓮糖廠前身是1921年興建的花蓮港製糖所大和工場，戰後改名花蓮港糖廠，1952年後改稱花蓮糖廠。官方資料指出宿舍群最早建於1922年，各種等級的宿舍並置在工廠旁，具體呈現工廠與居住空間緊密結合的「廠住合一」規劃，以及員工之間的職級區分，也是規格化營建技術的先驅，見證製糖產業在東部的發展。","highlights":["廠區最早一批興建的宿舍之一","一棟住兩戶的雙併丙種宿舍格局","與同巷5、7號比鄰，可對照觀察"],"funFact":"花蓮糖廠換過好幾個名字：大和工場、花蓮港糖廠，到1952年後才定名為花蓮糖廠。","photoSpot":"站在7巷巷口，把整排雙併木屋拍進畫面","visitMin":15,"openNote":"光復鄉在2025年9月馬太鞍溪堰塞湖溢流後仍在復原，出發前請查詢最新開放與道路狀況。位於光復鄉糖廠街7巷的花蓮糖廠宿舍區，官方資料未載開放時間，以外觀參觀為主；可搭臺鐵花東線至光復站。","dialogue":[{"who":"A","text":"考你一題，糖廠街7巷這棟雙併木屋，和隔壁的5、7號有什麼共同點？"},{"who":"R","text":"都姓糖嗎？還是住起來都特別甜？"},{"who":"A","text":"甜是甜在心裡啦！官方資料說它們是廠區最早一批興建的宿舍，宿舍群最早可以追到1922年。"},{"who":"R","text":"哇，一百年前，那時候的糖廠叫什麼名字？"},{"who":"A","text":"叫花蓮港製糖所大和工場，戰後變花蓮港糖廠，1952年後才叫花蓮糖廠，改名次數比我換眼鏡還多。"},{"who":"R","text":"Allan你的黑框眼鏡明明戴超久的。那雙併是什麼意思？"},{"who":"A","text":"就是一棟房子左右對分，住兩戶人家，丙種是其中一種規格。工廠就在旁邊，這叫廠住合一。"},{"who":"R","text":"上班不用走太遠，好羨慕當年的員工！"},{"who":"A","text":"到現場請你站在巷子裡，數數看這棟雙併宿舍有幾個入口，猜猜哪邊是哪一戶！"}],"clues":["我和同巷的鄰居是廠區最早一批宿舍","我是一棟分給兩戶住的丙種宿舍","我在光復鄉糖廠街7巷，門牌是1號和3號"],"quiz":[{"q":"大和工場在戰後先改成什麼名字？","options":["光復製糖所","花蓮港糖廠","台東糖廠","大進糖廠"],"answer":1,"explain":"戰後改名花蓮港糖廠，1952年後改稱花蓮糖廠。"},{"q":"花蓮糖廠宿舍群最早建於哪一年？","options":["1912年","1932年","1945年","1922年"],"answer":3,"explain":"官方資料指出宿舍群最早建於1922年。"}],"images":[]},{"id":"guangfu-tangchangyuangong4","name":"花蓮糖廠員工宿舍7巷5、7號","short":"糖廠宿舍7巷5、7號","category":"歷史建築","level":"","town":"光復鄉","types":["宅第"],"lat":23.656337,"lng":121.419276,"address":"花蓮縣光復鄉光復鄉大進村糖廠街7巷5、7號","announced":"2011-10-04","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20111004000006","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-20/a1a0a8f9-2d5c-4b4a-a5d0-a784dce80018/h光復-糖廠宿舍7巷5 7號02.jpg","year":1922,"yearText":"約1922年（大正11年，最早一批宿舍）","era":"japan","themes":["糖業","職務宿舍","日式建築"],"yearUnknown":false,"summary":"看懂大和工場廠住合一規劃的早期宿舍","intro":"花蓮糖廠員工宿舍7巷5、7號位於光復鄉大進村糖廠街7巷，屬最早期興建的雙併丙種員工宿舍，與同巷1、3號並列。大和工場1921年興建時，原料、運輸、水源與生產設施一併規劃，廠區由北而南排列生產工廠、行政辦公室、運輸鐵道、宿舍群、醫院與學校，宿舍緊鄰生產場所，形成生產與生活密切相連的聚落。官方認為這類宿舍是規格化營建技術的前驅，從工廠與宿舍的關係可以讀出整體規劃構想，具建築史與技術史價值，也見證臺灣製糖產業在東部的發展。","highlights":["從宿舍讀出廠區由北到南的整體規劃","依標準設計興建的規格化宿舍","與同巷1、3號形成同型宿舍街景"],"funFact":"大和工場的配置由北到南是工廠、辦公室、鐵道、宿舍、醫院、學校，一條線串起整個生活圈。","photoSpot":"把7巷5、7號和1、3號拍進同一個畫面","visitMin":15,"openNote":"光復鄉在2025年9月馬太鞍溪堰塞湖溢流後仍在復原，出發前請查詢最新開放與道路狀況。位於光復鄉糖廠街7巷的花蓮糖廠宿舍區，官方資料未載開放時間，以外觀參觀為主；可搭臺鐵花東線至光復站。","dialogue":[{"who":"A","text":"阿拉蕾，想像一下，從工廠下班，過個鐵道就到家，看病、上學也都在同一區。"},{"who":"R","text":"這不就是超級社區嗎？連出門找路都省了。"},{"who":"A","text":"沒錯，大和工場的規劃由北到南是工廠、辦公室、鐵道、宿舍、醫院和學校，像一條生活輸送帶。"},{"who":"R","text":"那這棟7巷5、7號在輸送帶的哪一格？"},{"who":"A","text":"在宿舍群裡，而且是最早期興建的雙併丙種宿舍，官方說它是規格化營建技術的前驅。"},{"who":"R","text":"規格化？聽起來像在做糕餅，一個模子壓出一整排。"},{"who":"A","text":"這個比喻我給一百分，等一下就請你吃糖廠冰品當獎勵。"},{"who":"R","text":"一言為定！那到現場我要觀察什麼？"},{"who":"A","text":"請你把這棟和同巷1、3號放在同一個畫面裡，比比看屋頂和窗戶是不是同一個模子！"}],"clues":["從我身上可以看出整座工廠由北到南的規劃","我是最早期興建的雙併丙種宿舍之一","我在光復鄉糖廠街7巷，門牌是5號和7號"],"quiz":[{"q":"大和工場廠區由北到南，鐵道後面接的是什麼？","options":["學校","醫院","宿舍群","生產工廠"],"answer":2,"explain":"順序是工廠、辦公室、鐵道、宿舍群、醫院、學校。"},{"q":"官方認為這類宿舍是哪種技術的前驅？","options":["規格化營建","鋼構建築","紅磚拱造","預鑄混凝土"],"answer":0,"explain":"糖廠宿舍被視為規格化營建技術的前驅。"}],"images":[]},{"id":"shoufeng-gangtingshouxun","name":"原花蓮港廳壽尋常高等小學校奉安殿（福德宮）","short":"壽小學校奉安殿","category":"歷史建築","level":"","town":"壽豐鄉","types":["其他設施"],"lat":23.874306,"lng":121.516572,"address":"花蓮縣壽豐鄉共和村大同路33號東北方","announced":"2025-07-04","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20250804000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-03-07/313bd61f-778d-4b25-a256-99bc3fe56418/S__37666891_0.jpg","year":1925,"yearText":"日治時期，不早於1922年（大正11年）","era":"japan","themes":["教育運動","宗教信仰","神社遺構"],"yearUnknown":false,"summary":"供奉天皇照片的奉安殿，戰後變土地公廟","intro":"原花蓮港廳壽尋常高等小學校奉安殿位於壽豐鄉共和村大同路，鄰近退輔會花蓮農場。奉安殿是日治時期學校用來供奉「教育敕語」與天皇、皇后「御真影」的獨立建築，是奉安設備中保護層級最高、造價最貴的一種。壽小學校前身為1910年設立的吳全城分教場，1914年獨立為賀田尋常高等小學校，1922年遷到壽村並改名。戰後學校廢校、校舍全拆，只有奉安殿改為福德祠奉祀土地公而留存。它是混凝土造並施以洗石子，仿「神明造」神社式樣，屋頂改成臺灣廟宇的燕尾脊瓦頂，門上仍留有日本皇室的「五七桐紋」，2025年登錄為歷史建築。","highlights":["門上保留的日本皇室五七桐紋","仿神明造神社樣式的洗石子混凝土殿身","戰後改成的臺灣廟宇燕尾脊屋頂"],"funFact":"官方資料指出，全臺日治奉安殿大多已拆毀或只剩基座，能完整留存的屈指可數。","photoSpot":"正面拍桐紋門楣與燕尾脊屋頂同框","visitMin":15,"openNote":"位於壽豐鄉共和村大同路一帶，現為地方土地公廟，官方資料未載開放時間。參觀時請尊重廟方與信眾。距臺鐵壽豐站車程約5分鐘。","dialogue":[{"who":"R","text":"Allan，這座土地公廟好奇怪，屋頂是燕尾，下面卻像一座小神社！"},{"who":"A","text":"觀察力滿分！它原本是壽小學校的奉安殿，戰後才改成福德祠拜土地公。"},{"who":"R","text":"奉安殿？聽起來好神秘，它是做什麼用的？"},{"who":"A","text":"日治時期學校用來供奉教育敕語和天皇、皇后照片的獨立小屋，是最高等級的奉安設備。"},{"who":"R","text":"那原本的學校呢？校舍現在還在嗎？"},{"who":"A","text":"戰後學校廢校，校舍全部拆掉，只剩它因為變成土地公廟而留了下來。"},{"who":"R","text":"原來是土地公保佑它！這下真的是神明加持。"},{"who":"A","text":"哈，說得一點也沒錯。官方說全臺的奉安殿大多已拆毀或只剩基座，留得下來很不容易。"},{"who":"R","text":"那大家抬頭看看廟門上方，找找日本皇室的五七桐紋，拍一張跟燕尾屋頂同框的照片！"}],"clues":["我原本供奉的是一張照片和一份敕語","我屋頂是燕尾脊，門上卻有皇室的桐紋","我是學校留下的唯一建築，現在住著土地公"],"quiz":[{"q":"奉安殿在日治時期的用途是什麼？","options":["存放學生作業","當作校長辦公室","放置體育器材","供奉教育敕語與御真影"],"answer":3,"explain":"奉安殿用來供奉教育敕語與天皇、皇后御真影。"},{"q":"戰後這座奉安殿被改成什麼？","options":["派出所","教堂","福德祠","倉庫"],"answer":2,"explain":"戰後改為福德祠，奉祀土地公而保存下來。"}],"images":[]},{"id":"guangfu-xiangbeifucunfu2","name":"光復鄉北富村富田納骨碑","short":"太巴塱富田納骨碑","category":"歷史建築","level":"","town":"光復鄉","types":["碑碣"],"lat":23.660676,"lng":121.454201,"address":"花蓮縣光復鄉北富村富強街22 號","announced":"2002-09-23","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020923000008","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-02-18/afc50130-45a1-494c-8664-02b9c79a22da/h光復-富田納骨碑07.jpg","year":1925,"yearText":"1925年（大正14年）","era":"japan","themes":["原住民族文化","墓葬碑碣"],"yearUnknown":false,"summary":"安放太巴塱先人遺骨的莊嚴碑亭","intro":"富田納骨碑位於光復鄉北富村富強街一帶的六角亭中。日治時期太巴塱一度改名「富田」，這附近原是阿美族先人的亂葬墳地。據《縣志》記載，1925年撤除太巴塱的「首棚」，也就是陳列頭骨的架子，將遺骨等物集中安放於此，立碑紀念以供憑弔。碑身正面陰刻「納骨碑」字樣，碑高105公分，向後傾斜約3度，外觀比馬太鞍納骨碑低矮短小；基座現改為花崗石板。它雖是日治時期修造，碑石、石階與基座仍保存完整，與原住民族的記憶密切相關，2002年登錄為歷史建築。","highlights":["六角錐形屋頂的納骨碑亭","正面陰刻「納骨碑」的碑身","向後傾斜約3度的碑體與石階"],"funFact":"富田納骨碑碑高105公分，向後傾約3度，官方資料特別記載它比馬太鞍納骨碑低矮短小。","photoSpot":"在亭外遠處靜靜拍下碑亭全景","visitMin":10,"openNote":"位於光復鄉北富村富強街，為族人先人安息與憑弔之所，請保持肅靜、勿攀爬或嬉戲。光復鄉在2025年9月馬太鞍溪堰塞湖溢流後仍在復原，出發前請查詢最新開放與道路狀況。","dialogue":[{"who":"A","text":"接下來這個地方，請大家放輕腳步。這裡是太巴塱的富田納骨碑。"},{"who":"R","text":"好的，我會小聲一點。Allan，這座碑是為誰立的呢？"},{"who":"A","text":"這附近原是阿美族先人的墳地，1925年撤除首棚後，遺骨集中安放在這裡。"},{"who":"R","text":"首棚是什麼呢？我是第一次聽到這個詞。"},{"who":"A","text":"依縣志記載，是部落過去陳列頭骨的架子。日治時期撤除，並在此立碑供人憑弔。"},{"who":"R","text":"所以這裡是讓族人追思先人的地方，要好好尊重。"},{"who":"A","text":"沒錯。碑高105公分，向後微微傾斜約3度，像一位安靜守候的長者。"},{"who":"R","text":"我會在亭子外面靜靜站一下，看看碑上刻的三個字就好。"},{"who":"A","text":"很好。請在亭外默默看一眼碑身，向這片土地的先人致上敬意。"}],"clues":["我的碑身向後傾斜約3度，比馬太鞍的同伴矮小","1925年部落首棚撤除後，遺骨集中安放於我這裡","我在光復鄉北富村的六角亭中，供族人憑弔"],"quiz":[{"q":"富田納骨碑的碑高大約是多少？","options":["55公分","105公分","205公分","305公分"],"answer":1,"explain":"官方記載碑高105公分，並向後傾斜約3度。"},{"q":"依縣志記載，1925年撤除了什麼，遺骨才集中安放於此？","options":["古井","神社","學校","首棚"],"answer":3,"explain":"1925年撤除首棚，遺骨集中於此立碑紀念。"}],"images":[]},{"id":"jian-taiwanzongdufu","name":"臺灣總督府專賣局花蓮支局吉野村煙草耕作指導員駐在所","short":"吉野煙草指導所","category":"歷史建築","level":"","town":"吉安鄉","types":["辦公廳舍"],"lat":23.974001,"lng":121.563753,"address":"花蓮縣吉安鄉吉安鄉吉安路二段136號","announced":"2015-12-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20151229000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-24/94555866-062f-42fa-917f-405faa3eb815/d吉安-吉野煙草耕作指導所03.jpg","year":1927,"yearText":"1927年（昭和2年）初建，1961年北側改建","era":"japan","themes":["日治移民村","產業遺產"],"yearUnknown":false,"summary":"見證吉野村菸草產業的指導員駐在所","intro":"臺灣總督府專賣局花蓮支局吉野村煙草耕作指導員駐在所位於吉安鄉吉安路二段，坐落在吉野移民村的「中園」，也就是當年官署集中的地方。總督府專賣局在此推廣黃色種煙草，指導移民種植，是吉野村產業經濟的重要設施。現存南側木造建物遺構最初建於1927年，2013年拆除，但保留日治時期的布基礎與水泥鋪面，可與史料中的工事圖一一對照；北側磚木混合主體則在1961年改建。戰後土地由臺灣省菸酒公賣局使用，曾登記為「公賣局花連菸葉加工廠」。門窗上方設有旋轉窗，下段用霧面玻璃，2015年登錄為歷史建築。","highlights":["北側砌磚牆體與批簷的磚木混合建築","南側保留的日治布基礎與水泥鋪面","門窗上方通風採光用的旋轉窗"],"funFact":"調查時在建築殘構的木構件上，發現了日治時期材料出廠的墨字。","photoSpot":"在吉安路二段側拍切妻屋頂與舊門窗","visitMin":15,"openNote":"位於吉安鄉吉安路二段，與吉安慶修院相距約百公尺，官方資料未載開放時間，目前以外觀參觀為主。距臺鐵吉安站車程約5分鐘，可與慶修院、吉野開村記念碑串遊。","dialogue":[{"who":"A","text":"阿拉蕾，從慶修院走過來沒幾步，這棟小房子以前可是管菸草的。"},{"who":"R","text":"管菸草？難道是在這裡偷偷賣香菸嗎？"},{"who":"A","text":"不是賣，是教種。總督府專賣局在吉野村推廣黃色種煙草，指導員就駐在這裡。"},{"who":"R","text":"原來移民除了種稻，還要種菸草賺錢。"},{"who":"A","text":"對，這是吉野村產業經濟的重要設施。南側最早的木造建物1927年就蓋好了。"},{"who":"R","text":"可是這棟房子看起來是磚造的，不是木造耶？"},{"who":"A","text":"眼睛很利！北側是1961年改建的磚木混合建築，南側木屋2013年拆了，只留下日治的基礎。"},{"who":"R","text":"所以一棟房子裡藏著兩個時代，好像疊疊樂。"},{"who":"A","text":"形容得好。你去看看門窗上方，找找那種可以轉動通風的旋轉窗，數數看總共有幾扇！"}],"clues":["我身上有兩個時代：南邊的日治基礎和北邊1961年的磚牆","我曾經指導移民種植一種黃色品種的經濟作物","我在吉野村中園，是專賣局的駐在所"],"quiz":[{"q":"這處駐在所當年指導移民種植什麼作物？","options":["甘蔗","茶葉","樟樹","黃色種煙草"],"answer":3,"explain":"總督府專賣局在吉野村推廣黃色種煙草。"},{"q":"駐在所北側的磚木混合主體是哪一年改建的？","options":["1927年","1945年","1961年","2013年"],"answer":2,"explain":"北側主體於1961年改建，南側則保留日治基礎。"}],"images":[]},{"id":"hualian-jiuhualianganggao","name":"舊花蓮港高等女學校校長宿舍","short":"花女校長宿舍","category":"歷史建築","level":"","town":"花蓮市","types":["其他設施"],"lat":23.979923,"lng":121.614592,"address":"花蓮縣花蓮市花蓮市菁華街11號","announced":"2006-11-02","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20061102000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-27/b9d70667-e4b7-4a6e-bfa7-56ddb242f588/c花蓮-花女校長宿舍08.jpg","year":1929,"yearText":"1929年（昭和4年）","era":"japan","themes":["職務宿舍","教育運動","日式建築"],"yearUnknown":false,"summary":"檜木打造的高女校長宿舍，今為花女校史館","intro":"花蓮女中創校於1927年，當時名為花蓮港高等女學校，校長宿舍1929年建於今花蓮市菁華街。依建築面積屬「高等官舍第三種」，官方比喻其等級相當於今日鄉鎮市長公館，可見當時高女校長的社會地位。宿舍為全棟檜木的日式木造建築，外牆使用防雨又隔溫的雨淋板。戰後成為花蓮女中歷任校長宿舍，約1971年後校長另覓居所，由一位資深國文老師入住多年，約1995年搬離後荒廢。2009年前後在學校與校友會努力下整修完成，規劃為花蓮女中校史館，館內保存日治時期存放「教育敕語」的奉安庫。","highlights":["全棟檜木與雨淋板外牆的日式木造宿舍","日治時期存放教育敕語的奉安庫","約587平方公尺、前後側院完整的庭院"],"funFact":"宿舍屬「高等官舍第三種」，官方資料說等級相當於今天的鄉鎮市長公館。","photoSpot":"在庭院樹下拍檜木宿舍的雨淋板外牆","visitMin":20,"openNote":"位於花蓮市菁華街，現為花蓮女中校史館，官方資料記載不定期舉辦展覽與活動，參觀前請先洽詢學校。附近有菁華林苑、將軍府等日式建築，步行可串遊。","dialogue":[{"who":"A","text":"阿拉蕾，這棟檜木房子，以前住的是花蓮港高等女學校的校長。"},{"who":"R","text":"高等女學校？就是現在的花蓮女中嗎？"},{"who":"A","text":"對，學校1927年創立，校長宿舍1929年蓋好，等級是高等官舍第三種。"},{"who":"R","text":"第三種是很厲害，還是普普通通？"},{"who":"A","text":"官方說相當於今天的鄉鎮市長公館，很有面子。我家要升到這個等級，大概要先中發票頭獎。"},{"who":"R","text":"那日本人離開以後，戰後是誰住在這裡呢？"},{"who":"A","text":"繼續給花女校長住，後來一位資深國文老師住了很多年，1995年左右搬走後就荒廢了。"},{"who":"R","text":"還好後來修好了，現在變成什麼？"},{"who":"A","text":"現在是花蓮女中校史館。進去以後，找找那座日治時期的奉安庫，看看它的門到底有多厚重！"}],"clues":["我曾經荒廢十多年，後來被校友們救了回來","我屬於高等官舍第三種，全棟用檜木蓋成","我是一所女子學校校長的家，現在變成校史館"],"quiz":[{"q":"花蓮港高等女學校校長宿舍現在作什麼用途？","options":["縣府招待所","咖啡館","教師宿舍","花蓮女中校史館"],"answer":3,"explain":"整修完成後規劃為花蓮女中校史館。"},{"q":"校史館裡保存了什麼日治時期設備？","options":["防空警報器","鐵道號誌","奉安庫","釀酒古井"],"answer":2,"explain":"館內保存存放教育敕語的奉安庫。"}],"images":[{"file":"舊花蓮港高等女學校校長宿舍.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/%E8%88%8A%E8%8A%B1%E8%93%AE%E6%B8%AF%E9%AB%98%E7%AD%89%E5%A5%B3%E5%AD%B8%E6%A0%A1%E6%A0%A1%E9%95%B7%E5%AE%BF%E8%88%8D.jpg/960px-%E8%88%8A%E8%8A%B1%E8%93%AE%E6%B8%AF%E9%AB%98%E7%AD%89%E5%A5%B3%E5%AD%B8%E6%A0%A1%E6%A0%A1%E9%95%B7%E5%AE%BF%E8%88%8D.jpg","page":"https://commons.wikimedia.org/wiki/File:%E8%88%8A%E8%8A%B1%E8%93%AE%E6%B8%AF%E9%AB%98%E7%AD%89%E5%A5%B3%E5%AD%B8%E6%A0%A1%E6%A0%A1%E9%95%B7%E5%AE%BF%E8%88%8D.jpg","artist":"☼ うみ 目覚めたら from Taipei, Taiwan","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","local":"img/hualian-jiuhualianganggao-0.webp","small":"img/hualian-jiuhualianganggao-0-s.webp"}]},{"id":"hualian-ganggongxuexiao","name":"花蓮港公學校校長宿舍","short":"明禮國小校長宿舍","category":"歷史建築","level":"","town":"花蓮市","types":["宅第"],"lat":23.979762,"lng":121.6102,"address":"花蓮縣花蓮市花蓮市明禮路31號","announced":"2018-06-12","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20180704000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-27/edeed79e-b96e-4cbb-892f-cfbd816a8f15/c花蓮-明禮路31號日式宿舍01.jpg","year":1929,"yearText":"昭和初期，1929年（昭和4年）已有校長住此","era":"japan","themes":["職務宿舍","教育運動","日式建築"],"yearUnknown":false,"summary":"撐過1951年大地震的百年校長宿舍","intro":"花蓮港公學校校長宿舍位於花蓮市明禮路，屬明禮國小。明禮國小創立於1897年，最初是「臺東國語傳習所奇萊分教場」，1903年改名花蓮港公學校，1968年才改為現名。宿舍約在昭和初期竣工，1929年第三任校長坂木茂的履歷已登記住在這裡。它是單棟獨戶的高等第四種官舍，符合1922年「臺灣總督府官舍建築標準」，主體為寄棟式屋頂、入口為切妻式屋頂，外牆雨淋板，院內還有假山、水池等庭園遺跡。1951年花蓮大地震讓學校三分之二校舍倒塌，宿舍僅內部受損，修繕後繼續使用，戰後校長還增建了緣側與浴室廚房，2018年登錄為歷史建築。","highlights":["寄棟式主屋頂搭配切妻式入口屋頂","院內日治時期的假山與水池遺跡","室內保存完整的建具與欄間"],"funFact":"1951年花蓮大地震震垮了學校三分之二的校舍和隔壁職員宿舍，這棟校長宿舍卻只有內部受損。","photoSpot":"在明禮路側拍入口的切妻式小屋頂","visitMin":15,"openNote":"位於花蓮市明禮路明禮國小一帶，官方資料未載開放時間，目前以外觀參觀為主，進入校園請遵守學校規定。距臺鐵花蓮站車程約10分鐘，周邊日式宿舍可步行串遊。","dialogue":[{"who":"A","text":"阿拉蕾，你知道明禮國小以前叫什麼嗎？名字可多了，我一口氣唸給你聽。"},{"who":"R","text":"好啊，我已經準備好用十根手指頭來數了！"},{"who":"A","text":"1897年叫臺東國語傳習所奇萊分教場，1903年改叫花蓮港公學校，1968年才叫明禮國小。"},{"who":"R","text":"改名改這麼多次，學生畢業證書都不知道要寫哪個了！"},{"who":"A","text":"這棟就是當年公學校的校長宿舍，1929年第三任坂木茂校長的履歷已經登記住在這裡。"},{"who":"R","text":"它看起來好堅固，經歷過什麼大事嗎？"},{"who":"A","text":"1951年花蓮大地震，學校三分之二校舍倒了，隔壁職員宿舍全倒，它只是內部受損，修好繼續用。"},{"who":"R","text":"好強！那後來住的校長有改過它嗎？"},{"who":"A","text":"有，增建了緣側和浴室廚房，還拿掉榻榻米。到現場找找看，院子裡的假山和水池遺跡在哪裡！"}],"clues":["1951年大地震時，我身邊的房子倒了，我卻撐了下來","我屬於高等第四種官舍，院子裡有假山和水池","我是明禮路上一所百年小學的校長之家"],"quiz":[{"q":"明禮國小最早的名稱是什麼？","options":["花蓮港小學校","明治國民學校","花蓮港廳立中學校","臺東國語傳習所奇萊分教場"],"answer":3,"explain":"1897年創立時名為臺東國語傳習所奇萊分教場。"},{"q":"1951年花蓮大地震時，這棟校長宿舍的狀況是？","options":["完全倒塌","屋頂被吹走","只有內部受損","沉入地下"],"answer":2,"explain":"學校三分之二校舍毀損，宿舍僅內部受損。"}],"images":[]},{"id":"guangfu-xiangdahuacungucuo","name":"光復鄉大華村古厝（益壽堂）","short":"益壽堂","category":"歷史建築","level":"","town":"光復鄉","types":["商店"],"lat":23.665849,"lng":121.423452,"address":"花蓮縣光復鄉大華村中正路1 段85 號","announced":"2002-09-23","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020923000009","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-02-18/b16f1553-6f09-4285-8b3b-82acee2f2186/h光復-益壽堂01.jpg","year":1929,"yearText":"1929年（昭和4年）","era":"japan","themes":["客家文化","藝術文化"],"yearUnknown":false,"summary":"光復街上的仿巴洛克洋樓，還在當藥房","intro":"益壽堂位於光復鄉大華村中正路上，是桃園龍潭客家人張枝明攜眷到馬太鞍行醫時開設的藥房。事業興旺後，他在1929年從龍潭聘請師傅興建二層樓店面3間，是當時光復街上最新式的洋樓。外觀為仿巴洛克式，洗石子山牆立面配上樑柱與雕花，正三角形山牆帶花邊裝飾，中間刻著屋主姓氏「張」字，頂部左右各有一尊石獅；圓拱立窗之間的柱子寫有對聯。內部全為木造，屬臺灣傳統街屋組合形式。官方說明這樣的洋樓在東臺灣難得一見，至今一樓仍經營藥局。","highlights":["山牆中央浮雕的「張」字堂號","山牆頂部左右兩尊石獅","圓拱立窗之間的柱聯書法"],"funFact":"益壽堂從1929年蓋好至今，一樓仍在賣藥，算得上是光復街上很長壽的藥房。","photoSpot":"在對街仰拍山牆、石獅與張字","visitMin":10,"openNote":"位於光復鄉大華村中正路，一樓仍為營業中的藥局，二樓為私人住家，請在外觀欣賞，勿進入打擾。光復鄉在2025年9月馬太鞍溪堰塞湖溢流後仍在復原，出發前請查詢最新開放與道路狀況。","dialogue":[{"who":"R","text":"Allan，光復街上這棟有花邊山牆的洋樓好漂亮，是以前的銀行還是郵局嗎？"},{"who":"A","text":"不是銀行，是藥房，叫益壽堂，1929年蓋的，當年是光復街最新式的洋樓。"},{"who":"R","text":"益壽堂？名字聽起來吃了就能延年益壽！"},{"who":"A","text":"哈，屋主張枝明是從桃園龍潭來馬太鞍行醫的客家人，名字確實很吉利。"},{"who":"R","text":"他從那麼遠的桃園來到花蓮，房子還蓋得這麼氣派！"},{"who":"A","text":"他特地從龍潭請師傅來蓋，洗石子山牆加上花草雕花，是仿巴洛克式，裡面卻全是木造。"},{"who":"R","text":"那山牆正中間刻的那個大字，是什麼意思呢？"},{"who":"A","text":"是屋主的姓，張。一樓現在還在賣藥，別打擾店家，請在對街抬頭，找找山牆頂上左右兩尊石獅拍下來！"}],"clues":["我的山牆中央刻著屋主的姓氏，頂上有兩尊石獅","1929年由龍潭師傅打造的仿巴洛克二層洋樓","我是光復街上至今仍在營業的老藥房"],"quiz":[{"q":"益壽堂的屋主張枝明原本來自哪裡？","options":["桃園龍潭","新竹北埔","苗栗頭份","屏東內埔"],"answer":0,"explain":"張枝明是桃園龍潭客家人，到馬太鞍行醫。"},{"q":"益壽堂山牆中央刻著什麼字？","options":["壽","福","張","藥"],"answer":2,"explain":"山牆中間刻著屋主姓氏「張」字。"}],"images":[{"file":"XT2K2463X.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/52/XT2K2463X.jpg/960px-XT2K2463X.jpg","page":"https://commons.wikimedia.org/wiki/File:XT2K2463X.jpg","artist":"Taiwankengo","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","local":"img/guangfu-xiangdahuacungucuo-0.webp","small":"img/guangfu-xiangdahuacungucuo-0-s.webp"}]},{"id":"hualian-qianhualianhuoche","name":"前花蓮火車站加水塔","short":"舊花蓮站加水塔","category":"歷史建築","level":"","town":"花蓮市","types":["其他設施"],"lat":23.975365,"lng":121.6091,"address":"花蓮縣花蓮市六期重劃區內，光復街與成功街口","announced":"2004-03-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20040319000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-25/12a461de-6471-42a8-bead-0f2449d75497/c花蓮-加水塔04.jpg","year":1930,"yearText":"年代不詳","era":"unknown","themes":["鐵道交通"],"yearUnknown":true,"summary":"舊花蓮車站唯一留下的蒸汽火車加水塔","intro":"前花蓮火車站加水塔位於花蓮市光復街與成功街口。今中華路沿福町路以東，原是舊花蓮車站的場區，車站與機房等鐵路設施遷到現址後，舊場區大多拆除，鐵軌鋪成柏油路，就是今天的福町路。機關轉運等設備全數拆除，只有這組加水塔幸運留下，是舊站區唯一留存的鐵道設施元素。共兩座：一座是圓柱形加水塔，另一座以6支方形混凝土柱架高到約三層樓高的圓形水塔，見證蒸汽機車南來北往、在此加水的年代。","highlights":["6支方形混凝土柱撐起的圓形高架水塔","旁邊另一座圓柱形加水塔","由鐵軌改成的福町路"],"funFact":"今天的福町路原本是舊花蓮車站的鐵道，拆軌後才鋪成柏油路。","photoSpot":"在街口仰拍高架水塔與方柱","visitMin":10,"openNote":"位於花蓮市光復街與成功街口，屬戶外設施。官方資料記載原有餐廳遷離後現況以圍籬包覆，請在圍籬外觀看。可與鐵道文化園區步行串遊。","dialogue":[{"who":"R","text":"Allan，路口這兩座高高的圓柱是什麼？大型保溫杯嗎？"},{"who":"A","text":"哈，猜得有創意！這是舊花蓮車站留下來的蒸汽火車加水塔，一高一矮共兩座。"},{"who":"R","text":"火車也會口渴，需要停下來喝水嗎？"},{"who":"A","text":"蒸汽機車靠燒煤把水煮成蒸汽來前進，水用完就跑不動，所以這裡就是它們的補給站。"},{"who":"R","text":"原來是火車的飲水機！那原本的舊車站呢？還在附近嗎？"},{"who":"A","text":"車站和機房搬走後，場區幾乎全拆了，連鐵軌都鋪成柏油，就是今天的福町路。"},{"who":"R","text":"什麼都拆光了，只剩水塔撐下來，它也太堅強了吧！"},{"who":"A","text":"對，它是舊站區唯一留下的鐵道設施，現在用圍籬圍著。請你在圍籬外數一數，撐起那座高水塔的方形柱子有幾支！"}],"clues":["我有一座用6支方柱撐到三層樓高的圓形水箱","我旁邊的福町路，以前其實是鐵軌","我是舊花蓮車站給蒸汽機車補水的設施"],"quiz":[{"q":"撐起高架圓形水塔的是幾支方形混凝土柱？","options":["4支","6支","8支","3支"],"answer":1,"explain":"由6隻方形混凝土柱架高至三層樓高。"},{"q":"舊花蓮車站拆除鐵軌後，變成了今天的哪條路？","options":["中山路","中華路","福町路","成功街"],"answer":2,"explain":"鐵軌拆除後鋪上柏油，成為今日的福町路。"}],"images":[{"file":"前花蓮火車站加水塔.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/42/%E5%89%8D%E8%8A%B1%E8%93%AE%E7%81%AB%E8%BB%8A%E7%AB%99%E5%8A%A0%E6%B0%B4%E5%A1%94.JPG/960px-%E5%89%8D%E8%8A%B1%E8%93%AE%E7%81%AB%E8%BB%8A%E7%AB%99%E5%8A%A0%E6%B0%B4%E5%A1%94.JPG","page":"https://commons.wikimedia.org/wiki/File:%E5%89%8D%E8%8A%B1%E8%93%AE%E7%81%AB%E8%BB%8A%E7%AB%99%E5%8A%A0%E6%B0%B4%E5%A1%94.JPG","artist":"王彥翔","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/hualian-qianhualianhuoche-0.webp","small":"img/hualian-qianhualianhuoche-0-s.webp"}]},{"id":"shoufeng-xikoushihuiyao","name":"壽豐溪口石灰窯","short":"溪口石灰窯","category":"歷史建築","level":"","town":"壽豐鄉","types":["產業"],"lat":23.814891,"lng":121.464964,"address":"花蓮縣壽豐鄉壽豐鄉溪口村中山路一段77號後方約100公尺處","announced":"2010-06-17","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20100617000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-04-10/f52e982a-fbb4-4436-9733-d120cf5aedec/e壽豐-溪口石窯05.jpg","year":1930,"yearText":"日治時期（確切年代不詳）","era":"japan","themes":["產業遺產"],"yearUnknown":false,"summary":"被榕樹根緊緊抱住的日治石灰窯","intro":"壽豐溪口石灰窯位於壽豐鄉溪口村，台9線約229.5公里處附近，現存兩座建於日治時期的石灰窯。壽豐溪上游出產石灰石與白雲石等石灰原料，溪口村在日治時期就發展出石灰產業；1940年後，這裡出產的石灰石還遠送到新竹，供玻璃工廠在燒製過程中當作高溫穩定劑。兩座窯口相距約650公尺，1號窯進深較淺、開口較寬約210公分，2號窯進深較深、開口約180公分，都是砌石與混凝土構造，窯體完整。其中一座被盤根錯節的榕樹根包覆，呈現自然與時間交錯共生的景象，2010年登錄為歷史建築。","highlights":["被盤根錯節榕樹根包覆的石灰窯","兩座窯口大小不同，開口約210與180公分","砌石與混凝土構成的完整窯體"],"funFact":"溪口的石灰石在1940年後被送到新竹，當作玻璃工廠燒製玻璃時的高溫穩定劑。","photoSpot":"拍榕樹根纏繞窯口的特寫","visitMin":20,"openNote":"位於壽豐鄉溪口村中山路一段後方約100公尺，官方資料記載戶外空間隨時開放。兩座窯相距約650公尺，周邊為田野小路，建議開車走台9線前往。","dialogue":[{"who":"A","text":"阿拉蕾，看那棵大榕樹，它的根把整座石灰窯都抱住了，像不像一隻巨大的章魚？"},{"who":"R","text":"好像喔！可是石灰窯是做什麼用的？烤地瓜嗎？"},{"who":"A","text":"差很多，烤地瓜我比較在行。石灰窯是把石灰石燒成石灰，日治時期溪口村就有這個產業。"},{"who":"R","text":"那燒石灰用的石灰石，是從哪裡來的？"},{"who":"A","text":"壽豐溪上游出產石灰石和白雲石，運下山就在這裡燒，原料就在家門口。"},{"who":"R","text":"這裡燒好的石灰和石灰石，都用在哪裡呢？"},{"who":"A","text":"1940年後，溪口的石灰石還遠送到新竹，給玻璃工廠當高溫穩定劑，幫忙燒出漂亮的玻璃。"},{"who":"R","text":"原來花蓮的石頭跑去新竹變成玻璃，真是遠距離合作！"},{"who":"A","text":"這裡有兩座窯，開口一寬一窄。到現場比比看，哪一座的窯口比較寬！"}],"clues":["我身上纏滿了一棵大樹的根","我燒出的原料曾遠送新竹的玻璃工廠","我在壽豐溪口村，是日治時期的燒灰設施"],"quiz":[{"q":"1940年後，溪口村的石灰石被送到哪裡使用？","options":["基隆造船廠","新竹玻璃工廠","高雄水泥廠","臺北印刷廠"],"answer":1,"explain":"石灰石運到新竹，作為燒製玻璃的高溫穩定劑。"},{"q":"溪口石灰窯最特別的景觀是什麼？","options":["窯體被榕樹根包覆","窯頂長出竹林","窯口面向大海","窯旁有瀑布"],"answer":0,"explain":"其中一座窯被盤根錯節的榕樹根包覆。"}],"images":[]},{"id":"fenglin-xiaozhangmenggong","name":"校長夢工廠","short":"校長夢工廠","category":"歷史建築","level":"","town":"鳳林鎮","types":["宅第"],"lat":23.74759,"lng":121.450306,"address":"花蓮縣鳳林鎮鳳林鎮鳳智里民生街16號","announced":"2013-01-10","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20130110000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-04-11/1b009edb-fa8c-49f1-8e3e-3e4af270a166/g鳳林-校長夢工廠01.jpg","year":1930,"yearText":"年代不詳（日治時期鳳林支廳長官舍）","era":"unknown","themes":["職務宿舍","教育運動"],"yearUnknown":true,"summary":"東臺灣僅存的郡級官舍，述說鳳林出校長","intro":"校長夢工廠位於鳳林鎮，原為日治時期花蓮港廳鳳林支廳長的官舍，後隨行政區改變成為區、郡長官官舍。東臺灣直到1937年才和西部一樣改行郡制，鳳林郡轄鳳林街、瑞穗庄、新社庄等地，這棟是東臺灣僅存的郡級長官宿舍。戰後鳳林初中首任校長張七郎爭取作為校長宿舍，直到1986年第七任校長調職後閒置。2003年鳳林鎮公所爭取經費整修，成為地方文化館。張七郎與次任校長張宗仁父子興學，奠定「鳳林出校長」的傳統；張七郎父子三人在二二八事件中受難罹難，這段歷史也是這裡保存的意義之一。","highlights":["保留原始和式構造與入口門廳的木造官舍","歷屆校長奉獻故事的常設展","日治教育文史書籍與老打字用具"],"funFact":"東臺灣的州郡街庄制比西部晚了17年，西部1920年就改制，東部到1937年才跟上。","photoSpot":"在入口門廳前拍木造官舍正面","visitMin":30,"openNote":"位於鳳林鎮民生街，官方資料記載週二至週日08:30至12:00、13:30至17:00開放，有志工簡單解說。出發前請查詢。鳳林市區可步行，近臺鐵鳳林站。","dialogue":[{"who":"A","text":"鳳林有句話叫鳳林出校長，阿拉蕾，你猜這裡為什麼叫校長夢工廠？"},{"who":"R","text":"難道是在這裡睡一覺，醒來就變成校長？"},{"who":"A","text":"哈，那我早就搬進來了。這棟原本是日治時期鳳林支廳長的官舍，後來成為郡級長官宿舍。"},{"who":"R","text":"所以是大官住的房子，後來怎麼跟校長扯上關係？"},{"who":"A","text":"戰後鳳林初中首任校長張七郎爭取來當校長宿舍，一路住到1986年。"},{"who":"R","text":"原來如此，那位張七郎校長後來怎麼了呢？"},{"who":"A","text":"張七郎和兒子們在二二八事件中受難，但他們重視教育的精神，在鳳林留了下來。"},{"who":"R","text":"這段歷史好沉重，也讓人更想好好認識他們，還有鳳林重視教育的傳統。"},{"who":"A","text":"館裡有歷屆校長的故事，請找一找你最有共鳴的一位，記下他的一句話！"}],"clues":["我是東臺灣僅存的郡級長官宿舍","戰後一位初中校長爭取我當宿舍，一路用到1986年","鳳林出校長這句話，在我這裡變成了展覽"],"quiz":[{"q":"東臺灣在哪一年才改行州郡街庄制？","options":["1920年","1937年","1945年","1909年"],"answer":1,"explain":"西部1920年改制，東臺灣遲至1937年。"},{"q":"戰後爭取這棟官舍作為校長宿舍的是哪位校長？","options":["張宗仁","王協森","淺野安吉","張七郎"],"answer":3,"explain":"鳳林初中首任校長張七郎爭取作為校長宿舍。"}],"images":[{"file":"鳳林校長夢工廠.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f1/%E9%B3%B3%E6%9E%97%E6%A0%A1%E9%95%B7%E5%A4%A2%E5%B7%A5%E5%BB%A0.JPG/960px-%E9%B3%B3%E6%9E%97%E6%A0%A1%E9%95%B7%E5%A4%A2%E5%B7%A5%E5%BB%A0.JPG","page":"https://commons.wikimedia.org/wiki/File:%E9%B3%B3%E6%9E%97%E6%A0%A1%E9%95%B7%E5%A4%A2%E5%B7%A5%E5%BB%A0.JPG","artist":"Pbdragonwang","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/fenglin-xiaozhangmenggong-0.webp","small":"img/fenglin-xiaozhangmenggong-0-s.webp"}]},{"id":"yuli-antongwenquanlvshe","name":"安通溫泉旅舍","short":"安通溫泉旅舍","category":"歷史建築","level":"","town":"玉里鎮","types":["產業"],"lat":23.28119,"lng":121.3418,"address":"花蓮縣玉里鎮樂合里5鄰溫泉36號","announced":"2004-03-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20040319000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-02-18/1ae65c31-d8cc-421f-8c0d-03a495a9e58d/j玉里-安通溫泉05.jpg","year":1930,"yearText":"1930年（昭和5年）","era":"japan","themes":["日式建築","產業遺產"],"yearUnknown":false,"summary":"日治警察招待所起家的木造溫泉旅社","intro":"安通溫泉旅舍位於玉里鎮樂合里、玉長公路旁的安通溪畔。1904年一位上山採樟腦的日本人在溪畔發現溫泉露頭，1930年日本人在此興建警察招待所，也是花蓮港廳長行館，並設公共澡堂，逐漸發展成溫泉勝地。戰後由鎮公所接管開設「玉里溫泉公共浴場」，1974年由民間業者接手，改為安通溫泉大旅社，仍保留日治木造平房，以及刻有新舊名稱的舊匾額。「安通」源自阿美語形容硫磺臭味的詞，1917年日人改譯為安通。旅社為寄棟屋根的木造建築，日式水泥瓦保存完整。","highlights":["1930年木造旅社與完整的日式水泥瓦","正背面刻著新舊名稱的老匾額","洗石子玄關柱與轉角入口"],"funFact":"「安通」來自阿美語形容硫磺的「臭味」，溫泉的味道直接變成了地名。","photoSpot":"在庭院樹下拍木造旅社的水泥瓦屋頂","visitMin":60,"openNote":"官方資料記載溫泉營業時間為上午8時至晚上10時，實際以業者公告為準。位於玉里鎮樂合里玉長公路旁，建議開車前往。","dialogue":[{"who":"R","text":"Allan，我好像聞到一股奇怪的味道，你是不是又偷吃茶葉蛋？"},{"who":"A","text":"冤枉啊！這是硫磺味。安通這個地名，就是從阿美語形容硫磺臭味的詞來的。"},{"who":"R","text":"原來味道變成了地名，好直接！那這裡什麼時候開始泡湯？"},{"who":"A","text":"1904年有人上山採樟腦，發現溫泉露頭，1930年蓋了警察招待所，也是花蓮港廳長的行館。"},{"who":"R","text":"連廳長都來泡的溫泉，應該很高級吧！"},{"who":"A","text":"那棟1930年的木造旅社現在還在，屋頂的日式水泥瓦保存得很完整。"},{"who":"R","text":"那戰爭結束以後，這裡變成什麼樣子了？"},{"who":"A","text":"鎮公所先開了玉里溫泉公共浴場，1974年民間接手改名安通溫泉大旅社，還把新名字刻在舊匾額背後。"},{"who":"R","text":"一塊匾額兩個名字，太會省了吧！我要去找那面匾額，看看兩面各寫了什麼！"}],"clues":["我的名字來自阿美語形容硫磺臭味的詞","我曾是日治警察招待所，也是花蓮港廳長行館","我是玉里安通溪畔1930年的木造溫泉旅社"],"quiz":[{"q":"「安通」這個地名源自什麼？","options":["日本人的姓氏","清代營盤名稱","阿美語形容硫磺臭味的詞","客家語的溪名"],"answer":2,"explain":"源自阿美語形容硫磺「臭味」的詞。"},{"q":"安通溫泉的木造旅社建於哪一年？","options":["1904年","1917年","1974年","1930年"],"answer":3,"explain":"1930年興建警察招待所，旅社為當年木造建築。"}],"images":[{"file":"Antong hot spring hotel.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2a/Antong_hot_spring_hotel.jpg/960px-Antong_hot_spring_hotel.jpg","page":"https://commons.wikimedia.org/wiki/File:Antong_hot_spring_hotel.jpg","artist":"Yusuke Kawasaki","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","local":"img/yuli-antongwenquanlvshe-0.webp","small":"img/yuli-antongwenquanlvshe-0-s.webp"}]},{"id":"yuli-xinyongzuhejicang","name":"玉里信用組合及倉庫群","short":"玉里信用組合","category":"歷史建築","level":"","town":"玉里鎮","types":["產業"],"lat":23.33823,"lng":121.315154,"address":"花蓮縣玉里鎮玉里鎮中華路179號","announced":"2006-12-28","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20061228000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-02-18/27d76363-3913-4480-a84b-7ce43a2e518d/j玉里-信用組合舊址04.jpg","year":1930,"yearText":"約1930年代建成（組合1917年成立）","era":"japan","themes":["公共建築","產業遺產"],"yearUnknown":false,"summary":"玉里第一個金融機構的新古典辦公樓","intro":"玉里信用組合及倉庫群位於玉里鎮中華路。1917年5月，玉里支廳地方士紳徐乾錦與松尾溫爾等日籍人士依「產業組合法」合組有限責任玉里信用組合，是玉里第一個金融機構，經營存放款業務。1919年因業務不振改組為保證責任玉里信用購買販賣利用組合，增加購買、販賣等事業，經營漸上軌道。1944年各類組合合併為「玉里街農業會」，接收這棟辦公大樓。建物約建於1930年代，是花蓮早期的鋼筋混凝土建築，外型方正對稱，門廊有四根洗石子希臘式圓柱，融合近代建築與新古典樣式。","highlights":["門廊的四根洗石子希臘式圓柱","出簷的丁掛與圓拱齒狀洗石子裝飾","一樓沒有隔間、只靠方柱支撐的大空間"],"funFact":"玉里信用組合1917年成立，是玉里第一個金融機構，但兩年後就因業務不振而改組。","photoSpot":"站在對街拍對稱立面與門廊圓柱","visitMin":15,"openNote":"位於玉里鎮中華路，官方資料未載開放時間，以外觀參觀為主。可搭臺鐵花東線至玉里站，市區景點可步行串遊。","dialogue":[{"who":"R","text":"Allan，這棟有圓柱的房子好氣派，是銀行嗎？"},{"who":"A","text":"差不多喔！它是玉里信用組合，1917年成立時是玉里第一個金融機構，負責存款和放款。"},{"who":"R","text":"玉里第一間銀行！那你在這裡存了多少錢？"},{"who":"A","text":"我存的都是冷笑話，利息是大家的白眼。說正經的，它1919年因業務不振改組，加入購買販賣事業，才慢慢步上軌道。"},{"who":"R","text":"那這棟氣派的大樓是什麼時候蓋的？"},{"who":"A","text":"大約1930年代，是花蓮早期的鋼筋混凝土建築，門廊有四根洗石子希臘式圓柱。"},{"who":"R","text":"那到了戰爭末期，它變成什麼單位？"},{"who":"A","text":"1944年各種組合合併成玉里街農業會，接收了這棟大樓。請你站在門廊前數數圓柱，再找找屋簷下的齒狀裝飾！"}],"clues":["我1919年因業務不振改組，加入購買販賣事業","我的門廊有四根洗石子希臘式圓柱","我是玉里第一個金融機構的辦公大樓"],"quiz":[{"q":"玉里信用組合在哪一年成立？","options":["1909年","1917年","1930年","1944年"],"answer":1,"explain":"1917年5月29日合組有限責任玉里信用組合。"},{"q":"1944年接收這棟大樓的是哪個單位？","options":["玉里街農業會","花蓮港廳廳舍","臺灣銀行","專賣局出張所"],"answer":0,"explain":"各類組合合併為玉里街農業會並接收大樓。"}],"images":[]},{"id":"hualian-fuzhuqiaojidierfu","name":"福住橋暨第二福住橋","short":"福住橋","category":"歷史建築","level":"","town":"花蓮市","types":["橋樑"],"lat":23.967425,"lng":121.608843,"address":"花蓮縣花蓮市和平路與南濱路交叉口","announced":"2013-01-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20140221000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-25/a20ce5b4-dcf9-4d68-acbf-d86a64ba4c84/c花蓮-自由街橋13.jpg","year":1931,"yearText":"1931年（昭和6年）開通","era":"japan","themes":["水利設施","公共建築"],"yearUnknown":false,"summary":"溝仔尾繁華記憶的兩座洗石子小橋","intro":"福住橋暨第二福住橋原本跨越花蓮市溝仔尾南京街與成功街交叉處的大排水溝。日治時期這一帶稱「福住通」，緊鄰花蓮港驛與臨港鐵路，旅館、酒樓、茶室、戲院林立，是當時花蓮最熱鬧的地區之一，繁華延續到戰後。依1931年《臺灣日日新報》記載，花蓮港街排水護岸工程竣工，福住橋同月開通。兩橋為水泥造、外覆洗石子，造型典雅，第二福住橋北側橋頭柱上仍留有日文草寫橋名。2013年登錄歷史建築，2015年因自由大排防洪需要，縣府將兩橋遷到南濱一帶公園保存，是花蓮市街排水與都市發展的見證。","highlights":["外覆洗石子的典雅橋頭柱","第二福住橋橋頭柱上的日文草寫橋名","橋名與竣工日期被抹去後殘留的字形"],"funFact":"第二福住橋的橋頭柱寫的是日文平假名「ふくすみはし」，而且是草寫，相當美觀。","photoSpot":"蹲低拍橋頭柱上的日文草寫字跡","visitMin":15,"openNote":"兩橋已從溝仔尾原址遷移，官方資料記載位於花蓮市和平路與南濱路口一帶，隨時開放；後續規劃安置於南濱滯洪池公園，確切位置請以現場為準。從臺鐵花蓮站開車或騎車約10分鐘。","dialogue":[{"who":"A","text":"阿拉蕾，你看這兩座小橋，底下沒有水，可是它們以前真的跨過一條大水溝喔。"},{"who":"R","text":"橋被搬家了？橋也能像人一樣搬家喔？"},{"who":"A","text":"可以啊。它們原本在溝仔尾南京街和成功街交叉口，2015年為了自由大排防洪，才搬到南濱這一帶。"},{"who":"R","text":"那這兩座小橋是什麼時候蓋好的呢？"},{"who":"A","text":"1931年的報紙記載，排水護岸工程完工，福住橋就開通了，到現在快一百歲了。"},{"who":"R","text":"福住這兩個字好吉利，以前這裡很熱鬧嗎？"},{"who":"A","text":"日治時期叫福住通，就在花蓮港驛後面，旅館、酒樓、戲院林立，熱鬧到晚上都不想回家。"},{"who":"R","text":"Allan你是說你自己吧！那現在要看什麼？"},{"who":"A","text":"去第二福住橋北側的橋頭柱找找看，上面有一行日文草寫的橋名，拍下來比比看字有多漂亮！"}],"clues":["我曾跨越溝仔尾的大排水溝，2015年被整座搬家","我身上有日文草寫，記得1931年開通的那一天","我名字裡有福也有住，是一對兄弟橋"],"quiz":[{"q":"福住橋為什麼在2015年遷移？","options":["道路拓寬需要","橋身遭颱風沖毀","要搬進博物館展示","自由大排防洪需要"],"answer":3,"explain":"為了自由大排治災防洪與居民安全，縣府將兩橋遷移。"},{"q":"第二福住橋的橋頭柱上留有什麼？","options":["英文橋名","清代石刻對聯","日文草寫橋名","阿美族圖騰"],"answer":2,"explain":"北側橋頭柱上保留完整的日文草寫橋名。"}],"images":[]},{"id":"guangfu-xiangmataianbuluo","name":"光復鄉馬太鞍部落納骨碑","short":"馬太鞍納骨碑","category":"歷史建築","level":"","town":"光復鄉","types":["碑碣"],"lat":23.675529,"lng":121.430624,"address":"花蓮縣光復鄉太平村延平街79巷北側","announced":"2002-09-23","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020923000006","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-02-18/5053b1b6-d21f-4cae-ba44-cc317804e05f/h光復-馬太鞍納骨碑07.jpg","year":1931,"yearText":"1931年（昭和6年）","era":"japan","themes":["原住民族文化","墓葬碑碣"],"yearUnknown":false,"summary":"馬太鞍族人收葬先人遺骨的追思之地","intro":"馬太鞍部落納骨碑位於光復鄉太平村延平街一帶。過去部落內因械鬥或疾病過世、無人收埋的遺骨，以及無人認領的刀、鏢槍、弓箭與生活器具，由族人收集，經年累月堆置在名為「布農安」的地方掩埋，供族人弔祭。1931年花蓮港廳長淺野安吉為撫靈，由官署撥款重修，並新建具紀念性的納骨碑。納骨碑隱身在農田與檳榔園之間，從路口往內約40公尺可到，周邊目前無人管理。它雖為日治時期所建，整體格局尚佳，對馬太鞍的原住民族歷史具有意義，2002年登錄為歷史建築。","highlights":["1931年興建的紀念性納骨碑","族人收葬先人遺骨與遺物的「布農安」","隱身農田與檳榔園間的靜謐環境"],"funFact":"族人收集的不只有遺骨，還有無人認領的刀、鏢槍、弓箭與生活器具，一併安放供弔祭。","photoSpot":"在小徑入口遠拍碑體，勿踩踏周邊","visitMin":10,"openNote":"位於光復鄉太平村延平街一帶，為室外空間，周邊為農田與檳榔園且無人管理，請保持肅靜、勿踩踏農地。光復鄉在2025年9月馬太鞍溪堰塞湖溢流後仍在復原，出發前請查詢最新開放與道路狀況。","dialogue":[{"who":"R","text":"Allan，這條小路走進去好安靜，前面是什麼地方呢？"},{"who":"A","text":"這裡是馬太鞍部落納骨碑，是族人追思先人的地方，我們放慢腳步。"},{"who":"R","text":"好的，我會輕聲說話。Allan，這裡為什麼會有一座納骨碑呢？"},{"who":"A","text":"過去部落裡因械鬥或疾病過世、無人收埋的先人遺骨，族人都收集到這裡安葬。"},{"who":"R","text":"連沒有人收埋的人，族人也照顧到了，好讓人感動。"},{"who":"A","text":"是的，還有刀、弓箭和生活器具一起安放。1931年官署撥款重修並立了這座碑。"},{"who":"R","text":"原來這座碑背後，是族人一代一代的守護。"},{"who":"A","text":"說得很好，這份守護就像田埂邊默默流過的溪水，安靜卻從不間斷。"},{"who":"R","text":"到了現場，我會在碑前停一下，安靜地鞠個躬再離開。"}],"clues":["族人把無人認領的刀、弓箭與器具也一起安放在這裡","1931年花蓮港廳長為撫靈撥款重修並立碑","我隱身在光復鄉太平村的農田與檳榔園間"],"quiz":[{"q":"馬太鞍納骨碑是在哪一年由官署撥款新建？","options":["1916年","1925年","1945年","1931年"],"answer":3,"explain":"1931年花蓮港廳長淺野安吉撥款重修並立碑。"},{"q":"族人收集遺骨與遺物後掩埋的地方叫什麼？","options":["拉度倫","布農安","拉鼓娃","達固湖灣"],"answer":1,"explain":"遺骨與遺物經年累月堆置於「布農安」掩埋。"}],"images":[]},{"id":"hualian-jiaotongbutaitie","name":"交通部台鐵管理局花蓮管理處","short":"鐵道文化園區一館","category":"歷史建築","level":"","town":"花蓮市","types":["辦公廳舍"],"lat":23.974639,"lng":121.610583,"address":"花蓮縣花蓮市花蓮市中山路71 號","announced":"2002-09-23","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020923000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-27/9e5fd6b8-0c50-49f7-8324-f0ca176da5d7/c花蓮-台鐵管理局06.jpg","year":1932,"yearText":"1932年（昭和7年）改建","era":"japan","themes":["鐵道交通","日式建築","公共建築"],"yearUnknown":false,"summary":"尖塔屋頂的東線鐵道指揮中心","intro":"交通部台鐵管理局花蓮管理處位於花蓮市中山路，前身是1909年設立的鐵道部花蓮港出張所，負責興建臺東線鐵路及通車後營運，地位如同東部的小交通部。現存木造建築於1932年改建，以檜木建造，採四合院格局的日式辦公廳舍，佔地約1140坪，以廊道串聯；正廳屋頂的仿哥德式尖塔是最大特色。1943年改組為鐵道部花蓮港事務所，1959年改為臺灣鐵路管理局花蓮管理處，1988年裁撤。今為花蓮鐵道文化園區一館，園區內還有表演舞臺與前後院防空洞。","highlights":["正廳屋頂的仿哥德式尖塔","以廊道串聯的四合院式日式木造廳舍","前後院各一座防空洞"],"funFact":"鐵道部花蓮港出張所的經費曾由國會直接撥給，不經總督府，所以被形容是東部的「小交通部」。","photoSpot":"在中庭仰拍尖塔與木造屋頂","visitMin":45,"openNote":"位於花蓮市中山路，今花蓮鐵道文化園區一館，官方資料記載週二至週日9:00至17:00開放、週一休館，以現場公告為準。距花蓮舊市區景點很近，可與舊工務段、加水塔步行串遊。","dialogue":[{"who":"A","text":"阿拉蕾，抬頭看！這座尖尖的屋頂，就是東部鐵道的指揮中心。"},{"who":"R","text":"好像童話裡的小城堡喔！這裡是車站嗎？"},{"who":"A","text":"不是車站，是1909年設立的鐵道部花蓮港出張所，負責蓋臺東線鐵路，像東部的小交通部。"},{"who":"R","text":"小交通部！那現在這棟房子是1909年的嗎？"},{"who":"A","text":"現在的木造建築是1932年改建的，用檜木蓋成四合院，前後院還各有一座防空洞。"},{"who":"R","text":"檜木房子耶，走進去一定香香的，比Allan的便當香！"},{"who":"A","text":"喂，我的扁食便當也很香好嗎！1988年管理處裁撤，現在變成鐵道文化園區一館。"},{"who":"R","text":"那今天到現場，我們的任務是什麼？"},{"who":"A","text":"站到中庭，用手機把尖塔和四周的木造迴廊一起拍進去，找出最對稱的角度！"}],"clues":["我正廳屋頂有一座仿哥德式尖塔","我前身在1909年設立，負責興建臺東線鐵路","我今天是花蓮鐵道文化園區的第一館"],"quiz":[{"q":"花蓮管理處正廳屋頂最大的特色是？","options":["金色圓頂","仿哥德式尖塔","燕尾翹脊","鐘樓"],"answer":1,"explain":"主建築上的仿哥德式尖塔是鐵道管理處的精神象徵。"},{"q":"現存的花蓮管理處木造建築是哪一年改建的？","options":["1909年","1919年","1932年","1959年"],"answer":2,"explain":"現存木造建築是1932年改建而成。"}],"images":[{"file":"原交通部臺鐵管理局花蓮管理處.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/%E5%8E%9F%E4%BA%A4%E9%80%9A%E9%83%A8%E8%87%BA%E9%90%B5%E7%AE%A1%E7%90%86%E5%B1%80%E8%8A%B1%E8%93%AE%E7%AE%A1%E7%90%86%E8%99%95.JPG/960px-%E5%8E%9F%E4%BA%A4%E9%80%9A%E9%83%A8%E8%87%BA%E9%90%B5%E7%AE%A1%E7%90%86%E5%B1%80%E8%8A%B1%E8%93%AE%E7%AE%A1%E7%90%86%E8%99%95.JPG","page":"https://commons.wikimedia.org/wiki/File:%E5%8E%9F%E4%BA%A4%E9%80%9A%E9%83%A8%E8%87%BA%E9%90%B5%E7%AE%A1%E7%90%86%E5%B1%80%E8%8A%B1%E8%93%AE%E7%AE%A1%E7%90%86%E8%99%95.JPG","artist":"Pbdragonwang","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/hualian-jiaotongbutaitie-0.webp","small":"img/hualian-jiaotongbutaitie-0-s.webp"}]},{"id":"hualian-taitiehualianjiu","name":"台鐵花蓮舊工務段、舊警務段建築群","short":"舊工務段警務段","category":"歷史建築","level":"","town":"花蓮市","types":["辦公廳舍"],"lat":23.97472,"lng":121.60966,"address":"花蓮縣花蓮市花蓮市福建街460號(原公告為：博愛街24巷34、35號)","announced":"2013-09-26","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20140124000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/1204/photo/台鐵花蓮舊工務段、舊警務段建築群1.JPG","year":1932,"yearText":"年代不詳","era":"unknown","themes":["鐵道交通","日式建築"],"yearUnknown":true,"summary":"鐵道養護與治安單位的日式木造建築群","intro":"台鐵花蓮舊工務段、舊警務段建築群位於花蓮市福建街，屬花蓮鐵道文化園區。1909年鐵道部花蓮港出張所成立時，周邊設有運務、工務、機務、電務、警務等段，宛如小型鐵路局。工務段負責鐵路設施的興建與維修，警務段負責東線鐵道沿線安全。1988年花蓮管理處裁撤、車站西移後，舊站區漸趨沒落，經地方奔走陸續登錄保存，2013年整合為建築群登錄。範圍包含舊工務段、舊警務段、附屬工廠、打鐵工坊與拘留所，建築為雨淋板外牆、洋小屋組，並設防颱防震斜撐木。","highlights":["舊工務段與舊警務段的雨淋板木造建築","牆內防颱防震的斜撐木","附屬工廠、打鐵工坊與小小的拘留所"],"funFact":"鐵路警務段有自己的拘留所，面積只有26.31平方公尺，比很多人家的客廳還小。","photoSpot":"拍木造建築與園區保存的火車","visitMin":30,"openNote":"位於花蓮市福建街，屬花蓮鐵道文化園區，官方資料記載10:00至18:00開放、週三休息，部分空間為商業使用，以現場公告為準。可與鐵道文化園區一館步行串遊。","dialogue":[{"who":"R","text":"Allan，鐵道園區這邊還有一區，那幾棟木頭房子是做什麼的？"},{"who":"A","text":"這裡是舊工務段和舊警務段，一個負責修鐵路，一個負責鐵路沿線的安全。"},{"who":"R","text":"原來鐵路也有自己專屬的警察喔？"},{"who":"A","text":"有啊，警務段就是東線鐵道的守護者，旁邊還有一間小小的拘留所，只有26平方公尺多。"},{"who":"R","text":"空間那麼小，被關進去應該只能乖乖罰站吧！"},{"who":"A","text":"哈，所以叫拘留不叫度假。旁邊還有附屬工廠和打鐵工坊，修鐵路要用的工具和零件，很多都在這裡處理。"},{"who":"R","text":"這裡根本是一個小城鎮嘛，修路、打鐵、抓壞人都自己來。"},{"who":"A","text":"沒錯，所以說它宛如一個小型鐵路局。請你找找看木牆裡的斜撐木，它可是防颱防震的祕密武器！"}],"clues":["我這群建築裡有打鐵工坊，還有一間很小的拘留所","一個單位修鐵路，一個單位守護沿線安全，兩者合在我身上","我在花蓮福建街的鐵道文化園區裡"],"quiz":[{"q":"舊警務段的主要任務是什麼？","options":["販售車票","製作鐵路便當","駕駛蒸汽機車","東線鐵道沿線安全"],"answer":3,"explain":"警務段負責東線鐵道沿線安全。"},{"q":"這個建築群在哪一年整合為一處歷史建築登錄？","options":["2005年","2013年","1988年","2002年"],"answer":1,"explain":"2013年整合為工務段、警務段建築群登錄。"}],"images":[{"file":"東線鐵道遺址舊工務段.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8c/%E6%9D%B1%E7%B7%9A%E9%90%B5%E9%81%93%E9%81%BA%E5%9D%80%E8%88%8A%E5%B7%A5%E5%8B%99%E6%AE%B5.JPG/960px-%E6%9D%B1%E7%B7%9A%E9%90%B5%E9%81%93%E9%81%BA%E5%9D%80%E8%88%8A%E5%B7%A5%E5%8B%99%E6%AE%B5.JPG","page":"https://commons.wikimedia.org/wiki/File:%E6%9D%B1%E7%B7%9A%E9%90%B5%E9%81%93%E9%81%BA%E5%9D%80%E8%88%8A%E5%B7%A5%E5%8B%99%E6%AE%B5.JPG","artist":"Pbdragonwang","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/hualian-taitiehualianjiu-0.webp","small":"img/hualian-taitiehualianjiu-0-s.webp"}]},{"id":"yuli-zhanglianglianjia","name":"長良連家古厝","short":"長良連家古厝","category":"歷史建築","level":"","town":"玉里鎮","types":["宅第"],"lat":23.274164,"lng":121.28826,"address":"花蓮縣玉里鎮長良里２鄰長良１２號","announced":"2004-03-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20040319000006","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-02-18/55ddac09-a640-464f-95ec-976b316b5d6f/j玉里-長良古厝11.jpg","year":1933,"yearText":"約1930年代（2004年登錄時已逾70年）","era":"japan","themes":["宅第家族"],"yearUnknown":false,"summary":"融合四種工法的七開間ㄇ字型合院","intro":"長良連家古厝位於玉里鎮長良里南側，背倚高山、前望秀姑巒溪，2004年登錄歷史建築時已有70多年歷史。主體是面寬七開間的ㄇ字型合院，由正身、左右護龍、內外埕與半月池組成，旁邊還有牆厚二尺的石砌倉庫，十分少見。初建時以當地的樟木、卵石與茅草為主要建材，由熟悉日式工法的人帶領會社工人興建，屋頂由熟悉茅草工法的原住民施作，融合閩南式、日式、西式與原住民構法。戰後初期曾拆用臺灣拓殖株式會社的菸草乾燥室建材修改建，2000年碧利斯颱風後也有較大規模整修。","highlights":["七開間ㄇ字型合院與門前半月池","牆厚二尺的石砌倉庫","閩南、日式、西式與原住民工法並存"],"funFact":"古厝戰後修改建時，曾拆用臺灣拓殖株式會社留下的菸草乾燥室當建材，很有資源再利用精神。","photoSpot":"在外圍拍合院正身與半月池倒影","visitMin":15,"openNote":"為私人宅第，位於玉里鎮長良里，官方資料未載開放，請在外觀參觀、勿擅入打擾。建議開車前往。","dialogue":[{"who":"A","text":"阿拉蕾，玉里長良這座老宅，背後靠山、前面望著秀姑巒溪，風景好到我想在這裡吃便當。"},{"who":"R","text":"好漂亮的合院！門口還有一個半月形的水池。"},{"who":"A","text":"那叫半月池。連家古厝是七開間、三面圍起來的合院，登錄時就已經有70多年歷史了。"},{"who":"R","text":"它長得像閩南合院，可是好像又有點日本味？"},{"who":"A","text":"好眼力！它融合閩南式、日式、西式和原住民的工法，屋頂當年請熟悉茅草工法的原住民來施作。"},{"who":"R","text":"四種工法一次到位，根本是建築界的綜合果汁。"},{"who":"A","text":"還有更酷的，旁邊石頭砌的倉庫，牆厚足足二尺，別處很少見。"},{"who":"R","text":"二尺是多厚啊？我只知道幾公分。"},{"who":"A","text":"大約60公分，比我的肚子還厚一點。這是私人住宅，請在外面觀察倉庫牆面，看看石頭怎麼堆疊！"}],"clues":["我的倉庫石牆厚達二尺","我曾拆用菸草乾燥室的材料來修改建","我是玉里長良里前望秀姑巒溪的七開間合院"],"quiz":[{"q":"連家古厝的主體是什麼格局？","options":["一條龍五開間","七開間ㄇ字型合院","四合院兩進","日式獨棟洋樓"],"answer":1,"explain":"主體為面寬七開間的ㄇ字型合院。"},{"q":"連家古厝初建時屋頂由誰施作？","options":["日本技師","閩南匠師","西洋傳教士","熟悉茅草工法的原住民"],"answer":3,"explain":"屋頂由熟悉茅草工法的原住民施作。"}],"images":[]},{"id":"hualian-taiwantielujuhua","name":"台灣鐵路局花蓮管理處處長官邸","short":"鐵路處長官邸","category":"歷史建築","level":"","town":"花蓮市","types":["官邸"],"lat":23.973658,"lng":121.612788,"address":"花蓮縣花蓮市中山路40巷1弄4號","announced":"2004-03-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20040319000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-25/502d77ac-2768-43fd-b4b4-72aa4f20758d/c花蓮-鐵路處長官邸05.jpg","year":1935,"yearText":"年代不詳","era":"unknown","themes":["職務宿舍","鐵道交通","日式建築"],"yearUnknown":true,"summary":"西洋列柱玄關配千鳥破風的鐵道長官邸","intro":"台灣鐵路局花蓮管理處處長官邸位於花蓮市中山路40巷，周圍日式木造屋都是鐵路宿舍，構成完整的鐵道宿舍聚落。官邸為單層日式木造建築，前庭寬廣、大門玄關內凹，格局方正。正門以西洋列柱結構結合傳統木構，屋頂兩側分別是寄棟造與入母屋破風，中間以千鳥破風式樣收束，外牆大部分仍是檜木板。屋後為半戶外的迴廊，後院有池塘與彎曲水道，入口處植龍柏，院內還有大型防空洞與地下水泥管線，是保存完整、氣派的官舍。","highlights":["正門的西洋列柱與內凹玄關","寄棟、入母屋與千鳥破風組合的屋頂","屋後迴廊、池塘與彎曲水道"],"funFact":"一棟官邸的屋頂就用了寄棟、入母屋、千鳥破風三種做法，是日式屋頂的綜合教材。","photoSpot":"在大門外拍列柱玄關與千鳥破風","visitMin":15,"openNote":"位於花蓮市中山路40巷，官方未載開放資訊，請以外觀參觀為主，出發前請查詢最新開放狀況。鄰近鐵道文化園區，可步行串遊。","dialogue":[{"who":"A","text":"阿拉蕾，鐵道文化園區附近這條巷子，以前住的都是鐵路人，而最大的這棟是處長官邸。"},{"who":"R","text":"處長住的房子，一定很豪華氣派吧？"},{"who":"A","text":"門口有西洋列柱，屋頂一次用了寄棟、入母屋和千鳥破風三種做法，很講究。"},{"who":"R","text":"千鳥破風？是千隻鳥一起破風飛過來嗎？"},{"who":"A","text":"哈，那是屋頂正面那個三角形的山牆裝飾，像鳥張開翅膀，可不是鳥群來攻擊。"},{"who":"R","text":"原來如此！那它的院子裡有什麼？"},{"who":"A","text":"屋後有迴廊、池塘和彎彎的水道，入口種龍柏，院子還有一座大型防空洞。"},{"who":"R","text":"有池塘又有防空洞，處長的生活也是又悠閒又緊張耶。"},{"who":"A","text":"說得好。請你在大門外，找出屋頂上那個三角形的千鳥破風，看看它在正中間還是旁邊！"}],"clues":["我的正門有西洋列柱，屋頂中間是千鳥破風","我的後院有池塘、彎曲水道和大型防空洞","我是花蓮中山路巷內，鐵路管理處最高長官的家"],"quiz":[{"q":"處長官邸正門結合了哪種西洋元素？","options":["列柱結構","玫瑰花窗","鐘樓","拱廊騎樓"],"answer":0,"explain":"正門為西洋列柱式結構，與傳統木構結合。"},{"q":"處長官邸入口處種的是哪一種樹？","options":["大王椰子","黑松","龍柏","櫻花"],"answer":2,"explain":"官邸大門入口處植有龍柏。"}],"images":[{"file":"花蓮縣定歷史建築台灣鐵路局花蓮管理處處長官邸-正門.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2e/%E8%8A%B1%E8%93%AE%E7%B8%A3%E5%AE%9A%E6%AD%B7%E5%8F%B2%E5%BB%BA%E7%AF%89%E5%8F%B0%E7%81%A3%E9%90%B5%E8%B7%AF%E5%B1%80%E8%8A%B1%E8%93%AE%E7%AE%A1%E7%90%86%E8%99%95%E8%99%95%E9%95%B7%E5%AE%98%E9%82%B8-%E6%AD%A3%E9%96%80.jpg/960px-%E8%8A%B1%E8%93%AE%E7%B8%A3%E5%AE%9A%E6%AD%B7%E5%8F%B2%E5%BB%BA%E7%AF%89%E5%8F%B0%E7%81%A3%E9%90%B5%E8%B7%AF%E5%B1%80%E8%8A%B1%E8%93%AE%E7%AE%A1%E7%90%86%E8%99%95%E8%99%95%E9%95%B7%E5%AE%98%E9%82%B8-%E6%AD%A3%E9%96%80.jpg","page":"https://commons.wikimedia.org/wiki/File:%E8%8A%B1%E8%93%AE%E7%B8%A3%E5%AE%9A%E6%AD%B7%E5%8F%B2%E5%BB%BA%E7%AF%89%E5%8F%B0%E7%81%A3%E9%90%B5%E8%B7%AF%E5%B1%80%E8%8A%B1%E8%93%AE%E7%AE%A1%E7%90%86%E8%99%95%E8%99%95%E9%95%B7%E5%AE%98%E9%82%B8-%E6%AD%A3%E9%96%80.jpg","artist":"Yanyiyi","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/hualian-taiwantielujuhua-0.webp","small":"img/hualian-taiwantielujuhua-0-s.webp"}]},{"id":"shoufeng-fenglicunribenyi","name":"壽豐豐裡村日本移民墓園","short":"豐田移民墓園","category":"歷史建築","level":"","town":"壽豐鄉","types":["墓葬"],"lat":23.841359,"lng":121.506463,"address":"花蓮縣壽豐鄉壽豐鄉豐裡村中山路280號後側","announced":"2009-08-13","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20090813000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-04-06/5a5584df-83c8-4f93-ba44-7e76659e436c/e壽豐-日本移民墓園10.jpg","year":1935,"yearText":"1935年（昭和10年）立碑","era":"japan","themes":["日治移民村","墓葬碑碣"],"yearUnknown":false,"summary":"豐田移民村留下的家族墓與「俱會一處」碑","intro":"壽豐豐裡村日本移民墓園位於壽豐鄉豐裡村中山路280號後側，靠近豐裡國小，屬日治時期豐田移民村的中里部落一帶。移民村在耕地一隅闢有公共墓地與火葬場。墓園內保留6組石碑與刻字石塊，其中一座石碑正面刻「俱會一處」與「松林」，背面刻「昭和十年七月吉日建之」，側面寫有「臺灣初代」與昭和九年的日期。「俱會一處」是淨土信仰中往生極樂、與諸佛菩薩相聚的意思，據說豐田移民身故火化後多將骨灰安放於此。另有「香月家累代之墓」收葬8位往生者，反映移民在風土病肆虐下拓墾的艱辛，2009年登錄為歷史建築。","highlights":["正面刻有「俱會一處」與「松林」的石碑","收葬8位往生者的香月家累代之墓","分布在池塘與小土丘前的6組石碑"],"funFact":"「俱會一處」出自淨土信仰，意思是往生極樂淨土的人，能與諸佛菩薩相聚在同一處。","photoSpot":"在池塘邊遠拍石碑群，請勿踩踏墓地","visitMin":15,"openNote":"位於壽豐鄉豐裡村中山路280號後側巷內，官方資料記載為戶外環境。這裡是墓地，參觀請保持莊重、勿踩踏或觸摸碑石。臺鐵豐田站周邊步行可達豐田移民村相關遺構。","dialogue":[{"who":"R","text":"Allan，這裡好安靜，池塘邊有好幾塊石碑，是誰的墓呢？"},{"who":"A","text":"這是日治時期豐田移民村的墓園。移民村在耕地一角闢了公共墓地，還有火葬場。"},{"who":"R","text":"那塊石碑上寫著俱會一處，是什麼意思？"},{"who":"A","text":"這是淨土信仰的說法，意思是往生極樂的人，能和諸佛菩薩相聚在一起。"},{"who":"R","text":"好溫柔的祝福。這些移民是怎麼過世的呢？"},{"who":"A","text":"當時風土病和疾病很多，像香月家的家族墓就收葬了8位往生者，可見拓墾有多艱辛。"},{"who":"R","text":"離開家鄉來到花蓮，最後長眠在這裡，想想也很不容易。"},{"who":"A","text":"是啊，這裡要用尊重的心情來看。據說豐田移民火化後，骨灰大多安放在這裡。"},{"who":"R","text":"那我們輕聲走過去，找找看那塊寫著俱會一處的石碑在哪個位置就好。"}],"clues":["我身上刻著昭和十年七月吉日建之","我旁邊有一座收葬了8位往生者的家族墓","我刻著俱會一處，守護著豐田移民的骨灰"],"quiz":[{"q":"石碑上的「俱會一處」出自哪一種信仰？","options":["神道教","天主教","道教","淨土信仰"],"answer":3,"explain":"俱會一處是淨土信仰中往生極樂者與諸佛菩薩相聚之意。"},{"q":"「香月家累代之墓」收葬了幾位往生者？","options":["3位","5位","8位","12位"],"answer":2,"explain":"香月家累代之墓原收葬香月勇次郎等8位往生者。"}],"images":[]},{"id":"hualian-meilunxipanrishisu2","name":"美崙溪畔日式宿舍","short":"將軍府周邊宿舍","category":"歷史建築","level":"","town":"花蓮市","types":["宅第"],"lat":23.980344,"lng":121.61307,"address":"花蓮縣花蓮市花蓮市中正路618巷及622巷（14間）。(花蓮市民勤段1426、1426-4地號)","announced":"2005-03-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20050329000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2026-06-12/47595ca1-55a5-4ca1-bd7d-73d4ae253edc/1781247035199_0.jpg","year":1936,"yearText":"1936年（昭和11年）","era":"japan","themes":["職務宿舍","日式建築","眷村與戰後移民"],"yearUnknown":false,"summary":"將軍府旁7棟14戶，日軍官舍變眷村","intro":"美崙溪畔日式宿舍的歷史建築部分，是花蓮市中正路618巷與622巷的7棟14戶雙併式宿舍，圍繞在俗稱「將軍府」的縣定古蹟本屋周邊，由兩條巷道分成三個區塊。整個社區1936年建成，以檜木等高級木料搭建，是日軍高級軍官居住的小型社區。戰後由國軍接管，改作眷村住宅。2005年在居民與學者連署下，本屋指定為縣定古蹟、周邊宿舍登錄為歷史建築。這些宿舍為「一棟二戶」的雙併形式，切妻式屋頂、水泥瓦，外牆釘雨淋板，地板架高並在牆基開小方窗通風，內牆則是小舞壁，和古蹟本屋的木摺壁不同。","highlights":["一棟兩戶的雙併式宿舍格局","牆基下方開設的通風小方窗","兩條巷道把7棟宿舍分成三個區塊"],"funFact":"同一個園區裡，古蹟本屋的內牆是木摺壁，周邊歷史建築宿舍則是小舞壁，工法不一樣。","photoSpot":"在618巷口拍一整排雙併宿舍的屋頂線","visitMin":30,"openNote":"位於花蓮市中正路618巷與622巷，將軍府園區一帶。官方資料記載修復工程進行中，各棟開放狀況不同，出發前請查詢最新開放狀況。與松園別館、菁華林苑步行可達。","dialogue":[{"who":"R","text":"Allan，將軍府不是只有一棟嗎？怎麼旁邊還有這麼多長得很像的房子？"},{"who":"A","text":"將軍府本屋是古蹟，周圍618巷和622巷還有7棟14戶宿舍，是另外登錄的歷史建築。"},{"who":"R","text":"7棟怎麼會是14戶？分給雙胞胎住嗎？"},{"who":"A","text":"差不多啦，這叫雙併式，一棟房子從中間分成兩戶，左右各一家，共用一面牆。"},{"who":"R","text":"那隔壁鄰居吵架，不就聽得一清二楚了！"},{"who":"A","text":"所以當鄰居要和氣。這個社區1936年建成，給日本高級軍官住，戰後國軍接管，變成眷村。"},{"who":"R","text":"原來同一排房子，先後住過日本軍官和眷村家庭。"},{"who":"A","text":"沒錯。房子地板架得很高，牆腳還開了小方窗讓地板下通風，防潮又防白蟻。"},{"who":"R","text":"那我們沿著巷子走，數數看一棟房子有幾個通風小方窗吧！"}],"clues":["我們7棟住了14戶，兩兩共用一面牆","日本高級軍官住過我們，戰後又變成眷村","我們圍繞在美崙溪畔一棟有名的大屋旁邊"],"quiz":[{"q":"美崙溪畔日式宿舍的歷史建築部分共有幾棟幾戶？","options":["5棟10戶","7棟14戶","6棟12戶","8棟16戶"],"answer":1,"explain":"中正路618巷與622巷共7棟14戶雙併宿舍。"},{"q":"戰後這片宿舍被拿來做什麼？","options":["國軍眷村住宅","改為小學校舍","林務局倉庫","觀光旅館"],"answer":0,"explain":"戰後由國軍接管，改作眷村住宅使用。"}],"images":[]},{"id":"fenglin-zhendarongguoxiao","name":"鳳林鎮大榮國小教師宿舍","short":"大榮國小宿舍","category":"歷史建築","level":"","town":"鳳林鎮","types":["宅第"],"lat":23.753076,"lng":121.468473,"address":"花蓮縣鳳林鎮鳳林鎮大榮二村復興路72號","announced":"2012-05-02","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20120502000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-04-10/edc09b98-58ab-4dce-9be8-d3a26c46a0cd/g鳳林-大榮國小教師宿舍06.jpg","year":1936,"yearText":"1936年（昭和11年）修繕或重建","era":"japan","themes":["職務宿舍","日治移民村","日式建築"],"yearUnknown":false,"summary":"三個大小切妻屋頂疊出的移民村官舍","intro":"大榮國小的前身是林田移民村的林田小學校，位在中野部落南端、移民指導所建築群的核心。這棟宿舍依建築形式推論，日治時期應是移民指導所相關人員的官舍，依官營移民事業報告書附圖為「乙號宿舍」，判斷1936年曾大規模修繕或重建。戰後成為大榮國小校長宿舍，曾有兩位校長居住，之後由學校教師入住。建築是純和式構造，屋頂由三組大小不同的切妻造組成，外牆是簓子下見板張，室內依玄關、居間、座敷、應接室、台所串連。周邊原有的訓導宿舍與雙併教師宿舍已拆除，2009年改建為休閒運動公園。","highlights":["三組大小不同切妻屋頂交錯的天際線","以細木條壓住的簓子下見板張外牆","格子玻璃窗與前、後、側三處出入口"],"funFact":"報告書附圖把這棟編為「乙號宿舍」，日治宿舍常用甲乙丙分等級，名字就藏著身分。","photoSpot":"從運動公園拍三層切妻屋頂側面","visitMin":15,"openNote":"位於鳳林鎮大榮里復興路，旁為大榮二村休閒運動公園，官方資料記載僅開放外觀參觀。可與林田派出所、林田神社一起步行串遊。","dialogue":[{"who":"R","text":"Allan，這棟房子的屋頂怎麼高高低低的，好像疊疊樂！"},{"who":"A","text":"眼睛很利。它的屋頂由三組大小不同的切妻造組成，這就是它的招牌特色。"},{"who":"R","text":"原來是故意的，我還以為蓋到一半沒材料了。"},{"who":"A","text":"哈，日本師傅聽到會哭。這是林田移民村的官舍，報告書裡編號叫乙號宿舍。"},{"who":"R","text":"乙號？那甲號是不是住更大的官？"},{"who":"A","text":"很有可能，宿舍等級常用甲乙丙來分。戰後它成了大榮國小的校長宿舍。"},{"who":"R","text":"這麼特別的房子，現在可以進去裡面參觀嗎？我想看看玄關和座敷。"},{"who":"A","text":"目前只能看外觀，但外牆的細節很值得看，那叫簓子下見板張。"},{"who":"R","text":"名字好難念！我去外牆找找那些壓著木板的細木條，拍個特寫！"}],"clues":["移民事業報告書附圖替我編了「乙號」","我有三組大小不同的切妻屋頂","戰後我成為鳳林一所國小的校長宿舍"],"quiz":[{"q":"這棟宿舍的屋頂由幾組切妻造組成？","options":["3組","2組","4組","5組"],"answer":0,"explain":"屋頂由三組大小不同之切妻造組成。"},{"q":"大榮國小在日治時期的前身是？","options":["豐田小學校","鳳林公學校","林田小學校","大和小學校"],"answer":2,"explain":"大榮國小前身為林田村的林田小學校。"}],"images":[{"file":"鳳林鎮大榮國小教師宿舍.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2e/%E9%B3%B3%E6%9E%97%E9%8E%AE%E5%A4%A7%E6%A6%AE%E5%9C%8B%E5%B0%8F%E6%95%99%E5%B8%AB%E5%AE%BF%E8%88%8D.jpg/960px-%E9%B3%B3%E6%9E%97%E9%8E%AE%E5%A4%A7%E6%A6%AE%E5%9C%8B%E5%B0%8F%E6%95%99%E5%B8%AB%E5%AE%BF%E8%88%8D.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%B3%B3%E6%9E%97%E9%8E%AE%E5%A4%A7%E6%A6%AE%E5%9C%8B%E5%B0%8F%E6%95%99%E5%B8%AB%E5%AE%BF%E8%88%8D.jpg","artist":"Pbdragonwang","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/fenglin-zhendarongguoxiao-0.webp","small":"img/fenglin-zhendarongguoxiao-0-s.webp"}]},{"id":"yuli-linwujuyuliguoyou","name":"林務局玉里國有眷舍","short":"林務局玉里眷舍","category":"歷史建築","level":"","town":"玉里鎮","types":["宅第"],"lat":23.337959,"lng":121.31339,"address":"花蓮縣玉里鎮玉里鎮中華路139巷48弄4號；玉里鎮中華路139巷50號、52號、54號","announced":"2007-11-07","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20051107000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-04-15/d2afeb9a-4955-43ab-8fef-5e34c0979fc9/DSC01160.jpg","year":1936,"yearText":"1936年（昭和11年）","era":"japan","themes":["職務宿舍","日式建築"],"yearUnknown":false,"summary":"從樟腦會社到林務局的日式木造宿舍","intro":"林務局玉里國有眷舍位於玉里鎮中華路139巷內。這片街廓原是日治時期臺灣製腦株式會社的宿舍用地，1934年專賣局將製腦會社收歸直營後，改為專賣局玉里出張所的員工宿舍，戰後由林務局接收作為員工宿舍。中華路139巷50、52、54號為丙種官舍，建於1936年，採四面坡的寄棟屋根；48弄4號為丁種官舍，推估建於1938至1945年間，採兩面坡的切妻屋根。外牆都是「簓子下見板張」雨淋板，室內保留玄關、座敷、居間與緣側等空間序列，2007年登錄歷史建築，見證林業與玉里市街發展。","highlights":["寄棟屋根與切妻屋根兩種屋頂並存","簓子下見板張的雨淋板外牆","從製腦會社延續到林務局的宿舍街廓"],"funFact":"這片街廓先後屬於製腦會社、專賣局與林務局，三任主人都和山林資源有關。","photoSpot":"在巷道比較兩種屋頂的斜面","visitMin":15,"openNote":"位於玉里鎮中華路139巷，部分宿舍仍有住戶，官方資料未載開放，請在巷道外觀參觀、勿打擾居民。可搭臺鐵花東線至玉里站。","dialogue":[{"who":"A","text":"阿拉蕾，走進玉里中華路的這條巷子，你聞聞看，有沒有樟腦的味道？"},{"who":"R","text":"樟腦？那是Allan你衣櫃的味道吧！"},{"who":"A","text":"被你抓包。不過這片街廓日治時期真的是臺灣製腦株式會社的宿舍地，專門做樟腦生意。"},{"who":"R","text":"那後來怎麼會變成林務局的房子？"},{"who":"A","text":"1934年專賣局把製腦會社收歸直營，這裡改成專賣局員工宿舍，戰後再由林務局接收。"},{"who":"R","text":"換了三個房東，房子本人應該很淡定。"},{"who":"A","text":"非常淡定。丙種官舍建於1936年，是四面落水的寄棟屋頂，丁種官舍則是兩面坡的切妻屋頂。"},{"who":"R","text":"一個四面、一個兩面，好像在比誰的屋頂比較多面。"},{"who":"A","text":"這裡還有住戶，請放低音量。在巷道裡比較一下兩種屋頂的斜面，拍一張對照照片吧！"}],"clues":["我這片地曾是製腦會社的宿舍用地","我有四面坡和兩面坡兩種屋頂的官舍","我是玉里中華路139巷、戰後由林務局接收的宿舍"],"quiz":[{"q":"這片宿舍街廓最早屬於哪個機構？","options":["臺灣製腦株式會社","鹽水港製糖株式會社","臺灣拓殖株式會社","臺灣電力株式會社"],"answer":0,"explain":"前身為臺灣製腦株式會社宿舍敷地。"},{"q":"中華路139巷50、52、54號屬於哪一種官舍？","options":["甲種","乙種","丙種","丁種"],"answer":2,"explain":"50、52、54號為1936年建的丙種官舍。"}],"images":[]},{"id":"hualian-mingliluxianghaori","name":"明禮路14巷2號日式住宅(三浦勳宅)","short":"三浦勳宅","category":"歷史建築","level":"","town":"花蓮市","types":["宅第"],"lat":23.981797,"lng":121.609212,"address":"花蓮縣花蓮市花蓮市明禮路14巷2號","announced":"2015-12-25","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20151225000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-27/7c057676-a547-4a8e-9700-44f338f56527/c花蓮-明禮路日式宿舍02.jpg","year":1937,"yearText":"約1937年（昭和12年）","era":"japan","themes":["日式建築"],"yearUnknown":false,"summary":"木料上還印著花蓮店號的和洋折衷住宅","intro":"明禮路日式住宅（三浦勳宅）位於花蓮市明禮路14巷、明禮抽水站旁的堤防道路附近，日治時期屬花蓮港新城通。依地籍資料，最早1937年登記為花蓮港廳所有，1941年轉賣給三浦勳。三浦勳生於1918年，原籍日本宮城縣，曾任花蓮港廳雇員，因雇員未配給獨棟宿舍，這棟是他擁有土地的私宅。戰後收歸國有。建築為寄棟與切妻屋頂、真壁構造配雨淋板外牆，保留雨戶與欄間；違棚上方的壁龕相當精美，木料上還打印「花蓮港（力）楊」「松商店」等字樣，作法與一般官舍不同。","highlights":["室內違棚上方精美的壁龕","木料上打印的「松商店」等字樣","庭院裡嵌入的大石頭與南洋杉"],"funFact":"建材上留著「花蓮港（力）楊」「松商店」的打印字樣，是當年在地材料行的「簽名」。","photoSpot":"在巷口拍寄棟屋頂與南洋杉","visitMin":10,"openNote":"位於花蓮市明禮路14巷、明禮抽水站附近，官方未載開放資訊，建物多處構件佚失，請以外觀參觀為主。位於花蓮市區，可步行前往。","dialogue":[{"who":"A","text":"阿拉蕾，明禮抽水站旁邊這棟日式老屋，有個名字叫三浦勳宅。"},{"who":"R","text":"三浦勳是誰？是以前的大明星嗎？"},{"who":"A","text":"他是日治時期花蓮港廳的雇員，1941年買下這棟房子。雇員沒有配獨棟宿舍，所以這是他自己的家。"},{"who":"R","text":"自己花錢買的房子，一定會特別用心布置吧！"},{"who":"A","text":"沒錯，室內違棚上方的壁龕很精美，跟一般官舍的做法不一樣。"},{"who":"R","text":"違棚是什麼？是違章建築的櫃子嗎？"},{"who":"A","text":"哈，不是違建啦！違棚是和室裡左右高低錯開的層板，用來擺飾品。最有趣的是木料上還印著店號。"},{"who":"R","text":"印店號？那不就是建材行的簽名嗎？"},{"who":"A","text":"可以這樣說！有「松商店」之類的字樣。現在屋況不佳，請在外面看看院子裡那棵南洋杉有多高！"}],"clues":["我的木料上印著「松商店」等材料行字樣","1941年一位花蓮港廳雇員買下了我","我在花蓮明禮路巷內，抽水站旁的日式私人住宅"],"quiz":[{"q":"三浦勳為什麼擁有自己的房子而非住官舍？","options":["他是外國商人","雇員未配給獨棟宿舍","官舍被颱風吹倒","他是花蓮港廳長"],"answer":1,"explain":"雇員未配給獨棟宿舍，故購入此屋。"},{"q":"三浦勳宅的建材上可以找到什麼？","options":["日本天皇題字","美援標誌","建築師的簽名","建材行的打印字樣"],"answer":3,"explain":"木料上有「花蓮港（力）楊」「松商店」打印字樣。"}],"images":[]},{"id":"shoufeng-jiuhualiangangting","name":"舊花蓮港廳豐田小學校劍道館（豐裡國小禮堂）","short":"豐田小學校劍道館","category":"歷史建築","level":"","town":"壽豐鄉","types":["學校"],"lat":23.841887,"lng":121.507961,"address":"花蓮縣壽豐鄉豐裡村中山路299號","announced":"2009-08-13","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20090813000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-04-10/bc35dbf0-2338-4bc4-aabf-27392b37126b/e壽豐-豐田小國劍道館07.jpg","year":1937,"yearText":"日治時期（確切年代不詳）","era":"japan","themes":["日治移民村","教育運動","日式建築"],"yearUnknown":false,"summary":"移民子弟練劍的武道館，今為豐裡國小禮堂","intro":"舊花蓮港廳豐田小學校劍道館位於壽豐鄉豐裡村豐裡國小校園中央。學校前身是1913年設立的豐田尋常高等小學校，專供豐田移民村的日本移民子弟就讀，戰後改為豐裡國民學校、豐裡國小。校內保存的這座劍道館又稱武道館，當年用來練習劍道等武道，也作為集會場所；登錄理由稱它是日治末期的會堂建築。建築為加強磚造，切妻式屋頂由8組真束小屋組木屋架支撐，沒有天花板，屋頂原為日式黑瓦，後改為鐵皮。戰後改作學校禮堂，1961至1981年間還曾是當地居民辦喜宴的重要場所，2009年登錄為歷史建築。","highlights":["8組真束小屋組木屋架、無天花板的室內","強調中軸對稱的矩形磚造會堂","校園裡僅存的兩棵老榕樹"],"funFact":"2013年返鄉尋根的灣生說，校園老榕樹當年其實是練劍道隨手插下的劍靶，沒想到長成了大樹。","photoSpot":"從川堂方向拍禮堂切妻屋頂正面","visitMin":15,"openNote":"位於壽豐鄉豐裡村豐裡國小校園內，官方資料未載開放時間。校園開放與否依學校規定，上課時間請勿進入，可在校外觀看。臺鐵豐田站附近，可與壽豐鄉文史館、移民墓園步行串遊。","dialogue":[{"who":"A","text":"阿拉蕾，你知道豐裡國小的禮堂，以前其實是一座劍道館嗎？"},{"who":"R","text":"劍道館？小學生要練劍喔？好帥！"},{"who":"A","text":"這所學校1913年創立，叫豐田尋常高等小學校，專門給移民村的日本子弟讀，練武道是課程之一。"},{"who":"R","text":"那戰後不練劍道了，劍道館要怎麼辦？"},{"who":"A","text":"戰後改成禮堂，1961年到1981年間，村民還常在這裡辦喜宴，從刀光劍影變成觥籌交錯。"},{"who":"R","text":"從練劍變成吃辦桌，Allan你一定最喜歡後面那個時期。"},{"who":"A","text":"被你看穿了。還有個小故事，2013年回來尋根的灣生說，校園老榕樹以前是練劍的劍靶。"},{"who":"R","text":"插在地上的劍靶竟然長成大樹，太神奇了！"},{"who":"A","text":"現在只剩兩棵還活著。到現場找找看那兩棵老榕樹，再抬頭看看禮堂屋頂的形狀！"}],"clues":["我曾聽見竹劍互擊的聲音，也曾擺滿喜宴桌","我身邊的老榕樹據說原本是練習用的靶","我是移民子弟學校留下的武道館，今天當禮堂"],"quiz":[{"q":"豐田小學校劍道館現在作什麼用途？","options":["鄉公所會議室","社區圖書館","壽豐鄉文史館","豐裡國小禮堂"],"answer":3,"explain":"劍道館戰後成為豐裡國小的禮堂。"},{"q":"灣生說校園老榕樹原本是什麼？","options":["神社的神木","移民種的行道樹","練劍道的劍靶","防風林"],"answer":2,"explain":"灣生表示老榕樹當年是練劍道隨地插立的劍靶。"}],"images":[{"file":"Former Fengtian Elementary School Kendo Training Center (The Assembly Hall of Fengli Elementary School), Fenglin Township, Hualien (Taiwan).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f5/Former_Fengtian_Elementary_School_Kendo_Training_Center_%28The_Assembly_Hall_of_Fengli_Elementary_School%29%2C_Fenglin_Township%2C_Hualien_%28Taiwan%29.jpg/960px-Former_Fengtian_Elementary_School_Kendo_Training_Center_%28The_Assembly_Hall_of_Fengli_Elementary_School%29%2C_Fenglin_Township%2C_Hualien_%28Taiwan%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Former_Fengtian_Elementary_School_Kendo_Training_Center_(The_Assembly_Hall_of_Fengli_Elementary_School),_Fenglin_Township,_Hualien_(Taiwan).jpg","artist":"Mk2010","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/shoufeng-jiuhualiangangting-0.webp","small":"img/shoufeng-jiuhualiangangting-0-s.webp"}]},{"id":"guangfu-tangchangzhensuo","name":"花蓮糖廠診所","short":"花蓮糖廠診所","category":"歷史建築","level":"","town":"光復鄉","types":["醫院"],"lat":23.655753,"lng":121.418957,"address":"花蓮縣光復鄉光復鄉大進村糖廠街5巷5號","announced":"2011-10-04","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20111004000009","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-02-18/caae9bcd-0325-460c-9484-4e668137d4b1/h光復-糖場診所05.jpg","year":1937,"yearText":"1937年（昭和12年）","era":"japan","themes":["糖業","公共建築","日式建築"],"yearUnknown":false,"summary":"照顧糖廠員工的合院式廠區診所","intro":"花蓮糖廠診所位於光復鄉大進村糖廠街，是大和工場廠區規劃中的醫療設施，創建於1937年，當時設有內科、外科、小兒科與牙科，照顧住廠各級員工。戰後除駐廠醫師外，也有花蓮陸軍805醫院的軍醫支援診療，從日治到戰後為花蓮中區提供醫療服務。診所採合院式配置：西南側是木造襯雨淋板的掛號藥房棟，西側是鋼筋混凝土洗石子牆的門診棟，東北側是切妻式屋頂的病房棟，不同時期的建物並存。依官方紀錄，各棟規劃修復再利用，部分仍待啟用。","highlights":["三棟圍成合院的診所配置","門診棟的洗石子牆與寄棟式屋頂","病房棟的切妻屋頂與雨淋板外牆"],"funFact":"戰後糖廠診所除了駐廠醫師，還有花蓮陸軍805醫院的軍醫來支援看診。","photoSpot":"從院落中央拍三棟建築的不同屋頂","visitMin":20,"openNote":"光復鄉在2025年9月馬太鞍溪堰塞湖溢流後仍在復原，出發前請查詢最新開放與道路狀況。位於光復鄉糖廠街5巷，官方資料未載開放時間，內部多未啟用，以外觀參觀為主；可搭臺鐵花東線至光復站。","dialogue":[{"who":"R","text":"Allan，糖廠裡怎麼會有診所？難道吃太多冰會被抓去打針？"},{"who":"A","text":"哈，冰品不用掛號啦。這間花蓮糖廠診所1937年就創建了，專門照顧住在廠區的員工。"},{"who":"R","text":"那時候的糖廠診所，有哪些科別可以看？"},{"who":"A","text":"內科、外科、小兒科、牙科都有，簡直是糖廠版的小醫院。"},{"who":"R","text":"糖廠裡有牙科，好合理喔，吃糖吃多了要補牙。"},{"who":"A","text":"你這個推理我無法反駁。戰後除了駐廠醫師，還有陸軍805醫院的軍醫來支援看診。"},{"who":"R","text":"那這間診所的建築，長什麼樣子呢？"},{"who":"A","text":"三棟圍成合院，掛號藥房棟是木造雨淋板，門診棟是洗石子牆，病房棟是切妻式斜屋頂。"},{"who":"R","text":"三棟三種風格，像建築版的大團體健檢。我要去找出洗石子牆那一棟，拍下來當健檢報告！"}],"clues":["我1937年創立，有內科、外科、小兒科與牙科","戰後曾有陸軍醫院的軍醫來這裡支援","我是光復鄉製糖廠區裡的三棟合院式醫療建築"],"quiz":[{"q":"花蓮糖廠診所創建於哪一年？","options":["1921年","1952年","1928年","1937年"],"answer":3,"explain":"診所創建於1937年（昭和12年）。"},{"q":"診所三棟中，哪一棟是洗石子牆體？","options":["病房棟","門診棟","掛號藥房棟","宿舍棟"],"answer":1,"explain":"門診棟為鋼筋混凝土洗石子牆、寄棟式屋頂。"}],"images":[{"file":"Clinic (1937), Hualien Sugar Factory, Guangfu Township, Hualien (Taiwan).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/02/Clinic_%281937%29%2C_Hualien_Sugar_Factory%2C_Guangfu_Township%2C_Hualien_%28Taiwan%29.jpg/960px-Clinic_%281937%29%2C_Hualien_Sugar_Factory%2C_Guangfu_Township%2C_Hualien_%28Taiwan%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Clinic_(1937),_Hualien_Sugar_Factory,_Guangfu_Township,_Hualien_(Taiwan).jpg","artist":"Mk2010","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/guangfu-tangchangzhensuo-0.webp","small":"img/guangfu-tangchangzhensuo-0-s.webp"}]},{"id":"xiulin-jiawanshenshecanji","name":"秀林加灣神社殘蹟","short":"加灣神社殘蹟","category":"歷史建築","level":"","town":"秀林鄉","types":["其他設施"],"lat":24.083179,"lng":121.60518,"address":"花蓮縣秀林鄉秀林鄉景美村景美國小後方","announced":"2011-04-12","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20110412000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-29/07a500bf-20c5-4e37-a40a-4457cec43fac/a秀林-加灣神社殘蹟03.jpg","year":1938,"yearText":"1938年（昭和13年）鎮座","era":"japan","themes":["神社遺構","原住民族文化"],"yearUnknown":false,"summary":"景美國小後方，日治部落小祠的殘存遺構","intro":"秀林加灣神社殘蹟位於秀林鄉景美村、景美國小後方。依中文維基百科整理的日治文獻，此地神社正式名稱為九宛祠（加灣舊稱九宛），1938年鎮座，祭祀開拓三神（大國魂命、大己貴命、少彥名命）與北白川宮能久親王，屬當時花蓮港廳花蓮郡的蕃地。日治時期推動參拜神社，作為同化政策的一環，部落附近也陸續設置神社。今天原有社殿已不存，只留下部分基座與遺構，見證殖民統治下太魯閣族部落被要求接受外來信仰的歷史。","highlights":["景美國小後方山坡上的神社殘存基座","從遺構想像參道與社殿的配置","與部落、學校相鄰的位置關係"],"funFact":"日治時期部落的神社多以「祠」為名，一說是為了避免和原住民部落的「社」混淆。","photoSpot":"從殘蹟回望景美國小與部落","visitMin":20,"openNote":"位於秀林鄉景美村景美國小後方，官方資料記載戶外空間隨時參觀。請尊重部落與學校作息，上課時間勿穿越校園。出發前請查詢最新開放與道路狀況。","dialogue":[{"who":"R","text":"Allan，景美國小後面有神社？我只看到樹和一些石頭耶。"},{"who":"A","text":"那些石頭就是重點。這裡是日治時期的加灣神社，現在只剩殘存的基座和遺構。"},{"who":"R","text":"它是什麼時候蓋的？當時拜的又是誰呢？"},{"who":"A","text":"文獻記載1938年鎮座，拜開拓三神和北白川宮能久親王。當時政府要求大家參拜神社，是同化政策的一部分。"},{"who":"R","text":"所以對住在這裡的太魯閣族人來說，這是被要求接受的外來信仰。"},{"who":"A","text":"沒錯，所以看這種遺構要帶著理解的心。順帶一提，當時部落裡的神社多叫祠，一說是怕跟部落的社搞混。"},{"who":"R","text":"社和社撞名，連日本人都會頭痛，比Allan記不住便當店名字還嚴重！"},{"who":"A","text":"被你抓到了。到現場時請安靜一點，找找看殘存基座的石砌邊緣，想像原本社殿有多大。"}],"clues":["文獻記載我在1938年鎮座，祭祀開拓三神與一位親王","我只剩下殘存基座，旁邊就是一所國小","我在秀林鄉景美村，舊名叫九宛的部落附近"],"quiz":[{"q":"依文獻，加灣神社是哪一年鎮座的？","options":["1914年","1926年","1945年","1938年"],"answer":3,"explain":"九宛祠1938年鎮座。"},{"q":"日治時期部落神社多以什麼為名，以免與部落單位混淆？","options":["祠","宮","殿","院"],"answer":0,"explain":"多以「祠」為名，一說是避免與部落的「社」混淆。"}],"images":[]},{"id":"hualian-linwujusushejing","name":"林務局宿舍菁華街33號及33-2號","short":"菁華街林務宿舍","category":"歷史建築","level":"","town":"花蓮市","types":["其他設施"],"lat":23.980374,"lng":121.615423,"address":"花蓮縣花蓮市花蓮市菁華街33號及33-2號","announced":"2006-11-02","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20061102000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-25/9dd20205-b39d-4af8-95ee-7f184264b653/c花蓮-林務局宿舍菁華街04.jpg","year":1938,"yearText":"1938～1940年間（昭和13～15年）","era":"japan","themes":["職務宿舍","日式建築","林業聚落"],"yearUnknown":false,"summary":"德式雨淋板外牆，臺灣少見的日式住宅","intro":"林務局宿舍菁華街33號及33-2號位於花蓮市菁華街，與花蓮港山林事業所、菁華林苑相鄰。依地籍資料，這塊地1938年仍是旱地，同年轉賣給東臺灣無盡會社專務安武伊八後改為建地，推斷建築是1938～1940年間興建的安武家自宅。戰後由公產機關接收，曾作為木瓜林區管理處副處長住所，1971年起配住給兩戶人家，1975年林務局又在西側空地加蓋兩棟兩層樓宿舍。原建築約42.7坪，屋頂為仿背心式切角頂，屋頂有六邊形通風氣窗，外牆用了一般官舍少見的德式雨淋板，2006年登錄為歷史建築。","highlights":["正立面中段少見的德式雨淋板","屋頂上防止木屋架受潮的六邊形通風氣窗","設有床之間與平書院的八帖接待室"],"funFact":"這棟房子原本是私人住宅，屋主安武伊八在東臺灣無盡會社擔任專務，戰後才變成林務宿舍。","photoSpot":"在菁華街側拍德式雨淋板與切角屋頂","visitMin":15,"openNote":"位於花蓮市菁華街，官方資料未載開放時間，目前以外觀參觀為主。和菁華林苑、花蓮港山林事業所、舊花蓮港高女校長宿舍都在步行範圍內，可一起串遊。","dialogue":[{"who":"R","text":"Allan，這棟房子的木板外牆跟旁邊的好像不太一樣耶，怎麼看起來比較整齊？"},{"who":"A","text":"眼力很好喔！這叫德式雨淋板，一般官舍很少用，是這棟房子立面的最大特色。"},{"who":"R","text":"那這麼講究的房子，是哪位大官住的啊？"},{"who":"A","text":"其實一開始是私宅。1938年地主安武伊八買下這塊旱地蓋房子，他是東臺灣無盡會社的專務。"},{"who":"R","text":"無盡會社？聽起來好像錢會無窮無盡！"},{"who":"A","text":"想得美，我的荷包倒是很有盡。戰後房子被接收，變成林務單位的宿舍，1971年起配住給兩戶人家。"},{"who":"R","text":"那屋頂上那個六角形的小窗戶又是做什麼的？"},{"who":"A","text":"那是通風氣窗，讓木頭屋架不會受潮發霉。你去數數看，那扇氣窗到底有幾個邊！"}],"clues":["我原本是私人住宅，屋主在無盡會社當專務","戰後我被接收，變成林區管理處長官的住所","我在菁華街，外牆用了少見的德式雨淋板"],"quiz":[{"q":"這棟宿舍正立面最有特色的外牆材料是什麼？","options":["紅磚清水牆","德式雨淋板","洗石子仿石牆","竹編灰泥牆"],"answer":1,"explain":"中段鋪的是官舍少見的德式雨淋板。"},{"q":"屋頂上的六邊形氣窗主要用途是什麼？","options":["防止木屋架受潮","觀察天象","排放炊煙","放置神龕"],"answer":0,"explain":"通風氣窗的目的是防止木構造屋架受潮。"}],"images":[{"file":"林務局宿舍菁華街33號及33-2號3.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fb/%E6%9E%97%E5%8B%99%E5%B1%80%E5%AE%BF%E8%88%8D%E8%8F%81%E8%8F%AF%E8%A1%9733%E8%99%9F%E5%8F%8A33-2%E8%99%9F3.jpg/960px-%E6%9E%97%E5%8B%99%E5%B1%80%E5%AE%BF%E8%88%8D%E8%8F%81%E8%8F%AF%E8%A1%9733%E8%99%9F%E5%8F%8A33-2%E8%99%9F3.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%9E%97%E5%8B%99%E5%B1%80%E5%AE%BF%E8%88%8D%E8%8F%81%E8%8F%AF%E8%A1%9733%E8%99%9F%E5%8F%8A33-2%E8%99%9F3.jpg","artist":"王綉敏","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/hualian-linwujusushejing-0.webp","small":"img/hualian-linwujusushejing-0-s.webp"}]},{"id":"hualian-shuguangqiao","name":"曙光橋","short":"曙光橋","category":"歷史建築","level":"","town":"花蓮市","types":["橋樑"],"lat":23.979331,"lng":121.618046,"address":"花蓮縣花蓮市花蓮市美崙區出海口，花蓮市北濱段115地號、民德段31地號(現在橋所在地無地號，僅有115-4、1511-2)","announced":"2005-03-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20050329000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-25/cefba7ce-147e-4148-bf2e-ec92c93a9fd0/c花蓮-曙光橋19.jpg","year":1939,"yearText":"約1939年（昭和14年）推測興建","era":"japan","themes":["鐵道交通","港口海運"],"yearUnknown":false,"summary":"臨港線舊鐵橋，變身迎接日出的單車步道","intro":"曙光橋位於花蓮市美崙溪出海口，舊稱美崙溪橋或米崙溪橋，原是花蓮港臨港支線的鐵道橋。日治初期花蓮港灘寬水淺，大船只能停在外海，再由阿美族人划「駁仔船」接駁上岸。1931年起興築花蓮港，1939年開港，臨港線鐵道同年通車，官方推測鐵橋也在此時興建，列車從舊花蓮車站經此駛往花蓮港車站。1970年代北迴鐵路完工、花蓮車站西遷後，臨港線荒廢。2000年縣府規劃南北濱自行車道，在鋼構上鋪木棧道並改名「曙光橋」，2005年登錄為歷史建築。","highlights":["長111公尺、寬2.8公尺的鋼構鐵道橋身","鋪上木棧板的橋面，單車與行人共用","保留原貌的橋墩基座與美崙溪出海口景色"],"funFact":"「曙光橋」這個名字是2000年改造成自行車道時才取的，意思是迎接第一道曙光。","photoSpot":"清晨站在橋頭，拍鋼構延伸向出海口的日出","visitMin":20,"openNote":"位於花蓮市美崙溪出海口，屬南北濱自行車道的一段，官方資料記載隨時開放。從臺鐵花蓮站搭車或騎單車到南濱、北濱一帶，可串遊花蓮市區景點。","dialogue":[{"who":"R","text":"Allan，這座橋上面鋪著木頭，騎腳踏車的人好多，它以前也是給人走的嗎？"},{"who":"A","text":"以前是給火車走的喔！它舊名叫美崙溪橋，是通往花蓮港的臨港線鐵道橋。"},{"who":"R","text":"火車開去港口幹嘛？要搭船出國嗎？"},{"who":"A","text":"是載貨啦。早年花蓮港水淺，大船停在外海，要靠阿美族人划駁仔船接駁上岸，很辛苦。"},{"who":"R","text":"所以後來蓋了港口，就需要鐵路把貨運進運出囉？"},{"who":"A","text":"沒錯，花蓮港1939年開港，臨港線同年通車，官方推測這座橋也是那時候蓋的。"},{"who":"R","text":"那它怎麼會變成叫曙光橋？聽起來好浪漫！"},{"who":"A","text":"2000年改成自行車道時取的名字，意思是迎接第一道曙光。我每次來都想說，曙光早安，早餐呢？"},{"who":"R","text":"大家可以挑個清晨來，站在橋上數數看鋼構橋身有幾段，再拍一張日出！"}],"clues":["我曾經載著列車往返港口，後來荒廢了好多年","我長111公尺，橋面後來鋪上木棧板給單車騎","我在美崙溪出海口，名字的意思是迎接第一道陽光"],"quiz":[{"q":"曙光橋原本是哪一種橋？","options":["公路汽車橋","臨港線鐵道橋","人行吊橋","灌溉水圳渡槽"],"answer":1,"explain":"曙光橋舊稱美崙溪橋，原是通往花蓮港的臨港支線鐵橋。"},{"q":"官方推測曙光橋大約在哪一年前後興建？","options":["1939年","1912年","1925年","1955年"],"answer":0,"explain":"花蓮港1939年開港，臨港線同年通車，推測鐵橋也在此時興建。"}],"images":[{"file":"曙光橋.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/%E6%9B%99%E5%85%89%E6%A9%8B.JPG/960px-%E6%9B%99%E5%85%89%E6%A9%8B.JPG","page":"https://commons.wikimedia.org/wiki/File:%E6%9B%99%E5%85%89%E6%A9%8B.JPG","artist":"The original uploader was Pinc at Chinese Wikipedia.","license":"CC BY-SA 1.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/1.0","local":"img/hualian-shuguangqiao-0.webp","small":"img/hualian-shuguangqiao-0-s.webp"}]},{"id":"hualian-gaonongxiaozhangsushe","name":"國立花蓮高級農業職業學校舊校長宿舍","short":"花農舊校長宿舍","category":"歷史建築","level":"","town":"花蓮市","types":["宅第"],"lat":23.982478,"lng":121.607697,"address":"花蓮縣花蓮市花蓮市林森路260號","announced":"2018-06-12","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20180704000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-27/cbbc91f8-5863-4e69-8d8a-ec7063b90b01/c花蓮-花農校長舊宿舍02.jpg","year":1940,"yearText":"約1937～1945年（昭和12～20年）","era":"japan","themes":["職務宿舍","教育運動","日式建築"],"yearUnknown":false,"summary":"搬了三次家的花農，校長住的日式木屋","intro":"國立花蓮高級農業職業學校舊校長宿舍位於花蓮市林森路。花蓮高農前身是1921年創立的花蓮港街立簡易農業學校，次年改名花蓮農業補習學校，先後在1928、1933年遷校，1942年遷到現址並改名花蓮港廳立農林學校。依日治都市計畫圖與美軍航照判斷，校長宿舍建於1937至1945年間，為獨棟木造高級職官舍，戰後1954年登記為校長宿舍。屋頂為入母屋與切妻形式，真壁構造配雨淋板外牆，室內格局完整並保有建具與欄間；外加斜撐補強，後方另有加強磚造的防颱室。","highlights":["入母屋與切妻組合、變化豐富的屋面","室內保留的建具與欄間","後方加強磚造的防颱室"],"funFact":"花蓮高農從1921年創校到1942年落腳現址，前後遷校了三次。","photoSpot":"從圍牆外拍入母屋屋頂側面","visitMin":10,"openNote":"位於花蓮市林森路，為學校經管建物，官方未載開放資訊，請以外觀參觀為主，出發前請查詢最新開放狀況。位於花蓮市區，可步行前往。","dialogue":[{"who":"R","text":"Allan，這棟木屋是校長宿舍？校長每天走路上班嗎？"},{"who":"A","text":"很有可能喔！這是花蓮高農的舊校長宿舍，大約建於1937到1945年間，戰後一直給歷任校長住。"},{"who":"R","text":"花蓮高農是一所歷史很悠久的學校嗎？"},{"who":"A","text":"1921年就創校了，前後搬了三次家，1942年才搬到現址，改叫花蓮港廳立農林學校。"},{"who":"R","text":"搬了三次家，比我換手機殼還要勤勞！"},{"who":"A","text":"哈哈。這棟宿舍屋頂有入母屋也有切妻，裡面還保留欄間，就是門上方透氣的雕花板。"},{"who":"R","text":"那它後面那間水泥小屋又是做什麼的？"},{"who":"A","text":"那是防颱室，花蓮颱風多，木屋旁邊加一間堅固的磚造避難空間，跟原本的房子搭配得剛剛好。到現場找找看外牆的斜撐補強在哪裡！"}],"clues":["我後方有一間加強磚造的防颱室","我服務的學校1921年創校，搬了三次家","我是花蓮林森路上，一所農業學校校長住過的木屋"],"quiz":[{"q":"花蓮高農在哪一年遷到現址？","options":["1921年","1928年","1933年","1942年"],"answer":3,"explain":"1942年遷移至現址並更名為花蓮港廳立農林學校。"},{"q":"校長宿舍後方為因應氣候增建了什麼？","options":["防颱室","溫室","游泳池","防空塔"],"answer":0,"explain":"後方增建加強磚造防颱室，反映本地氣候。"}],"images":[{"file":"國立花蓮高級農業職業學校舊校長宿舍.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/da/%E5%9C%8B%E7%AB%8B%E8%8A%B1%E8%93%AE%E9%AB%98%E7%B4%9A%E8%BE%B2%E6%A5%AD%E8%81%B7%E6%A5%AD%E5%AD%B8%E6%A0%A1%E8%88%8A%E6%A0%A1%E9%95%B7%E5%AE%BF%E8%88%8D.jpg/960px-%E5%9C%8B%E7%AB%8B%E8%8A%B1%E8%93%AE%E9%AB%98%E7%B4%9A%E8%BE%B2%E6%A5%AD%E8%81%B7%E6%A5%AD%E5%AD%B8%E6%A0%A1%E8%88%8A%E6%A0%A1%E9%95%B7%E5%AE%BF%E8%88%8D.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%9C%8B%E7%AB%8B%E8%8A%B1%E8%93%AE%E9%AB%98%E7%B4%9A%E8%BE%B2%E6%A5%AD%E8%81%B7%E6%A5%AD%E5%AD%B8%E6%A0%A1%E8%88%8A%E6%A0%A1%E9%95%B7%E5%AE%BF%E8%88%8D.jpg","artist":"王綉敏","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/hualian-gaonongxiaozhangsushe-0.webp","small":"img/hualian-gaonongxiaozhangsushe-0-s.webp"}]},{"id":"hualian-jiuhualiantieluyi","name":"舊花蓮鐵路醫院","short":"舊鐵路醫院","category":"歷史建築","level":"","town":"花蓮市","types":["醫院"],"lat":23.97313,"lng":121.609196,"address":"花蓮縣花蓮市花蓮市廣東街326號","announced":"2009-08-13","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20090813000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-04-15/14a1cca1-299a-4184-868b-ca802878d09c/舊花蓮鐵路醫院1.jpg","year":1940,"yearText":"1940年（昭和15年）遷至現址","era":"japan","themes":["鐵道交通","公共建築"],"yearUnknown":false,"summary":"照顧鐵道職員的老醫院，後來變成石藝大街","intro":"舊花蓮鐵路醫院位於花蓮市廣東街一帶，是日治時期鐵道部「鐵道職員共濟組合」經營的醫療設施。1936年花蓮港設立共濟組合養療所，1940年遷到現址，官方稱其為花蓮港廳的大醫院之一，與當時的花蓮港醫院並駕齊驅。戰後持續作為鐵路醫院，1983年因經營入不敷出而結束營運。閒置多年後，2003年花蓮縣手工藝協會承租，轉型為「石藝大街」。建築為一層木構造，平面呈「工」字形，前棟為門診、後棟為病房，以迴廊與小中庭串連；台基下有四層弧形洗石子線腳，車寄有兩對花瓶造型柱，2009年登錄為歷史建築。","highlights":["車寄前兩對洗石子花瓶造型柱","台基下四層弧形的土黃色洗石子線腳","工字形平面與迴廊、小中庭的配置"],"funFact":"醫院停業後，2003年由花蓮縣手工藝協會承租，老病房區搖身變成賣石藝品的石藝大街。","photoSpot":"正面拍車寄的花瓶柱與入口門廳","visitMin":30,"openNote":"位於花蓮市廣東街，現為石藝大街，官方資料記載每日15:00至22:00開放。從臺鐵花蓮站開車或騎車約10分鐘，可與舊東線鐵道相關遺構、鐵道文化園區一帶串遊。","dialogue":[{"who":"R","text":"Allan，這裡明明在賣石頭和藝品，為什麼你說它以前是醫院？"},{"who":"A","text":"因為它真的是醫院啊！日治時期鐵道部為了照顧職員，成立共濟組合，這裡就是他們的醫院。"},{"who":"R","text":"專門給鐵路員工看病的醫院？那火車司機感冒也來這裡嗎？"},{"who":"A","text":"對。1940年遷到這裡，官方說它是當時花蓮港廳的大醫院之一，跟花蓮港醫院並駕齊驅。"},{"who":"R","text":"那醫院後來怎麼會變成賣石頭的石藝大街？"},{"who":"A","text":"1983年因為入不敷出停業，閒置很多年，2003年手工藝協會接手，病房就變成藝品店了。"},{"who":"R","text":"以前來這裡要掛號，現在來這裡要殺價！"},{"who":"A","text":"說得好！醫院平面是工字形，前棟看門診，後棟住病房，中間有好幾個小中庭。"},{"who":"R","text":"那我要去入口找那兩對花瓶造型的柱子，拍下來給大家看！"}],"clues":["我從前專門照顧某個交通事業的員工","1983年我因入不敷出而停業，後來被手工藝協會接手","我現在白天睡覺，下午開始熱鬧，到處都是石頭藝品"],"quiz":[{"q":"舊花蓮鐵路醫院最初是由哪個組織經營？","options":["花蓮港廳衛生課","鐵道職員共濟組合","臺灣紅十字會","東臺灣無盡會社"],"answer":1,"explain":"醫療部是鐵道職員共濟組合的附屬事業。"},{"q":"鐵路醫院停業後轉型成什麼？","options":["石藝大街","鐵道博物館","旅客服務中心","社區圖書館"],"answer":0,"explain":"2003年手工藝協會承租，轉型為石藝大街。"}],"images":[{"file":"Former Hualien Railway Hospital, ramp, Hualien City (Taiwan).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/Former_Hualien_Railway_Hospital%2C_ramp%2C_Hualien_City_%28Taiwan%29.jpg/960px-Former_Hualien_Railway_Hospital%2C_ramp%2C_Hualien_City_%28Taiwan%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Former_Hualien_Railway_Hospital,_ramp,_Hualien_City_(Taiwan).jpg","artist":"Mk2010","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/hualian-jiuhualiantieluyi-0.webp","small":"img/hualian-jiuhualiantieluyi-0-s.webp"}]},{"id":"hualian-songyuanbieguan","name":"松園別館","short":"松園別館","category":"歷史建築","level":"","town":"花蓮市","types":["機關"],"lat":23.982518,"lng":121.615515,"address":"花蓮縣花蓮市水源街26 號","announced":"2002-09-23","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020923000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-27/96daeae1-e20a-4fa3-9bef-5c45cc38555c/c花蓮-松園別館02.jpg","year":1942,"yearText":"1942～1943年（昭和17～18年）","era":"japan","themes":["軍事遺構","日式建築","藝術文化"],"yearUnknown":false,"summary":"老松環抱、俯瞰海港的日治軍事指揮所","intro":"松園別館位於花蓮市美崙山麓水源街一帶，興建於1942～1943年，是日治末期花蓮港陸軍兵事部的辦公室，也是當時日軍在花蓮的最高軍事指揮中心，因四周老松林立而得名。戰後1947年由陸軍總部管理，後來成為美軍顧問團軍官休閒度假中心；1978年交由退輔會管理。1996年退輔會擬將土地當作旅館建地出售，地方人士群起反對，2000年縣府劃為歷史風貌專區並整修，2002年登錄歷史建築。基地呈不規則三角形，主體為二層樓仿洋式拱廊建築，另有武道館等建築與一座防空壕，官方稱它是花蓮縣最完整的日治軍事建築。","highlights":["二層樓仿洋式拱廊主建築，外觀簡樸牢固","園區內的老松林，以及俯瞰花蓮港的視野","保留下來的日治時期防空壕與昔日武道館"],"funFact":"1996年這裡差點被當作旅館建地出售，是地方人士群起反對，才保留成今天的歷史風貌專區。","photoSpot":"在松林間拍二樓拱廊立面","visitMin":60,"openNote":"位於花蓮市美崙山麓水源街，官方資料記載營業時間9:00至18:00，最後入園17:30，目前委外經營，有展覽、表演與餐飲。從花蓮市區開車或騎車約10分鐘，可與將軍府、菁華林苑一帶串遊。","dialogue":[{"who":"A","text":"阿拉蕾，聞到了嗎？這一片松樹的味道，就是松園別館名字的由來。"},{"who":"R","text":"好香喔！可是Allan，別館聽起來像度假會館，它以前是做什麼的？"},{"who":"A","text":"1942年前後蓋的，是花蓮港陸軍兵事部的辦公室，日軍在花蓮的最高軍事指揮中心。"},{"who":"R","text":"指揮中心外觀這麼樸素？我還以為會很氣派。"},{"who":"A","text":"那時戰事已經開打，只求實用牢固。不過二樓拱廊加上俯瞰海港的視野，還是很有派頭。"},{"who":"R","text":"那戰後呢？一直都是軍方在用嗎？"},{"who":"A","text":"戰後軍方接管，還當過美軍軍官的休閒度假中心。1996年差點被賣掉蓋旅館，是地方人士站出來保住的。"},{"who":"R","text":"好險！不然我們今天就只能來這裡辦入住了。"},{"who":"A","text":"哈，我還真想住。現在去園區找找那座日治時期留下來的防空壕，看看入口長什麼樣子！"}],"clues":["我曾差點被當成旅館建地賣掉，地方人士把我留了下來","我是日治末期的陸軍兵事部，院子裡還有防空壕","我在美崙山麓，四周老松林立，名字也因此而來"],"quiz":[{"q":"松園別館在日治時期的用途是什麼？","options":["花蓮港廳長官邸","移民村指導所","專賣局倉庫","陸軍兵事部辦公室"],"answer":3,"explain":"它是花蓮港陸軍兵事部的辦公室，日軍在花蓮的最高指揮中心。"},{"q":"松園別館的名稱由來是什麼？","options":["第一任主人姓松","建材全用松木","四周老松林立","靠近松山車站"],"answer":2,"explain":"因為四周老松林立、環境清幽而得名。"}],"images":[{"file":"松園別館.jpg","thumb":"https://upload.wikimedia.org/wikipedia/commons/8/8e/%E6%9D%BE%E5%9C%92%E5%88%A5%E9%A4%A8.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%9D%BE%E5%9C%92%E5%88%A5%E9%A4%A8.jpg","artist":"Fcuk1203","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"}]},{"id":"fenglin-zhiyaganqiao","name":"支亞干橋（豐平橋）","short":"支亞干橋","category":"歷史建築","level":"","town":"鳳林鎮","types":["橋樑"],"lat":23.81177,"lng":121.451697,"address":"花蓮縣鳳林鎮舊台9線230K+837～231K+378","announced":"2016-09-06","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20160906000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-04-10/bd4fdeed-44b7-409f-97a5-73254ac4fae1/g鳳林-支亞干橋05.jpg","year":1943,"yearText":"1943年（昭和18年）","era":"japan","themes":["公共建築"],"yearUnknown":false,"summary":"20座圓拱連成的老豐平橋，服役約70年","intro":"支亞干橋又稱豐平橋，橫跨壽豐溪（舊名支亞干溪），位在壽豐鄉與鳳林鎮交界，恰是溪流出中央山脈後河道最窄處。橋建於1943年戰爭期間，原為花東公路（日治稱台東花蓮港道）的一段，長約500公尺、寬4公尺，以20座鋼筋混凝土圓拱連結而成，拱上另有垂直支撐的柱牆，官方說明稱是臺灣碩果僅存的最大型多體連結圓拱橋。1981年因車流增加，在舊橋東側緊鄰處增建新橋，橋面淨寬增為11公尺，成為新舊合體的橋。2012年台9線新豐平橋通車後，它才卸下約70年的重任。","highlights":["20座圓拱一路連到對岸的壯觀橋身","1943年老橋與1981年新橋並肩合體","拱圈上方的垂直柱牆複合結構"],"funFact":"1981年增建時並沒有拆舊橋，而是在東側緊貼著蓋新橋，讓左車道是老橋、右車道是新橋。","photoSpot":"從河岸側面拍一整排連續圓拱","visitMin":20,"openNote":"位於鳳林鎮林榮里舊台9線，跨壽豐溪，官方資料記載隨時開放。舊橋已由新豐平橋取代，現場請注意車輛與河床安全。建議開車前往。","dialogue":[{"who":"R","text":"Allan，這座橋的拱一個接一個，到底有幾個啊？我數到眼睛都花了！"},{"who":"A","text":"總共20座圓拱，連成一座約500公尺的長橋，它叫支亞干橋，也叫豐平橋，數到眼花很正常。"},{"who":"R","text":"看起來好有年紀，是什麼時候蓋的？"},{"who":"A","text":"1943年，戰爭期間蓋的，橫跨壽豐溪，剛好在壽豐和鳳林的交界。"},{"who":"R","text":"可是後來車子越來越多，這麼窄的老橋撐得住嗎？"},{"who":"A","text":"1981年在旁邊緊貼著加蓋新橋，新舊合體，像老爸背著兒子一起上班。"},{"who":"R","text":"好溫馨又好累！那它什麼時候退休？"},{"who":"A","text":"2012年新豐平橋通車，它才卸下約70年的重任，比我上班還資深。"},{"who":"R","text":"我去河岸拍一張全景，看能不能把20座拱都塞進同一張照片裡！"}],"clues":["1981年有個新夥伴緊貼著我的東側一起扛車流","我由20座鋼筋混凝土圓拱連結而成","我橫跨壽豐溪，就在壽豐鄉與鳳林鎮交界"],"quiz":[{"q":"支亞干橋由幾座圓拱連結而成？","options":["10座","12座","16座","20座"],"answer":3,"explain":"橋體以20座圓拱橋體結構連結而成。"},{"q":"支亞干橋在哪一年因新橋通車而退役？","options":["1981年","2012年","1998年","2020年"],"answer":1,"explain":"2012年台9線新豐平橋完工通車後卸下重任。"}],"images":[]},{"id":"hualian-zhongguoguangbogu","name":"中國廣播股份有限公司花蓮電台（原台灣放送協會花蓮港放送局）","short":"中廣花蓮台","category":"歷史建築","level":"","town":"花蓮市","types":["辦公廳舍"],"lat":23.982955,"lng":121.614726,"address":"花蓮縣花蓮市花蓮市松園街96號","announced":"2015-11-26","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20151126000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-29/c133bda6-e8b3-486d-af54-da899b7e257e/c花蓮-中廣電台06.jpg","year":1944,"yearText":"1944年（昭和19年）","era":"japan","themes":["公共建築"],"yearUnknown":false,"summary":"日治最後一座放送局，東部廣播的起點","intro":"中國廣播公司花蓮電台位於花蓮市松園街底，前身為台灣放送協會花蓮港放送局。日治時期臺灣陸續設立台北、臺南、臺中、嘉義放送局，花蓮港放送局於1944年4月15日完工、5月1日正式播音，是臺灣第5座、也是日治時期最後一座放送機構，象徵全島廣播網完成與東部廣播事業的開端。局址在美崙山東南側松林坡地，與兵事部（今松園別館）、海岸電台及水源地相鄰。建築為磚木混合平房，寄棟與切妻屋頂，主入口設車寄，牆面貼昭和時期流行的黃色小磁磚。","highlights":["車寄與玄關之間3.8公分見方的黃色磁磚","主入口車寄兩側的弧形緩坡","園區內的廣播電塔與列管老樹"],"funFact":"花蓮港放送局的天線是日治時期5座放送局裡最矮的一座，推測與它位在山坡高處有關。","photoSpot":"拍車寄入口與黃色磁磚牆面","visitMin":20,"openNote":"位於花蓮市松園街底，鄰近松園別館。官方資料記載修復暨環境美化工程進行中，未載開放時間，出發前請查詢最新開放狀況。","dialogue":[{"who":"R","text":"Allan，松園街走到底，這棟房子旁邊有一根好高的鐵塔！"},{"who":"A","text":"那是廣播電塔。這裡是中廣花蓮台，前身是1944年開播的花蓮港放送局。"},{"who":"R","text":"1944年？那不是第二次世界大戰快結束的時候嗎？"},{"who":"A","text":"對，它是日治時期臺灣第5座、也是最後一座放送局，完成了全島廣播網。"},{"who":"R","text":"所以東部的廣播事業，就是從這裡開始的囉！"},{"who":"A","text":"沒錯。它旁邊是兵事部，就是現在的松園別館，位置居高臨下，看得到海面和機場。"},{"who":"R","text":"位置這麼好，那它的天線一定是全臺灣最高最帥的吧？"},{"who":"A","text":"反而是5座放送局裡最矮的，推測是因為本身就在山坡高處，不用再拚身高。到現場找找車寄牆上的黃色小磁磚吧！"}],"clues":["我的牆上貼著昭和時期流行的黃色小磁磚","我是日治時期臺灣最後設立的放送局","我在花蓮松園街底，至今仍是廣播電台"],"quiz":[{"q":"花蓮港放送局是日治時期臺灣第幾座放送局？","options":["第2座","第3座","第4座","第5座"],"answer":3,"explain":"繼台北、臺南、臺中、嘉義之後的第5座。"},{"q":"與花蓮港放送局相鄰、今稱松園別館的是當年的什麼單位？","options":["兵事部","郵便局","公學校","神社"],"answer":0,"explain":"花蓮港兵事部辦公室，即今松園別館。"}],"images":[{"file":"中廣公司花蓮台 Taiwan Broadcasting Company Hualian Station - panoramio.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0f/%E4%B8%AD%E5%BB%A3%E5%85%AC%E5%8F%B8%E8%8A%B1%E8%93%AE%E5%8F%B0_Taiwan_Broadcasting_Company_Hualian_Station_-_panoramio.jpg/960px-%E4%B8%AD%E5%BB%A3%E5%85%AC%E5%8F%B8%E8%8A%B1%E8%93%AE%E5%8F%B0_Taiwan_Broadcasting_Company_Hualian_Station_-_panoramio.jpg","page":"https://commons.wikimedia.org/wiki/File:%E4%B8%AD%E5%BB%A3%E5%85%AC%E5%8F%B8%E8%8A%B1%E8%93%AE%E5%8F%B0_Taiwan_Broadcasting_Company_Hualian_Station_-_panoramio.jpg","artist":"lienyuan lee","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0","local":"img/hualian-zhongguoguangbogu-0.webp","small":"img/hualian-zhongguoguangbogu-0-s.webp"}]},{"id":"hualian-guozijiuguju","name":"郭子究故居","short":"郭子究故居","category":"歷史建築","level":"","town":"花蓮市","types":["宅第"],"lat":23.987313,"lng":121.624593,"address":"花蓮縣花蓮市花蓮市民權7街1巷3號","announced":"2005-03-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20050329000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/1197/photo/郭子究故居1.jpg","year":1945,"yearText":"年代不詳（登錄理由稱戰後早期木構造）","era":"unknown","themes":["藝術文化","職務宿舍"],"yearUnknown":true,"summary":"花蓮音樂之父的雨淋板老家","intro":"郭子究故居位於花蓮市民權七街，附近是花蓮高中的教師宿舍群。郭子究被稱為「花蓮音樂之父」，長年在花蓮推動音樂教育與合唱藝術，這棟雨淋板木構造宿舍就是他生前的住家。官方資料記載它原為「花蓮港廳立花蓮港中學校」教職員宿舍第15號，登錄理由則稱為戰後早期木構造建築，興建年代說法不一。郭子究生前曾整修擴建，現況大致維持原樣，僅做白蟻防治。故居於2005年登錄為歷史建築，旁邊整修完成的建築作為音樂文化館，有展覽室、小型會議室與表演場，故居本身則展示文物與生前住家的樣貌。","highlights":["保留生前樣貌的郭子究住家房舍","日式雨淋板外牆的木構造宿舍","旁邊作為展覽與表演空間的音樂文化館"],"funFact":"故居原本是花蓮港中學校的教職員宿舍第15號，所在地號與周邊花蓮高中教師宿舍屬同一筆。","photoSpot":"在民權七街1巷口拍木造故居與巷弄","visitMin":30,"openNote":"位於花蓮市民權七街，官方資料記載週一至週五10:00至12:00、14:00至16:00開放參觀，出發前請再確認。從花蓮市區開車或騎車約10分鐘。","dialogue":[{"who":"A","text":"阿拉蕾，先別說話，想像一下，這條巷子裡曾經飄出合唱練習的歌聲。"},{"who":"R","text":"好有畫面！這是哪位音樂家的家？"},{"who":"A","text":"這是郭子究故居。他被稱為花蓮音樂之父，在花蓮推動音樂和合唱教育很多年。"},{"who":"R","text":"音樂之父住的房子，會不會連門鈴都是交響樂？"},{"who":"A","text":"哈，沒那麼誇張。它是雨淋板木造宿舍，原本是花蓮港中學校的教職員宿舍第15號。"},{"who":"R","text":"那旁邊那幾棟新整理的房子是什麼？"},{"who":"A","text":"那是音樂文化館，有展覽和小型表演場。故居本身則保留郭老師生前住家的樣子。"},{"who":"R","text":"那我要輕聲細語地參觀，免得打擾到音樂的回憶。"},{"who":"A","text":"很好。進去之後，找找看他生前用過的書桌或樂譜，想像他當年在這間屋子裡寫歌的樣子！"}],"clues":["我原本是一所中學的教職員宿舍第15號","我的主人一輩子在花蓮推廣合唱","我是花蓮音樂之父的家，在民權七街"],"quiz":[{"q":"郭子究被稱為什麼？","options":["花蓮文學之父","花蓮音樂之父","花蓮鐵道之父","花蓮林業之父"],"answer":1,"explain":"官方資料稱郭子究為花蓮音樂之父。"},{"q":"郭子究故居原本是哪所學校的宿舍？","options":["花蓮港中學校","花蓮港高等女學校","花蓮港公學校","豐田小學校"],"answer":0,"explain":"原為花蓮港廳立花蓮港中學校教職員宿舍第15號。"}],"images":[{"file":"郭子究故居.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/da/%E9%83%AD%E5%AD%90%E7%A9%B6%E6%95%85%E5%B1%85.jpg/960px-%E9%83%AD%E5%AD%90%E7%A9%B6%E6%95%85%E5%B1%85.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%83%AD%E5%AD%90%E7%A9%B6%E6%95%85%E5%B1%85.jpg","artist":"☼ うみ 目覚めたら from Taipei, Taiwan","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","local":"img/hualian-guozijiuguju-0.webp","small":"img/hualian-guozijiuguju-0-s.webp"}]},{"id":"guangfu-tangchangyuangong","name":"花蓮糖廠員工宿舍1巷1、3號","short":"糖廠員工宿舍","category":"歷史建築","level":"","town":"光復鄉","types":["宅第"],"lat":23.654454,"lng":121.418675,"address":"花蓮縣光復鄉光復鄉大進村糖廠街1巷1、3號","announced":"2011-10-04","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20111004000007","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-20/7d87c2e5-290f-449f-bd37-9e00a486df6a/h光復-糖廠宿舍1巷1 3號04.jpg","year":1948,"yearText":"1948年（民國37年）","era":"postwar","themes":["糖業","職務宿舍"],"yearUnknown":false,"summary":"一棟住兩戶的乙種雙併宿舍","intro":"花蓮糖廠員工宿舍1巷1、3號位於光復鄉大進村糖廠街，是花蓮糖廠宿舍群的一部分。糖廠的日式木構宿舍最早建於1922年，之後在1936、1939、1948年陸續興建。這棟是乙種雙併員工宿舍，與同巷5、7號一樣，都在1948年仿照日治時期乙種雙併宿舍的設計建造。糖廠為了解決員工通勤費時，把宿舍與生產場所緊密相連，宿舍依職位分成多種格局與等級，形成規格化的營建制度。這棟雙併宿舍呈現花蓮糖廠宿舍建築的演變與階級區分，也見證製糖產業在光復地方的發展。","highlights":["一棟兩戶的乙種雙併宿舍格局","1948年仿日治設計建造的木構宿舍","與同巷5、7號成組的宿舍街景"],"funFact":"糖廠宿舍分好幾種等級，這棟乙種雙併宿舍一棟住兩戶，和隔壁的5、7號是同一年仿日治設計蓋的。","photoSpot":"在1巷巷口拍雙併宿舍對稱立面","visitMin":10,"openNote":"位於光復鄉大進村糖廠街1巷，官方資料未載開放資訊，以外觀參觀為主，請勿打擾住戶。光復鄉在2025年9月馬太鞍溪堰塞湖溢流後仍在復原，出發前請查詢最新開放與道路狀況。","dialogue":[{"who":"R","text":"Allan，前面看過廠長和副廠長的家，那一般員工住哪裡？"},{"who":"A","text":"就住這裡，花蓮糖廠員工宿舍1巷1、3號，是一棟住兩戶的乙種雙併宿舍。"},{"who":"R","text":"一棟住兩戶？那隔壁打呼聲是不是聽得一清二楚？"},{"who":"A","text":"很有可能，所以當年鄰居感情一定很好，連晚餐菜色都瞞不住。"},{"who":"R","text":"哈哈，好有畫面！那這棟宿舍是日治時期蓋的嗎？"},{"who":"A","text":"是1948年仿照日治乙種雙併宿舍的設計蓋的，跟同巷5、7號是同一批。"},{"who":"R","text":"為什麼糖廠要把宿舍蓋在工廠旁邊？"},{"who":"A","text":"為了讓員工上班不用通勤太久，宿舍和工廠緊緊相連，等級也分得很清楚。"},{"who":"R","text":"我去1巷巷口找找，看這棟雙併宿舍左右兩半，是不是長得一模一樣！"}],"clues":["我一棟住兩戶，和隔壁5、7號是同年出生","1948年仿照日治乙種雙併宿舍的設計建造","我是光復鄉糖廠1巷給一般職員住的家"],"quiz":[{"q":"員工宿舍1巷1、3號屬於哪一種宿舍？","options":["甲種獨棟","丙種連棟","乙種雙併","單身宿舍"],"answer":2,"explain":"官方記載為雙併乙種員工宿舍。"},{"q":"花蓮糖廠的日式木構宿舍最早建於哪一年？","options":["1922年","1913年","1948年","1952年"],"answer":0,"explain":"宿舍群最早建於1922年，之後陸續興建。"}],"images":[]},{"id":"guangfu-tangchangyuangong2","name":"花蓮糖廠員工宿舍1巷5、7號","short":"糖廠宿舍1巷5、7號","category":"歷史建築","level":"","town":"光復鄉","types":["宅第"],"lat":23.654572,"lng":121.418367,"address":"花蓮縣光復鄉光復鄉大進村糖廠街1巷5、7號","announced":"2011-10-04","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20111004000008","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-20/2da236a4-abe0-4a35-9e8a-acd86d72698f/h光復-糖廠宿舍1巷5 7號08.jpg","year":1948,"yearText":"1948年（民國37年）","era":"postwar","themes":["糖業","職務宿舍","日式建築"],"yearUnknown":false,"summary":"戰後照日治乙種雙併設計蓋的糖廠宿舍","intro":"花蓮糖廠員工宿舍1巷5、7號位於光復鄉大進村糖廠街，是一棟雙併乙種員工宿舍。花蓮糖廠前身為1921年興建的鹽水港製糖株式會社花蓮港製糖所大和工場，廠區由北而南配置工廠、辦公室、鐵道、宿舍、醫院與學校。宿舍群最早建於1922年，之後在1936、1939、1948年陸續增建；這棟建於1948年，戰後仍仿照日治時期乙種雙併宿舍的設計建造。木造軸組、雨淋板外牆、水泥瓦屋頂與架高通風的台基保存完整，也反映廠方依職級配置宿舍的制度。","highlights":["簷廊下收納防颱板的雨戶袋","撐住屋身、兼顧防颱防震的斜撐木","架高通風的台基與雨淋板外牆"],"funFact":"這棟宿舍1948年戰後才蓋，卻完全照著日治時期乙種雙併宿舍的設計，像是一棟「復刻版」宿舍。","photoSpot":"在巷口拍雙併屋頂與簷廊的對稱感","visitMin":15,"openNote":"光復鄉在2025年9月馬太鞍溪堰塞湖溢流後仍在復原，出發前請查詢最新開放與道路狀況。位於光復鄉糖廠街1巷的花蓮糖廠宿舍區，官方資料未載開放時間，以外觀參觀為主；可搭臺鐵花東線至光復站。","dialogue":[{"who":"A","text":"阿拉蕾，我們站在光復鄉花蓮糖廠的宿舍區，這一排日式木屋可是有分等級的喔。"},{"who":"R","text":"分等級？房子也要打考績嗎？Allan你別嚇我。"},{"who":"A","text":"差不多啦！廠區宿舍分成好幾種規格，職位不同住的也不同，這棟是雙併的乙種宿舍。"},{"who":"R","text":"看起來好有日本味，一定是日治時期蓋的吧？"},{"who":"A","text":"猜錯了！它是1948年戰後才蓋的，但完全照日治乙種宿舍的設計，算是原汁原味的復刻版。"},{"who":"R","text":"復刻版宿舍，聽起來像限量公仔耶。那它怎麼對付花蓮的颱風和地震？"},{"who":"A","text":"外牆有防颱板，屋身靠斜撐木撐住，台基還墊高通風，比我這顆光頭還耐風吹。"},{"who":"R","text":"噗，你的光頭只是反光比較厲害吧。"},{"who":"A","text":"看完記得去吃一支糖廠冰品。現在請你在簷廊下找找看，收納防颱板的雨戶袋藏在哪裡！"}],"clues":["我是戰後才蓋的，卻照著日治時期的設計圖","我是一棟住兩戶的乙種宿舍","我在光復鄉糖廠街1巷，旁邊就是製糖工廠"],"quiz":[{"q":"這棟糖廠宿舍建於哪一年？","options":["1922年","1936年","1948年","1952年"],"answer":2,"explain":"建於1948年，仿日治乙種雙併宿舍設計。"},{"q":"宿舍用什麼構件穩固屋身、防颱又防震？","options":["斜撐木","鋼筋水泥柱","紅磚拱圈","石砌外牆"],"answer":0,"explain":"斜撐木穩固房屋本體，防颱又防震。"}],"images":[]},{"id":"fenglin-taitiejiulinrong","name":"台鐵舊林榮車站倉庫","short":"舊林榮車站倉庫","category":"歷史建築","level":"","town":"鳳林鎮","types":["其他設施"],"lat":23.80317,"lng":121.451386,"address":"花蓮縣鳳林鎮鳳林鎮林榮里永安街42號","announced":"2016-05-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20160531000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-04-11/73b5a950-e5ea-408b-921d-246f3749c549/g鳳林-林榮車站倉庫09.jpg","year":1949,"yearText":"1949年（民國38年）登記","era":"postwar","themes":["鐵道交通"],"yearUnknown":false,"summary":"車站拆了，只剩這座木造倉庫守著記憶","intro":"林榮車站位於鳳林鎮林榮里，創設於1918年，當時稱平林停車場，1962年改名林榮。1982年臺東線鐵道拓寬，路線改由河底隧道穿過，林榮車站隨之廢站，車站主體在1988年拆除。這座倉庫依臺鐵財產資料登記於1949年，當年作為搶修材料倉庫，是舊車站唯一留存的建築。倉庫長寬約18乘6公尺，切妻式屋頂，內有6組真束小屋組桁架，雨淋板外牆搭配防颱斜撐木，出入口在東北側。官方說明在花蓮相同樣式的建物不多見，也是鳳林鎮唯一同類型建物。","highlights":["切妻屋頂下的6組真束小屋組木桁架","雨淋板外牆與防颱斜撐木","舊車站唯一倖存的建築，旁有公園廣場"],"funFact":"這座倉庫的身分是搶修材料倉庫，專門存放鐵道搶修用料，車站拆了，反而是它留了下來。","photoSpot":"在永安街與大雅街口拍倉庫山牆","visitMin":15,"openNote":"位於鳳林鎮林榮里永安街與大雅街口，旁為公園廣場，官方未載開放時間，以外觀參觀為主。建議開車前往。","dialogue":[{"who":"R","text":"Allan，這裡只有一棟木造倉庫，火車站跑到哪裡去了？"},{"who":"A","text":"問得好。林榮車站1918年就設立，當時叫平林停車場，可惜1988年主體拆掉了。"},{"who":"R","text":"車站被拆了，倉庫卻留下來？這是什麼大逃殺劇情？"},{"who":"A","text":"1982年鐵道拓寬，路線改走河底隧道，車站就廢站，最後只剩這座倉庫。"},{"who":"R","text":"那這座倉庫以前裝什麼？難道是裝一整箱的車票嗎？"},{"who":"A","text":"裝的是鐵道搶修材料。它專門救別人，結果自己成了最後的倖存者。"},{"who":"R","text":"好熱血！根本是倉庫界的超級英雄，最後一個站著！"},{"who":"A","text":"到了現場，請數數看外牆上有幾根斜斜的木頭撐著，那是防颱用的斜撐木，數完再看看屋頂山牆的形狀！"}],"clues":["我原本存放的是鐵道搶修材料","我的同伴在1988年被拆除，鐵路後來改走河底隧道","我是鳳林鎮林榮里舊車站唯一留下的建築"],"quiz":[{"q":"林榮車站在日治時期設立時叫什麼名字？","options":["平林停車場","鳳林驛","林田停車場","萬榮停車場"],"answer":0,"explain":"1918年設立時稱平林停車場，1962年改名林榮。"},{"q":"這座倉庫外牆用什麼來防颱？","options":["鋼索拉繩","磚造扶壁","斜撐木","沙包堆疊"],"answer":2,"explain":"雨淋板外牆搭配防颱斜撐木。"}],"images":[{"file":"Taiwan Railways Administration, Old Linjung Station Warehouse, Fenglin Township, Hualien (Taiwan).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/da/Taiwan_Railways_Administration%2C_Old_Linjung_Station_Warehouse%2C_Fenglin_Township%2C_Hualien_%28Taiwan%29.jpg/960px-Taiwan_Railways_Administration%2C_Old_Linjung_Station_Warehouse%2C_Fenglin_Township%2C_Hualien_%28Taiwan%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Taiwan_Railways_Administration,_Old_Linjung_Station_Warehouse,_Fenglin_Township,_Hualien_(Taiwan).jpg","artist":"Mk2010","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/fenglin-taitiejiulinrong-0.webp","small":"img/fenglin-taitiejiulinrong-0-s.webp"}]},{"id":"guangfu-tangchangfuchang","name":"花蓮糖廠副廠長宿舍","short":"糖廠副廠長宿舍","category":"歷史建築","level":"","town":"光復鄉","types":["宅第"],"lat":23.65633,"lng":121.4201,"address":"花蓮縣光復鄉光復鄉大進村糖廠街8巷10號","announced":"2011-10-04","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20111004000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-02-18/03891be4-42ed-4e12-966e-37c0f2908693/h光復-副廠長宿舍07.jpg","year":1949,"yearText":"1949年（民國38年）","era":"postwar","themes":["糖業","職務宿舍"],"yearUnknown":false,"summary":"戰後蓋的仿日式甲級宿舍，庭院植栽多樣","intro":"花蓮糖廠副廠長宿舍位於光復鄉大進村糖廠街，雖然外觀是日式，其實建於戰後1949年，整棟仿日式樣式建造，屬花蓮糖廠甲級獨棟宿舍。前身大和工場1921年興建，廠區由北到南依序是生產工廠、行政辦公室、運輸鐵道、宿舍群、醫院與學校，宿舍與工作場所緊密相連；戰後改稱花蓮港糖廠，1952年更名花蓮糖廠。這棟宿舍有和洋折衷樣式的陽台，原有前後日式庭院雖已更動，現況庭院仍有水池、花圃、日本黑松、榕樹、雨豆樹等多元植栽，保存良好，被視為宿舍群中重要而獨特的一棟。","highlights":["戰後仿日式建造的甲級獨棟宿舍","和洋折衷樣式的陽台","日本黑松、榕樹、雨豆樹等庭院植栽"],"funFact":"這棟看起來很日式的宿舍，其實是戰後1949年才蓋的，屬於「仿日式」的甲級宿舍。","photoSpot":"把陽台和庭院黑松一起拍進來","visitMin":15,"openNote":"位於光復鄉大進村糖廠街，官方資料未載開放資訊，以外觀參觀為主。光復鄉在2025年9月馬太鞍溪堰塞湖溢流後仍在復原，出發前請查詢最新開放與道路狀況。","dialogue":[{"who":"R","text":"Allan，這棟日式宿舍應該是日治時期蓋的吧？"},{"who":"A","text":"這題是陷阱題。花蓮糖廠副廠長宿舍其實是戰後1949年蓋的，只是仿日式。"},{"who":"R","text":"什麼！它是戰後才假裝日式的？這演技也太好了吧！"},{"who":"A","text":"應該說是承襲日式工法和樣式。它屬甲級獨棟宿舍，還有和洋折衷的陽台，等級可不低。"},{"who":"R","text":"副廠長永遠排第二，但這棟房子一點也不輸人耶。"},{"who":"A","text":"官方甚至說它是宿舍群裡最重要而獨特的一棟，副字輩也能出頭天。"},{"who":"R","text":"那這棟宿舍的庭院裡，種了哪些植物呢？"},{"who":"A","text":"有水池、花圃，還有日本黑松、榕樹和雨豆樹，簡直是迷你植物園。"},{"who":"R","text":"我要在庭院裡找出雨豆樹，拍下它和日本黑松站在一起的樣子！"}],"clues":["我看起來像日治建築，其實是戰後仿日式蓋的","我的庭院有日本黑松、榕樹和雨豆樹","我是光復鄉糖廠第二號主管的甲級宿舍"],"quiz":[{"q":"花蓮糖廠副廠長宿舍建於哪一年？","options":["1921年","1949年","1934年","1979年"],"answer":1,"explain":"副廠長宿舍建於戰後1949年，採仿日式建造。"},{"q":"副廠長宿舍屬於糖廠哪一級宿舍？","options":["乙級雙併","丙級連棟","單身宿舍","甲級獨棟"],"answer":3,"explain":"官方記載它屬花蓮糖廠內甲級獨棟式宿舍。"}],"images":[{"file":"Deputy Factory Manager's Quarters, front yard (1949), Hualien Sugar Factory, Guangfu Township, Hualien County (Taiwan).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/47/Deputy_Factory_Manager%27s_Quarters%2C_front_yard_%281949%29%2C_Hualien_Sugar_Factory%2C_Guangfu_Township%2C_Hualien_County_%28Taiwan%29.jpg/960px-Deputy_Factory_Manager%27s_Quarters%2C_front_yard_%281949%29%2C_Hualien_Sugar_Factory%2C_Guangfu_Township%2C_Hualien_County_%28Taiwan%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Deputy_Factory_Manager%27s_Quarters,_front_yard_(1949),_Hualien_Sugar_Factory,_Guangfu_Township,_Hualien_County_(Taiwan).jpg","artist":"Mk2010","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/guangfu-tangchangfuchang-0.webp","small":"img/guangfu-tangchangfuchang-0-s.webp"}]},{"id":"fenglin-lintianshanzhong","name":"林田山中山堂及康樂新村殘構","short":"林田山中山堂","category":"歷史建築","level":"","town":"鳳林鎮","types":["產業"],"lat":23.716888,"lng":121.398138,"address":"花蓮縣鳳林鎮森榮里林森路231號","announced":"2002-09-23","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020923000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-04-10/5fd713b6-39dc-4b85-83f2-1bd23c200187/g鳳林-林田山中山堂09.jpg","year":1954,"yearText":"1954年（民國43年）","era":"postwar","themes":["林業聚落","公共建築"],"yearUnknown":false,"summary":"林場的禮堂兼電影院，曾有東部最新放映機","intro":"林田山林場位於鳳林鎮森榮里，日治時期稱「森坂」，日語發音「摩里沙卡」，是臺灣東部三大伐木林場之一。中山堂建於1954年，是林場的精神寄託，慶祝會、畢業典禮、遊藝會與戲劇表演都在這裡舉辦。1961年林場用職工福利金購進兩部日製電影放映機，堪稱當時東部最新，中山堂晚上常有免費電影。同年代興建的康樂新村員工宿舍，1999年由林田山文史工作室修補開放。2001年半山腰石階兩旁35棟檜木屋遭火災燒毀，林務局之後原地原貌重建，並整修中山堂，2003年重新啟用，館內展示林場老照片與當年的老放映機。","highlights":["切妻屋頂前方以斜撐木固定的水平雨庇","館內陳列的老式電影放映機","林場老照片與導覽影片展示"],"funFact":"1961年林場分得30萬元福利金，拿其中20萬元買了兩部日製放映機，讓中山堂晚上變成免費電影院。","photoSpot":"在中山堂正面連同斜撐雨庇一起入鏡","visitMin":30,"openNote":"位於鳳林鎮森榮里林田山林業文化園區內，官方資料記載09:00至17:00開放，除夕及每週一休館，假日有志工解說。出發前請查詢最新公告，建議開車前往。","dialogue":[{"who":"R","text":"Allan，這棟木造大房子門口還有遮雨板，是林場的辦公室嗎？"},{"who":"A","text":"不是喔，這是林田山的中山堂，1954年蓋的，林場所有大型活動都在這裡辦。"},{"who":"R","text":"大型活動？像是伐木工人的尾牙嗎？"},{"who":"A","text":"有慶祝會、畢業典禮、戲劇表演，最厲害的是，它還是林場的電影院。"},{"who":"R","text":"電影院？在山上看電影耶，好浪漫！"},{"who":"A","text":"1961年林場買了兩部日製放映機，當時東部最新，晚上常放免費電影。"},{"who":"R","text":"免費！那Allan一定每晚都去，而且自備雞排！"},{"who":"A","text":"被你看穿了。那兩部放映機的老前輩，現在還在館裡展示，只是退休不再放片了。"},{"who":"R","text":"我要去找那台老放映機，拍一張它跟我的合照，幫它重溫明星夢！"}],"clues":["1961年我買進兩部日製放映機，晚上變身免費電影院","我是1954年在伐木林場蓋的禮堂，曾辦畢業典禮與戲劇表演","我在鳳林鎮摩里沙卡林場，名字跟國父有關"],"quiz":[{"q":"中山堂在1961年添購了什麼，讓林場居民晚上有娛樂？","options":["日製電影放映機","卡拉OK設備","撞球檯","收音機"],"answer":0,"explain":"林場用福利金購進兩部日製電影放映機。"},{"q":"2001年林田山發生什麼事，使聚落需要重建？","options":["大水災","地震","火災燒毀35棟檜木屋","颱風吹倒中山堂"],"answer":2,"explain":"2001年半山腰35棟檜木屋群遭火災燒毀。"}],"images":[]},{"id":"xiulin-taidiangongsidong","name":"台電公司東部發電廠銅門機組支援修護人員備勤房屋銅門145-146號舊宿舍","short":"銅門電廠舊宿舍","category":"歷史建築","level":"","town":"秀林鄉","types":["宅第"],"lat":23.96651,"lng":121.48837,"address":"花蓮縣秀林鄉秀林鄉銅門村銅門145-146號","announced":"2017-12-05","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20180704000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-29/791ebcf0-87e2-4fe6-afad-39003b45b502/a秀林-台電銅門舊舍04.jpg","year":1956,"yearText":"1956年（民國45年）","era":"postwar","themes":["職務宿舍","產業遺產"],"yearUnknown":false,"summary":"戰後重建銅門電廠時的日式木造員工宿舍","intro":"位於秀林鄉銅門村，是台電東部發電廠銅門機組支援修護人員的備勤宿舍。銅門機組原為日治時期所建，1939年興工、1943年發電，但1944、1945年兩次暴洪淹沒廠房與設備。依房屋稅籍資料，這棟宿舍建於1956年，與1955年銅門發電所眷屬宿舍工程圖說比對，屬當時的「乙種宿舍」。建築延續日式木造宿舍的外觀與構法又有所調整，並設置多樣防颱板與相對應的門窗，反映1950年代東部國營事業員工的生活空間，也見證銅門電廠的重建歷程。","highlights":["多種形式的防颱板與配套門窗設計","延續日式外觀、卻有戰後調整的木造構法","1955年圖說中的乙種宿舍格局"],"funFact":"銅門機組在1944、1945年兩度遭暴洪淹沒，這棟宿舍正是戰後重建期間的產物。","photoSpot":"在允許範圍內拍外牆的防颱板與窗","visitMin":15,"openNote":"位於秀林鄉銅門村，為台電所屬宿舍，官方未載開放資訊，目前請以外觀參觀為主，勿擅入。山區道路與天候狀況請出發前查詢。","dialogue":[{"who":"R","text":"Allan，銅門這間木頭房子看起來很像日式宿舍，可是你說它是戰後蓋的？"},{"who":"A","text":"沒錯，稅籍資料寫它是1956年興建，是台電銅門電廠修護人員的備勤宿舍。"},{"who":"R","text":"電廠不是日本時代就有了嗎？為什麼要等到戰後才蓋宿舍？"},{"who":"A","text":"銅門機組1943年發電，可是1944和1945年連續兩次暴洪，把廠房和設備都淹了，戰後才重建。"},{"who":"R","text":"原來宿舍是重建電廠的一部分。那它跟日式宿舍哪裡不一樣？"},{"who":"A","text":"外觀延續日式風格，但為了花蓮的颱風，裝了好多種防颱板，門窗也配合設計。"},{"who":"R","text":"防颱板這麼多種，根本是房子的雨衣衣櫃嘛！"},{"who":"A","text":"形容得好！這裡是台電的宿舍，請在外面安靜看。找找看窗外的防颱板，數數有幾種樣式！"}],"clues":["我建於1956年，屬於1955年工程圖說裡的乙種宿舍","我所服務的發電機組曾在1944、1945年被暴洪淹沒","我是秀林鄉台電電廠修護人員的備勤木造宿舍"],"quiz":[{"q":"這棟宿舍為因應花蓮氣候，最有特色的設計是？","options":["高架地板防淹水","多樣的防颱板","雙層玻璃窗","屋頂太陽能板"],"answer":1,"explain":"為因應颱風設置多樣防颱板與配套門窗。"},{"q":"銅門機組在日治末期遭遇什麼災害？","options":["大地震","大火","兩次暴洪","戰爭轟炸"],"answer":2,"explain":"1944、1945年兩次暴洪淹沒廠房與設備。"}],"images":[]},{"id":"xiulin-tailugepailou","name":"太魯閣牌樓","short":"太魯閣牌樓","category":"歷史建築","level":"","town":"秀林鄉","types":["牌坊"],"lat":24.15548,"lng":121.621635,"address":"花蓮縣秀林鄉台8線東側入口處189k","announced":"2005-03-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20050329000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-29/fc0cd958-f034-4c56-9a1a-8c8d263b27be/a秀林-太魯閣牌樓01.jpg","year":1960,"yearText":"中橫1960年通車後設置（官方未載確切年份）","era":"postwar","themes":["紀念地景"],"yearUnknown":false,"summary":"中橫公路東口的北方宮殿式紀念牌樓","intro":"太魯閣牌樓位於秀林鄉台8線189K、中橫公路東側入口，匾額題「東西橫貫公路」六字，所以也稱東西橫貫公路牌樓，是紀念臺灣第一條東西橫貫公路開鑿的地標。牌樓為鋼筋混凝土仿木構造，採中國北方宮殿樣式的四柱三間形式，覆黃色琉璃瓦，旁有石獅，山壁設碑誌記載沿革。行車道寬4.7公尺、高4.3公尺，總寬8.3公尺，緊鄰山壁。這類宮殿式牌樓在臺灣相當少見，官方認為具稀少性、不易再現。","highlights":["匾額「東西橫貫公路」六個大字","四柱三間的北方宮殿式造型與黃色琉璃瓦","牌樓旁的石獅與山壁上的沿革碑誌"],"funFact":"牌樓行車道只有4.7公尺寬、4.3公尺高，後來臨河側另闢道路，原出入口改為單向通行。","photoSpot":"在牌樓前廣場安全處拍黃瓦與匾額","visitMin":20,"openNote":"位於秀林鄉台8線189K太魯閣口，戶外空間。受2024年強震影響，出發前請查詢太魯閣國家公園管理處與公路局最新開放與道路狀況。周邊車多，拍照請留意交通安全。","dialogue":[{"who":"A","text":"到太魯閣口了！阿拉蕾你看，這座黃瓦牌樓就是中橫公路的大門。"},{"who":"R","text":"好氣派！上面那六個大字是寫什麼？"},{"who":"A","text":"寫的是東西橫貫公路，所以它也叫東西橫貫公路牌樓，紀念這條公路開鑿的辛苦。"},{"who":"R","text":"它長得好像古裝劇裡皇宮的門，花蓮怎麼會有這種造型？"},{"who":"A","text":"這是仿中國北方宮殿樣式，四根柱子隔出三個開間，其實骨子裡是鋼筋混凝土仿木頭喔。"},{"who":"R","text":"原來是外表古典、內心現代的鋼鐵人！那車子都從中間穿過去嗎？"},{"who":"A","text":"以前是，現在臨河側另外開了路，原出入口改成單向。出發前記得先查太魯閣的開放和路況。"},{"who":"R","text":"知道了，出發前一定先查！那到了現場要找什麼？"},{"who":"A","text":"牌樓旁邊有石獅守門，請你找一找，比一比左右兩隻表情是不是一樣！"}],"clues":["我身上鋪著黃色琉璃瓦，是四柱三間的宮殿式造型","我的匾額寫著一條公路的名字，共六個字","我站在台8線189K，是中橫公路東邊的大門"],"quiz":[{"q":"太魯閣牌樓的匾額題了哪幾個字？","options":["太魯閣國家公園","中部橫貫公路","東西橫貫公路","立霧溪峽谷"],"answer":2,"explain":"匾題「東西橫貫公路」六字，也因此稱橫貫公路牌樓。"},{"q":"太魯閣牌樓的建築樣式屬於？","options":["日式神社鳥居","中國北方宮殿式","西洋凱旋門","閩南燕尾式"],"answer":1,"explain":"鋼筋混凝土仿木，屬北方宮殿樣式四柱三間牌樓。"}],"images":[{"file":"Taroko Archway,taken by Tomas Fano.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b6/Taroko_Archway%2Ctaken_by_Tomas_Fano.jpg/960px-Taroko_Archway%2Ctaken_by_Tomas_Fano.jpg","page":"https://commons.wikimedia.org/wiki/File:Taroko_Archway,taken_by_Tomas_Fano.jpg","artist":"Tomas Fano","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","local":"img/xiulin-tailugepailou-0.webp","small":"img/xiulin-tailugepailou-0-s.webp"}]},{"id":"xiulin-pumingsi","name":"秀林普明寺","short":"秀林普明寺","category":"歷史建築","level":"","town":"秀林鄉","types":["寺廟"],"lat":24.05441,"lng":121.59978,"address":"花蓮縣秀林鄉秀林鄉佳民村佳民121號","announced":"2012-10-12","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20121012000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-29/bdadeb8e-4d33-438d-90ed-e1cf6ce02e6f/a秀林-普明寺02.jpg","year":1960,"yearText":"1960年（民國49年）興建","era":"postwar","themes":["宗教信仰"],"yearUnknown":false,"summary":"證嚴法師早年修行處，也是慈濟的發源地","intro":"秀林普明寺位於秀林鄉佳民村。1922年，鹽水港製糖株式會社北埔農場主任嘉村忠吾發起建造延命地藏尊與木造地藏堂，戰後日人離臺，地藏堂逐漸破敗。1960年花蓮仕紳許聰敏發現這尊地藏，籌建約10坪的普明寺，即今大殿。隔年證嚴法師在後院搭木屋修行居住，1969年遷往慈濟精舍，因此普明寺被視為慈濟發源地。大殿為硬山式二坡水屋頂，鋼筋混凝土加強磚造；1982年起陸續增建誦經堂、齋堂、寮房等。","highlights":["1960年興建、硬山二坡水屋頂的小巧大殿","垂脊上的鳳凰與獅子裝飾、雕花滴水瓦","源自1922年北埔農場的地藏王菩薩像"],"funFact":"寺裡的地藏菩薩比寺還早：1922年北埔農場就已立地藏尊，1960年才在旁邊蓋了普明寺。","photoSpot":"在大殿前拍誦經堂的石板寺名","visitMin":20,"openNote":"位於秀林鄉佳民村，鄰近佳民國小與靜思精舍。官方未載開放時間，屬宗教場所，參訪請保持安靜、尊重寺方作息。可搭臺鐵到北埔站或新城站再轉車。","dialogue":[{"who":"A","text":"阿拉蕾，這間小小的普明寺，在臺灣佛教史上可是大有來頭。"},{"who":"R","text":"看起來好樸素喔，它有什麼特別的故事？"},{"who":"A","text":"1961年證嚴法師就在這裡後院的木屋修行，後來才搬到慈濟精舍，所以它被視為慈濟的發源地。"},{"who":"R","text":"原來是起點！那普明寺是誰蓋的？"},{"who":"A","text":"1960年花蓮仕紳許聰敏發現一尊乏人照顧的地藏菩薩，就籌建了約10坪的寺，就是現在的大殿。"},{"who":"R","text":"10坪？比我想像中的大雄寶殿小好多，根本是迷你版！"},{"who":"A","text":"迷你但是有料。那尊地藏還更早，是1922年糖廠北埔農場主任發起建造的。"},{"who":"R","text":"先有菩薩、再有寺，好像先有房客才蓋房子耶！"},{"who":"A","text":"說得妙！進寺記得放輕腳步，抬頭看看大殿垂脊上，找一找鳳凰和獅子的裝飾在哪裡。"}],"clues":["我的地藏菩薩比我還早，1922年就由一位糖業農場主任發起建造","我最初只有約10坪，1960年由花蓮仕紳籌建","一位法師在我的後院木屋修行，我因此被視為慈濟發源地"],"quiz":[{"q":"1960年籌建普明寺的花蓮仕紳是誰？","options":["嘉村忠吾","許聰敏","佐野梅太郎","劉漢英"],"answer":1,"explain":"許聰敏發現地藏尊後籌建普明寺。"},{"q":"普明寺最早的地藏尊是由哪個單位的人發起建造？","options":["糖業會社北埔農場","花蓮港廳役所","臺灣總督府鐵道部","林業事業所"],"answer":0,"explain":"1922年鹽水港製糖北埔農場主任嘉村忠吾發起。"}],"images":[]},{"id":"fuli-funanzhuanyaochang","name":"富南磚窯場","short":"富南磚窯場","category":"歷史建築","level":"","town":"富里鄉","types":["產業"],"lat":23.140325,"lng":121.23739,"address":"花蓮縣富里鄉富里鄉富南村11鄰20號","announced":"2007-02-12","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20070212000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-29/bbf460f6-4bb5-4512-8378-d46229f96c29/l富里-富南窯場48.jpg","year":1961,"yearText":"1961年（民國50年）","era":"postwar","themes":["產業遺產"],"yearUnknown":false,"summary":"東臺灣碩果僅存的八卦窯","intro":"富南磚窯場位於富里鄉富南村，八卦窯於1961年建造啟用，1969年易主後，1971年再建隧道窯以增加產量。八卦窯運轉到1972年停窯，隧道窯則燒到1991年；富南一帶磚窯極盛期約在1961至1991年間，紅磚供應南至鹿野、北至玉里，部分遠銷臺東與花蓮市。1991年因採土困難停燒，2000年碧利斯颱風毀損窯區後，窯主以自力營造整修，轉型為磚窯文化休閒園區。官方指出這裡是東臺灣碩果僅存的八卦窯，窯室環繞成橢圓形長廊，燒窯時可用紙擋隔成4個小窯室，煙道如樹枝般匯入煙囪。","highlights":["東臺灣碩果僅存的八卦窯","環繞成橢圓長廊的拱形窯室","1966年就裝設避雷針的煙囪"],"funFact":"八卦窯的窯室看起來是一整圈長廊，燒窯時卻能用紙擋隔成4個小窯室。","photoSpot":"從窯體外側仰拍高聳的煙囪","visitMin":40,"openNote":"位於富里鄉富南村，官方資料記載園區已轉型為磚窯文化休閒園區並經營民宿與休閒農場，開放與預約方式請洽業者；建議開車前往。","dialogue":[{"who":"R","text":"Allan，遠遠那根又高又直的煙囪，是花蓮跟臺東的界碑嗎？"},{"who":"A","text":"哈，差一點點！它是富里鄉富南磚窯場的煙囪，官方說它就屹立在花蓮與臺東的交界一帶。"},{"who":"R","text":"原來是磚窯！這裡燒了多少年的磚？"},{"who":"A","text":"八卦窯1961年啟用、1972年停窯，1971年又蓋了隧道窯，一路燒到1991年，前後幾十年都在冒煙。"},{"who":"R","text":"八卦窯是長成八卦圖案的形狀嗎？"},{"who":"A","text":"平面其實比較像橢圓形，裡面是一圈拱形長廊，燒窯時用紙擋隔成4個小窯室，像在跑操場。"},{"who":"R","text":"1991年停燒以後，聽說窯主自己動手把它整修成園區？"},{"who":"A","text":"沒錯，碧利斯颱風後自力營造修復。到現場請你找找煙道，想像熱氣怎麼像樹枝一樣匯進煙囪！"}],"clues":["我的窯室是一圈長廊，燒窯時能隔成4個小窯室","我1991年停燒，後來轉型成文化休閒園區","我是富里鄉富南村、東臺灣碩果僅存的八卦窯"],"quiz":[{"q":"富南磚窯的八卦窯在哪一年建造啟用？","options":["1951年","1961年","1971年","1991年"],"answer":1,"explain":"八卦窯於1961年建造啟用，1972年停窯。"},{"q":"八卦窯燒窯時可用紙擋隔成幾個小窯室？","options":["4個","2個","3個","8個"],"answer":0,"explain":"中空長隧道燒窯時可被紙擋分成4個小窯室。"}],"images":[]},{"id":"hualian-gaogongjianzhuqun","name":"國立花蓮高級工業職業學校歷史建築群","short":"花蓮高工建築群","category":"歷史建築","level":"","town":"花蓮市","types":["學校"],"lat":23.99861,"lng":121.6206,"address":"花蓮縣花蓮市花蓮市府前路27號","announced":"2016-12-20","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20161220000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-27/25f9c21e-75af-4c58-897d-ef9e1dceebfc/c花蓮-花工歷史建築04.jpg","year":1962,"yearText":"1960～1965年間（美援時期）","era":"postwar","themes":["教育運動","公共建築"],"yearUnknown":false,"summary":"美援示範工業學校留下的校舍與紀念碑","intro":"國立花蓮高級工業職業學校歷史建築群位於花蓮市府前路。學校前身是1940年設立的花蓮港廳立工業學校，初設機械、電機、化工三科。戰後美援從1951年持續到1965年，涵蓋職業教育計畫，花蓮高工於1955年加入美援教育計畫，被指定為示範工業學校。依歷史照片判斷，美援時期校舍約在1960至1965年間完工，包括電子連棟群、員工消費合作社與美援紀念碑；電化教室、美術教室與第二學生宿舍則由該校建築科教師自行設計。電子連棟群以加強磚造搭配斜向山牆屋頂與清水磚牆。","highlights":["美援紀念碑","電子連棟群的清水磚山牆與斜屋頂","建築科老師自己設計的電化教室與宿舍"],"funFact":"學校的電化教室、美術教室和第二學生宿舍，是由該校建築科老師親自設計的。","photoSpot":"經同意後拍美援紀念碑與連棟山牆","visitMin":20,"openNote":"位於花蓮市府前路，為使用中的校園，官方資料記載08:00至18:00可參觀，需先向校門口警衛室洽詢，請勿干擾教學。","dialogue":[{"who":"A","text":"阿拉蕾，今天來花蓮高工，這裡藏著一段美國援助臺灣的歷史。"},{"who":"R","text":"一所花蓮的高工和美國會有什麼關係？"},{"who":"A","text":"1950年代美國援助臺灣，也包括職業教育。花蓮高工1955年加入美援計畫，成為示範工業學校。"},{"who":"R","text":"示範學校！那就是全班的模範生嘛！"},{"who":"A","text":"差不多。1960到1965年間蓋了電子連棟群、員工消費合作社，還立了一座美援紀念碑。"},{"who":"R","text":"那些美援校舍，現在還在使用嗎？"},{"who":"A","text":"還在用！有的當實習工廠，有的當餐廳。電化教室和宿舍還是建築科老師親手設計的。"},{"who":"R","text":"老師自己設計教室，學生在裡面上課一定不敢遲到！"},{"who":"A","text":"進校園前記得先到警衛室登記，然後找到美援紀念碑，看看碑上寫了哪一年。"}],"clues":["我的校園裡立著一座紀念外國援助的石碑","我在1955年被指定為示範工業學校","我是花蓮府前路上的一所工業職業學校"],"quiz":[{"q":"花蓮高工在哪一年加入美援教育計畫？","options":["1940年","1951年","1955年","1965年"],"answer":2,"explain":"1955年加入美援教育計畫，被指定為示範工業學校。"},{"q":"花蓮高工的電化教室與第二學生宿舍是誰設計的？","options":["該校建築科教師","日本總督府技師","美國顧問團","公路局工程師"],"answer":0,"explain":"由該校建築科教師自行設計。"}],"images":[]},{"id":"jian-guanghuanongchang","name":"光華農場旁牌樓","short":"光華農場牌樓","category":"歷史建築","level":"","town":"吉安鄉","types":["牌坊"],"lat":23.931382,"lng":121.555331,"address":"花蓮縣吉安鄉光英段186道路上","announced":"2004-03-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20040319000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-24/89a83904-6b40-469a-9367-d9b5ae842361/d吉安-光華牌樓03.jpg","year":1964,"yearText":"約1964年（民國53年）榮民屯墾時期","era":"postwar","themes":["眷村與戰後移民","紀念地景"],"yearUnknown":false,"summary":"榮民在木瓜溪河床墾荒的歷史門面","intro":"光華農場旁牌樓位於吉安鄉光華村華城五街靠近光城街口。戰後為安置移居東部的外省族群，1952年成立花蓮大同合作農場，後歸併壽豐大同合作農場。光華分場則是1963年來臺的部隊響應退除役官兵農墾政策，到木瓜溪旁拓荒而成；這裡原是沒有土壤的河川砂石地，經過開發才變成可耕作的良田。牌樓見證1964年前後退輔會開發木瓜溪河床地、榮民大隊屯墾的歷史，為四柱三間形式，總寬約8公尺，柱上有書法家題寫的對聯。隨著榮民逐漸凋零、農場轉型，牌樓成為農場的歷史記憶，2004年登錄為歷史建築。","highlights":["四柱三間、總寬約8公尺的牌樓造型","書法家題寫的對聯文字","牌樓後方由河床砂石地開墾成的田地"],"funFact":"光華一帶原本是木瓜溪旁的砂石地，官方資料說「沒有土壤」，是榮民一點一滴墾成良田的。","photoSpot":"站在華城五街正面拍牌樓與對聯","visitMin":10,"openNote":"位於吉安鄉光華村華城五街近光城街口，屬戶外空間，官方資料記載可隨時在路邊觀看。牌樓下為通行道路，淨高約3.8公尺，拍照請注意來車。建議開車前往。","dialogue":[{"who":"A","text":"阿拉蕾，前面那座四根柱子的牌樓，就是光華農場的大門面。"},{"who":"R","text":"看起來好像廟口的牌坊，可是牌樓後面是一大片田耶。"},{"who":"A","text":"對，它紀念的是榮民屯墾。1963年來臺的部隊響應政府政策，到木瓜溪旁邊開荒。"},{"who":"R","text":"開荒？所以這裡以前是一大片荒地嗎？"},{"who":"A","text":"比荒地還辛苦，是河川砂石地，官方說根本沒有土壤，全靠一雙手慢慢墾成良田。"},{"who":"R","text":"從石頭堆裡種出稻子，這毅力真的好驚人。"},{"who":"A","text":"是啊。我在家種一盆蔥都會種死，跟他們比起來，我只能說，佩服佩服。"},{"who":"R","text":"那現在榮民伯伯們還在這裡種田嗎？"},{"who":"A","text":"榮民逐漸凋零，農場也在轉型，牌樓就成了大家共同的記憶。去讀讀看柱子上的對聯寫了什麼吧！"}],"clues":["我腳下的土地，原本是一片沒有土壤的河床砂石地","我有四根柱子，柱上掛著書法家寫的對聯","我是榮民在木瓜溪畔屯墾農場的門面"],"quiz":[{"q":"光華農場一帶原本是什麼樣的土地？","options":["肥沃的水田","茶園山坡地","海邊鹽田","河川砂石地"],"answer":3,"explain":"此區原是沒有土壤的河川砂石地，經開墾才成良田。"},{"q":"光華農場旁牌樓是什麼形式？","options":["兩柱一間","六柱五間","四柱三間","八柱七間"],"answer":2,"explain":"牌樓為四柱三間形式，總寬約8公尺。"}],"images":[]},{"id":"xiulin-zhongbudongxiheng","name":"中部東西橫貫公路慈雲橋","short":"中橫慈雲橋","category":"歷史建築","level":"","town":"秀林鄉","types":["橋樑"],"lat":24.212563,"lng":121.430013,"address":"花蓮縣秀林鄉台8線149K+550","announced":"2015-01-28","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20150128000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-30/86d8aa33-90c8-4c32-a40c-464288ed942c/a秀林-慈雲橋05.jpg","year":1965,"yearText":"1965～1966年間改建為鋼桁架橋","era":"postwar","themes":["鐵道交通","產業遺產"],"yearUnknown":false,"summary":"原本要給越南鐵路用的法國鋼樑，落腳中橫","intro":"慈雲橋位於秀林鄉台8線中橫公路149K附近。中橫闢建時物資缺乏，天祥以西多以臨時便橋或涵洞跨越溪流，通車後於1965至1966年間陸續改建為鋼桁架橋。鋼材來自美援物資：一批原為法國替越南1公尺軌距單線鐵路設計的華倫式鋼桁架，1954年奠邊府戰役後未能使用，輾轉運抵臺灣。因技術文件盡失，公路局工程人員逐一丈量構件、拼裝並繪製施工圖，是「先有橋、後有設計」的特殊案例。橋跨50公尺，以鉚釘接合，構架上仍保有原廠法文鐵牌。","highlights":["帶垂直桿件的華倫式三角桁架，一格一格很有節奏","鉚釘接合的舊式鋼構工法","橋上原廠鐵牌，有艾菲爾鐵塔圖徽的法文銘誌"],"funFact":"工程師當年把這批鋼樑叫「西德鋼樑」，一說是把鐵牌上的法文誤認成德文，以訛傳訛。","photoSpot":"在橋頭安全處斜拍整排三角桁架","visitMin":20,"openNote":"位於秀林鄉台8線中橫公路山區路段，屬戶外橋樑。受2024年強震影響，出發前請查詢太魯閣國家公園管理處與公路局最新開放與道路狀況。行車請勿在橋上停留拍照。","dialogue":[{"who":"A","text":"阿拉蕾，中橫山裡這座鋼橋，身世比我的履歷還曲折，它原本根本不是要來臺灣的。"},{"who":"R","text":"橋也會走錯路？難道它是坐船坐過頭了嗎？"},{"who":"A","text":"差不多啦！這批鋼桁架原本是法國替越南鐵路設計的，1954年奠邊府戰役後用不上，最後輾轉來到臺灣。"},{"who":"R","text":"哇，從越南的鐵路變成花蓮的公路橋，這是跨國轉職成功耶！"},{"who":"A","text":"更厲害的是技術文件全部不見，工程師只好一根一根量尺寸、拼回去，再自己畫施工圖。"},{"who":"R","text":"這不就是沒有說明書的超大型積木嗎？我連組個衣櫃都會多出螺絲！"},{"who":"A","text":"所以說它是先有橋、後有設計，很少見。當年大家還叫它西德鋼樑，其實鐵牌上寫的是法文。"},{"who":"R","text":"好可愛的誤會！那現在去看要注意什麼？"},{"who":"A","text":"中橫路況要先查清楚。到了現場，找找桁架上那塊有艾菲爾鐵塔圖案的鐵牌，拍下來當紀念！"}],"clues":["我身上有一塊印著巴黎知名鐵塔圖案的法文鐵牌","我原本是為1公尺軌距的越南鐵路設計，後來用在公路上","我是中橫公路149K附近的美援鋼桁架橋，名字帶著慈悲的雲"],"quiz":[{"q":"慈雲橋的鋼桁架原本是為哪裡的鐵路設計？","options":["越南","泰國","菲律賓","法屬北非"],"answer":0,"explain":"原為法國替越南1公尺軌距鐵路設計，戰後輾轉來臺。"},{"q":"工程師為何要逐一丈量鋼構件？","options":["想要改成更長的橋","為了申請專利","鋼料被颱風吹散","技術文件已經遺失"],"answer":3,"explain":"技術文件盡失，只能丈量拼裝再畫施工圖。"}],"images":[{"file":"2023 Ciyun Bridge N1.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/43/2023_Ciyun_Bridge_N1.jpg/960px-2023_Ciyun_Bridge_N1.jpg","page":"https://commons.wikimedia.org/wiki/File:2023_Ciyun_Bridge_N1.jpg","artist":"Taiwankengo","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/xiulin-zhongbudongxiheng-0.webp","small":"img/xiulin-zhongbudongxiheng-0-s.webp"}]},{"id":"shoufeng-lixinkuangyegufen","name":"理新礦業股份有限公司台灣閃玉礦業事務所","short":"豐田玉礦事務所","category":"歷史建築","level":"","town":"壽豐鄉","types":["產業"],"lat":23.862377,"lng":121.454034,"address":"花蓮縣壽豐鄉豐山村山邊路二段83巷17號","announced":"2018-10-09","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20181226000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-04-14/0f28fa9f-f744-45c9-b387-0039ad1314a1/DSC_0002.jpg","year":1970,"yearText":"年代不詳（台灣玉開採時期使用）","era":"unknown","themes":["產業遺產"],"yearUnknown":true,"summary":"台灣玉黃金年代留下的礦區木造事務所","intro":"理新礦業股份有限公司台灣閃玉礦業事務所位於壽豐鄉豐山村山邊路二段，是豐田玉礦區的木造平房。台灣玉在礦物學上屬於閃玉，集中在花蓮豐田地區，1960年代大量開發加工外銷，全盛時年產量一千四百多公噸，官方資料稱占全世界九成。1974年後受能源危機、生產過剩、惡性競爭與爆破採石造成玉料內裂等影響，產業一落千丈；1979年礦權由中國石油礦公司轉給理想礦業，1984年再由理新礦業接手，目前開採暫停。事務所外牆為雨淋板配砌磚台度，屋頂是兩坡鍍鋅鐵皮浪板，屋架為洋式真束桁架，室內有事務所、通鋪、廚房與浴廁。2018年登錄歷史建築。","highlights":["雨淋板外牆與砌磚台度","洋式真束桁架屋架與兩坡鐵皮浪板屋頂","事務所、通鋪、廚房並存的礦工生活空間"],"funFact":"台灣玉全盛時，年產量一千四百多公噸，官方資料說占了全世界的百分之九十。","photoSpot":"拍木造平房與後方山景的全景","visitMin":15,"openNote":"位於壽豐鄉豐山村山邊路二段，官方資料未載開放時間，礦區相關土地請勿擅入，目前以外觀參觀為主，出發前請查詢最新狀況。建議開車前往，可與豐田移民村一帶串遊。","dialogue":[{"who":"R","text":"Allan，這間木頭小平房看起來好普通，為什麼也算文化資產？"},{"who":"A","text":"別小看它！這是台灣玉礦區的事務所，見證豐田玉曾經紅遍全世界的年代。"},{"who":"R","text":"台灣玉？就是阿嬤手上戴的玉鐲子那種玉嗎？"},{"who":"A","text":"對，礦物學上叫閃玉。1960年代大量外銷，全盛時年產一千四百多公噸，官方說占全世界九成。"},{"who":"R","text":"九成！那豐田當時一定很多人在挖玉吧。"},{"who":"A","text":"沒錯，可惜後來能源危機、產量過剩，加上爆破採石讓玉料內部裂開，生意就一落千丈。"},{"who":"R","text":"那這間事務所，以前都在裡面做些什麼呢？"},{"who":"A","text":"辦公、讓礦工睡通鋪、煮飯洗澡都在這裡。我最在意的當然是廚房，挖玉也要吃飽才有力氣。"},{"who":"R","text":"大家去看看它的外牆，找找下面那一圈砌磚台度和上面雨淋板的交界線！"}],"clues":["我屋裡有通鋪和廚房，曾讓工作的人在這裡吃睡","我見證一種寶石曾占全世界九成產量的年代","我是豐田山邊一間採玉公司的木造事務所"],"quiz":[{"q":"台灣玉在礦物學上屬於哪一類？","options":["翡翠","閃玉","瑪瑙","水晶"],"answer":1,"explain":"台灣玉在礦物學與寶石學上歸類為閃玉。"},{"q":"下列哪一項是台灣玉產業衰退的原因之一？","options":["爆破採石造成玉料內裂","颱風摧毀礦區","政府禁止外銷","礦脈完全挖光"],"answer":0,"explain":"爆炸法採出的原石內裂嚴重，品質不良使信譽受損。"}],"images":[]},{"id":"yuli-chezhantiedaosushe","name":"玉里車站鐵道宿舍群","short":"玉里車站宿舍群","category":"聚落建築群","level":"聚落建築群","town":"玉里鎮","types":["近代宿舍"],"lat":23.329924,"lng":121.311903,"address":"花蓮縣玉里鎮康樂街39號","announced":"2019-06-10","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/groupsOfBuildings/20200316000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-04-15/81f4399c-6458-41a3-a69d-4c5c2306db2c/DSC01944.jpg","year":1930,"yearText":"1930年（昭和5年）","era":"japan","themes":["鐵道交通","職務宿舍"],"yearUnknown":false,"summary":"臺東線第一期南端站留下的鐵道宿舍聚落","intro":"玉里車站鐵道宿舍群位於玉里鎮康樂街一帶，2019年登錄為聚落建築群。1917年完工的玉里車站，是日治時期臺東線第一期花蓮港至璞石閣（玉里）的南端站，除客貨運輸外也負責調度火車方向，因此站區發展出規模完整、型態多樣的生活聚落。宿舍群由獨棟官舍、共濟官舍、本島人官舍及附屬設施構成，現存1930年的共濟官舍與本島人官舍，以及1960年改建的磚造宿舍，可看出不同時期的鐵道宿舍工法。車站在日治末期曾遭美軍轟炸，這批宿舍成為少數留存的見證，也帶動驛前商業聚落。","highlights":["1930年的共濟官舍與本島人官舍","1960年改建的磚造鐵道宿舍","以宿舍群為核心發展的站前商圈"],"funFact":"玉里站曾是臺東線第一期的南端站，除了載客運貨，還要負責調度火車方向。","photoSpot":"把木造官舍和磚造宿舍拍成對照組","visitMin":20,"openNote":"位於玉里鎮康樂街，鄰近臺鐵玉里站，官方資料未載開放時間，以外觀參觀為主；出站後可步行前往，順遊市區景點。","dialogue":[{"who":"R","text":"Allan，一出玉里車站就看到一片老宿舍，以前住的都是誰啊？"},{"who":"A","text":"都是鐵道員工！玉里站1917年完工，是臺東線第一期的南端站，人多事多，宿舍自然一大片。"},{"who":"R","text":"當南端站，要做什麼特別的工作嗎？"},{"who":"A","text":"除了載客運貨，還要負責調度火車方向，比我在路口迷路掉頭還專業。"},{"who":"R","text":"你那叫迷路，人家那叫調度好嗎！那這裡有哪些宿舍？"},{"who":"A","text":"有獨棟官舍、共濟官舍、本島人官舍，現存1930年的官舍，還有1960年改建的磚造宿舍。"},{"who":"R","text":"本島人官舍是什麼意思？有點聽不懂。"},{"who":"A","text":"就是當時給臺灣籍員工住的官舍。車站在日治末期還曾遭美軍轟炸，這批宿舍能留下來很不容易。"},{"who":"R","text":"那我要去比較木造官舍和磚造宿舍的外牆，拍兩張照片排在一起看差異！"}],"clues":["我有共濟官舍、本島人官舍，也有1960年改建的磚造宿舍","我的車站曾是臺東線第一期的南端站","我是2019年登錄、在玉里站旁的鐵道宿舍聚落"],"quiz":[{"q":"玉里車站是臺東線第一期的什麼站？","options":["北端起點站","南端站","轉乘樞紐站","貨運專用站"],"answer":1,"explain":"第一期花蓮港至璞石閣，玉里為南端站。"},{"q":"宿舍群中的磚造宿舍是哪一年改建的？","options":["1917年","1930年","1945年","1960年"],"answer":3,"explain":"現存1960年改建的磚造宿舍。"}],"images":[]},{"id":"fenglin-lintianshanlinyeju","name":"林田山(MORISAKA)林業聚落","short":"林田山林業聚落","category":"聚落建築群","level":"聚落建築群","town":"鳳林鎮","types":["其他"],"lat":23.716918,"lng":121.397809,"address":"花蓮縣鳳林鎮林森路2~9鄰、林森路99巷及林安路等","announced":"2006-12-28","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/groupsOfBuildings/20061228000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-01-25/bf265b68-9bdc-4d3b-bb84-79ee516b8c34/3602331250689.jpg","year":1939,"yearText":"1939年（昭和14年）設事業所","era":"japan","themes":["林業聚落","產業遺產","日式建築"],"yearUnknown":false,"summary":"群山環抱的檜木聚落，見證東部林業興衰","intro":"林田山林業聚落位於鳳林鎮森榮里，範圍跨到萬榮鄉，舊稱「森坂」（MORISAKA），意為長滿森林的山坡。大正年間花蓮港木材株式會社入山採伐紅檜與扁柏，1934年因木材價格低落結束經營；1938年臺灣興業株式會社取得採伐權，隔年設置事業所，聚落逐漸成形，全盛時期聚集約四五百戶，有「小上海」之稱。1972年林場發生森林大火，林業逐漸沒落；之後政府禁伐天然林，林場關閉。現存原子炭工廠、捲揚機、修理工廠、鐵道與台車，以及日治到戰後各等級木造宿舍，戰後宿舍室內釘木壁板，形成獨特裝修風格，今由林業單位規劃為林業文化園區。","highlights":["沿山坡層層排列的檜木宿舍群","原子炭工廠、捲揚機與運材台車","老消防車、機關車與木造車廂"],"funFact":"林田山的木造宿舍室內常釘上木壁板，戰後初期興建的宿舍更是一開始就釘，成了這裡獨有的室內風格。","photoSpot":"在石階高處俯拍層疊的檜木屋頂","visitMin":90,"openNote":"位於鳳林鎮森榮里，官方資料記載09:00至17:00開放，除夕及每週一休館。山區聚落，出發前請查詢最新開放與道路狀況，建議開車前往。","dialogue":[{"who":"A","text":"歡迎來到摩里沙卡，就是日文森坂的發音，意思是長滿森林的山坡。"},{"who":"R","text":"摩里沙卡，念起來好像魔法咒語！這裡以前是做什麼的？"},{"who":"A","text":"這是林田山林業聚落，日治時期開始伐木，1939年設置事業所，人越聚越多。"},{"who":"R","text":"有多熱鬧？比花蓮市區還熱鬧嗎？"},{"who":"A","text":"全盛時期約四五百戶，有小上海的外號。米店、學校、教堂、禮堂一應俱全。"},{"who":"R","text":"這麼熱鬧的小上海，後來怎麼安靜下來了？"},{"who":"A","text":"1972年一場森林大火重創林場，後來政府禁伐天然林，林場也就關閉了。"},{"who":"R","text":"好可惜，但留下的檜木屋群沿著山坡排開，還是好有味道。"},{"who":"A","text":"沒錯，進去先深呼吸聞聞檜木香，再去找找那台運木材的台車拍張照！"}],"clues":["我的舊名在日語裡唸作摩里沙卡","全盛時期有四五百戶，被稱為小上海","我是鳳林鎮群山環抱的檜木伐木聚落"],"quiz":[{"q":"林田山舊名「森坂」，日語發音是？","options":["哆啦哆啦","阿里阿多","摩里沙卡","沙喲哪啦"],"answer":2,"explain":"森坂日語發音摩里沙卡，意指長滿森林的山坡。"},{"q":"林田山全盛時期有什麼外號？","options":["小上海","小東京","小香港","小臺北"],"answer":0,"explain":"林田山林場早期有小上海之稱。"}],"images":[]},{"id":"hualian-sibagaodikaoguyi","name":"四八高地考古遺址","short":"四八高地遺址","category":"考古遺址","level":"縣(市)定考古遺址","town":"花蓮市","types":[],"lat":24.021533,"lng":121.629877,"address":"花蓮縣花蓮市海岸路附近","announced":"2022-08-17","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/archaeologicalSite/20230214000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-02-14/7520fa32-3ae2-43e8-852f-b83014c172fc/四八高地遺址.jpg","year":-2500,"yearText":"新石器時代中期（東部繩紋紅陶文化）","era":"prehistoric","themes":["考古遺址"],"yearUnknown":false,"summary":"出土大量網墜的史前海洋生活遺址","intro":"四八高地考古遺址位於花蓮市海岸路附近，面積約17公頃，2022年公告為縣定考古遺址。2011年民眾通報「花蓮國際雕塑文化園區」施工預定地可能是遺址，2012年1月現場會勘後確認並定名，同年由陳有貝進行地表調查、鑽探與考古發掘。遺址屬新石器時代中期的東部繩紋紅陶文化，出土大量陶器，包括特殊的陶豆，以及數量多、樣式多樣的石網墜，顯示史前人群對海洋的適應。出土的玉質錛鑿與矛鏃形器，也見證奇萊平原與花東縱谷之間的交通與交流。遺址現況主要是椰子林，保存相當完整。","highlights":["數量龐大、樣式多樣的石網墜","特殊造型的陶豆等繩紋紅陶器","見證奇萊平原與縱谷交流的玉質錛鑿"],"funFact":"這處遺址是2011年民眾通報雕塑園區施工預定地有遺物，才被考古學者確認的。","photoSpot":"遠拍海岸路旁的椰子林與海天一線","visitMin":15,"openNote":"位於花蓮市海岸路附近，官方資料未載開放資訊，現場多為椰子林，沒有展示設施。考古遺址受法律保護，請勿挖掘或撿拾遺物，出發前請查詢最新狀況。","dialogue":[{"who":"R","text":"Allan，這裡只有一片椰子林，哪裡有古蹟啊？"},{"who":"A","text":"古蹟藏在地底下。這裡是四八高地遺址，屬於新石器時代中期的東部繩紋紅陶文化。"},{"who":"R","text":"新石器時代！那時候的人在這裡做什麼？"},{"who":"A","text":"他們很會靠海吃海，考古挖到大量石網墜，就是綁在漁網上讓網子沉下去的石頭。"},{"who":"R","text":"所以他們是史前漁夫！那我們今天的晚餐也吃海鮮好不好？"},{"who":"A","text":"你跟我想得一樣。這裡還挖到玉質錛鑿，代表奇萊平原和花東縱谷的人早就有往來。"},{"who":"R","text":"那這麼重要的遺址，當初是怎麼被發現的？"},{"who":"A","text":"2011年有民眾通報施工預定地有遺物，2012年確認定名。記得，遺址受法律保護，不能挖也不能撿。"},{"who":"R","text":"了解！那大家在路邊遠遠拍一張椰子林，想像幾千年前漁夫撒網的樣子就好！"}],"clues":["我曾經差點變成雕塑園區的工地","我的地底下藏著很多讓漁網下沉的石頭","我在花蓮市海岸邊，名字裡有兩個數字"],"quiz":[{"q":"四八高地遺址大量出土哪一種器物，顯示海洋適應？","options":["青銅箭頭","鐵製魚鉤","陶製紡輪","石網墜"],"answer":3,"explain":"遺址出土大量石網墜，顯示史前人群的海洋適應。"},{"q":"四八高地遺址屬於哪一個史前文化？","options":["大坌坑文化","十三行文化","東部繩紋紅陶文化","靜浦文化"],"answer":2,"explain":"遺址屬新石器時代中期的東部繩紋紅陶文化。"}],"images":[]},{"id":"wanrong-zhiyagankaoguyizhi","name":"支亞干(萬榮．平林)考古遺址","short":"支亞干遺址","category":"考古遺址","level":"縣(市)定考古遺址","town":"萬榮鄉","types":[],"lat":23.801997,"lng":121.436417,"address":"花蓮縣萬榮鄉萬榮鄉西林村西林段1715、1716、1717、1718、1719、1720、1721、1722、1723、1724、1725、1726、1727、1728、1729地號。","announced":"2010-06-08","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/archaeologicalSite/20100608000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/archeology/38159/photo/cecfc340-35c4-4b83-ba31-54bad23286be.JPG","year":-2500,"yearText":"距今約4500至1500年","era":"prehistoric","themes":["考古遺址","原住民族文化"],"yearUnknown":false,"summary":"臺灣最大型的史前玉器製造遺址","intro":"支亞干（萬榮．平林）考古遺址位於萬榮鄉西林村西南方，坐落在林田山山麓向花東縱谷傾斜的兩層河階上，西南臨清水溪、東北側是壽豐溪（知亞干溪）。1929年由鹿野忠雄調查發現，戰後歷經多位學者調查與試掘，1998年起的試掘出土玉器製造遺跡，2004年也發現玻璃珠與鐵器。學者指出這裡是目前已知臺灣最重要的玉器產地與最大型玉器製造遺址，製玉活動延續約3000年，產品透過交換體系擴及臺灣本島、周邊島嶼，甚至遠達菲律賓、越南與泰國等環南海地區，具有重要的海域交流意義。2010年公告為縣定考古遺址。","highlights":["全臺罕見的大型史前玉器製造場","管狀旋截器留下的圓形玉核","玉器交換網遠達環南海地區"],"funFact":"這裡出土的「管狀旋截器」又叫圓形玉核，是古人用管鑽在玉料上旋切後留下的圓柱芯。","photoSpot":"在西林村河階遠眺林田山與縱谷","visitMin":20,"openNote":"位於萬榮鄉西林村，遺址多為農地，現場無展示設施，請勿擅入田地或撿拾、挖掘遺物。近臺鐵萬榮站，建議開車前往。","dialogue":[{"who":"R","text":"Allan，這裡放眼望去只有田和山，到底哪裡有遺址啊？"},{"who":"A","text":"寶藏都在地底下。支亞干遺址又叫平林遺址，是臺灣最大型的史前玉器製造場。"},{"who":"R","text":"史前就有玉器工廠？那時候沒有機器，人要怎麼做玉？"},{"who":"A","text":"他們用管子旋轉切玉，切下來的圓柱芯叫圓形玉核，像蘋果去核那樣。"},{"who":"R","text":"原來史前人類就會用去核器了！那他們做多久？"},{"who":"A","text":"大約從距今4500年到1500年，前後約3000年，比任何老店都資深。"},{"who":"R","text":"做那麼多玉，在史前時代真的賣得出去嗎？"},{"who":"A","text":"學者認為這裡的玉器交換網，一路遠到菲律賓、越南和泰國。"},{"who":"R","text":"原來是史前跨國貿易！我要站在河階上，拍下古人每天抬頭看到的林田山！"}],"clues":["1929年鹿野忠雄調查發現我","我的玉器交換網遠達菲律賓、越南與泰國","我在萬榮鄉西林村，是臺灣最大型的史前玉器製造場"],"quiz":[{"q":"支亞干遺址最重要的特色是什麼？","options":["日治神社基壇","大型石棺墓群","清代軍營遺跡","大型玉器製造場"],"answer":3,"explain":"學者指出它是臺灣最大型的玉器製造遺址。"},{"q":"學者認為這裡的製玉活動延續大約多久？","options":["約300年","約3000年","約1000年","約8000年"],"answer":1,"explain":"距今4500至1500年之間，長達約3000年。"}],"images":[]},{"id":"ruisui-wuhekaoguyizhi","name":"Satokoay（舞鶴）考古遺址","short":"舞鶴遺址","category":"考古遺址","level":"縣(市)定考古遺址","town":"瑞穗鄉","types":[],"lat":23.470835,"lng":121.359434,"address":"花蓮縣瑞穗鄉新舞鶴段330、331、332地號","announced":"2006-11-02","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/archaeologicalSite/20190306000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/archeology/38158/photo/523bc13a-f4b3-4aa0-a7c0-b2732ea73334.JPG","year":-1000,"yearText":"距今約3000年前起（新石器時代晚期）","era":"prehistoric","themes":["考古遺址","原住民族文化"],"yearUnknown":false,"summary":"立著全臺最大史前石柱的縱谷遺址","intro":"Satokoay（舞鶴）考古遺址位於瑞穗鄉舞鶴台地、台9線旁，中央立有一大一小兩根石柱，官方說明為全臺目前所見最大的史前石柱。依中央研究院郭素秋的研究，遺址包含距今約3,000至2,400年前的麒麟文化、約2,100至1,600年前的花岡山上層文化，以及500年前以降的靜浦晚期文化（阿美文化）；過去曾歸為卑南文化，後改歸麒麟文化。1988年公告為三級古蹟，2006年改為縣定遺址，2016年依阿美語「石柱所在之地」重新公告名稱。周遭部落的阿美族、撒奇萊雅族都視大石柱為重要象徵。","highlights":["全臺目前所見最大的史前石柱","一大一小兩根石柱與周邊木棧道","疊了三個時期的史前文化層"],"funFact":"Satokoay是阿美語「石柱所在之地」，2016年縣府為尊重部落命名，重新公告遺址名稱。","photoSpot":"從木棧道拍大小石柱與縱谷山景","visitMin":20,"openNote":"位於瑞穗鄉舞鶴台9線旁，花東縱谷國家風景區管理處設有停車場、涼亭與木棧道；石柱周圍多為果園，請勿進入農地。官方資料未載開放時間，出發前請查詢最新開放與道路狀況。","dialogue":[{"who":"A","text":"阿拉蕾，舞鶴台地上這兩根石柱，一大一小站在這裡，已經等了好幾千年。"},{"who":"R","text":"好高喔！它們是誰、在什麼時候立起來的？"},{"who":"A","text":"這裡是舞鶴遺址，最早的文化層屬於距今約3000年前的麒麟文化，大石柱是全臺目前所見最大的史前石柱。"},{"who":"R","text":"全臺最大！那它的族語名字是什麼意思？"},{"who":"A","text":"阿美語的名稱意思是石柱所在之地，2016年縣政府為了尊重部落的命名，重新公告了名稱。"},{"who":"R","text":"除了麒麟文化，還有別的文化住過這裡嗎？"},{"who":"A","text":"還有距今約2100到1600年前的花岡山上層文化，以及500年前以後的靜浦晚期文化，也就是阿美文化。"},{"who":"R","text":"一個地方疊了三層文化，比千層蛋糕還厲害。"},{"who":"A","text":"周圍的阿美族、撒奇萊雅族都把石柱視為重要象徵，請放輕腳步，從木棧道比比看大小石柱差多高。"}],"clues":["我身上疊著麒麟文化、花岡山上層文化與阿美文化","我的族語名稱意思是石柱所在之地","我在瑞穗台9線旁，立著全臺最大的史前石柱"],"quiz":[{"q":"舞鶴遺址最早的文化層屬於哪一個文化？","options":["卑南文化","麒麟文化","十三行文化","大坌坑文化"],"answer":1,"explain":"最早為距今約3000至2400年前的麒麟文化。"},{"q":"縣政府在哪一年依族語重新公告遺址名稱？","options":["1988年","2006年","2016年","2022年"],"answer":2,"explain":"2016年重新公告為Satokoay（舞鶴）遺址。"}],"images":[]},{"id":"fuli-gongpukaoguyizhi","name":"公埔考古遺址","short":"公埔遺址","category":"考古遺址","level":"縣(市)定考古遺址","town":"富里鄉","types":[],"lat":23.186548,"lng":121.262145,"address":"花蓮縣富里鄉富里鄉石牌村","announced":"2006-11-02","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/archaeologicalSite/20061102000003","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/archeology/38161/photo/99138b7d-16f8-4bcf-a2c2-2bee5b76fc2f.jpg","year":-1000,"yearText":"距今約3000至2500年前（新石器時代晚期）","era":"prehistoric","themes":["考古遺址"],"yearUnknown":false,"summary":"兩面史前大石壁相對而立的文化交界遺址","intro":"公埔考古遺址位於富里鄉石牌村的丘頂平台，1929年由日籍學者鹿野忠雄發現，當時記錄立石4個、石壁2座。依中央研究院郭素秋2012至2013年的研究，遺址年代約距今3,000至2,500年前，屬新石器時代晚期，同時呈現臺東平原與縱谷南段常見的卑南文化，以及花東海岸常見的麒麟文化特色，位處文化交界。兩面相對而立的大石壁高約180至245公分，是花東縱谷少見的史前大石壁遺址；出土石鋤、石錛、石鐮、穿孔板岩器，以及多量閃玉製作的玉錛、玉鑿、玉環。目前設有遺址公園、解說牌、涼亭與導覽步道。","highlights":["兩面相對而立的史前板岩大石壁","卑南與麒麟兩種文化交會的特色","閃玉製作的玉錛、玉鑿與玉環"],"funFact":"鹿野忠雄1929年5月13日首次調查公埔遺址，之後的紀錄幾乎都圍繞著那兩面板岩石壁。","photoSpot":"站在兩面石壁之間拍出夾道感","visitMin":20,"openNote":"位於富里鄉石牌村，官方資料記載設有遺址公園、解說牌、涼亭與導覽步道，開放時間未載；周邊有私人墳墓與福德祠，請保持尊重。建議開車前往。","dialogue":[{"who":"A","text":"阿拉蕾，富里石牌村的小山丘上，有兩面大石壁面對面站著，已經站了快3000年。"},{"who":"R","text":"面對面站那麼久，是在比賽誰先眨眼嗎？"},{"who":"A","text":"哈，它們超有耐心。這是公埔遺址，石壁高約180到245公分，是花東縱谷少見的史前大石壁。"},{"who":"R","text":"比Allan你還高耶！是誰發現的？"},{"who":"A","text":"1929年日籍學者鹿野忠雄來調查，記錄了立石4個、石壁2座。"},{"who":"R","text":"那住在這裡的古人屬於哪個文化？"},{"who":"A","text":"有趣的是兩種特色都有，同時呈現卑南文化和麒麟文化，年代大約距今3000到2500年前。"},{"who":"R","text":"文化交界處，就像兩條河在這裡匯流一樣。"},{"who":"A","text":"還出土不少閃玉做的玉錛、玉鑿和玉環。到遺址公園請你走到兩面石壁中間，感受一下被巨石夾道的感覺！"}],"clues":["我同時有卑南文化和麒麟文化的特色","1929年鹿野忠雄在我這裡記錄了立石與石壁","我是富里石牌村有兩面史前大石壁的遺址"],"quiz":[{"q":"公埔遺址在哪一年被鹿野忠雄發現？","options":["1909年","1945年","1992年","1929年"],"answer":3,"explain":"鹿野忠雄於1929年5月首次調查本遺址。"},{"q":"公埔遺址同時呈現哪兩種史前文化？","options":["大坌坑與圓山","十三行與靜浦","卑南與麒麟","花岡山與植物園"],"answer":2,"explain":"同時具卑南文化與麒麟文化特色。"}],"images":[]},{"id":"xiulin-fushikaoguyizhi","name":"富世考古遺址","short":"富世考古遺址","category":"考古遺址","level":"縣(市)定考古遺址","town":"秀林鄉","types":[],"lat":24.151938,"lng":121.621409,"address":"花蓮縣秀林鄉太魯閣段63、123、125、127、137、138、139、140、143、144、145、152、153、157、195地號","announced":"2006-11-02","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/archaeologicalSite/20121011000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/archeology/38152/photo/65d7a581-8073-409f-bd54-76c11f2187c3.JPG","year":-200,"yearText":"距今約2000多年","era":"prehistoric","themes":["考古遺址","自然地景"],"yearUnknown":false,"summary":"立霧溪口河階上的史前石板棺與單石","intro":"富世考古遺址位於秀林鄉立霧溪下游右岸、海拔約90公尺的彎月形河階上，長約300公尺，南倚新城山，東望太平洋，就在太魯閣牌樓南側、富世長老教會上方。考古學家陳仲玉1985年調查發掘，確認有兩個文化層：上層為方格印紋陶文化；下層出土寬短形石板棺與立於地表的單石，呈現東海岸巨石文化（麒麟文化）與卑南文化結合的特色，年代距今約2000多年。顯示在山高水急的太魯閣地區，史前人群早已在溪口生活並入山狩獵。1988年曾公告為三級古蹟，2006年公告為縣定考古遺址。","highlights":["彎月形河階地形與立霧溪出海口景觀","麒麟文化與卑南文化交會的石板棺與單石","階地上因開墾堆砌的石壘牆"],"funFact":"這裡有兩層文化疊在一起，下層受東海岸巨石文化與卑南文化雙重影響，十分少見。","photoSpot":"從河階邊緣眺望立霧溪口與太平洋","visitMin":20,"openNote":"位於秀林鄉富世村太魯閣口附近的河階地，部分為農地，官方未載開放資訊，請勿進入私人田地或撿拾地表遺物。受2024年強震影響，出發前請查詢太魯閣國家公園管理處與公路局最新開放與道路狀況。","dialogue":[{"who":"A","text":"阿拉蕾，太魯閣牌樓南邊這片高高的河階，2000多年前就有人住了。"},{"who":"R","text":"真的嗎？這裡看起來只有菜園和樹耶！"},{"who":"A","text":"考古學家陳仲玉1985年在這裡發掘，找到石板棺、立在地上的單石，還有方格印紋陶片。"},{"who":"R","text":"石板棺？那是用石板拼成的棺材嗎？"},{"who":"A","text":"對，下層的石板棺受到東海岸巨石文化和卑南文化的雙重影響，像兩種文化在這裡交會。"},{"who":"R","text":"兩種文化混搭，史前人也很懂創意嘛！"},{"who":"A","text":"而且他們會沿著立霧溪往山裡打獵，證明太魯閣地形再險峻，也擋不住人的生活。"},{"who":"R","text":"那我們去現場，可以自己挖挖看找寶藏嗎？"},{"who":"A","text":"千萬不行！遺址受法律保護。請你站在河階邊，找出立霧溪出海口，拍一張2000年來沒變的風景。"}],"clues":["我在一片彎月形的河階上，長約300公尺","我有兩個文化層，下層有石板棺和立在地表的單石","我在立霧溪口，就在中橫東口牌樓南側"],"quiz":[{"q":"富世考古遺址下層文化具有哪兩種文化結合的特質？","options":["巨石文化與卑南文化","大坌坑與圓山文化","十三行與植物園文化","牛罵頭與營埔文化"],"answer":0,"explain":"下層兼具東海岸巨石文化（麒麟）與卑南文化石板棺特質。"},{"q":"富世考古遺址位在哪一條溪的出海口附近？","options":["木瓜溪","花蓮溪","立霧溪","秀姑巒溪"],"answer":2,"explain":"位於立霧溪下游右岸的河階上。"}],"images":[]},{"id":"zhuoxi-huangmakaoguyizhi","name":"Koma（黃麻）考古遺址","short":"黃麻遺址","category":"考古遺址","level":"縣(市)定考古遺址","town":"卓溪鄉","types":[],"lat":23.349718,"lng":121.204625,"address":"花蓮縣卓溪鄉玉山國家公園境內","announced":"2022-08-18","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/archaeologicalSite/20230214000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-02-14/53c6f891-822e-4138-b131-d1a0f47b04fc/Koma（黃麻）考古遺址.jpg","year":500,"yearText":"史前鐵器時代至近代","era":"prehistoric","themes":["考古遺址","原住民族文化"],"yearUnknown":false,"summary":"中央山脈孔道上的史前聚落與布農舊社","intro":"Koma（黃麻）考古遺址位於卓溪鄉玉山國家公園境內的拉庫拉庫溪流域，2022年公告為縣定考古遺址。這裡是中央山脈東西交通的孔道，經正式考古發掘，出土帶刺點紋與圈印紋的磨光黑陶等東部鐵器時代特色遺物，是探討山區靜浦文化的重要依據，也是花蓮少見的鐵器時代山區大型聚落遺址。遺址同時保存完整的布農族舊社遺構，包括家屋、工寮與圈舍，與當代社區連結深厚，見證史前人群由縱谷往山區移動，以及近代山區聚落與交通發展。","highlights":["帶刺點紋與圈印紋的磨光黑陶","布農族舊社的家屋、工寮與圈舍遺構","中央山脈東西交通孔道上的聚落"],"funFact":"1954年馬淵東一已記載拉庫拉庫溪出土的陶片，1988年才首次有學者在此調查試掘。","photoSpot":"只在步道上拍山谷遠景，勿踩踏遺構","visitMin":60,"openNote":"位於卓溪鄉玉山國家公園境內山區，進入須依玉山國家公園規定申請，東段山區路況請查詢玉山國家公園管理處最新公告。請勿撿拾或挖掘任何遺物。","dialogue":[{"who":"A","text":"阿拉蕾，這次我們要往卓溪鄉的深山走，去拉庫拉庫溪旁的黃麻遺址。"},{"who":"R","text":"深山裡也有遺址？古人不怕爬山嗎？"},{"who":"A","text":"這裡剛好是中央山脈東西往來的孔道，就像古代的山中交流道，人群自然會經過、住下來。"},{"who":"R","text":"山中交流道？那有沒有休息站賣茶葉蛋？"},{"who":"A","text":"茶葉蛋沒有，倒是挖到了帶刺點紋和圈印紋的磨光黑陶，是東部鐵器時代的特色遺物。"},{"who":"R","text":"磨光黑陶，聽起來好酷！除了史前的東西還有什麼？"},{"who":"A","text":"還有保存完整的布農族舊社，家屋、工寮、圈舍都在，和現在的族人仍有深厚的情感連結。"},{"who":"R","text":"原來一個地方記得好幾個時代。那我們可以去看嗎？"},{"who":"A","text":"它在玉山國家公園裡，要依規定申請並查最新路況。到現場只用眼睛看、用相機記錄，什麼都不要帶走喔！"}],"clues":["我出土帶刺點紋和圈印紋的磨光黑陶","我同時保存了布農族舊社的家屋與圈舍","我在卓溪鄉拉庫拉庫溪流域，2022年公告為縣定遺址"],"quiz":[{"q":"黃麻遺址出土的東部鐵器時代特色遺物是什麼？","options":["彩繪紅陶","磨光黑陶","青花瓷片","玉製人獸形耳飾"],"answer":1,"explain":"出土帶刺點紋和圈印紋的磨光黑陶。"},{"q":"黃麻遺址保存了哪一族的舊社遺構？","options":["阿美族","太魯閣族","布農族","噶瑪蘭族"],"answer":2,"explain":"遺址保存完整的布農族舊社聚落遺構。"}],"images":[]},{"id":"zhuoxi-jiaxinjiubuluo","name":"mai-asang kasing佳心舊部落","short":"佳心舊部落","category":"文化景觀","level":"文化景觀","town":"卓溪鄉","types":["其他人類與自然互動而形成之景觀"],"lat":23.34834,"lng":121.2147,"address":"花蓮縣卓溪鄉卓溪鄉山風段3地號","announced":"2020-02-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/culturalLandscape/20200427000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-04-27/10f6166a-9ecc-4d75-8013-be4443e30450/004.jpg","year":1900,"yearText":"年代不詳","era":"unknown","themes":["原住民族文化","自然地景"],"yearUnknown":true,"summary":"凝結布農族集團移住前樣貌的山中地景","intro":"mai-asang kasing佳心舊部落位於卓溪鄉玉山國家公園內，東自佳心駐在所前支稜、西至黃麻溪谷、北抵拉庫拉庫溪谷，面積約488公頃，2020年登錄為文化景觀。這裡呈現東部布農族傳統聚落與生活型態：範圍內密布壘石構築的旱作遺跡，可看出耕地、工寮與家屋的相互關係；布農族傳統以山田燒墾種植小米、番薯、玉米、山芋與旱稻。1933至1934年間，拉庫拉庫溪流域的族人受集團移住政策遷離，戰後劃為國有林班地，1985年劃入玉山國家公園。舊社地景如同時光膠囊，也記錄外來政權道路建設與治理的痕跡。","highlights":["密布山坡的壘石旱作遺跡","耕地、工寮與家屋相互連結的配置","鄰近日治佳心駐在所的道路痕跡"],"funFact":"佳心舊部落1985年劃入玉山國家公園，集團移住前的聚落樣貌因此像時光膠囊般被保存下來。","photoSpot":"在步道旁拍壘石牆與林間光影","visitMin":120,"openNote":"位於卓溪鄉玉山國家公園境內，經卓溪鄉南安一帶進出的八通關越嶺道東段前往，須依玉山國家公園規定申請，東段山區路況請查詢玉山國家公園管理處最新公告。","dialogue":[{"who":"R","text":"Allan，你為什麼一直在綁鞋帶？我們今天要去哪裡？"},{"who":"A","text":"要去卓溪鄉山裡的佳心舊部落，路不短，我的鞋帶和小腿都要先做好心理準備。"},{"who":"R","text":"舊部落？那片山裡以前是誰的家呢？"},{"who":"A","text":"是布農族的傳統聚落，2020年登錄文化景觀，整片山坡都是壘石旱作遺跡，耕地、工寮和家屋彼此相連。"},{"who":"R","text":"族人以前在這裡種什麼？後來為什麼離開？"},{"who":"A","text":"過去種小米、番薯、玉米和旱稻。1933到1934年，日治的集團移住政策讓族人遷離，1985年這裡劃入玉山國家公園。"},{"who":"R","text":"原來這片安靜的山坡，記得那麼多故事。我們要怎麼去呢？"},{"who":"A","text":"要依玉山國家公園規定申請，先查最新路況。到了請找一段壘石牆，想想當年一家人在這裡耕作的樣子。"}],"clues":["我的山坡上密布壘石構築的旱作遺跡","1933到1934年間，我的族人因集團移住而離開","我是卓溪鄉拉庫拉庫溪畔的布農族舊聚落"],"quiz":[{"q":"佳心舊部落在哪一年登錄為文化景觀？","options":["1985年","2020年","1933年","2012年"],"answer":1,"explain":"2020年登錄為文化景觀。"},{"q":"佳心舊部落族人在什麼時候因集團移住遷離？","options":["1914到1915年","1945到1946年","1933到1934年","1985到1986年"],"answer":2,"explain":"1933至1934年受集團移住政策遷移。"}],"images":[{"file":"Mai-asang kasing佳心舊部落(202110261158).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c1/Mai-asang_kasing%E4%BD%B3%E5%BF%83%E8%88%8A%E9%83%A8%E8%90%BD%28202110261158%29.jpg/960px-Mai-asang_kasing%E4%BD%B3%E5%BF%83%E8%88%8A%E9%83%A8%E8%90%BD%28202110261158%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Mai-asang_kasing%E4%BD%B3%E5%BF%83%E8%88%8A%E9%83%A8%E8%90%BD(202110261158).jpg","artist":"WU, TIEN-HSI","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/zhuoxi-jiaxinjiubuluo-0.webp","small":"img/zhuoxi-jiaxinjiubuluo-0-s.webp"}]},{"id":"guangfu-taitanggongsihua","name":"台糖公司花蓮糖廠(舊名:鹽水港製糖株式會社花蓮港製糖所大和工場)","short":"花蓮糖廠","category":"文化景觀","level":"文化景觀","town":"光復鄉","types":["工業地景"],"lat":23.657775,"lng":121.420945,"address":"花蓮縣光復鄉光復鄉大進村糖廠街19號","announced":"2009-09-28","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/culturalLandscape/20090929000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-01-10/546a219b-15a1-4160-89a4-16b86f35c8aa/台糖公司花蓮糖廠.jpg","year":1921,"yearText":"1921年（大正10年）","era":"japan","themes":["糖業","產業遺產","鐵道交通"],"yearUnknown":false,"summary":"製糖機具、糖鐵與27棟宿舍俱全的糖業地景","intro":"花蓮糖廠位於光復鄉大進村糖廠街，前身為鹽水港製糖株式會社花蓮港製糖所大和工場，1921年興建，2009年登錄為文化景觀，範圍約26公頃。廠區分為製糖工廠、行政空間與日式宿舍群：製糖工廠完整保存壓榨、清淨、蒸發、結晶、分蜜各步驟的機具；廠區留有糖廠鐵道與蒸汽火車頭、甘蔗車等；日式宿舍群共27棟73戶，涵蓋甲、乙、丙、丁等不同等級的型制。2002年4月停止製糖後轉型為觀光糖廠，部分宿舍改作旅館與藝文空間。","highlights":["保存完整的壓榨到分蜜製糖機具","糖廠鐵道上的蒸汽火車頭與甘蔗車","27棟73戶的日式木造宿舍群"],"funFact":"花蓮糖廠2002年4月停止製糖後轉型觀光糖廠，冰品成了許多遊客到光復必吃的招牌。","photoSpot":"在鐵道邊拍蒸汽火車頭與甘蔗車同框","visitMin":60,"openNote":"光復鄉在2025年9月馬太鞍溪堰塞湖溢流後仍在復原，出發前請查詢最新開放與道路狀況。官方資料記載園區提供導覽、日式木屋住宿、餐飲與冰品等服務，實際營業時間請洽糖廠；可搭臺鐵花東線至光復站。","dialogue":[{"who":"R","text":"Allan，你一路念念不忘的冰品聖地，就是這裡嗎？"},{"who":"A","text":"對，花蓮糖廠！不過先別急著排隊，它在2009年登錄文化景觀，故事比冰還多。"},{"who":"R","text":"好啦，那它是什麼時候開始做糖的？"},{"who":"A","text":"1921年興建，原名鹽水港製糖株式會社花蓮港製糖所大和工場，名字長到我念完冰都融了。"},{"who":"R","text":"噗！那2002年停止製糖以後，機器和火車還在嗎？"},{"who":"A","text":"都在，從壓榨、清淨、蒸發、結晶到分蜜的機具都保存完整，鐵道上還有蒸汽火車頭和甘蔗車。"},{"who":"R","text":"聽說在光復鄉受災之後，這裡也幫了很多忙？"},{"who":"A","text":"是的，2025年馬太鞍溪災後，地勢較高的糖廠曾作為救災物資與前進指揮基地，陪著鄉親一起走過。"},{"who":"R","text":"那我的任務是到鐵道邊找蒸汽火車頭，和甘蔗車拍一張同框照，再去吃冰！"}],"clues":["我停止製糖後，機具、鐵道與27棟宿舍都還在","2025年鄰近溪流災後，我曾成為救災物資的據點","我原是大和工場，現在以冰品聞名光復鄉"],"quiz":[{"q":"花蓮糖廠在哪一年停止製糖？","options":["2002年","1996年","2009年","2012年"],"answer":0,"explain":"2002年4月停止製糖，轉型觀光糖廠。"},{"q":"花蓮糖廠的日式宿舍群共有多少棟？","options":["15棟","32棟","47棟","27棟"],"answer":3,"explain":"日式宿舍群共27棟73戶。"}],"images":[{"file":"花蓮糖廠日本建築群.jpg","thumb":"https://upload.wikimedia.org/wikipedia/commons/0/0d/%E8%8A%B1%E8%93%AE%E7%B3%96%E5%BB%A0%E6%97%A5%E6%9C%AC%E5%BB%BA%E7%AF%89%E7%BE%A4.jpg","page":"https://commons.wikimedia.org/wiki/File:%E8%8A%B1%E8%93%AE%E7%B3%96%E5%BB%A0%E6%97%A5%E6%9C%AC%E5%BB%BA%E7%AF%89%E7%BE%A4.jpg","artist":"Fcuk1203","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"}]},{"id":"fuli-xiangfengnancunji","name":"花蓮縣富里鄉豐南村吉哈拉艾文化景觀","short":"吉哈拉艾","category":"文化景觀","level":"文化景觀","town":"富里鄉","types":["農林漁牧景觀"],"lat":23.145647,"lng":121.280994,"address":"花蓮縣富里鄉豐南村位於富里鄉最南端，東隔海岸山脈與台東縣成功鎮銜接，西與同鄉的富南村比鄰，南與台東縣池上鄉及東河鄉接壤，北邊為同鄉的永豐村。登錄地位於豐南村境內鱉溪流域中最北邊之支流石厝溝溪流域。","announced":"2012-05-02","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/culturalLandscape/20120502000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-05-25/d0736c09-5d68-47e0-bdf5-418e36cdbc10/花蓮縣富里鄉豐南村吉哈拉艾文化景觀 3.jpg","year":1926,"yearText":"1926至1928年闢建石門圳（昭和元年起）","era":"japan","themes":["原住民族文化","水利設施","自然地景"],"yearUnknown":false,"summary":"阿美族部落百年開墾的梯田與水圳地景","intro":"花蓮縣富里鄉豐南村吉哈拉艾文化景觀位於富里鄉最南端，涵蓋鱉溪支流石厝溝溪流域，2012年登錄為文化景觀。這裡是阿美族吉哈拉艾部落居民近百年陸續開墾、持續維護的梯田、水圳與聚落地景，核心區梯田約15公頃，六條水圳總長約4,100公尺。其中穿越「小天祥」峽谷岩壁的石門圳闢建於1926至1928年，是民間原漢合作開墾的例子；上游五條水圳則由部落居民利用農閒自力開鑿。田間仍留有隨溪流滾落的火山角礫岩大石。地名中的「哈拉」是阿美語的台東間爬岩鰍，以動物命名地方在縱谷阿美族中罕見。","highlights":["順著丘陵坡地層層排列的水稻梯田","穿越小天祥峽谷岩壁的石門圳","田間保留的火山角礫岩大石"],"funFact":"地名中的「哈拉」是阿美語的台東間爬岩鰍，花東縱谷阿美族以動物命名地方相當罕見。","photoSpot":"從田邊道路拍層層梯田與海岸山脈","visitMin":60,"openNote":"位於富里鄉豐南村，梯田與水圳是居民仍在耕作的生活場域，請勿踩踏田埂與水圳；官方資料未載開放時間，出發前請查詢最新開放與道路狀況，建議開車前往。","dialogue":[{"who":"R","text":"Allan，這裡的梯田一層一層，像綠色的樓梯，好像可以一路走到天上去！"},{"who":"A","text":"走到天上之前，先認識它的名字，這裡是富里鄉豐南村的吉哈拉艾文化景觀。"},{"who":"R","text":"吉哈拉艾，名字好特別，有什麼意思嗎？"},{"who":"A","text":"其中的哈拉，是阿美語裡一種溪魚，叫台東間爬岩鰍，祖先就用這種魚來命名這個地方。"},{"who":"R","text":"用溪裡的魚當地名，好有生命力！那這些梯田是怎麼來的？"},{"who":"A","text":"是阿美族居民近百年陸續開墾的，梯田約15公頃，還有六條水圳，總長約4100公尺。"},{"who":"R","text":"4100公尺的水圳，是用怪手挖的嗎？"},{"who":"A","text":"沒有怪手喔。石門圳1926到1928年穿過小天祥峽谷岩壁，其他五條是居民利用農閒自己開鑿的。"},{"who":"R","text":"太厲害了！我會乖乖走在路邊不踩田埂，去找田裡的大石頭和稻浪拍張合照！"}],"clues":["我的名字裡藏著一種溪魚的族語","我有六條水圳，其中一條穿過小天祥峽谷","我是富里鄉最南端阿美族部落的梯田文化景觀"],"quiz":[{"q":"吉哈拉艾的「哈拉」在阿美語指什麼？","options":["一種野菜","台東間爬岩鰍","山豬","小米"],"answer":1,"explain":"「哈拉」是保育類溪魚台東間爬岩鰍的阿美語。"},{"q":"穿越小天祥峽谷的石門圳闢建於何時？","options":["1908至1910年","1951至1953年","1926至1928年","1985至1987年"],"answer":2,"explain":"石門圳闢建於1926至1928年。"}],"images":[]},{"id":"guangfu-taibalangzuwu","name":"光復鄉阿美族太巴塱kakita'an祖屋","short":"太巴塱祖屋","category":"文化景觀","level":"文化景觀","town":"光復鄉","types":["其他場域"],"lat":23.657157,"lng":121.451858,"address":"花蓮縣光復鄉光復鄉東富段841地號","announced":"2007-02-12","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/culturalLandscape/20080723000004","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/cultural_tourism/38157/photo/372d25f6-cafd-4284-b1fc-1e78a6b47d19.JPG","year":2006,"yearText":"2006年重建（2007年登錄文化景觀）","era":"modern","themes":["原住民族文化","宗教信仰"],"yearUnknown":false,"summary":"阿美族太巴塱部落族人生活與祭祀的祖屋","intro":"光復鄉阿美族太巴塱kakita'an祖屋位於光復鄉東側的太巴塱（Tafalong）部落，2007年登錄為文化景觀，官方說明它是族人生活與舉行祭祀活動的場所。太巴塱是阿美族大部落之一，kakita'an傳統上是部落的領袖家族，負責年祭主祭等重要事務。依中文維基百科整理的資料，原始祖屋在1958年遭颱風損毀，殘件經族人同意由中央研究院學者移往典藏；2002年起族人推動文化復振，2006年重建完成。今日部落事務主要由年齡階層、頭目與祭師主導，祖屋則是認識部落文化的重要場域，參訪請保持尊重。","highlights":["2006年族人推動重建的祖屋","認識kakita'an家族在部落中的角色","族人生活與祭祀活動的文化景觀"],"funFact":"依部落說法，太巴塱的族語Tafalong源自一種陸生的白螃蟹，古時這一帶數量很多。","photoSpot":"徵得同意後於屋外拍攝，勿進入祭儀空間","visitMin":20,"openNote":"光復鄉在2025年9月馬太鞍溪堰塞湖溢流後仍在復原，出發前請查詢最新開放與道路狀況。祖屋是部落生活與祭祀場所，位於光復鄉東側太巴塱部落，官方資料未載開放時間，參觀前請先洽詢部落並尊重相關規範。","dialogue":[{"who":"A","text":"阿拉蕾，我們來到光復鄉東邊的太巴塱部落，等一下說話要放輕聲音，這裡對族人非常重要。"},{"who":"R","text":"收到，我把音量調小，Allan你的冷笑話也要切換成靜音模式喔。"},{"who":"A","text":"遵命。眼前是太巴塱祖屋，2007年登錄為文化景觀，是族人生活和舉行祭祀的場所。"},{"who":"R","text":"這座祖屋屬於誰呢？它在部落裡扮演什麼角色？"},{"who":"A","text":"傳統上屬於部落的領袖家族，過去負責年祭主祭等重要事務，是部落文化的核心之一。"},{"who":"R","text":"那這棟房子從很久以前一直保存到現在嗎？"},{"who":"A","text":"原來的祖屋在1958年遭颱風損毀，2002年起族人推動文化復振，2006年把祖屋重建起來。"},{"who":"R","text":"族人親手把祖屋找回來，真的好令人感動。"},{"who":"A","text":"光復鄉在2025年受堰塞湖溢流重創，出發前請先確認狀況。到了先向部落打招呼，徵得同意後在屋外靜靜看看祖屋。"}],"clues":["我原本的樣子在1958年被颱風損毀","我在2006年由族人推動重建，2007年登錄文化景觀","我屬於光復鄉一個阿美族大部落的領袖家族"],"quiz":[{"q":"太巴塱祖屋在哪一年重建完成？","options":["2006年","1958年","2002年","2012年"],"answer":0,"explain":"原祖屋1958年遭颱風損毀，2006年重建完成。"},{"q":"太巴塱祖屋登錄為哪一類文化資產？","options":["國定古蹟","歷史建築","文化景觀","考古遺址"],"answer":2,"explain":"2007年登錄為文化景觀。"}],"images":[]}],"eras":[{"id":"dutch","name":"西荷時期","range":"約1622–1662","cityName":"哆囉滿（Turoboan）與奇萊各社","title":"砂金傳說引來的西荷探險","summary":"17世紀的花蓮還沒有城鎮，立霧溪口一帶的哆囉滿社以出產砂金聞名，奇萊平原與花東縱谷則是阿美族等族群的部落。西班牙人1626年占領臺灣北部後，把立霧溪口到秀姑巒溪口的海岸與縱谷稱為哆囉滿省區；《花蓮縣志》也記載西班牙人曾來這裡採取砂金。荷蘭東印度公司從原住民口中聽說東部有金，1638年起多次派人尋金，沿途經過馬太鞍、水璉等村社；1642年驅逐北部的西班牙人後，又從北海岸向宜蘭、花蓮探查，並在大港口駐軍，1645年底以後才找到哆囉滿的產金地點，但交易到的黃金很少。1644年設立的卑南地方會議區，實際管轄只北到玉里一帶。","population":"","events":[{"year":"1626","text":"西班牙人占領臺灣北部，之後把立霧溪口到秀姑巒溪口一帶劃為哆囉滿省區"},{"year":"1638","text":"荷蘭東印度公司展開東部探金行動，在卑南社設立駐點"},{"year":"1642","text":"荷蘭人驅逐北部的西班牙人，並派兵進入東部，在大港口駐軍"},{"year":"1644","text":"設立卑南地方會議區，實際管轄北到玉里一帶"},{"year":"1645","text":"年底以後荷蘭人找到哆囉滿的產金地點，但取得的黃金很少"},{"year":"1662","text":"荷蘭人離開臺灣，東部駐點人員由卑南社人護送到屏東海邊登船"}],"landmarks":[{"name":"哆囉滿推定位置（今秀林鄉崇德一帶）","lat":24.163,"lng":121.6543,"note":"國立臺灣歷史博物館推測多囉滿社可能是崇德遺址，標示點為崇德聚落","approx":true},{"name":"大港口（今豐濱鄉港口村）","lat":23.4936,"lng":121.4966,"note":"1642年荷蘭人在此駐軍；附近港口遺址的陶器與多囉滿社使用的陶器接近","approx":true},{"name":"水璉（今壽豐鄉水璉村）","lat":23.7842,"lng":121.5627,"note":"荷蘭人沿途聽說水璉社有黃金，今水璉遺址可能就是當年的村社","approx":true},{"name":"馬太鞍（今光復鄉）","lat":23.6739,"lng":121.4298,"note":"荷蘭人尋金時經過的縱谷村社之一","approx":true},{"name":"玉里（卑南地方會議區實際北界）","lat":23.3315,"lng":121.3118,"note":"會議區實際管轄只北到玉里，標示點為玉里市區","approx":true}],"view":{"lat":23.75,"lng":121.5,"zoom":9},"dialogue":[{"who":"R","text":"Allan，這張古紙地圖上的花蓮幾乎一片空白，西班牙人和荷蘭人跑來這裡做什麼？"},{"who":"A","text":"答案亮晶晶：砂金！立霧溪口一帶的哆囉滿社，在當時就以出產砂金出名。"},{"who":"R","text":"哆囉滿在哪裡？聽起來好像一首歌的名字。"},{"who":"A","text":"大約在今天新城、崇德到立霧溪口一帶。西班牙人1626年占領臺灣北部後，就把這一帶叫做哆囉滿省區。"},{"who":"R","text":"那荷蘭人呢？他們不是待在臺南嗎？"},{"who":"A","text":"荷蘭東印度公司聽說東部有金，1638年起從南部繞過來，一路經過馬太鞍、水璉這些村社打聽消息。"},{"who":"R","text":"那他們最後到底有沒有挖到一座金山？"},{"who":"A","text":"1642年他們趕走北部的西班牙人，還在大港口駐軍，到1645年底以後才找到哆囉滿的產金地點，可惜換到的黃金少得可憐。"},{"who":"R","text":"繞了大半個臺灣，只換到一小撮金沙，這趟出差真不划算！"},{"who":"A","text":"小任務：到立霧溪出海口看看溪水沖下來的砂石，想像四百年前人們在這裡淘洗砂金的樣子。"}],"quiz":[{"q":"西班牙與荷蘭文獻中，以產砂金聞名、位在立霧溪口一帶的地方叫什麼？","options":["哆囉滿","卑南覓","璞石閣","吳全城"],"answer":0,"explain":"哆囉滿大約在今新城、崇德到立霧溪口一帶，西班牙人把這一帶稱為哆囉滿省區。"},{"q":"1642年荷蘭人在今花蓮的哪裡駐軍？","options":["吉野","大港口","花蓮港","新城"],"answer":1,"explain":"大港口在今豐濱鄉港口村，秀姑巒溪出海口附近。"}],"sources":[{"title":"花蓮縣（中文維基百科）","url":"https://zh.wikipedia.org/wiki/花蓮縣"},{"title":"哆囉滿省區（中文維基百科）","url":"https://zh.wikipedia.org/wiki/哆囉滿省區"},{"title":"荷蘭人東部探金（中文維基百科）","url":"https://zh.wikipedia.org/wiki/荷蘭人東部探金"},{"title":"卑南地方會議區（中文維基百科）","url":"https://zh.wikipedia.org/wiki/卑南地方會議區"},{"title":"尋找東方金銀島：荷蘭人遇見臺灣東部村社（國立臺灣歷史博物館）","url":"https://special.nmp.gov.tw/2016VOTI/show04.html"}]},{"id":"zheng","name":"部落社會（明鄭與清前期）","range":"1662–1874","cityName":"奇萊與後山各族部落","title":"後山是各族的家園","summary":"明鄭與清代前期，政權都沒有真正進入中央山脈以東，花蓮仍是各族群自主生活的土地。奇萊平原上撒奇萊雅族勢力最強，最大的部落達固湖灣約在今慈濟大學到四維高中一帶，外圍種了一圈又一圈的刺竹作為屏障；南勢阿美的七腳川、荳蘭、薄薄等社分布在平原南側，縱谷與海岸還有太巴塱、馬太鞍等阿美族大社。太魯閣族、賽德克族生活在立霧溪、木瓜溪一帶山區，布農族則分布在南邊的中央山脈。1830到1840年間，在蘭陽平原失去土地的噶瑪蘭族南遷，在美崙溪北岸建立加禮宛六社。漢人也開始零星入墾：道光年間吳全從宜蘭招募移民到今壽豐築城開墾，幾年後失敗；咸豐元年（1851年）又有漢人到奇萊開墾。","population":"","events":[{"year":"1662","text":"明鄭取代荷蘭，但政權沒有進入後山，花蓮仍由各族部落自主生活"},{"year":"1683","text":"清廷領有臺灣，長期沒有在後山設官治理"},{"year":"1828","text":"道光八年，吳全從宜蘭招募移民到今壽豐鄉平和村築吳全城開墾，約三年後失敗"},{"year":"1830–1840","text":"噶瑪蘭族南遷奇萊，在美崙溪北岸建立加禮宛六社"},{"year":"1851","text":"咸豐元年，漢人到奇萊開墾，相傳因溪水與海浪迴旋，稱此地為洄瀾"},{"year":"1874","text":"牡丹社事件後，清廷決定開山撫番，後山的部落社會面臨巨變"}],"landmarks":[{"name":"達固湖灣推定位置（今慈濟大學一帶）","lat":23.9942,"lng":121.5893,"note":"撒奇萊雅族最大的部落，範圍約在今慈濟大學到四維高中一帶","approx":true},{"name":"加禮宛（今新城鄉嘉里村）","lat":24.0203,"lng":121.6148,"note":"噶瑪蘭族南遷後建立的加禮宛六社所在","approx":true},{"name":"七腳川社（今吉安鄉）","lat":23.9817,"lng":121.5566,"note":"南勢阿美的大社之一","approx":true},{"name":"太巴塱部落（光復鄉）","lat":23.6582,"lng":121.4516,"note":"縱谷中的阿美族大社","approx":true},{"name":"馬太鞍部落（光復鄉）","lat":23.6739,"lng":121.4298,"note":"縱谷中的阿美族大社","approx":true},{"name":"吳全城開拓記念碑（壽豐鄉平和村）","lat":23.8889,"lng":121.5524,"note":"日治時期立的紀念碑，標示道光年間吳全城一帶","approx":false},{"name":"卓溪鄉（布農族分布區）","lat":23.3464,"lng":121.3035,"note":"南邊中央山脈是布農族的家園，標示點為卓溪鄉公所","approx":true}],"view":{"lat":23.75,"lng":121.5,"zoom":9},"dialogue":[{"who":"R","text":"這個時期叫做部落社會，難道明鄭和清朝都沒有來花蓮嗎？"},{"who":"A","text":"前山換了好幾次老闆，後山卻一直是各族自己當家。中央山脈這道高牆，可不是說翻就能翻。"},{"who":"R","text":"那時候奇萊平原上，誰的勢力最強？"},{"who":"A","text":"撒奇萊雅族！最大的部落達固湖灣，大約在今天慈濟大學一帶，外面種了一圈又一圈的刺竹當城牆。"},{"who":"R","text":"刺竹城牆，比我的手機殼還要防摔！其他族群住在哪裡？"},{"who":"A","text":"阿美族在平原南邊和縱谷、海岸，有七腳川、太巴塱、馬太鞍這些大社，太魯閣族在立霧溪山區，布農族在南邊的中央山脈。"},{"who":"R","text":"噶瑪蘭族不是住在宜蘭嗎？怎麼也出現在花蓮地圖上？"},{"who":"A","text":"他們在蘭陽平原漸漸失去土地，1830到1840年間南遷，在美崙溪北岸建立加禮宛六社。"},{"who":"R","text":"那漢人呢？有沒有人搶先來開墾？"},{"who":"A","text":"道光年間吳全帶移民到壽豐築城，幾年後就失敗了。小任務：到吳全城開拓記念碑拍張照，再找找附近哪條路名還留著吳全兩個字。"}],"quiz":[{"q":"撒奇萊雅族最大的部落叫什麼？","options":["達固湖灣","加禮宛","璞石閣","吳全城"],"answer":0,"explain":"達固湖灣約在今慈濟大學到四維高中一帶，外圍有濃密的刺竹林。"},{"q":"噶瑪蘭族南遷花蓮後，在美崙溪北岸建立的聚落群稱為什麼？","options":["南勢七社","加禮宛六社","大庄","吉野村"],"answer":1,"explain":"1830到1840年間，以加禮宛社為首的噶瑪蘭族南遷，建立加禮宛六社。"}],"sources":[{"title":"加禮宛事件（中文維基百科）","url":"https://zh.wikipedia.org/wiki/加禮宛事件"},{"title":"噶瑪蘭族（中文維基百科）","url":"https://zh.wikipedia.org/wiki/噶瑪蘭族"},{"title":"撒奇萊雅族（中文維基百科）","url":"https://zh.wikipedia.org/wiki/撒奇萊雅族"},{"title":"吳全城（中文維基百科）","url":"https://zh.wikipedia.org/wiki/吳全城"},{"title":"花蓮縣（中文維基百科）","url":"https://zh.wikipedia.org/wiki/花蓮縣"},{"title":"七腳川事件（中文維基百科）","url":"https://zh.wikipedia.org/wiki/七腳川事件"}]},{"id":"qing","name":"清代（1875 年開山以後）","range":"1875–1895","cityName":"卑南廳、臺東直隸州（奇萊、花蓮港、璞石閣）","title":"開山撫番：開路與抵抗","summary":"1874年牡丹社事件後，沈葆楨推動「開山撫番」，分北、中、南三路打通前後山。北路由羅大春從蘇澳開往奇萊；中路由總兵吳光亮在1875年開闢，從林圯埔（今竹山）越過中央山脈到璞石閣（今玉里），就是今天的八通關古道。1875年清廷設卑南廳，1888年改設臺東直隸州。對清廷來說，這是開發後山、鞏固海防；對原住民族來說，則是軍隊進入傳統領域。1876年太魯閣族在三棧一帶抵抗；1877年大港口事件中阿美族菁英遭誘殺；1878年撒奇萊雅族與噶瑪蘭族聯合抵抗，達固湖灣與加禮宛相繼被攻破，族人離散；1888年大庄一帶又爆發抗清事件。清末實際控制的範圍大致只有縱谷與海岸平地。","population":"","events":[{"year":"1874","text":"羅大春開始修築北路，從蘇澳通往奇萊"},{"year":"1875","text":"吳光亮率兵開闢中路，從林圯埔到璞石閣；同年設卑南廳管轄後山"},{"year":"1876","text":"太魯閣族在三棧一帶抵抗北路清軍，清軍在三棧溪畔築順安城"},{"year":"1877","text":"大港口事件，阿美族大港口、奇密等社抵抗開路，菁英遭清軍誘殺"},{"year":"1878","text":"加禮宛事件，撒奇萊雅族與噶瑪蘭族聯合抵抗清軍，達固湖灣與加禮宛被攻破"},{"year":"1888","text":"8月大庄事件，縱谷各庄社聯合抗清；12月臺東直隸州正式設立"}],"landmarks":[{"name":"玉里協天宮（八通關古道東端璞石閣）","lat":23.3339,"lng":121.316,"note":"相傳廟址原為清軍駐地，正殿有「後山保障」木匾","approx":false},{"name":"順安城推定位置（秀林鄉三棧）","lat":24.102,"lng":121.6058,"note":"1876年清軍在三棧溪畔築的營壘，標示點為三棧聚落","approx":true},{"name":"加禮宛（今新城鄉嘉里村）","lat":24.0203,"lng":121.6148,"note":"1878年加禮宛事件的戰場之一","approx":true},{"name":"達固湖灣推定位置（今慈濟大學一帶）","lat":23.9942,"lng":121.5893,"note":"1878年遭清軍火攻攻破的撒奇萊雅族部落","approx":true},{"name":"大港口（今豐濱鄉港口村）","lat":23.4936,"lng":121.4966,"note":"1877年大港口事件發生地","approx":true},{"name":"水尾（今瑞穗鄉）","lat":23.4968,"lng":121.376,"note":"臺東直隸州名義上的州治","approx":true},{"name":"大庄（今富里鄉東里村）","lat":23.2527,"lng":121.3299,"note":"1888年大庄事件發生地","approx":true}],"view":{"lat":23.65,"lng":121.45,"zoom":9},"dialogue":[{"who":"R","text":"Allan，這張地圖終於有路線了！清朝是怎麼走進花蓮的？"},{"who":"A","text":"1874年牡丹社事件後，沈葆楨推動開山撫番，分北、中、南三路打通前山和後山。"},{"who":"R","text":"這三條路裡面，哪一條和花蓮最有關係？"},{"who":"A","text":"北路從蘇澳開往奇萊，中路由總兵吳光亮在1875年開闢，從竹山翻過中央山脈到玉里，就是八通關古道。"},{"who":"R","text":"翻山越嶺開路，清朝的工程隊也太拚了吧！"},{"who":"A","text":"對清廷來說是開發後山，可是對原住民族來說，是軍隊走進自己的獵場和家園，所以抵抗不斷。"},{"who":"R","text":"那開路的時候，都發生了哪些衝突？"},{"who":"A","text":"1876年太魯閣族在三棧一帶抵抗，1877年大港口的阿美族菁英遭誘殺，1878年撒奇萊雅族和噶瑪蘭族聯合抵抗，就是加禮宛事件。"},{"who":"R","text":"這段歷史好沉重，那兩族後來怎麼了？"},{"who":"A","text":"部落被攻破後族人離散，隱身在阿美族部落一百多年。小任務：到玉里協天宮找找正殿那塊「後山保障」木匾。"}],"quiz":[{"q":"八通關古道是清代開山撫番三條道路中的哪一路？","options":["北路","中路","南路","西路"],"answer":1,"explain":"中路由吳光亮在1875年開闢，從林圯埔到璞石閣，全長約152公里。"},{"q":"1878年撒奇萊雅族與噶瑪蘭族聯合抵抗清軍的事件稱為什麼？","options":["七腳川事件","加禮宛事件","新城事件","大庄事件"],"answer":1,"explain":"加禮宛事件又稱達固湖灣事件，兩族在事件後幾乎離散。"}],"sources":[{"title":"開山撫番（中文維基百科）","url":"https://zh.wikipedia.org/wiki/開山撫番"},{"title":"八通關古道（中文維基百科）","url":"https://zh.wikipedia.org/wiki/八通關古道"},{"title":"加禮宛事件（中文維基百科）","url":"https://zh.wikipedia.org/wiki/加禮宛事件"},{"title":"太魯閣戰役（中文維基百科）","url":"https://zh.wikipedia.org/wiki/太魯閣戰役"},{"title":"大港口事件（中文維基百科）","url":"https://zh.wikipedia.org/wiki/大港口事件"},{"title":"卑南廳（中文維基百科）","url":"https://zh.wikipedia.org/wiki/卑南廳"},{"title":"臺東直隸州（中文維基百科）","url":"https://zh.wikipedia.org/wiki/臺東直隸州"},{"title":"大庄事件（中文維基百科）","url":"https://zh.wikipedia.org/wiki/大庄事件"}]},{"id":"japan","name":"日治時期","range":"1895–1945","cityName":"臺東廳、花蓮港廳（1909年起）","title":"移民村、鐵道與港口","summary":"日治初期花蓮屬臺東廳，1909年10月花蓮港廳獨立設置。殖民政府推動理蕃與開發，也引發激烈衝突：1896年新城事件中太魯閣族擊退日軍；1908年七腳川社因隘勇薪資與勤務分配不滿而與日警衝突，日方派軍警討伐，族人被迫遷離，土地後來成為吉野移民村；1914年太魯閣戰爭是20世紀臺灣本島最大的戰役，族人戰敗後被迫遷往平地。1910年起，官營的吉野、豐田、林田移民村相繼成立，日本移民在颱風、旱災與疾病中辛苦開墾。臺東線鐵路1926年全線通車；1931年起興築花蓮港，1939年開港；鹽水港製糖在馬太鞍建大和工場（今花蓮糖廠），林田山也在1939年由台灣興業株式會社設伐木事業所。","population":"","events":[{"year":"1896","text":"新城事件，太魯閣族擊退日軍"},{"year":"1908","text":"12月七腳川事件，七腳川社遭軍警討伐，土地被沒收"},{"year":"1909","text":"10月花蓮港廳設立，脫離臺東廳獨立"},{"year":"1910","text":"吉野村開始招募日本移民，是第一個官營移民村"},{"year":"1914","text":"太魯閣戰爭；同年林田移民村成立"},{"year":"1926","text":"臺東線鐵路全線通車"},{"year":"1931","text":"花蓮港開始築港"},{"year":"1939","text":"花蓮港第一期工程完成開港；林田山設立伐木事業所"}],"landmarks":[{"name":"吉安慶修院（吉野移民村布教所）","lat":23.9736,"lng":121.5647,"note":"原真言宗吉野布教所","approx":false},{"name":"豐田移民村（豐田文史館一帶）","lat":23.8454,"lng":121.5029,"note":"豐田文史館原為豐田派出所廳舍","approx":false},{"name":"林田神社本殿基座（鳳林鎮大榮里）","lat":23.7488,"lng":121.4656,"note":"林田移民村留下的神社殘蹟","approx":false},{"name":"新城天主堂（新城事件紀念碑所在）","lat":24.1294,"lng":121.6503,"note":"天主堂前有日方為新城事件殉難將士所立的瘞骨碑","approx":false},{"name":"花蓮港","lat":23.9878,"lng":121.6343,"note":"1931年起築港、1939年開港的陸掘式港灣","approx":false},{"name":"花蓮糖廠（大和工場）","lat":23.6574,"lng":121.421,"note":"1921年完工的大和工場，今花蓮觀光糖廠","approx":false},{"name":"林田山林業文化園區（森坂）","lat":23.7172,"lng":121.3995,"note":"1939年台灣興業株式會社在森坂設伐木事業所","approx":false}],"view":{"lat":23.8,"lng":121.5,"zoom":9},"dialogue":[{"who":"R","text":"Allan，日治時期的地圖上，怎麼突然多了好多日本名字的村子？"},{"who":"A","text":"那是官營移民村！1910年起，吉野、豐田、林田相繼成立，從日本招募農民來開墾。"},{"who":"R","text":"吉野這個名字好熟，就是今天的吉安嗎？"},{"who":"A","text":"沒錯，吉安慶修院就是當年吉野村的布教所。移民在颱風、旱災和疾病中開墾，也吃足了苦頭。"},{"who":"R","text":"可是移民村的土地，原本是誰的？"},{"who":"A","text":"吉野村的土地，來自1908年七腳川事件後被沒收的七腳川社土地。移民的辛苦和原住民族失去家園，要一起記得。"},{"who":"R","text":"我聽說太魯閣族也和日本打過仗？"},{"who":"A","text":"1896年新城事件，太魯閣族擊退日軍，1914年太魯閣戰爭，是20世紀臺灣本島最大的戰役，族人戰敗後被迫遷往平地。"},{"who":"R","text":"除了戰爭，日本時代還留下了什麼？"},{"who":"A","text":"1926年臺東線鐵路全線通車，1939年花蓮港開港。小任務：到吉安慶修院，找找參道兩旁排成一列的石佛。"}],"quiz":[{"q":"臺灣日治時期第一個官營日本移民村是哪一個？","options":["豐田村","林田村","吉野村","瑞穗村"],"answer":2,"explain":"吉野村在今吉安鄉，1910年開始招募日本移民，移民多來自德島縣吉野川沿岸。"},{"q":"花蓮港在哪一年開港？","options":["1909年","1926年","1939年","1963年"],"answer":2,"explain":"花蓮港1931年起興築，1939年10月第一期工程完成開港。"}],"sources":[{"title":"花蓮港廳（中文維基百科）","url":"https://zh.wikipedia.org/wiki/花蓮港廳"},{"title":"新城事件（中文維基百科）","url":"https://zh.wikipedia.org/wiki/新城事件"},{"title":"七腳川事件（中文維基百科）","url":"https://zh.wikipedia.org/wiki/七腳川事件"},{"title":"太魯閣戰爭（中文維基百科）","url":"https://zh.wikipedia.org/wiki/太魯閣戰爭"},{"title":"吉野村（中文維基百科）","url":"https://zh.wikipedia.org/wiki/吉野村"},{"title":"豐田移民村（中文維基百科）","url":"https://zh.wikipedia.org/wiki/豐田移民村"},{"title":"林田移民村（中文維基百科）","url":"https://zh.wikipedia.org/wiki/林田移民村"},{"title":"花東線（中文維基百科）","url":"https://zh.wikipedia.org/wiki/花東線"},{"title":"花蓮港（中文維基百科）","url":"https://zh.wikipedia.org/wiki/花蓮港"},{"title":"花蓮觀光糖廠（中文維基百科）","url":"https://zh.wikipedia.org/wiki/花蓮觀光糖廠"},{"title":"林田山（中文維基百科）","url":"https://zh.wikipedia.org/wiki/林田山"}]},{"id":"early-roc","name":"民國初年","range":"1945–1950年代","cityName":"花蓮縣（1946年1月成立）","title":"戰後新縣與大陳新村","summary":"1945年日治結束，日本移民全數返鄉，移民村的農地多在公地放領後成為耕地，吉野也改名為吉安。1946年1月花蓮港廳改制為花蓮縣，1950年10月成為第一個依憲法實施地方自治的縣市，選出首任民選縣長。1951年10月22日花蓮附近發生規模7.3的強震，之後到12月，縱谷一帶接連發生多次強烈地震，氣象單位統計共85人罹難。1955年大陳島撤退後，約3000位上大陳島居民被安置到花蓮，在美崙一帶建立大陳一村、二村。1956年東西橫貫公路開工，上萬名榮民投入開路。產業方面，臺糖接收大和工場成為花蓮港糖廠，林田山林場則由台灣紙業接手繼續伐木。","population":"","events":[{"year":"1945","text":"日治結束，日本移民全數返鄉"},{"year":"1946","text":"1月花蓮港廳改制為花蓮縣"},{"year":"1950","text":"10月成為第一個依憲法實施地方自治的縣市"},{"year":"1951","text":"10月22日花蓮附近規模7.3強震，到12月的系列地震共85人罹難"},{"year":"1955","text":"大陳島撤退，約3000位上大陳島居民安置到花蓮"},{"year":"1956","text":"7月東西橫貫公路開工"}],"landmarks":[{"name":"花蓮縣政府","lat":23.9915,"lng":121.6193,"note":"標示今日縣政府位置，戰後縣治一直設在花蓮市","approx":true},{"name":"大陳一村、二村（花蓮市民意里）","lat":24.001,"lng":121.6174,"note":"1955年安置上大陳島居民的大陳新村","approx":true},{"name":"花蓮港","lat":23.9878,"lng":121.6343,"note":"戰後初期每年裝卸量只有幾十萬噸","approx":false},{"name":"花蓮糖廠（戰後花蓮港糖廠）","lat":23.6574,"lng":121.421,"note":"1946年臺糖保留大和工場，合併成花蓮港糖廠","approx":false},{"name":"林田山林場","lat":23.7172,"lng":121.3995,"note":"戰後由台灣紙業接手伐木","approx":false},{"name":"太魯閣（東西橫貫公路東端）","lat":24.1555,"lng":121.6216,"note":"1956年開工的橫貫公路東端起點，標示點為今太魯閣牌樓","approx":true}],"view":{"lat":23.9,"lng":121.55,"zoom":9},"dialogue":[{"who":"R","text":"1945年戰爭結束，花蓮的移民村後來怎麼了？"},{"who":"A","text":"日本移民全部返鄉，農地多半在公地放領後成為農民的耕地，吉野也改名叫吉安。"},{"who":"R","text":"那花蓮縣是什麼時候正式出現的？"},{"who":"A","text":"1946年1月花蓮港廳改制為花蓮縣。1950年10月，還成為第一個依憲法實施地方自治的縣市。"},{"who":"R","text":"第一名耶！花蓮在這件事上是模範生。"},{"who":"A","text":"不過1951年10月22日，花蓮附近發生規模7點3的強震，到12月縱谷一帶又接連強震，總共85人罹難。"},{"who":"R","text":"城市要一邊重建一邊往前走，真的很不容易。"},{"who":"A","text":"1955年大陳島撤退，大約3000位上大陳島居民來到花蓮，在美崙一帶落腳，就是今天的大陳一村和二村。"},{"who":"R","text":"從海島搬到另一個靠海的地方，應該很快就聞到熟悉的海味了吧？"},{"who":"A","text":"大陳一村的居民最初多半靠捕魚維生。小任務：到美崙的大陳新村走走，聽聽長輩說的家鄉話和你熟悉的口音有什麼不同。"}],"quiz":[{"q":"花蓮縣在哪一年成立？","options":["1909年","1946年","1951年","1960年"],"answer":1,"explain":"1946年1月，花蓮港廳改制為花蓮縣。"},{"q":"1955年來到花蓮定居的大陳居民，主要來自哪座島？","options":["上大陳島","金門","蘭嶼","綠島"],"answer":0,"explain":"花蓮的大陳一村、二村居民來自大陳列島中的上大陳島。"}],"sources":[{"title":"花蓮縣（中文維基百科）","url":"https://zh.wikipedia.org/wiki/花蓮縣"},{"title":"花蓮港廳（中文維基百科）","url":"https://zh.wikipedia.org/wiki/花蓮港廳"},{"title":"吉野村（中文維基百科）","url":"https://zh.wikipedia.org/wiki/吉野村"},{"title":"花蓮大陳新村（中文維基百科）","url":"https://zh.wikipedia.org/wiki/花蓮大陳新村"},{"title":"大陳新村（中文維基百科）","url":"https://zh.wikipedia.org/wiki/大陳新村"},{"title":"中部橫貫公路（中文維基百科）","url":"https://zh.wikipedia.org/wiki/中部橫貫公路"},{"title":"花蓮觀光糖廠（中文維基百科）","url":"https://zh.wikipedia.org/wiki/花蓮觀光糖廠"},{"title":"林田山（中文維基百科）","url":"https://zh.wikipedia.org/wiki/林田山"},{"title":"1951 East Rift Valley earthquakes（英文維基百科）","url":"https://en.wikipedia.org/wiki/1951_East_Rift_Valley_earthquakes"}]},{"id":"roc60","name":"民國60年前後","range":"約1963–1981","cityName":"花蓮縣","title":"橫貫公路與北迴鐵路","summary":"1960年5月東西橫貫公路通車，從太魯閣穿越大理石峽谷通往臺中，開路的榮民在峭壁間鑿出隧道與橋樑，長春祠供奉在工程中殉職的人員。1963年9月花蓮港開放為國際商港，成立花蓮港務局；1968年臺東線開始行駛光華號柴油特快車，花蓮到臺東縮短到約3小時10分。1972年林田山發生森林大火，次年林務局接管林場，伐木盛況逐漸結束。最重要的改變是北迴鐵路：1973年列入十大建設動工，以多座長隧道穿越山區與斷崖，1979年底完工，1980年2月全線通車，宜蘭與花蓮終於有鐵路直通，花蓮「陸上離島」的處境大為改善。","population":"","events":[{"year":"1960","text":"5月東西橫貫公路通車"},{"year":"1963","text":"9月花蓮港開放為國際商港"},{"year":"1968","text":"臺東線行駛光華號，花蓮到臺東縮短到約3小時10分"},{"year":"1972","text":"林田山發生森林大火，次年林務局接管林場"},{"year":"1973","text":"12月北迴鐵路列入十大建設動工"},{"year":"1979","text":"2月北迴線南段通車營運，年底全線完工"},{"year":"1980","text":"2月北迴鐵路全線通車"}],"landmarks":[{"name":"太魯閣牌樓（中橫公路東端）","lat":24.1555,"lng":121.6216,"note":"東西橫貫公路的東端入口","approx":false},{"name":"長春祠","lat":24.16,"lng":121.604,"note":"供奉中橫開路殉職人員；1988年在原址左側重建","approx":false},{"name":"花蓮港","lat":23.9878,"lng":121.6343,"note":"1963年開放為國際商港","approx":false},{"name":"花蓮車站（北迴線花蓮新站）","lat":23.994,"lng":121.6009,"note":"1980年北迴鐵路通車典禮在花蓮新站舉行","approx":false},{"name":"和平車站一帶（北迴鐵路殉職員工紀念碑）","lat":24.2978,"lng":121.7547,"note":"紀念碑設在和平站，標示點為和平車站","approx":true},{"name":"林田山林場","lat":23.7172,"lng":121.3995,"note":"1972年森林大火後伐木事業逐漸結束","approx":false}],"view":{"lat":24.05,"lng":121.55,"zoom":9},"dialogue":[{"who":"R","text":"Allan，民國60年前後的花蓮，最大的新聞是什麼？"},{"who":"A","text":"交通！1960年5月東西橫貫公路通車，從太魯閣穿過大理石峽谷，一路通到臺中。"},{"who":"R","text":"在大理石峭壁上開路，光聽就覺得腿軟。"},{"who":"A","text":"開路的榮民用很簡陋的工具鑿隧道，不少人因此殉職，長春祠就是為了紀念他們而建。"},{"who":"R","text":"那時候從臺北到花蓮，還是要走蘇花公路或坐船嗎？"},{"who":"A","text":"對，所以花蓮有「陸上離島」的外號。1973年北迴鐵路列入十大建設動工，要穿過一座又一座山。"},{"who":"R","text":"什麼時候才通車？我已經替當時的人等得好心急！"},{"who":"A","text":"1979年底完工，1980年2月全線通車。從此火車可以從宜蘭直接開進花蓮新站。"},{"who":"R","text":"終於不用暈船了！那港口那邊有什麼變化？"},{"who":"A","text":"1963年花蓮港成為國際商港。小任務：到花蓮港邊看看大船進出，想想當年全靠船運往來的日子。"}],"quiz":[{"q":"東西橫貫公路在哪一年通車？","options":["1956年","1960年","1973年","1980年"],"answer":1,"explain":"中橫1956年7月開工，1960年5月9日通車。"},{"q":"北迴鐵路在哪一年全線通車？","options":["1973年","1975年","1980年","1986年"],"answer":2,"explain":"北迴鐵路1973年動工，1979年底完工，1980年2月全線通車。"}],"sources":[{"title":"中部橫貫公路（中文維基百科）","url":"https://zh.wikipedia.org/wiki/中部橫貫公路"},{"title":"北迴線（中文維基百科）","url":"https://zh.wikipedia.org/wiki/北迴線"},{"title":"花蓮港（中文維基百科）","url":"https://zh.wikipedia.org/wiki/花蓮港"},{"title":"花東線（中文維基百科）","url":"https://zh.wikipedia.org/wiki/花東線"},{"title":"林田山（中文維基百科）","url":"https://zh.wikipedia.org/wiki/林田山"}]},{"id":"now","name":"現在","range":"1982–今","cityName":"花蓮縣","title":"族群正名與災後復原","summary":"1982年臺東線完成拓寬，東部鐵路接上全臺路網；1986年太魯閣國家公園成立，1987年八通關古道指定為古蹟。2002年噶瑪蘭族、2007年撒奇萊雅族先後獲政府認定為臺灣原住民族，族人恢復自己的名字，撒奇萊雅族也以火神祭追念加禮宛事件中犧牲的祖先。2020年1月蘇花公路改善工程全線通車，行車更安全。2024年4月3日花蓮強震造成嚴重災情，太魯閣峽谷多數步道與中橫公路太魯閣段長期封閉或管制；2025年9月23日馬太鞍溪堰塞湖溢流，洪水衝入光復鄉，造成重大傷亡，地勢較高的光復糖廠成為救災前進指揮所，災區仍在復原。到花蓮旅行，出發前請查詢最新開放與道路狀況。","population":"約32萬人","events":[{"year":"1982","text":"臺東線完成拓寬，東部鐵路與全臺路網接軌"},{"year":"1986","text":"太魯閣國家公園成立"},{"year":"2002","text":"12月噶瑪蘭族獲認定為臺灣原住民族第11族"},{"year":"2007","text":"1月撒奇萊雅族獲認定為臺灣原住民族第13族"},{"year":"2020","text":"1月蘇花公路改善工程全線通車"},{"year":"2024","text":"4月3日花蓮強震，太魯閣步道與中橫太魯閣段長期封閉或管制"},{"year":"2025","text":"9月23日馬太鞍溪堰塞湖溢流，光復鄉受災嚴重"}],"landmarks":[{"name":"太魯閣國家公園管理處","lat":24.1582,"lng":121.6234,"note":"受2024年強震影響，出發前請查詢太魯閣國家公園管理處與公路局最新開放與道路狀況","approx":false},{"name":"國福部落（撒奇萊雅族）","lat":24.0089,"lng":121.5796,"note":"2006年撒奇萊雅族在此舉辦第一次火神祭，標示點為國福里","approx":true},{"name":"新社部落（豐濱鄉新社村）","lat":23.6454,"lng":121.5225,"note":"花東海岸較具規模的噶瑪蘭族部落","approx":true},{"name":"花蓮觀光糖廠（光復糖廠）","lat":23.6574,"lng":121.421,"note":"2025年馬太鞍溪堰塞湖溢流後的救災前進指揮所","approx":false},{"name":"馬太鞍溪橋","lat":23.6887,"lng":121.4091,"note":"2025年9月被洪水沖毀，正在重建","approx":false},{"name":"玉山國家公園南安遊客中心","lat":23.3025,"lng":121.2584,"note":"日治八通關越嶺道東段從卓溪南安進出，入山須依規定申請","approx":false}],"view":{"lat":23.8,"lng":121.5,"zoom":9},"dialogue":[{"who":"R","text":"來到現在的花蓮了，Allan，你最想先介紹哪一件事？"},{"who":"A","text":"名字！2002年噶瑪蘭族、2007年撒奇萊雅族先後正名，族人終於能用自己的族名介紹自己。"},{"who":"R","text":"撒奇萊雅族，就是加禮宛事件後隱身在阿美族裡的那一族吧？"},{"who":"A","text":"沒錯，他們現在以火神祭追念當年為族人奮戰的祖先，這是很莊重的祭儀。"},{"who":"R","text":"那交通是不是也變得比較方便了？"},{"who":"A","text":"2020年1月蘇花公路改善工程全線通車，加上北迴鐵路，回花蓮的路比以前安全多了。"},{"who":"R","text":"可是這幾年，常聽到花蓮的災情新聞。"},{"who":"A","text":"2024年4月3日強震後，太魯閣多數步道和中橫太魯閣段長期封閉或管制，2025年9月23日馬太鞍溪堰塞湖溢流，光復鄉受災嚴重。"},{"who":"R","text":"我們去花蓮旅行，可以怎麼盡一份心力？"},{"who":"A","text":"出發前先查最新開放與道路狀況，在地消費就是支持。小任務：到光復糖廠買一支冰品，看看社區復原的努力。"}],"quiz":[{"q":"撒奇萊雅族在哪一年正名為臺灣原住民族？","options":["1996年","2002年","2007年","2014年"],"answer":2,"explain":"撒奇萊雅族在2007年1月17日獲認定為第13個臺灣原住民族。"},{"q":"2025年9月馬太鞍溪堰塞湖溢流，哪個鄉受災最嚴重？","options":["秀林鄉","光復鄉","富里鄉","新城鄉"],"answer":1,"explain":"洪水沖毀馬太鞍溪橋並衝入光復鄉市區，光復鄉至今仍在復原。"}],"sources":[{"title":"花東線（中文維基百科）","url":"https://zh.wikipedia.org/wiki/花東線"},{"title":"太魯閣國家公園（中文維基百科）","url":"https://zh.wikipedia.org/wiki/太魯閣國家公園"},{"title":"八通關古道（中文維基百科）","url":"https://zh.wikipedia.org/wiki/八通關古道"},{"title":"噶瑪蘭族（中文維基百科）","url":"https://zh.wikipedia.org/wiki/噶瑪蘭族"},{"title":"撒奇萊雅族（中文維基百科）","url":"https://zh.wikipedia.org/wiki/撒奇萊雅族"},{"title":"蘇花公路改善計畫（中文維基百科）","url":"https://zh.wikipedia.org/wiki/蘇花公路改善計畫"},{"title":"2024年花蓮地震（中文維基百科）","url":"https://zh.wikipedia.org/wiki/2024年花蓮地震"},{"title":"馬太鞍溪堰塞湖（中文維基百科）","url":"https://zh.wikipedia.org/wiki/馬太鞍溪堰塞湖"}]}],"qingCity":null,"ich":{"items":[{"id":"ich-dazhuang-yeji","name":"大庄西拉雅族夜祭","type":"民俗","holder":"花蓮縣富里鄉大庄公廨協會","registered":"2013-07-09","summary":"富里大庄公廨的大武壠系統夜祭與牽曲","intro":"富里鄉東里村一帶的大庄部落，平埔族居民以大武壠（Taivoan）與馬卡道（Makatao）兩個亞族為主，祖先原居今臺南烏山山脈西麓的頭社、茄拔、霄裡、芒仔芒等「四社熟番」，後來輾轉東遷到花東縱谷。大庄公廨奉祀祖神阿立祖、太祖，公廨內不拜壺而設向神座，祭祖時舉行夜祭，以牽戲、牽曲歌舞敬神。官方紀錄指出，臺灣大武壠公廨文化保存最完整的有高雄甲仙小林與花蓮大庄兩處；大庄保留一套共12首祭儀歌謠，婦女牽曲班傳承傳統舞步也有創新，並融入馬卡道重視「向」的特色，是東臺灣西拉雅文化復振的重要據點。花蓮縣於2013年登錄。","whereToSee":"大庄公廨（富里鄉東里村大庄）。官方紀錄提到大武壠系統於9月15日祭祖並舉行夜祭，實際日期與流程每年由部落決定，請以花蓮縣富里鄉大庄公廨協會或富里鄉公所公告為準。夜祭是祭祖儀式，請聽從公廨人員指示，不要擅入公廨內部或觸碰祭物，拍照前先徵得同意。","venueId":"venue-f-dazhuang","dialogue":[{"who":"R","text":"Allan，富里的夜裡怎麼傳來好多人一起唱歌的聲音？"},{"who":"A","text":"這是大庄部落的夜祭。大庄的平埔族人以大武壠和馬卡道為主，祖先是從臺南山區一路遷到花東縱谷的。"},{"who":"R","text":"從臺南搬到富里？那可是翻山越嶺的大搬家耶。"},{"who":"A","text":"所以官方說這個祭儀見證了祖先遷移的艱辛。族人在公廨祭拜祖神阿立祖和太祖，夜裡牽起手唱牽曲。"},{"who":"R","text":"公廨我知道，是平埔族的祭祀場所！裡面也有供壺嗎？"},{"who":"A","text":"有趣的是，大庄公廨內不拜壺，而是設向神座。這裡還保留一整套12首祭儀歌謠，由婦女牽曲班傳唱。"},{"who":"R","text":"12首耶！Allan，你學得會幾首？"},{"who":"A","text":"我只會唱肚子餓之歌，一唱就想到富里的米飯。祭典上還是安靜聆聽，不要跟著亂哼。"},{"who":"R","text":"小任務：依公告日期到場，靜靜數一數牽曲的隊伍繞了幾圈。"}],"quiz":[{"q":"官方紀錄中，大庄公廨保留了一套共幾首的祭儀歌謠？","options":["4首","8首","12首","36首"],"answer":2,"explain":"官方紀錄記載大庄公廨保留一套完整的祭儀歌謠，共計12首，由婦女牽曲班傳承。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20130709000001"},{"id":"ich-cihuitang-tangqing","name":"聖地慈惠堂總堂開堂紀念日","type":"民俗","holder":"聖地慈惠堂總堂","registered":"2013-07-10","summary":"慈惠堂瑤池金母信仰從花蓮傳往全臺的堂慶","intro":"依慈惠堂總堂簡介，戰後初年瘟疫四起，民國37年（1948年）農曆六月初三，瑤池金母降臨花蓮市郊田浦荒野丘地的一間小茅屋，收50位契子女，勸人修身向善，成為慈惠堂信仰的起點。總堂位於吉安鄉，是各地分堂重要儀式的源頭。每年農曆2月18日總堂堂慶，是各地分堂及宮、寺、廟、壇回總堂朝聖的日子；從農曆正月初三起，各堂執事就帶著契子女與信眾組團回來「省親謁母」，慶典綿延約兩個月。農曆7月18日金母聖誕則由各分堂自行祝壽。官方登錄理由指出，這是信仰從臺灣東部傳往西部的特例。花蓮縣於2013年登錄。","whereToSee":"聖地慈惠堂總堂（吉安鄉勝安村慈惠三街）。總堂堂慶在每年農曆2月18日，朝聖團自農曆正月初三起陸續回總堂，期間人潮與車潮多，詳細行程請以總堂公告為準。參拜時請依堂方指示動線，儀式進行中勿大聲喧嘩。","venueId":"venue-f-cihuitang","dialogue":[{"who":"R","text":"Allan，吉安這條街怎麼停滿了外縣市的遊覽車？"},{"who":"A","text":"這是慈惠堂總堂的堂慶時節。各地分堂組團回總堂朝聖，他們叫做「省親謁母」，就是回娘家看母親。"},{"who":"R","text":"回娘家！那這位大家口中的母親，到底是哪一位神明？"},{"who":"A","text":"是瑤池金母。依總堂簡介，1948年金母降臨花蓮市郊田浦的一間小茅屋，收了50位契子女。"},{"who":"R","text":"從一間小茅屋開始，後來分堂遍布全臺？"},{"who":"A","text":"對，官方說這是信仰從東部傳往西部的特例。一般都是西部往東部傳，這次花蓮反過來當起老家。"},{"who":"R","text":"花蓮通的我給一百分！那堂慶是哪一天？"},{"who":"A","text":"農曆2月18日，不過從正月初三就開始有朝聖團，熱鬧兩個月，比我家過年的剩菜還能撐。"},{"who":"R","text":"小任務：在總堂找一找各地分堂的旗幟，看看你能認出幾個縣市的名字。"}],"quiz":[{"q":"聖地慈惠堂總堂的堂慶在每年哪一天？","options":["農曆正月初九","農曆2月18日","農曆6月初三","農曆7月18日"],"answer":1,"explain":"總堂堂慶在農曆2月18日；農曆7月18日是金母聖誕，由各分堂自行祝壽。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20130710000001"},{"id":"ich-shenganggong-raojing","name":"花蓮勝安宮王母娘娘遶境活動","type":"民俗","holder":"花蓮勝安宮管理委員會","registered":"2013-07-17","summary":"勝安宮王母娘娘出巡收圓、綏靖地方","intro":"吉安鄉勝安宮是王母娘娘信仰的重要祖廟。官方紀錄引用研究指出，遶境約從民國40年代開始，目的是王母娘娘「收圓」、綏靖地方：收圓指圓滿之意，相傳遶境時王母娘娘會渡化沿途孤魂，使其回歸修行、不再作祟，以求合境平安。考量人力與經費，分為三年一次、規模較小的吉安、新城、秀林三鄉與花蓮市遶境，以及五年一次的全縣大遶境；全縣遶境由管理委員會統籌路線與請神，並邀請全臺宮廟陣頭參加。隊伍以勝安宮車隊在前，依序為順天聖母陳靖姑、王三娘、二郎神、齊天大聖、王母娘娘，手持利劍的順天聖母擔任先鋒開路。花蓮縣於2013年登錄。","whereToSee":"花蓮勝安宮（吉安鄉勝安村慈惠三街）與遶境路線。三鄉一市遶境約三年一次，全縣遶境約五年一次，舉辦年份、日期、路線與交通管制請以勝安宮公告為準。遶境時請勿穿越神轎與陣頭隊伍。","venueId":"venue-f-shenganggong","dialogue":[{"who":"R","text":"Allan，遶境隊伍最前面那位拿著寶劍的神明是誰？好有氣勢！"},{"who":"A","text":"那是順天聖母陳靖姑，勝安宮王母娘娘遶境的開路先鋒。傳說她擅長收妖除煞，所以站第一排。"},{"who":"R","text":"那開路先鋒的後面，還跟著哪幾位神明呢？"},{"who":"A","text":"依序是王三娘、二郎神、齊天大聖，最後才是王母娘娘，各宮廟的陣頭再跟在後面。"},{"who":"R","text":"這麼大的陣仗，是每年都會出巡一次嗎？"},{"who":"A","text":"不是喔，三年一次走吉安、新城、秀林三鄉和花蓮市，五年一次才是全縣大遶境。"},{"who":"R","text":"三年和五年，那剛好重疊的年份怎麼辦？"},{"who":"A","text":"這要問廟方的行事曆，我只負責算每次遶境能吃幾顆麻糬。實際年份請看勝安宮公告。"},{"who":"R","text":"小任務：遶境時找一找手持寶劍的順天聖母，看她排在隊伍的哪個位置。"}],"quiz":[{"q":"勝安宮王母娘娘遶境隊伍中，擔任開路先鋒的是哪位神明？","options":["齊天大聖","二郎神","王三娘","順天聖母陳靖姑"],"answer":3,"explain":"廟方說明陳靖姑習有法術、擅長收妖除煞，因此以手持利劍的形象在車隊前開路。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20130717000001"},{"id":"ich-wenmian","name":"紋面傳統","type":"民俗","holder":"花蓮縣柏達散文化學會；紋面耆老古阿采、方阿妹、陳清香、邱春妹、鄭好妹、林智妹（均已故）","registered":"2009-12-09","summary":"太魯閣族、賽德克族的生命禮俗與認同表徵","intro":"紋面是泛泰雅族群（太魯閣族、賽德克族、泰雅族）重要的傳統表徵。官方紀錄說明，傳統社會中男子須具備獵首能力、女子須具備織布能力，才能取得紋面資格、論及婚嫁；紋面象徵成為「社會人」，肩負成家與保護聚落的責任，死後得以進入祖靈界。紋面工具有桐木製的刺刷、藤條做的刮血工具與木槌，男子紋在前額與下巴，女子紋在前額與臉頰，花紋有直線、斜線、點三類共22種。今日紋面已不再實際施作，族人改以紋面貼紙或暫時性紋畫表達認同。花蓮縣柏達散文化學會長年陪伴紋面耆老、留下影音紀錄，官方登錄的紋面耆老皆已辭世。花蓮縣於2009年登錄。","whereToSee":"流傳於秀林鄉、萬榮鄉、卓溪鄉的太魯閣族與賽德克族部落，沒有固定的公開展示地點，可留意部落文化館舍與族群文化活動的展覽。紋面是族人的生命禮俗與認同，請以尊重的態度認識，不要模仿嬉戲；拍攝族人或相關影像前請先徵得同意。","venueId":"","dialogue":[{"who":"R","text":"Allan，我在老照片裡看到臉上有紋路的長輩，那是什麼意義呢？"},{"who":"A","text":"那是紋面，太魯閣族、賽德克族和泰雅族重要的生命禮俗，代表成為能承擔責任的大人。"},{"who":"R","text":"那要怎樣才能紋面？是長大就可以嗎？"},{"who":"A","text":"官方紀錄說，傳統上男子要有獵首能力，女子要會織布，才取得紋面資格，也才能論及婚嫁。"},{"who":"R","text":"原來紋面是一種肯定，也關係到過世後能不能回到祖靈那裡吧？"},{"who":"A","text":"對，族人相信紋面的人死後能進入祖靈界。男子紋前額和下巴，女子紋前額和臉頰，花紋共有22種。"},{"who":"R","text":"那現在部落裡還有人在實際紋面嗎？"},{"who":"A","text":"已經不再實際施作了，官方登錄的紋面耆老也都已辭世。柏達散文化學會留下許多影音紀錄，讓後代記得。"},{"who":"A","text":"小任務：到部落文化館看展時，留意紋面紋樣的直線、斜線和點，並用心記下它們背後的故事。"}],"quiz":[{"q":"依官方紀錄，傳統上女子要具備什麼能力才能取得紋面資格？","options":["織布","製陶","捕魚","釀酒"],"answer":0,"explain":"傳統泛泰雅社會中，男子須曾獵首、女子須具織布能力，才能取得紋面資格。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20091209000004"},{"id":"ich-ruanbi-zhenjun","name":"大陳新村阮弼真君祭典","type":"民俗","holder":"阮弼真君廟管理委員會","registered":"2014-05-28","summary":"大陳移民帶到花蓮的海神信仰與祭典","intro":"1955年大陳島居民遷臺，部分族人落腳花蓮美崙一帶的大陳新村。阮弼真君是大陳人信仰中的守護神之一，被奉為海神，原祀於上大陳寮頭岩的樁頭廟。花蓮大陳一村的真君廟原本是供奉觀世音菩薩的觀音寺，民國73年（1984年）改奉阮弼真君為主神，觀音移奉偏殿。祭典以農曆10月13日真君誕辰為主，延聘道士誦經拜懺兩天；每隔一段時間配合誕辰舉行「庚申甲子會」，以每月庚申、甲子日為祭期，拜滿36次為一個滿會，重頭戲是過五層寶塔。另有農曆正月15日燒王船、燒寶塔，以及不定期為期八天的拜萬佛與「過十橋」儀式，保留大陳原鄉的海洋文化。花蓮縣於2014年登錄。","whereToSee":"阮弼真君廟（花蓮市民意里大陳一村）。真君誕辰祭典在農曆10月13日前後，燒王船、燒寶塔在農曆正月15日；庚申甲子會與拜萬佛不定期舉行，實際時間請以廟方公告為準。燒王船時請與火場保持距離，聽從工作人員指示。","venueId":"venue-f-ruanbi","dialogue":[{"who":"R","text":"Allan，花蓮的大陳新村裡，竟然有一座拜海神的廟？"},{"who":"A","text":"對，阮弼真君是大陳人的守護神之一，被奉為海神。1955年大陳居民遷臺，也把這份信仰帶到了花蓮。"},{"who":"R","text":"那這座廟從一開始就是拜阮弼真君嗎？"},{"who":"A","text":"原本是供奉觀世音菩薩的觀音寺，1984年改奉阮弼真君為主神，觀音移到偏殿。"},{"who":"R","text":"聽說祭典裡有一個「過五層寶塔」，聽起來好像闖關遊戲！"},{"who":"A","text":"那是庚申甲子會的重頭戲，要拜滿36次才算一個滿會，比我集點換贈品還要有毅力。"},{"who":"R","text":"那元宵節的時候，這裡有什麼特別的儀式嗎？"},{"who":"A","text":"農曆正月15日燒王船、燒寶塔，還有不定期的拜萬佛和過十橋，都是這座廟獨有的大陳風俗。"},{"who":"R","text":"小任務：到廟裡找一找主神和偏殿各供奉哪位神明，想想他們換位子的故事。"}],"quiz":[{"q":"阮弼真君在大陳人的信仰中主要被奉為什麼神？","options":["土地神","海神","文昌神","灶神"],"answer":1,"explain":"阮弼真君為大陳人信仰中的守護神之一，被奉為海神，原祀於上大陳的樁頭廟。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20140428000003"},{"id":"ich-lidaw-sikawasay","name":"花蓮縣吉安鄉東昌村阿美族里漏部落巫師祭儀","type":"民俗","holder":"財團法人原住民音樂文教基金會；祭師黃丁妹、莊美梅、黃陳勤蘭、高金妣、邱碧蓮、陳西妹、楊玉英、邱金英、黃花妹（已故）","registered":"2009-12-09","summary":"里漏部落祭師團體的歲時祭儀","intro":"阿美族的祭師（sikawasay）是擁有神靈的人，為私人與部落執行祭祀。吉安鄉東昌村的里漏（Lidaw）部落屬南勢阿美，登錄時祭師團體僅存9名，全為女性，官方紀錄認為是當時阿美族中祭師組織最完整、儀式與信仰體系最精緻者。成為祭師並非自願，而是經神靈挑選、生病或作夢後，由資深祭師鑑定認可；平日須遵守禁忌，例如終生不吃蔥、蒜、羊、雞、兔，儀式當日禁吃蔬菜與魚類，儀式期間不碰生水、不遠遊。祭師的歲時祭儀多配合部落農事舉行，十月初另有巫師祭。財團法人原住民音樂文教基金會長年記錄與推廣。花蓮縣於2009年登錄，名單中的黃花妹祭師已辭世。","whereToSee":"里漏部落（吉安鄉東昌村）。祭師祭儀多為部落與家族的信仰儀式，沒有對外公開的固定時程，時間依部落與祭師團體決定。外人請勿擅自前往觀看或拍攝，如欲了解，請透過部落或文化單位的公開活動認識。","venueId":"venue-f-lidaw","dialogue":[{"who":"R","text":"Allan，阿美族的祭師是怎麼產生的？可以報名嗎？"},{"who":"A","text":"不行喔。官方紀錄說，祭師是被神靈挑選的，常是生病或作夢之後，再由資深祭師鑑定認可。"},{"who":"R","text":"原來是被選中的人。里漏部落的祭師團體有多少人？"},{"who":"A","text":"登錄時僅存9位，全是女性，官方認為是當時阿美族祭師組織最完整的一群。"},{"who":"R","text":"當了祭師之後，平常的生活會不一樣嗎？"},{"who":"A","text":"要守很多禁忌，例如終生不吃蔥、蒜、羊、雞、兔，儀式期間不碰生水、不遠遊，是很大的承擔。"},{"who":"R","text":"聽起來很辛苦，也很令人敬佩。那我們可以去看祭儀嗎？"},{"who":"A","text":"這些多半是部落自己的信仰儀式，外人不要擅自前往或拍攝。想認識的話，就參加部落公開的文化活動。"},{"who":"R","text":"小任務：在公開的文化展覽裡，找一找祭師在部落裡扮演哪些角色。"}],"quiz":[{"q":"依官方紀錄，里漏部落的祭師是如何產生的？","options":["由部落投票選出","自行報名參加","經神靈挑選並由資深祭師鑑定認可","由頭目指派"],"answer":2,"explain":"祭師並非自願參加，而是經神靈挑選、生病或作夢後，由資深祭師鑑定認可。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20091209000005"},{"id":"ich-makotaay-ilisin","name":"花蓮縣豐濱鄉Makotaay(港口)部落阿美族ilisin豐年祭","type":"民俗","holder":"花蓮縣吉浦巒文化發展協會、港口部落豐年祭籌備委員會","registered":"2011-05-30","summary":"港口部落年齡階級主導的海岸阿美豐年祭","intro":"港口部落（Makotaay）位於豐濱鄉秀姑巒溪口，港口村的大港口、港口、石梯坪、石梯灣、石門五個聚落，每年統一在港口聚落共同舉行ilisin，族語意為「祭祀」。傳說昔日吠犬階級（Miaowaoway）從山上巡守作物返回時，族人舉行盛大活動迎接、慶祝豐收。祭典由男性年齡階級籌備執行，從凌晨由頭目在廣場迎神靈與祖靈開始，整夜吟唱到天明，至今不用麥克風，由領唱者清唱；流程包括迎靈、宴靈、晉階儀式（四年一次）、敬老、牽情之夜、送靈與漁撈祭。男女分日進行祭典是少見特色。日治時期青年在羽冠頂端繫上白布條，至今仍可見。花蓮縣於2011年登錄，同年文化部指定為重要民俗。","whereToSee":"港口部落祭典廣場（豐濱鄉港口村天主堂活動廣場一帶）。官方紀錄記載每年國曆7月20日至25日舉行，實際日程請以部落及豐濱鄉公所公告為準。官方紀錄的禁忌：迎靈祭到宴靈祭女性不得入內參加儀式及歌舞、只能旁觀；未經族人及頭目同意禁止進入祭場中間；豐年祭歌舞平常不唱。請在場外靜觀，拍照前先徵得同意，勿使用閃光燈。","venueId":"venue-f-makotaay","dialogue":[{"who":"R","text":"Allan，港口部落豐年祭聽說是從半夜開始的？"},{"who":"A","text":"對，凌晨時分由頭目在廣場迎接神靈與祖靈，也迎接提著火把來到廣場的青年，然後整夜吟唱到天明。"},{"who":"R","text":"唱一整晚！他們會用麥克風擴音嗎？"},{"who":"A","text":"不用，至今都是領唱者現場清唱，大家跟著應和。聲音直接打進心裡，比任何音響都震撼。"},{"who":"R","text":"我還聽說男生和女生的祭典是分開的天數？"},{"who":"A","text":"沒錯，男性參與四天，女性的送靈祭有自己的一天。迎靈到宴靈期間，女性只能旁觀，這是官方紀錄的禁忌。"},{"who":"R","text":"那我們外地人去參觀，要特別注意什麼？"},{"who":"A","text":"未經族人和頭目同意，不能走進祭場中間。我在場外最好的位置，就是不擋路的那一格。"},{"who":"R","text":"小任務：遠遠觀察青年羽冠頂端的白布條，想一想它背後的歷史故事。"}],"quiz":[{"q":"港口部落豐年祭的祭典歌謠有什麼特色？","options":["全程播放錄音","不用麥克風，由領唱者清唱","只由女性演唱","以樂器演奏為主"],"answer":1,"explain":"官方紀錄指出港口部落的祭典至今不使用麥克風，由一名或數名領唱者現場清唱。"},{"q":"依官方紀錄，未經誰的同意禁止進入祭場中間？","options":["鄉長","觀光導遊","族人及頭目","派出所"],"answer":2,"explain":"官方紀錄的禁忌之一：若未受到族人及頭目同意，禁止進入祭場中間。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20110825000010"},{"id":"ich-fakong-ilisin","name":"Ilisin no Fakong","type":"民俗","holder":"Fakong（貓公）部落","registered":"2014-05-28","summary":"貓公部落年年不輟的豐年祭","intro":"Fakong（貓公）部落位於豐濱鄉，數百年前阿美族祖先來到貓公溪，見溪谷台地長滿文殊蘭（fakong），便以此為名，昭和12年（1937年）改稱豐濱。部落的ilisin從建社以來每年舉行，官方紀錄為8月5日至10日，前一天還有登聖山昭告祖靈。流程包括部落會議、在聚會所祭祖迎靈、獎勵青年、獻酒祭、牽手情、宴請賓客、娛靈歌舞與送靈。迎靈時族人在歷代頭目名木匾前念誦頭目名字，祭拜祖靈的陶杯仍依傳統工藝製作。年齡階級分工嚴謹，由青年之父規劃監督。2011年田野調查統計祭歌共36首。花蓮縣於2014年登錄，2024年文化部登錄為重要民俗。","whereToSee":"貓公部落聚會所與祭場（豐濱鄉豐濱村）。官方紀錄記載每年8月5日至10日舉行，實際日程請以部落及豐濱鄉公所公告為準。官方紀錄的禁忌：8月5日起到8月6日晚間的祭祖迎靈與獻酒祭期間，禁止女性、小孩及非部落族人進入聚會所周邊道路；獻酒祭外人禁止入場；祭典期間未經邀請共舞，禁止入場。請遵守部落管制，拍照前先徵得同意。","venueId":"venue-f-fakong","dialogue":[{"who":"R","text":"Allan，豐濱鄉的貓公部落，名字跟貓有關係嗎？"},{"who":"A","text":"沒有喔。祖先來到溪谷時看到滿山文殊蘭，族語就用這種植物替部落命名，後來音譯成貓公。"},{"who":"R","text":"原來是花的名字！那貓公部落豐年祭什麼時候舉行？"},{"who":"A","text":"官方紀錄是每年8月5日到10日，從建社以來沒有中斷過，不過還是要看部落當年的公告。"},{"who":"R","text":"祭典裡最讓你印象深刻的是什麼？"},{"who":"A","text":"迎靈時族人在歷代頭目名的木匾前，一個一個念出頭目名字，部落的歷史就這樣代代記住。"},{"who":"R","text":"那我們外地人可以走進祭場參觀嗎？"},{"who":"A","text":"前兩天的祭祖迎靈和獻酒祭，女性、小孩和非部落族人都不能進入聚會所周邊，沒被邀請也不能下場共舞。"},{"who":"R","text":"小任務：留意公告的開放時段，在場邊找一找祭祖用的傳統陶杯。"}],"quiz":[{"q":"貓公部落的族語名稱來自哪一種植物？","options":["檳榔","文殊蘭","月桃","小米"],"answer":1,"explain":"祖先來到貓公溪時，看見溪谷台地長滿文殊蘭，便以此命名部落。"},{"q":"迎靈祭儀時，族人在什麼前面念誦歷代頭目的名字？","options":["歷代頭目名木匾","教堂祭壇","海邊礁石","部落大門"],"answer":0,"explain":"官方紀錄記載迎靈祭儀時，族人在聚會所歷代頭目名木匾前祝禱並念誦歷代頭目名字。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20240912000002"},{"id":"ich-fakong-pottery","name":"花蓮縣豐濱鄉豐濱部落阿美族傳統製陶","type":"民俗","holder":"Alike工作室；莊阿妹（已故）、莊江玉、蔡娟綱、鍾秋香、蔡桂美、莊利心、蔡明碧","registered":"2009-12-09","summary":"手捏、木拍、露天燒的阿美族古法製陶","intro":"官方紀錄指出，臺灣原住民族中至今仍保有傳統製陶技術的，只有阿美族與達悟族。過去東海岸阿美族形成太巴塱、豐濱等製陶中心，豐濱部落每年五月集體製陶一次，幾乎每戶有一位婦女參加，製作水壺、飯鍋、陶甑、酒杯與祭器。阿美陶以手捏塑，不用陶車、不上釉：先到部落公墓旁的田埂黃土採土，搗土時以酒作祭；再一手持卵石墊住、一手持木拍拍打成形，沾水把表面摩光，陰乾後在溪埔空地以稻草、茅草、稻穀覆蓋露天悶燒約24小時。採土、燒陶前都要舉行祭儀，過去製陶期間婦女還要守禁忌。登錄保存者為Alike工作室的婦女，其中莊阿妹已辭世。花蓮縣於2009年登錄。","whereToSee":"豐濱部落（貓公部落，豐濱鄉豐濱村）。製陶沒有固定的公開展演時程，可留意部落工作室或文化活動的公開體驗。部落的豐年祭也會用到傳統陶杯，參觀時請尊重相關祭儀與禁忌。","venueId":"venue-f-fakong","dialogue":[{"who":"R","text":"Allan，這個陶壺摸起來好樸實，好像沒有上釉？"},{"who":"A","text":"沒錯，這是豐濱部落的阿美族傳統陶。手捏塑形，不用陶車、不上釉，最後露天燒製。"},{"who":"R","text":"不用陶車要怎麼做出圓圓的形狀？"},{"who":"A","text":"一手拿卵石在裡面墊著，一手拿木拍在外面拍打，再沾水把表面磨光，全靠一雙巧手。"},{"who":"R","text":"露天燒陶的話，要燒多久才會完成？"},{"who":"A","text":"在溪埔空地用稻草、茅草、稻穀蓋起來悶燒約24小時，守窯的人要整天顧火，比我顧烤肉還認真。"},{"who":"R","text":"官方紀錄說，臺灣原住民族中只剩兩族還保有傳統製陶？"},{"who":"A","text":"對，就是阿美族和達悟族。採土、燒陶前都要舉行祭儀，祈求陶器順利燒成不龜裂。"},{"who":"R","text":"小任務：如果有機會看到阿美陶，找一找表面上木拍拍打留下的痕跡。"}],"quiz":[{"q":"豐濱部落阿美族傳統製陶的特色是什麼？","options":["使用電動陶車","表面施釉","手捏塑形、不上釉、露天燒製","以高溫窯燒"],"answer":2,"explain":"阿美族傳統陶以手捏塑、不用陶車、不上釉，不設窯、露天燒製而成。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20091209000006"},{"id":"ich-lidaw-palunan","name":"Palunan nu Lidaw","type":"民俗","holder":"Lidaw部落年齡階層","registered":"2023-07-04","summary":"里漏部落每八年一次的成年禮祭典","intro":"里漏（Lidaw）部落位於吉安鄉東昌村，屬南勢阿美七社之一。Palunan是部落最重要的祭禮，重現祖先上岸建立部落的歷史，象徵男女成年、即將共組家庭，也代表部落有一個新的年齡階級誕生。Palunan每隔七年（前後共八年）舉行一次，每年暑期由前兩級到四級的長輩協助訓練即將進階的青少年，內容包括海邊求生訓練、祭儀歌舞、捕鳥陷阱製作、尋找飲水與傳說故事。祭船歌謠會呼喚先祖名稱，包括傳說中的開拓祖先；祭典開始前的競跑活動也會造訪特定的傳統祭拜地點。這是族人自主、自發參與的部落大事，凝聚向心力並傳遞文化。花蓮縣於2023年登錄。","whereToSee":"里漏部落（吉安鄉東昌村）。每八年舉行一次，下一次的年份與日期請以部落或吉安鄉公所公告為準。祭典與訓練屬部落年齡階層事務，外人請在開放範圍觀看，勿跟隨進入訓練或祭拜地點，拍照前先徵得同意。","venueId":"venue-f-lidaw","dialogue":[{"who":"R","text":"Allan，有一種成年禮要等八年才輪到一次？"},{"who":"A","text":"對，這是吉安鄉里漏部落的成年禮祭典，每隔七年舉行，前後算起來共八年，部落會誕生一個新的年齡階級。"},{"who":"R","text":"八年一次，等待的人一定很期待！要準備什麼？"},{"who":"A","text":"每年暑假，長輩會帶青少年做海邊求生訓練、學祭儀歌舞、做捕鳥陷阱，還要學會找飲水和聽傳說故事。"},{"who":"R","text":"哇，根本是部落版的野外生存營！"},{"who":"A","text":"而且祭典會重現祖先上岸建立部落的歷史，祭船歌謠裡還會呼喚開拓祖先的名字。"},{"who":"R","text":"那我這個外地人也能去報名參加訓練嗎？"},{"who":"A","text":"這是部落年齡階層的事，我們在開放範圍安靜觀看就好。我的求生技能只有找到最近的便利商店。"},{"who":"R","text":"小任務：留意部落公告，下一次祭典時，聽聽祭船歌謠裡呼喚祖先的段落。"}],"quiz":[{"q":"里漏部落的成年禮祭典多久舉行一次？","options":["每年一次","每三年一次","每五年一次","每隔七年，前後共八年一次"],"answer":3,"explain":"官方紀錄記載這項祭典每隔七年（前後共八年）舉行一次，代表部落新年齡階級的誕生。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20240116000002"},{"id":"ich-a-pasibutbut-zhuoxi","name":"布農族音樂pasibutbut(小米豐收歌)","type":"傳統表演藝術","holder":"花蓮縣布農文化教育關懷協會","registered":"2015-10-23","summary":"卓溪鄉布農族祈禱小米豐收的複音歌謠","intro":"Pasibutbut是布農族祈禱小米豐收的歌，常被稱為「八部合音」，只存在於布農族郡社群（isi bukun）與巒社群（take banua）。演唱時族人有默契地由領唱人起音，其餘聲部依循主音漸漸往上爬升，尋找完美的共鳴，把祈求豐收的心願交付在歌聲中。卓溪鄉古風部落曾讓中斷一段時間的pasibutbut等歌謠重新恢復，再推廣到卓溪鄉全境的布農族部落，官方紀錄指出自1980年代以來一直承載著傳統的延續。卓溪鄉各部落也傳唱Malastapang（誇功宴）與其他祭儀歌謠。保存團體花蓮縣布農文化教育關懷協會長年投入傳承。花蓮縣於2015年登錄。","whereToSee":"流傳於卓溪鄉古風等布農族部落，沒有固定的公開演出時刻；可留意部落祭儀與卓溪鄉的文化活動公告。祭儀場合請依部落規範，勿擅自闖入，錄音錄影前先徵得同意。","venueId":"","dialogue":[{"who":"R","text":"Allan，卓溪鄉的布農族也會唱那首有名的八部合音嗎？"},{"who":"A","text":"會喔，花蓮這裡登錄的是卓溪鄉的祈禱小米豐收歌，由花蓮縣布農文化教育關懷協會傳承。"},{"who":"R","text":"這首歌是怎麼開始唱的？大家一起開口嗎？"},{"who":"A","text":"先由領唱的人起音，其他人依著主音慢慢往上爬，一直找到最完美的共鳴，像一起爬山攻頂。"},{"who":"R","text":"那這首歌在卓溪一直都有人唱嗎？"},{"who":"A","text":"官方紀錄說，古風部落曾把中斷一段時間的歌謠重新唱回來，再推廣到卓溪鄉全境的布農部落。"},{"who":"R","text":"一個部落把歌找回來，再分享給大家，好感人！"},{"who":"A","text":"我也想加入合音，可是我一開口，共鳴就變成共振，大家的小米都嚇得不敢長。"},{"who":"R","text":"小任務：聆聽時試著分辨領唱的第一個音，再數數後面加入了幾層聲音。"}],"quiz":[{"q":"依官方紀錄，祈禱小米豐收歌只存在於布農族的哪兩個社群？","options":["卓社群與卡社群","丹社群與蘭社群","郡社群與巒社群","卓社群與郡社群"],"answer":2,"explain":"官方紀錄指出，祈禱小米豐收歌只存在於布農族的郡社群與巒社群。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalPerformingart/20151023000001"},{"id":"ich-a-kavalan-banana","name":"噶瑪蘭族ni tenunan tu benina香蕉絲織布","type":"傳統工藝","holder":"嚴玉英（aing banday，文化部認定之重要傳統工藝保存者）、許來富、花蓮縣噶瑪蘭族發展協會；朱阿菊、潘烏吉、潘阿玉、潘金英（均已故）","registered":"2015-10-26","summary":"新社噶瑪蘭族以香蕉纖維織布的獨特工藝","intro":"香蕉絲織布是臺灣原住民族中極少數以香蕉纖維織布的技藝，今日能完整呈現並應用的只有豐濱鄉新社的噶瑪蘭族人。1990年代初新社噶瑪蘭族人發起民族復興運動，由部落三位祭師從記憶中一步步把香蕉絲編織的知識與技術找回來。工序包括收割香蕉假莖、製作香蕉絲材料、日曬水洗、績線、整經、織作與後處理，以竹管地織機、立柱式整經台等機具平織，多呈現北蕉纖維的自然色澤。傳統上割莖採纖與織布都要舉行Sbau儀式祈求祖靈保佑。花蓮縣於2015年登錄，文化部於2021年登錄為重要傳統工藝並認定嚴玉英為保存者；縣登錄名單中的朱阿菊、潘烏吉、潘阿玉、潘金英已辭世。","whereToSee":"新社香蕉絲工坊一帶（豐濱鄉新社村）。可留意工坊與部落公開的展示、體驗活動，開放時間與預約方式請以工坊或部落公告為準。若遇到Sbau等祭儀，請勿打擾或拍攝。","venueId":"venue-a-xinshe-banana","dialogue":[{"who":"R","text":"Allan，香蕉除了吃，竟然還可以拿來織布？"},{"who":"A","text":"可以！豐濱鄉新社的噶瑪蘭族人，把香蕉的假莖剖開刮出纖維，再一根一根接成長線來織布。"},{"who":"R","text":"一根一根接？那織一塊布要花多少功夫啊！"},{"who":"A","text":"從收割、刮纖、日曬水洗、績線、整經到上地織機，每一步都靠手工，官方說這是臺灣極少數的香蕉纖維織布技藝。"},{"who":"R","text":"這門手藝在部落裡一直都沒有斷過嗎？"},{"who":"A","text":"1990年代初，部落三位祭師從記憶中把技術一步步找回來，族人再一起傳承下去。"},{"who":"R","text":"那現在文化部認定的保存者是哪一位呢？"},{"who":"A","text":"是嚴玉英。以後我吃香蕉都會先跟香蕉樹道謝，它的全身都是寶。"},{"who":"R","text":"小任務：到工坊看看香蕉布，找一找北蕉纖維原本的自然色澤。"}],"quiz":[{"q":"噶瑪蘭族香蕉絲織布主要使用香蕉樹的哪個部位取得纖維？","options":["果實","假莖","根部","花苞"],"answer":1,"explain":"工序從收割香蕉假莖開始，取其纖維製成香蕉絲，再績線、整經、織作。"},{"q":"文化部登錄香蕉絲織布為重要傳統工藝時，認定的保存者是誰？","options":["嚴玉英","潘烏吉","胡正昌","施菊花"],"answer":0,"explain":"文化部於2021年登錄噶瑪蘭族香蕉絲織布為重要傳統工藝，並認定嚴玉英為保存者。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalCraft/20210521000002"},{"id":"ich-a-seediq-rattan","name":"賽德克族傳統籐編工藝","type":"傳統工藝","holder":"花蓮縣卓溪鄉山里社區發展協會（工藝師胡正昌）","registered":"2016-03-03","summary":"卓溪山里部落保留陶賽傳統的籐編背簍","intro":"卓溪鄉立山村的山里部落，有賽德克族陶賽群的族人居住。官方紀錄說明，工藝師胡正昌製作的籐編成品包括裝一般物品的Beluwui，以及裝獵物的Lawa。Beluwui上緣採反摺編法以加強強度，連接背帶或頭帶的扣環收編得非常漂亮。作品造形與工法雖然樸拙，但技法傳承自部落耆老；工藝師較少與外界互動，因此仍保有陶賽的傳統技法與樣式，與太魯閣族的籐編有所區別。籐編也反映賽德克族男性的工藝文化。保存團體山里社區發展協會擔任工藝師與外界交流的橋樑。花蓮縣於2016年登錄。","whereToSee":"卓溪鄉立山村山里部落。沒有固定的公開展示地點，可留意山里社區發展協會或卓溪鄉的文化活動與工藝展覽；拜訪部落前請先與社區聯繫，勿擅自進入私人工作空間。","venueId":"","dialogue":[{"who":"R","text":"Allan，這個籐編背簍的上緣怎麼摺了一圈？"},{"who":"A","text":"這是反摺編法，用來加強強度。卓溪鄉山里部落的工藝師胡正昌，就是這樣編裝東西的背簍。"},{"who":"R","text":"這種籐編背簍，還有分不同的種類嗎？"},{"who":"A","text":"有，一種裝日常物品，另一種專門裝獵物。背帶連接處的扣環，官方紀錄還特別稱讚收編得很漂亮。"},{"who":"R","text":"賽德克族的籐編，跟太魯閣族的看起來一樣嗎？"},{"who":"A","text":"官方說工藝師保有陶賽群的傳統技法與樣式，跟太魯閣族的有所區別，這也是登錄的原因之一。"},{"who":"R","text":"那工藝師的這身手藝，是跟誰學來的呢？"},{"who":"A","text":"傳承自部落耆老。我編過最複雜的東西是藉口，可惜一下就被看穿了。"},{"who":"R","text":"小任務：看到籐編背簍時，找一找背帶和簍身連接的扣環是怎麼收尾的。"}],"quiz":[{"q":"胡正昌工藝師的籐編背簍上緣採用什麼編法來加強強度？","options":["鏤空編法","反摺編法","雙層夾編","螺旋編法"],"answer":1,"explain":"官方紀錄記載Beluwui的上方有反摺的編法，以加強其強度。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalCraft/20160303000001"},{"id":"ich-a-seediq-weaving","name":"賽德克族陶賽(山里)部落傳統編織工藝","type":"傳統工藝","holder":"花蓮縣卓溪鄉山里社區發展協會","registered":"2016-03-10","summary":"山里部落以地織機織出的桃紅色傳統布","intro":"卓溪鄉山里部落的賽德克族婦女，保有從陶賽溪流域延續下來的編織傳統。編織（tminun）傳統布（pala）不只是生產，也是一種生活觀與對土地的連結，相關的Waya（宗教禁忌、道德規範和社會規則）很早就流傳，每位賽德克族婦女都是傳統的守護者。社區仍使用地織機，保有從割苧麻、剝麻皮、打紗、捻紗、紡紗、煮線到理經、織布的14道工序；理經時婦女要先算好針數與樣式並默記下來。紋路有平紋、斜紋、菱形、花織、米粒織與浮織，設色以桃紅為主，布幅寬達45甚至60公分，難度頗高。山里社區發展協會整合20至30位老藝師，並到學校傳授。花蓮縣於2016年登錄。","whereToSee":"卓溪鄉立山村山里部落。沒有固定的公開展示地點，可留意山里社區發展協會、學校或卓溪鄉的文化活動與織品展覽；拜訪前請先與社區聯繫。","venueId":"","dialogue":[{"who":"R","text":"Allan，這塊布的顏色好鮮豔，以桃紅色為主耶！"},{"who":"A","text":"這是卓溪鄉山里部落賽德克族的傳統布，設色以桃紅為主，是他們很鮮明的特色。"},{"who":"R","text":"織一塊這樣的布要經過哪些步驟？"},{"who":"A","text":"從割苧麻、剝麻皮、捻紗、紡紗、煮線，到理經、織布，一共有14道工序，現在還用地織機在織。"},{"who":"R","text":"14道工序！那其中哪一道最困難？"},{"who":"A","text":"官方紀錄說理經最重要，要先算好針數和樣式，全部默記在腦子裡。我連早餐吃什麼都記不住。"},{"who":"R","text":"我看這塊布的布幅好像也特別寬？"},{"who":"A","text":"寬達45公分甚至60公分，用地織機織這麼寬很不容易。社區還有二三十位老藝師在傳承，也到學校教學。"},{"who":"R","text":"小任務：看到賽德克織布時，數數看你能認出平紋、斜紋、菱形紋其中幾種。"}],"quiz":[{"q":"山里部落賽德克族傳統織布的設色以哪個顏色為主？","options":["深藍","黑色","黃色","桃紅"],"answer":3,"explain":"官方紀錄指出，山里部落的織布設色以桃紅為主，具有鮮明特色。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalCraft/20160303000002"},{"id":"ich-a-bunun-menswear","name":"布農族男子傳統服飾編織","type":"傳統工藝","holder":"施菊花（Muia Sunavan，已故）","registered":"2011-05-30","summary":"卓溪鄉布農族男子傳統服飾的水平織技藝","intro":"傳統服飾是布農族男子身分與認同的表徵。花蓮縣登錄的布農族男子傳統服飾編織，保存者是卓溪鄉的織布者施菊花（Muia Sunavan）。官方紀錄指出，這項布農族織布技藝在物質文化與水平織法上都有價值，深具藝術性、特殊性與地方性。施菊花使用傳統工具織布，作品除了保留舊有的圖樣，也能在其中加以變化，展現創造力。依官方紀錄，保存者施菊花已經辭世，她留下的作品與技法，仍是後輩認識布農族男子服飾的重要參考。花蓮縣於2011年登錄。","whereToSee":"流傳於卓溪鄉布農族部落，沒有固定的公開展示地點；可留意卓溪鄉與花蓮縣的原住民族文化展覽，以及部落祭儀時族人穿著的傳統服飾。拍攝穿著傳統服飾的族人前，請先徵得同意。","venueId":"","dialogue":[{"who":"R","text":"Allan，布農族男子穿的傳統服飾，原來也是一門登錄的工藝？"},{"who":"A","text":"對，花蓮縣登錄了布農族男子傳統服飾編織，傳統服飾是布農族男子身分與認同的表徵。"},{"who":"R","text":"那這項工藝登錄的保存者是哪一位？"},{"who":"A","text":"是卓溪鄉的織布者施菊花，官方紀錄說她已經辭世，但她的作品和技法仍是重要的參考。"},{"who":"R","text":"她織出來的作品，有什麼特別的地方？"},{"who":"A","text":"她用傳統工具和水平織法，作品保留舊有圖樣，又能變化出新意，傳統和創意兼顧。"},{"who":"R","text":"傳統和創意兼顧，聽起來真的很厲害！"},{"who":"A","text":"我也想新舊兼顧，結果只做到舊衣服配新肚子。服飾的美，還是交給真正的織布者吧。"},{"who":"R","text":"小任務：在部落活動中看到布農族男子傳統服飾時，留意衣服上的織紋圖樣。"}],"quiz":[{"q":"依官方紀錄，施菊花的布農族服飾編織使用哪一種織法？","options":["提花機織法","水平織法","針織法","刺繡貼布"],"answer":1,"explain":"官方紀錄指出，這項布農族織布技藝在物質文化及技法（水平織法）均有其價值。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalCraft/20190715000002"}],"venues":[{"id":"venue-f-dazhuang","name":"大庄公廨","address":"花蓮縣富里鄉東里村大庄","lat":null,"lng":null,"relatedSiteId":"","ichIds":["ich-dazhuang-yeji"],"antiquities":[]},{"id":"venue-f-cihuitang","name":"聖地慈惠堂總堂","address":"花蓮縣吉安鄉勝安村慈惠三街136號","lat":23.9780673,"lng":121.5860601,"relatedSiteId":"","ichIds":["ich-cihuitang-tangqing"],"antiquities":[]},{"id":"venue-f-shenganggong","name":"花蓮勝安宮","address":"花蓮縣吉安鄉勝安村慈惠三街118號","lat":23.9782108,"lng":121.5867273,"relatedSiteId":"","ichIds":["ich-shenganggong-raojing"],"antiquities":[]},{"id":"venue-f-ruanbi","name":"阮弼真君廟（大陳一村）","address":"花蓮縣花蓮市民意里大陳一村","lat":24.0043562,"lng":121.616461,"relatedSiteId":"","ichIds":["ich-ruanbi-zhenjun"],"antiquities":[]},{"id":"venue-f-lidaw","name":"里漏部落","address":"花蓮縣吉安鄉東昌村","lat":null,"lng":null,"relatedSiteId":"","ichIds":["ich-lidaw-sikawasay","ich-lidaw-palunan"],"antiquities":[]},{"id":"venue-f-makotaay","name":"港口部落祭典廣場（港口天主堂一帶）","address":"花蓮縣豐濱鄉港口村","lat":23.4753502,"lng":121.5039987,"relatedSiteId":"","ichIds":["ich-makotaay-ilisin"],"antiquities":[]},{"id":"venue-f-fakong","name":"貓公部落（豐濱部落）","address":"花蓮縣豐濱鄉豐濱村","lat":23.5970241,"lng":121.5206177,"relatedSiteId":"","ichIds":["ich-fakong-ilisin","ich-fakong-pottery"],"antiquities":[]},{"id":"venue-a-xietiangong","name":"玉里協天宮","address":"花蓮縣玉里鎮光復路54巷","lat":23.3339232,"lng":121.3160077,"relatedSiteId":"yuli-batongguangudao","ichIds":[],"antiquities":[{"name":"玉里協天宮後山保障牌匾","level":"一般古物","registered":"2013-07-01","note":"牛樟木牌匾，金漆楷書「後山保障」，上款光緒七年；相傳為總兵吳光亮所立，今為協天宮鎮宮之寶"}]},{"id":"venue-a-bilian","name":"碧蓮寺（豐田神社舊址）","address":"花蓮縣壽豐鄉豐裡村民權街1號","lat":23.8389390845471,"lng":121.501546732631,"relatedSiteId":"shoufeng-fengtianshenshecan","ichIds":[],"antiquities":[{"name":"林田村本願寺銅鐘","level":"一般古物","registered":"2009-12-28","note":"原屬林田村本願寺的青銅鐘，戰後日人遣返時由住持送至豐田神社，今由碧蓮寺管理委員會保管"}]},{"id":"venue-a-fengli-cemetery","name":"壽豐豐裡村日本移民墓園","address":"花蓮縣壽豐鄉豐裡村中山路旁巷內","lat":23.8413590962349,"lng":121.506463338608,"relatedSiteId":"shoufeng-fenglicunribenyi","ichIds":[],"antiquities":[{"name":"密教鎮地石碑","level":"一般古物","registered":"2009-12-28","note":"正面刻「南無阿彌陀佛」的日治時期石碑，曾移置他處，後移回移民墓園；位於民宅後側，請保持安靜"}]},{"id":"venue-a-fengping-dishen","name":"豐坪村地神祠","address":"花蓮縣壽豐鄉豐坪村豐正路二段","lat":null,"lng":null,"relatedSiteId":"","ichIds":[],"antiquities":[{"name":"地神","level":"一般古物","registered":"2009-12-28","note":"日治移民村設置的大理石戶外地神，1971年村民集資建祠，今當作土地公祭拜"}]},{"id":"venue-a-xining","name":"吉安西寧寺","address":"花蓮縣吉安鄉干城村吉安路六段839號","lat":23.9484548,"lng":121.5234771,"relatedSiteId":"jian-hengduandaolukai","ichIds":[],"antiquities":[{"name":"西寧寺不動明王","level":"一般古物","registered":"2016-05-25","note":"日治時期留存的大型木雕不動明王坐像，右手持劍、左手持索，花蓮同類大型神像僅存兩尊"}]},{"id":"venue-a-yanpingwang","name":"花蓮市延平王廟","address":"花蓮縣花蓮市","lat":null,"lng":null,"relatedSiteId":"","ichIds":[],"antiquities":[{"name":"花蓮市延平王廟開基延平王神像","level":"一般古物","registered":"2023-05-04","note":"以單塊樟木雕成、身椅一體的開基神像，廟方相傳與咸豐年間十六股庄開墾有關；參拜時請勿觸碰"}]},{"id":"venue-a-xinshe-banana","name":"新社香蕉絲工坊","address":"花蓮縣豐濱鄉新社村","lat":23.6566737,"lng":121.539644,"relatedSiteId":"","ichIds":["ich-a-kavalan-banana"],"antiquities":[]}]},"ubike":{"meta":{},"stations":[]},"extra":{"intro":[{"who":"A","text":"嗨，我是 Allan Lo！搭火車穿過北迴線一個又一個隧道，一邊是中央山脈、一邊是太平洋，我們到花蓮了。"},{"who":"R","text":"我是阿拉蕾！花蓮不就是太魯閣、麻糬，還有一條長長的花東縱谷嗎？"},{"who":"A","text":"說得好。花蓮的文化資產一共99處，有縣定古蹟、歷史建築、考古遺址、文化景觀和聚落建築群。"},{"who":"R","text":"那國定古蹟呢？花蓮有很多嗎？"},{"who":"A","text":"老實說，登錄在花蓮的國定古蹟是0處。不過清代1875年開闢的八通關古道，從南投竹山通到花蓮玉里，是和南投共有的國定古蹟，我們把它的東端放在玉里。"},{"who":"R","text":"原來如此！那文資最多在哪裡？"},{"who":"A","text":"花蓮市有28處，很多是日治時期的宿舍和官舍；光復鄉有17處，大多在花蓮糖廠一帶；鳳林還有林田山林業聚落。"},{"who":"R","text":"我還知道，這裡是阿美族、太魯閣族、撒奇萊雅族、噶瑪蘭族、布農族和賽德克族的家園，富里大庄還有西拉雅族的夜祭！"},{"who":"A","text":"沒錯。2024年的強震和2025年馬太鞍溪的洪災，讓太魯閣和光復都還在復原，出發前記得查詢最新的開放與道路狀況。"},{"who":"R","text":"花蓮南北超過120公里，建議開車。準備好了嗎？從花蓮火車站出發囉！"}],"timeIntro":[{"who":"R","text":"Allan，花蓮的時光地圖要看什麼？"},{"who":"A","text":"先看西荷時期，西班牙人和荷蘭人都曾經到哆囉滿一帶找金子，那時縱谷和海岸是各族部落的天地。"},{"who":"A","text":"1875年清廷開山撫番，開闢八通關古道；日治時期有花蓮港廳和移民村。清代以後都會疊上當年的老地圖，可以拉透明度，也能左右對照。"},{"who":"R","text":"那我要找找看日治時期的花蓮港市街，和今天的花蓮市差多少！"},{"who":"A","text":"好，滑過去對照看看，答案就在地圖上！"}],"planIntro":[{"who":"A","text":"花蓮南北超過120公里，景點分散在花蓮市區、花東縱谷和山區，建議開車；花蓮市區的景點很密集，停好車就可以走路串遊。"},{"who":"R","text":"花蓮沒有高鐵，也沒有 YouBike，不過臺鐵北迴線和花東線從新城、花蓮一路到鳳林、光復、瑞穗、玉里和富里，搭火車也很方便！"},{"who":"A","text":"太魯閣一帶和中橫公路還有時段管制，光復鄉也還在災後復原，出發前請先查詢最新的開放和道路狀況。"},{"who":"R","text":"中午記得留肚子給扁食、麻糬和炸彈蔥油餅！"}],"gameIntro":[{"who":"R","text":"洄瀾遊戲場開張！問答王、時光排序、猜猜我是誰、翻翻樂，還有洄瀾擲骰大冒險！"},{"who":"A","text":"題目從松園別館、吉安慶修院，一路考到林田山、花蓮糖廠和八通關古道，看你能不能全部答對。"},{"who":"R","text":"Allan，這次擲骰子我一定贏你！"},{"who":"A","text":"哈哈，那就從花蓮火車站出發，比比看吧！"}],"reactions":[{"who":"R","text":"答對了！你根本就是花蓮通！"},{"who":"A","text":"正確答案！給你一個大大的讚。"},{"who":"R","text":"哎呀，答錯了，沒關係，看看解說再挑戰！"},{"who":"A","text":"可惜！差一點點，下次一定行。"},{"who":"R","text":"換我擲骰子囉！看我的！"},{"who":"A","text":"恭喜你贏了！今天的扁食和麻糬算我的！"},{"who":"R","text":"耶！這一局是我贏了，要不要再來一局？"},{"who":"A","text":"平手！你們兩個都是文資高手。"},{"who":"R","text":"時光排序完成！你從縱谷的史前遺址一路排到今天的洄瀾，好厲害！"},{"who":"A","text":"恭喜集到新的護照印章！"},{"who":"R","text":"全部配對成功，記憶力滿分！"},{"who":"A","text":"嗯，這一題我們一起看看解說。"}],"starts":[{"id":"station","name":"臺鐵花蓮車站","lat":23.99395,"lng":121.60093},{"id":"airport","name":"花蓮航空站","lat":24.02571,"lng":121.61384},{"id":"xincheng","name":"臺鐵新城（太魯閣）車站","lat":24.12805,"lng":121.6407},{"id":"fenglin","name":"臺鐵鳳林車站","lat":23.7463,"lng":121.44671},{"id":"guangfu","name":"臺鐵光復車站","lat":23.66635,"lng":121.42116},{"id":"ruisui","name":"臺鐵瑞穗車站","lat":23.49756,"lng":121.37677},{"id":"yuli","name":"臺鐵玉里車站","lat":23.33148,"lng":121.31176},{"id":"gps","name":"我的目前位置","lat":null,"lng":null},{"id":"pick","name":"在地圖上點選出發點","lat":null,"lng":null}],"plans":{"1":{"name":"一日：花蓮市區（松園別館、將軍府、山林事業所、文創園區）與吉安慶修院","days":[["hualian-songyuanbieguan","hualian-meilunxipanrishisu","hualian-meilunxipanrishisu2","hualian-gangshanlinshiye","hualian-jinghualinyuan","hualian-jiujianyuyiji","hualian-jiujiuchang","hualian-guozijiuguju","jian-qingxiuyuan","jian-jiyekaicunjinian"]]},"2":{"name":"二日：花蓮市區 ＋ 縱谷北段（豐田移民村、林田山、花蓮糖廠、太巴塱）","days":[["hualian-songyuanbieguan","hualian-meilunxipanrishisu","hualian-meilunxipanrishisu2","hualian-gangshanlinshiye","hualian-jinghualinyuan","hualian-jiujianyuyiji","hualian-jiujiuchang","hualian-guozijiuguju","jian-qingxiuyuan","jian-jiyekaicunjinian"],["shoufeng-fengtiancunyimin","shoufeng-jiufengtianyimin","shoufeng-fengtianshenshecan","fenglin-xiaozhangmenggong","fenglin-lintianshenshecan","fenglin-lintianshanlinyeju","guangfu-tangchangzhitang","guangfu-taitanggongsihua","guangfu-taibalangzuwu"]]},"3":{"name":"三日：再加縱谷南段（舞鶴、玉里、八通關古道東端、富里）","days":[["hualian-songyuanbieguan","hualian-meilunxipanrishisu","hualian-meilunxipanrishisu2","hualian-gangshanlinshiye","hualian-jinghualinyuan","hualian-jiujianyuyiji","hualian-jiujiuchang","hualian-guozijiuguju","jian-qingxiuyuan","jian-jiyekaicunjinian"],["shoufeng-fengtiancunyimin","shoufeng-jiufengtianyimin","shoufeng-fengtianshenshecan","fenglin-xiaozhangmenggong","fenglin-lintianshenshecan","fenglin-lintianshanlinyeju","guangfu-tangchangzhitang","guangfu-taitanggongsihua","guangfu-taibalangzuwu"],["ruisui-saobasuidao","ruisui-wuhekaoguyizhi","yuli-shenshecanji","yuli-chezhantiedaosushe","yuli-xinyongzuhejicang","yuli-batongguangudao","fuli-xiangdonglicunqiu","fuli-funanzhuanyaochang"]]}},"food":[]}};
